/* 자동 생성 — tools/build_data.py. 직접 고치지 마세요. */
(window.TS_DATA = window.TS_DATA || {}).p5 = [{"id":"p5-001","level":1,"type":"품사","question":"Ms. Kim is a very ------- manager.","choices":["careful","carefully","care","carefulness"],"answer":0,"explanation":"관사 a와 명사 manager 사이에서 very의 꾸밈을 받으며 명사를 수식할 자리이므로 형용사 careful이 정답이다. carefully는 부사라 명사를 꾸밀 수 없고, care와 carefulness는 명사라 이 자리에 맞지 않는다.","translation":"김 씨는 매우 신중한 관리자이다.","part":5},{"id":"p5-002","level":1,"type":"품사","question":"Please read the instructions ------- before using the machine.","choices":["cared","care","carefully","careful"],"answer":2,"explanation":"read the instructions라는 완전한 문장 뒤에서 동사 read를 꾸미는 자리이므로 부사 carefully가 정답이다. careful은 형용사, care는 명사·동사, cared는 과거형이라 동사를 수식할 수 없다.","translation":"기계를 사용하기 전에 설명서를 주의 깊게 읽어 주세요.","part":5},{"id":"p5-003","level":1,"type":"품사","question":"The ------- of the new store is next Monday.","choices":["opened","opens","opening","open"],"answer":2,"explanation":"정관사 The 뒤, 전치사 of 앞은 주어 역할을 하는 명사 자리이므로 명사 opening(개장)이 정답이다. open은 동사·형용사, opened와 opens는 동사 형태라 주어 자리에 올 수 없다.","translation":"새 매장의 개장일은 다음 주 월요일이다.","part":5},{"id":"p5-004","level":1,"type":"품사","question":"Our staff will ------- your order by Friday.","choices":["delivered","deliver","delivery","delivering"],"answer":1,"explanation":"조동사 will 뒤에는 동사원형이 와야 하므로 deliver가 정답이다. delivery는 명사이고, delivered와 delivering은 will 바로 뒤에 올 수 없는 형태다.","translation":"저희 직원이 금요일까지 주문하신 물건을 배송해 드릴 것입니다.","part":5},{"id":"p5-005","level":1,"type":"품사","question":"The hotel offers ------- rooms at low prices.","choices":["comfort","comfortably","comfortable","comforts"],"answer":2,"explanation":"동사 offers의 목적어인 명사 rooms를 앞에서 꾸미는 자리이므로 형용사 comfortable이 정답이다. comfortably는 부사라 명사를 꾸밀 수 없고, comfort와 comforts는 명사라 의미가 통하지 않는다.","translation":"그 호텔은 편안한 객실을 저렴한 가격에 제공한다.","part":5},{"id":"p5-006","level":1,"type":"품사","question":"Mr. Lee answered the customer's question -------.","choices":["quickness","quickly","quicken","quick"],"answer":1,"explanation":"answered the customer's question은 이미 완전한 문장이므로 빈칸은 동사를 꾸미는 부사 자리다. 따라서 quickly가 정답이고, quick(형용사), quickness(명사), quicken(동사)은 이 자리에 맞지 않는다.","translation":"이 씨는 고객의 질문에 빠르게 답했다.","part":5},{"id":"p5-007","level":1,"type":"품사","question":"We need your ------- before we can begin the project.","choices":["approve","approval","approves","approved"],"answer":1,"explanation":"소유격 your 뒤에는 명사가 와야 하므로 approval(승인)이 정답이다. approve, approved, approves는 모두 동사 형태라 소유격 뒤에 올 수 없다.","translation":"프로젝트를 시작하기 전에 당신의 승인이 필요합니다.","part":5},{"id":"p5-008","level":1,"type":"어휘","question":"Please ------- this form and give it to the receptionist.","choices":["happen","complete","sleep","arrive"],"answer":1,"explanation":"목적어 this form(이 양식)과 어울려 '양식을 작성하다'라는 뜻이 되는 complete가 정답이다. arrive, happen, sleep은 목적어를 바로 받을 수 없는 자동사이고 의미도 맞지 않는다.","translation":"이 양식을 작성해서 접수 담당자에게 주세요.","part":5},{"id":"p5-009","level":1,"type":"어휘","question":"The meeting room is on the second -------.","choices":["door","roof","street","floor"],"answer":3,"explanation":"on the second 뒤에 와서 '2층에'라는 뜻을 만드는 floor가 정답이다. roof(지붕), street(거리), door(문)는 서수 second와 함께 건물 안 위치를 나타내기에 어색하다.","translation":"회의실은 2층에 있다.","part":5},{"id":"p5-010","level":1,"type":"어휘","question":"Our store is ------- from 9 A.M. to 6 P.M. every day.","choices":["open","late","empty","full"],"answer":0,"explanation":"from 9 A.M. to 6 P.M.이라는 영업시간 표현과 어울리는 것은 '문을 연'이라는 뜻의 open이다. empty(비어 있는), late(늦은), full(가득 찬)은 매일 정해진 시간대를 나타내는 문맥에 맞지 않는다.","translation":"저희 매장은 매일 오전 9시부터 오후 6시까지 문을 엽니다.","part":5},{"id":"p5-011","level":1,"type":"어휘","question":"Could you ------- me the price list, please?","choices":["send","talk","listen","say"],"answer":0,"explanation":"'me(간접목적어) + the price list(직접목적어)' 두 개의 목적어를 받아 '~에게 …을 보내다'가 되는 send가 정답이다. say와 talk는 사람을 간접목적어로 바로 받지 않고, listen은 to가 필요하다.","translation":"가격표를 저에게 보내 주시겠어요?","part":5},{"id":"p5-012","level":1,"type":"어휘","question":"The train to Busan leaves from ------- 5.","choices":["seat","platform","driver","ticket"],"answer":1,"explanation":"기차가 출발하는(leaves from) 장소를 나타내므로 '승강장'을 뜻하는 platform이 정답이다. ticket, seat, driver는 기차가 출발하는 장소가 될 수 없다.","translation":"부산행 기차는 5번 승강장에서 출발한다.","part":5},{"id":"p5-013","level":1,"type":"어휘","question":"Please ------- your name on the sign-in sheet at the entrance.","choices":["write","speak","watch","read"],"answer":0,"explanation":"on the sign-in sheet(출입 명부에)라는 표현과 어울려 '이름을 적다'가 되는 write가 정답이다. read, speak, watch는 명부에 이름을 남기는 행동이 아니다.","translation":"입구에 있는 출입 명부에 이름을 적어 주세요.","part":5},{"id":"p5-014","level":1,"type":"어휘","question":"The company picnic was ------- because of the heavy rain.","choices":["hired","bought","canceled","painted"],"answer":2,"explanation":"because of the heavy rain(폭우 때문에)이라는 이유와 자연스럽게 연결되는 것은 '취소된'이라는 뜻의 canceled다. bought(구매된), hired(고용된), painted(칠해진)는 야유회와 어울리지 않는다.","translation":"회사 야유회는 폭우 때문에 취소되었다.","part":5},{"id":"p5-015","level":1,"type":"동사 시제·태","question":"Mr. Park ------- to Tokyo last week.","choices":["went","going","go","goes"],"answer":0,"explanation":"과거 시점을 나타내는 last week가 있으므로 과거형 went가 정답이다. goes는 현재형이고, go는 3인칭 단수 주어와 맞지 않으며, going은 be동사 없이 동사 자리에 올 수 없다.","translation":"박 씨는 지난주에 도쿄에 갔다.","part":5},{"id":"p5-016","level":1,"type":"동사 시제·태","question":"The manager ------- the report tomorrow.","choices":["reviewing","has reviewed","will review","reviewed"],"answer":2,"explanation":"미래 시점 tomorrow가 있으므로 미래 시제 will review가 정답이다. reviewed(과거)와 has reviewed(현재완료)는 tomorrow와 함께 쓸 수 없고, reviewing은 문장의 동사가 될 수 없다.","translation":"관리자가 내일 보고서를 검토할 것이다.","part":5},{"id":"p5-017","level":1,"type":"동사 시제·태","question":"Ms. Chen is ------- a letter to the client right now.","choices":["wrote","writing","write","written"],"answer":1,"explanation":"be동사 is와 right now(지금)가 함께 쓰였으므로 현재진행형을 만드는 writing이 정답이다. written은 is와 함께 수동태가 되지만 뒤에 목적어 a letter가 있어 맞지 않고, write와 wrote는 is 뒤에 올 수 없다.","translation":"첸 씨는 지금 고객에게 편지를 쓰고 있다.","part":5},{"id":"p5-018","level":1,"type":"동사 시제·태","question":"The office ------- every evening by the cleaning staff.","choices":["cleans","cleaning","clean","is cleaned"],"answer":3,"explanation":"사무실은 청소를 '받는' 대상이고 뒤에 by the cleaning staff(청소 직원에 의해)가 있으므로 수동태 is cleaned가 정답이다. cleans는 능동태라 사무실이 청소를 하는 뜻이 되고, cleaning과 clean은 형태상 동사 자리에 맞지 않는다.","translation":"사무실은 매일 저녁 청소 직원들이 청소한다.","part":5},{"id":"p5-019","level":1,"type":"전치사","question":"The meeting will start ------- 10 A.M.","choices":["in","at","to","on"],"answer":1,"explanation":"10 A.M.처럼 구체적인 시각 앞에는 전치사 at을 쓴다. on은 날짜·요일, in은 월·연도·오전/오후 같은 긴 기간 앞에 쓰며, to는 시작 시각을 나타내지 않는다.","translation":"회의는 오전 10시에 시작할 것이다.","part":5},{"id":"p5-020","level":1,"type":"전치사","question":"The conference will be held ------- May.","choices":["of","in","at","on"],"answer":1,"explanation":"May처럼 월 앞에는 전치사 in을 쓴다. at은 시각, on은 날짜·요일 앞에 쓰고, of는 시간을 나타내지 않는다.","translation":"회의는 5월에 열릴 것이다.","part":5},{"id":"p5-021","level":1,"type":"접속사","question":"The shop is small, ------- it sells many kinds of products.","choices":["or","because","so","but"],"answer":3,"explanation":"'가게가 작다'와 '많은 종류의 제품을 판다'는 서로 반대되는 내용이므로 역접 접속사 but이 정답이다. so(그래서)와 because(왜냐하면)는 인과 관계라 의미가 어색하고, or는 선택을 나타낸다.","translation":"그 가게는 작지만 많은 종류의 제품을 판다.","part":5},{"id":"p5-022","level":1,"type":"접속사","question":"Please call me ------- you arrive at the airport.","choices":["when","so","but","what"],"answer":0,"explanation":"'공항에 도착하면 전화해 달라'는 시간 관계이므로 시간 접속사 when이 정답이다. what은 두 절을 이어 주지 못하고, but과 so는 앞 문장과 의미가 연결되지 않는다.","translation":"공항에 도착하면 저에게 전화해 주세요.","part":5},{"id":"p5-023","level":1,"type":"접속사","question":"You can pay by cash ------- credit card.","choices":["but","so","because","or"],"answer":3,"explanation":"현금과 신용카드 중 하나를 고르는 내용이므로 선택을 나타내는 or가 정답이다. but, so, because는 두 결제 수단을 나란히 연결하는 의미가 되지 않는다.","translation":"현금이나 신용카드로 결제하실 수 있습니다.","part":5},{"id":"p5-024","level":1,"type":"관계사","question":"The woman ------- is standing by the door is our new manager.","choices":["who","whose","which","what"],"answer":0,"explanation":"선행사 The woman이 사람이고 빈칸 뒤에 주어 없이 동사 is standing이 오므로 사람 주격 관계대명사 who가 정답이다. which는 사물에 쓰고, what은 선행사를 가질 수 없으며, whose 뒤에는 명사가 와야 한다.","translation":"문 옆에 서 있는 여성이 우리의 새 관리자이다.","part":5},{"id":"p5-025","level":1,"type":"준동사(to부정사·동명사·분사)","question":"We are happy ------- you to our team.","choices":["welcomed","welcome","to welcome","welcomes"],"answer":2,"explanation":"감정 형용사 happy 뒤에서 '~하게 되어 기쁘다'라는 이유를 나타낼 때는 to부정사를 쓰므로 to welcome이 정답이다. welcome, welcomed, welcomes는 형용사 뒤에 바로 이어질 수 없다.","translation":"당신을 우리 팀에 맞이하게 되어 기쁩니다.","part":5},{"id":"p5-026","level":1,"type":"준동사(to부정사·동명사·분사)","question":"Thank you for ------- our store.","choices":["to visit","visit","visited","visiting"],"answer":3,"explanation":"전치사 for 뒤에는 명사나 동명사가 와야 하고, 뒤에 목적어 our store가 있으므로 동명사 visiting이 정답이다. to visit은 전치사 뒤에 올 수 없고, visit과 visited는 동사 형태다.","translation":"저희 매장을 방문해 주셔서 감사합니다.","part":5},{"id":"p5-027","level":1,"type":"대명사","question":"Ms. Jones will send ------- the file today.","choices":["we","ours","us","our"],"answer":2,"explanation":"동사 send 뒤에서 '~에게'를 뜻하는 간접목적어 자리이므로 목적격 us가 정답이다. our는 뒤에 명사가 필요하고, we는 주격, ours는 '우리의 것'이라는 뜻이라 맞지 않는다.","translation":"존스 씨가 오늘 우리에게 파일을 보낼 것이다.","part":5},{"id":"p5-028","level":1,"type":"대명사","question":"Mr. Tanaka left ------- umbrella in the meeting room.","choices":["him","himself","he","his"],"answer":3,"explanation":"명사 umbrella 앞에서 '그의'라는 소유를 나타내야 하므로 소유격 his가 정답이다. him은 목적격, he는 주격, himself는 재귀대명사라 명사 앞에 올 수 없다.","translation":"다나카 씨는 회의실에 자신의 우산을 두고 갔다.","part":5},{"id":"p5-029","level":1,"type":"수 일치","question":"The new printers ------- on the third floor.","choices":["is","be","was","are"],"answer":3,"explanation":"주어 The new printers가 복수이므로 복수 동사 are가 정답이다. is와 was는 단수 주어에 쓰고, be는 주어 바로 뒤 동사 자리에 올 수 없다.","translation":"새 프린터들은 3층에 있다.","part":5},{"id":"p5-030","level":1,"type":"비교","question":"This laptop is ------- than the old one.","choices":["lighter","light","lightest","lightly"],"answer":0,"explanation":"빈칸 뒤에 than이 있으므로 비교급 lighter가 정답이다. light는 원급, lightest는 최상급이라 than과 함께 쓸 수 없고, lightly는 부사라 be동사 뒤 보어 자리에 맞지 않는다.","translation":"이 노트북은 예전 것보다 더 가볍다.","part":5},{"id":"p5-031","level":2,"type":"품사","question":"The seminar on digital marketing was ------- informative.","choices":["extremely","extremes","extremity","extreme"],"answer":0,"explanation":"형용사 informative 앞에서 그 정도를 꾸미는 자리이므로 부사 extremely가 정답이다. extreme은 형용사라 다른 형용사를 꾸밀 수 없고, extremity와 extremes는 명사다.","translation":"디지털 마케팅 세미나는 매우 유익했다.","part":5},{"id":"p5-032","level":2,"type":"품사","question":"The company has received many ------- from customers about the new menu.","choices":["suggested","suggestions","suggest","suggestive"],"answer":1,"explanation":"수량 형용사 many 뒤, 동사 received의 목적어 자리이므로 복수 명사 suggestions가 정답이다. suggest와 suggested는 동사 형태이고, suggestive는 형용사라 목적어가 될 수 없다.","translation":"그 회사는 새 메뉴에 대해 고객들로부터 많은 제안을 받았다.","part":5},{"id":"p5-033","level":2,"type":"품사","question":"Please make sure the documents are ------- before you submit them.","choices":["completely","complete","completes","completion"],"answer":1,"explanation":"be동사 are 뒤에서 주어 the documents의 상태를 설명하는 보어 자리이므로 형용사 complete(완전한, 빠짐없는)가 정답이다. completely는 부사라 보어가 될 수 없고, completion은 명사로 '서류 = 완성'이 되어 어색하며, completes는 동사다.","translation":"제출하기 전에 서류가 빠짐없이 갖춰졌는지 확인해 주세요.","part":5},{"id":"p5-034","level":2,"type":"품사","question":"Mr. Garcia gave a ------- presentation at the conference.","choices":["succeed","successfully","success","successful"],"answer":3,"explanation":"관사 a와 명사 presentation 사이에서 명사를 꾸미는 형용사 자리이므로 successful이 정답이다. successfully는 부사, success는 명사, succeed는 동사라 이 자리에 올 수 없다.","translation":"가르시아 씨는 회의에서 성공적인 발표를 했다.","part":5},{"id":"p5-035","level":2,"type":"품사","question":"The new travel policy will take ------- on July 1.","choices":["effective","effect","effectively","effectiveness"],"answer":1,"explanation":"take effect는 '(법·규정이) 시행되다, 효력이 발생하다'라는 뜻의 관용 표현으로, 동사 take의 목적어 자리에 명사 effect가 온다. effective와 effectively는 목적어가 될 수 없고, effectiveness(효과성)는 take와 이런 의미로 결합하지 않는다.","translation":"새 출장 규정은 7월 1일부터 시행된다.","part":5},{"id":"p5-036","level":2,"type":"품사","question":"Applicants should submit their résumés ------- through our Web site.","choices":["electronic","electronics","electron","electronically"],"answer":3,"explanation":"submit their résumés라는 완전한 구조 뒤에서 동사 submit을 꾸미는 부사 자리이므로 electronically가 정답이다. electronic은 형용사, electronics와 electron은 명사라 동사를 꾸밀 수 없다.","translation":"지원자들은 우리 웹사이트를 통해 이력서를 전자 방식으로 제출해야 한다.","part":5},{"id":"p5-037","level":2,"type":"품사","question":"The ------- of the event thanked all the volunteers for their hard work.","choices":["organize","organized","organizational","organizer"],"answer":3,"explanation":"The 뒤에서 동사 thanked의 주어가 되는 명사 자리이고, 봉사자들에게 감사한 주체는 사람이므로 organizer(주최자)가 정답이다. organize와 organized는 동사, organizational은 형용사라 주어가 될 수 없다.","translation":"행사 주최자는 모든 자원봉사자들의 노고에 감사를 표했다.","part":5},{"id":"p5-038","level":2,"type":"어휘","question":"Please ------- the attached file for more information about the workshop.","choices":["look","see","watch","show"],"answer":1,"explanation":"'첨부 파일을 참조하다'는 see the attached file로 표현한다. look은 at 없이 목적어를 받을 수 없고, watch는 움직이는 것을 지켜볼 때, show는 '보여 주다'라는 뜻이라 맞지 않다.","translation":"워크숍에 대한 자세한 정보는 첨부 파일을 참조해 주세요.","part":5},{"id":"p5-039","level":2,"type":"어휘","question":"The restaurant is so popular that customers must make a ------- in advance.","choices":["destination","direction","reservation","promotion"],"answer":2,"explanation":"식당이 인기가 많아 미리(in advance) 해야 하는 일은 '예약'이므로 make a reservation이 정답이다. destination(목적지), promotion(승진·판촉), direction(방향)은 문맥에 맞지 않는다.","translation":"그 식당은 매우 인기가 많아서 손님들은 미리 예약을 해야 한다.","part":5},{"id":"p5-040","level":2,"type":"어휘","question":"Due to the storm, all flights have been ------- until tomorrow morning.","choices":["delayed","landed","traveled","departed"],"answer":0,"explanation":"폭풍 때문에 비행편이 내일 아침까지(until tomorrow morning) '지연되었다'는 의미가 자연스러우므로 delayed가 정답이다. departed, traveled, landed는 자동사라 수동태로 쓰기 어렵고 의미도 맞지 않는다.","translation":"폭풍으로 인해 모든 항공편이 내일 아침까지 지연되었다.","part":5},{"id":"p5-041","level":2,"type":"어휘","question":"Ms. Rossi was ------- to regional manager last month.","choices":["delivered","promoted","located","advertised"],"answer":1,"explanation":"'to + 직책'과 함께 쓰여 '~로 승진하다'라는 뜻이 되는 be promoted to가 정답이다. advertised(광고된), located(위치한), delivered(배달된)는 사람의 직책 변화와 어울리지 않는다.","translation":"로시 씨는 지난달 지역 관리자로 승진했다.","part":5},{"id":"p5-042","level":2,"type":"어휘","question":"Our customer service team is ------- 24 hours a day.","choices":["careful","useful","available","possible"],"answer":2,"explanation":"24 hours a day(하루 24시간)와 어울려 '응대 가능한, 이용 가능한'을 뜻하는 available이 정답이다. possible은 사람 주어와 쓰지 않고, useful(유용한)과 careful(신중한)은 시간 표현과 의미가 맞지 않는다.","translation":"저희 고객 서비스팀은 하루 24시간 응대 가능합니다.","part":5},{"id":"p5-043","level":2,"type":"어휘","question":"The ------- for the marketing position is May 15.","choices":["deadline","résumé","location","salary"],"answer":0,"explanation":"보어가 May 15라는 날짜이므로 '마감일'을 뜻하는 deadline이 정답이다. location(장소), salary(급여), résumé(이력서)는 날짜와 같다고 할 수 없다.","translation":"마케팅 직책의 지원 마감일은 5월 15일이다.","part":5},{"id":"p5-044","level":2,"type":"어휘","question":"Employees can ------- up to 20 days of paid vacation per year.","choices":["make","do","give","take"],"answer":3,"explanation":"'휴가를 쓰다'는 take a vacation(days off)으로 표현하므로 take가 정답이다. make, do, give는 vacation과 이런 의미로 결합하지 않는다.","translation":"직원들은 1년에 최대 20일의 유급 휴가를 쓸 수 있다.","part":5},{"id":"p5-045","level":2,"type":"동사 시제·태","question":"Since 2015, Hanwell Foods ------- its products to over 20 countries.","choices":["will export","exported","has exported","exports"],"answer":2,"explanation":"Since 2015(2015년 이후로)는 과거부터 현재까지 이어지는 기간을 나타내므로 현재완료 has exported가 정답이다. exported(단순 과거), exports(현재), will export(미래)는 since와 함께 쓰지 않는다.","translation":"2015년 이후로 핸웰 푸드는 20개국 이상에 제품을 수출해 왔다.","part":5},{"id":"p5-046","level":2,"type":"동사 시제·태","question":"The new branch office ------- next month.","choices":["will open","was opening","opened","has opened"],"answer":0,"explanation":"next month라는 미래 시점이 있으므로 미래 시제 will open이 정답이다. opened, has opened, was opening은 모두 과거나 완료를 나타내어 next month와 맞지 않는다.","translation":"새 지점은 다음 달에 문을 열 것이다.","part":5},{"id":"p5-047","level":2,"type":"동사 시제·태","question":"The package ------- to the wrong address yesterday.","choices":["was sent","sends","sent","is sending"],"answer":0,"explanation":"소포는 보내지는 대상이고 뒤에 목적어가 없으므로 수동태가 필요하며, yesterday가 있으므로 과거 수동태 was sent가 정답이다. sent는 능동태로 목적어가 필요하고, sends와 is sending은 현재 시제다.","translation":"그 소포는 어제 잘못된 주소로 발송되었다.","part":5},{"id":"p5-048","level":2,"type":"동사 시제·태","question":"When Ms. Wu arrived at the office, the meeting ------- already begun.","choices":["has","have","had","having"],"answer":2,"explanation":"우 씨가 도착한(arrived) 과거 시점보다 회의 시작이 먼저 일어났으므로 과거완료 had begun이 되어야 한다. has는 현재완료라 과거 시점 기준과 맞지 않고, have는 주어 the meeting과 수가 맞지 않으며, having은 동사 자리에 올 수 없다.","translation":"우 씨가 사무실에 도착했을 때 회의는 이미 시작되어 있었다.","part":5},{"id":"p5-049","level":2,"type":"전치사","question":"The report must be submitted ------- Friday at 5 P.M.","choices":["since","by","until","during"],"answer":1,"explanation":"제출(submit)은 한 번에 끝나는 동작이므로 '~까지(기한)'를 나타내는 by가 정답이다. until은 동작이 그 시점까지 계속될 때 쓰고, during은 기간, since는 '~이후로'를 뜻해 맞지 않는다.","translation":"보고서는 금요일 오후 5시까지 제출되어야 한다.","part":5},{"id":"p5-050","level":2,"type":"전치사","question":"The staff lounge is located ------- the elevator and the copy room.","choices":["between","across","through","among"],"answer":0,"explanation":"'A and B'와 함께 쓰여 두 장소 '사이에'를 나타내는 between이 정답이다. among은 셋 이상 사이에 쓰고, through(~을 통과해)와 across(~을 가로질러)는 A and B 구조와 어울리지 않는다.","translation":"직원 휴게실은 엘리베이터와 복사실 사이에 있다.","part":5},{"id":"p5-051","level":2,"type":"접속사","question":"------- the weather was bad, the outdoor concert was held as planned.","choices":["If","Although","Because","Unless"],"answer":1,"explanation":"'날씨가 나빴다'와 '예정대로 열렸다'는 서로 반대되는 내용이므로 양보 접속사 Although가 정답이다. Because는 이유, If는 조건, Unless는 '~하지 않으면'이라 의미가 맞지 않는다.","translation":"날씨가 나빴지만 야외 콘서트는 예정대로 열렸다.","part":5},{"id":"p5-052","level":2,"type":"접속사","question":"Please turn off the lights ------- you leave the office.","choices":["before","so","despite","during"],"answer":0,"explanation":"빈칸 뒤에 주어와 동사(you leave)가 있는 절이 오므로 접속사가 필요하고, '나가기 전에'라는 의미의 before가 정답이다. during과 despite는 전치사라 절을 이끌 수 없고, so는 '그래서'라는 결과를 나타내 의미가 맞지 않는다.","translation":"사무실을 나가기 전에 전등을 꺼 주세요.","part":5},{"id":"p5-053","level":2,"type":"관계사","question":"The book ------- Ms. Lee recommended is now on sale.","choices":["what","whose","who","that"],"answer":3,"explanation":"선행사 The book이 사물이고 빈칸 뒤 recommended의 목적어가 빠져 있으므로 목적격 관계대명사 that이 정답이다. who는 사람에게 쓰고, what은 선행사를 포함하므로 앞에 명사가 올 수 없으며, whose 뒤에는 명사가 와야 한다.","translation":"이 씨가 추천한 책이 지금 할인 판매 중이다.","part":5},{"id":"p5-054","level":2,"type":"관계사","question":"Customers ------- orders exceed $100 receive free shipping.","choices":["which","whom","whose","who"],"answer":2,"explanation":"빈칸 뒤 orders는 앞의 Customers가 가진 것(고객들의 주문)이므로 소유격 관계대명사 whose가 정답이다. who와 which 뒤에는 주어 또는 목적어가 빠진 절이 와야 하는데 orders exceed $100은 완전한 절이고, whom도 마찬가지로 맞지 않는다.","translation":"주문 금액이 100달러를 넘는 고객은 무료 배송을 받는다.","part":5},{"id":"p5-055","level":2,"type":"준동사(to부정사·동명사·분사)","question":"Mr. Choi decided ------- the job offer from Metro Bank.","choices":["accepted","accept","accepting","to accept"],"answer":3,"explanation":"동사 decide는 목적어로 to부정사를 취하므로 to accept가 정답이다. accepting(동명사)은 decide의 목적어로 쓰지 않고, accepted와 accept는 동사 형태라 decided 뒤에 바로 올 수 없다.","translation":"최 씨는 메트로 은행의 일자리 제안을 받아들이기로 결정했다.","part":5},{"id":"p5-056","level":2,"type":"준동사(to부정사·동명사·분사)","question":"Please return the ------- contract to the legal department by Friday.","choices":["signed","signing","sign","signs"],"answer":0,"explanation":"명사 contract를 꾸미는 자리이며, 계약서는 '서명된' 대상이므로 수동의 의미인 과거분사 signed가 정답이다. signing은 '서명하는'이라는 능동 의미라 계약서와 맞지 않고, sign과 signs는 명사를 꾸미는 형태로 쓰기 어렵다.","translation":"서명된 계약서를 금요일까지 법무팀에 돌려주세요.","part":5},{"id":"p5-057","level":2,"type":"대명사","question":"Ms. Patel prepared the presentation slides -------.","choices":["her","she","herself","hers"],"answer":2,"explanation":"문장이 이미 완전하므로 빈칸은 '직접, 스스로'를 강조하는 재귀대명사 자리이며, 주어가 Ms. Patel이므로 herself가 정답이다. her는 목적어가 이미 있어 올 자리가 없고, she(주격)와 hers(소유대명사)도 맞지 않는다.","translation":"파텔 씨는 발표 슬라이드를 직접 준비했다.","part":5},{"id":"p5-058","level":2,"type":"대명사","question":"Employees should keep ------- desks clean and organized.","choices":["theirs","their","they","them"],"answer":1,"explanation":"명사 desks 앞에서 '그들의'라는 소유를 나타내야 하므로 소유격 their가 정답이다. they는 주격, them은 목적격, theirs는 소유대명사라 명사 앞에 올 수 없다.","translation":"직원들은 자신의 책상을 깨끗하고 정돈된 상태로 유지해야 한다.","part":5},{"id":"p5-059","level":2,"type":"수 일치","question":"Each of the participants ------- a name tag at the registration desk.","choices":["receiving","receive","have received","receives"],"answer":3,"explanation":"'Each of + 복수 명사'가 주어일 때 핵심 주어는 Each이므로 단수 동사 receives가 정답이다. receive와 have received는 복수 주어에 쓰는 형태이고, receiving은 동사 자리에 올 수 없다.","translation":"참가자 각자는 등록 데스크에서 이름표를 받는다.","part":5},{"id":"p5-060","level":2,"type":"비교","question":"Parkview Hotel is the ------- hotel in the downtown area.","choices":["larger","largely","largest","large"],"answer":2,"explanation":"정관사 the와 범위를 나타내는 in the downtown area가 있으므로 최상급 largest가 정답이다. larger는 비교급이라 than이 필요하고, large는 원급, largely는 부사라 명사를 꾸밀 수 없다.","translation":"파크뷰 호텔은 시내에서 가장 큰 호텔이다.","part":5},{"id":"p5-061","level":3,"type":"품사","question":"The marketing team worked ------- to meet the tight deadline.","choices":["diligence","diligently","more diligent","diligent"],"answer":1,"explanation":"자동사 worked 뒤에서 일하는 방식을 꾸미는 부사 자리이므로 diligently가 정답이다. diligent와 more diligent는 형용사라 동사를 꾸밀 수 없고, diligence는 명사다.","translation":"마케팅팀은 촉박한 마감일을 맞추기 위해 부지런히 일했다.","part":5},{"id":"p5-062","level":3,"type":"품사","question":"Sales of the new smartphone have increased ------- since the price reduction.","choices":["significantly","significance","significant","signify"],"answer":0,"explanation":"자동사 have increased 뒤에서 증가의 정도를 나타내는 부사 자리이므로 significantly가 정답이다. significant는 형용사, significance는 명사, signify는 동사라 이 자리에 올 수 없다.","translation":"가격 인하 이후 새 스마트폰의 판매량이 크게 증가했다.","part":5},{"id":"p5-063","level":3,"type":"품사","question":"Mr. Ahmed's ------- to detail makes him an excellent editor.","choices":["attentively","attend","attentive","attention"],"answer":3,"explanation":"소유격 Mr. Ahmed's 뒤, 문장의 주어가 되는 명사 자리이므로 attention이 정답이다(attention to detail: 세부 사항에 대한 주의력). attend는 동사, attentive는 형용사, attentively는 부사라 주어가 될 수 없다.","translation":"세부 사항에 주의를 기울이는 능력 덕분에 아메드 씨는 훌륭한 편집자이다.","part":5},{"id":"p5-064","level":3,"type":"품사","question":"The board members found the revised proposal ------- and approved it.","choices":["acceptable","acceptance","acceptably","accept"],"answer":0,"explanation":"'find + 목적어 + 목적격 보어' 구조에서 목적어 the revised proposal의 상태를 설명하는 형용사 자리이므로 acceptable이 정답이다. acceptably는 부사라 보어가 될 수 없고, acceptance는 '제안 = 수락'이 되어 의미가 맞지 않으며, accept는 동사다.","translation":"이사회 구성원들은 수정된 제안서가 수용할 만하다고 판단하고 승인했다.","part":5},{"id":"p5-065","level":3,"type":"품사","question":"Please direct all ------- about the product recall to our customer service department.","choices":["inquiring","inquired","inquiries","inquire"],"answer":2,"explanation":"all 뒤에서 동사 direct의 목적어가 되는 명사 자리이므로 복수 명사 inquiries가 정답이다. inquire는 동사원형, inquiring과 inquired는 분사 형태라 all 뒤 목적어로 쓸 수 없다.","translation":"제품 회수에 관한 모든 문의는 고객 서비스 부서로 해 주십시오.","part":5},{"id":"p5-066","level":3,"type":"품사","question":"The hotel's conference rooms are ------- equipped with modern audiovisual systems.","choices":["fully","fullness","fuller","full"],"answer":0,"explanation":"수동태 are equipped 사이에서 과거분사 equipped를 꾸미는 부사 자리이므로 fully가 정답이다. full과 fuller는 형용사이고 fullness는 명사라 분사를 수식할 수 없다.","translation":"그 호텔의 회의실은 최신 시청각 장비를 완벽하게 갖추고 있다.","part":5},{"id":"p5-067","level":3,"type":"품사","question":"Tenwick Corporation is a ------- supplier of office furniture in the region.","choices":["rely","reliable","reliance","reliably"],"answer":1,"explanation":"관사 a와 명사 supplier 사이에서 명사를 꾸미는 형용사 자리이므로 reliable이 정답이다. reliably는 부사, reliance는 명사, rely는 동사라 명사를 수식할 수 없다.","translation":"텐윅 사는 이 지역에서 믿을 만한 사무용 가구 공급업체이다.","part":5},{"id":"p5-068","level":3,"type":"어휘","question":"The IT department will ------- the new accounting software next week.","choices":["insist","inform","involve","install"],"answer":3,"explanation":"목적어 the new accounting software와 어울려 '소프트웨어를 설치하다'가 되는 install이 정답이다. inform은 사람을 목적어로 받고, involve(수반하다)는 의미가 맞지 않으며, insist는 on이나 that절이 필요하다.","translation":"IT 부서는 다음 주에 새 회계 소프트웨어를 설치할 것이다.","part":5},{"id":"p5-069","level":3,"type":"어휘","question":"Please keep all receipts so that your travel ------- can be reimbursed.","choices":["expenses","incomes","profits","budgets"],"answer":0,"explanation":"reimburse(환급하다)의 대상은 개인이 지출한 비용이므로 travel expenses(출장 경비)가 정답이다. incomes(수입)와 profits(이익)는 환급 대상이 아니고, budgets(예산)는 배정되는 것이지 환급받는 것이 아니다.","translation":"출장 경비를 환급받을 수 있도록 모든 영수증을 보관해 주세요.","part":5},{"id":"p5-070","level":3,"type":"어휘","question":"Ms. Tran has been ------- for organizing the annual awards ceremony.","choices":["responsible","capable","available","eligible"],"answer":0,"explanation":"전치사 for와 함께 '~을 담당하다, ~에 책임이 있다'라는 뜻을 만드는 responsible이 정답이다. capable은 of와 쓰고, available for(~에 시간이 되는)와 eligible for(~할 자격이 있는)는 행사를 준비해 왔다는 문맥과 맞지 않는다.","translation":"트란 씨는 연례 시상식 준비를 담당해 왔다.","part":5},{"id":"p5-071","level":3,"type":"어휘","question":"The warranty ------- repairs for up to two years after purchase.","choices":["charges","applies","covers","remains"],"answer":2,"explanation":"보증서가 수리를 '보장하다, 포함하다'라는 의미이므로 covers가 정답이다. charges(청구하다)는 보증의 역할과 반대되고, applies는 to가 필요하며, remains는 목적어를 받지 않는다.","translation":"품질 보증은 구매 후 최대 2년 동안 수리를 보장한다.","part":5},{"id":"p5-072","level":3,"type":"어휘","question":"Due to ------- demand, the factory has added a night shift.","choices":["informed","increased","enclosed","qualified"],"answer":1,"explanation":"공장이 야간 근무를 추가한 이유로 '늘어난 수요'가 자연스러우므로 increased가 정답이다. informed(잘 아는), enclosed(동봉된), qualified(자격을 갖춘)는 demand를 꾸미기에 의미가 맞지 않다.","translation":"늘어난 수요 때문에 공장은 야간 근무조를 추가했다.","part":5},{"id":"p5-073","level":3,"type":"어휘","question":"The survey results will be ------- at next Monday's staff meeting.","choices":["agreed","spoken","talked","discussed"],"answer":3,"explanation":"discuss는 타동사라 수동태 be discussed(논의되다)가 가능하므로 정답이다. talk는 about이 필요하고, speak도 results(결과)를 목적어로 받지 않아 수동태로 쓰기 어려우며, agree는 on/to가 필요하고 의미도 맞지 않는다.","translation":"설문 조사 결과는 다음 주 월요일 직원회의에서 논의될 것이다.","part":5},{"id":"p5-074","level":3,"type":"어휘","question":"Guests are asked to ------- from using mobile phones during the performance.","choices":["prevent","refrain","avoid","stop"],"answer":1,"explanation":"refrain from -ing는 '~을 삼가다'라는 뜻으로 전치사 from과 함께 쓰는 자동사다. prevent는 'prevent 목적어 from -ing' 구조가 필요하고, avoid와 stop은 from 없이 바로 동명사를 목적어로 취한다.","translation":"관객들께서는 공연 중 휴대 전화 사용을 삼가 주시기 바랍니다.","part":5},{"id":"p5-075","level":3,"type":"동사 시제·태","question":"By the time the new manager arrives, the staff ------- the office renovation.","choices":["are completing","have completed","will have completed","completed"],"answer":2,"explanation":"By the time + 현재시제(arrives)는 미래의 기준 시점을 나타내며, 그때까지 완료될 일은 미래완료로 표현하므로 will have completed가 정답이다. completed(과거)와 have completed(현재완료)는 미래 기준 시점과 맞지 않고, are completing은 완료를 나타내지 못한다.","translation":"새 관리자가 도착할 때쯤이면 직원들은 사무실 보수 공사를 끝마쳤을 것이다.","part":5},{"id":"p5-076","level":3,"type":"동사 시제·태","question":"The quarterly results ------- to shareholders at the end of this month.","choices":["will announce","have announced","will be announced","announced"],"answer":2,"explanation":"실적은 발표되는 대상이고 뒤에 목적어 없이 to shareholders가 이어지므로 수동태가, at the end of this month가 미래이므로 미래 시제가 필요하다. 따라서 will be announced가 정답이며, will announce와 have announced는 능동태, announced는 과거(또는 능동)라 맞지 않는다.","translation":"분기 실적은 이번 달 말에 주주들에게 발표될 것이다.","part":5},{"id":"p5-077","level":3,"type":"동사 시제·태","question":"Ms. Kwon ------- as a financial consultant for ten years before she joined our firm.","choices":["has worked","works","had worked","will work"],"answer":2,"explanation":"우리 회사에 합류한(joined) 과거 시점보다 이전에 10년간 계속된 일이므로 과거완료 had worked가 정답이다. has worked는 현재까지 이어지는 일에, works와 will work는 현재·미래에 쓰므로 before she joined와 맞지 않는다.","translation":"권 씨는 우리 회사에 합류하기 전에 10년 동안 재무 컨설턴트로 일했다.","part":5},{"id":"p5-078","level":3,"type":"동사 시제·태","question":"Tickets for the concert ------- online starting next Monday.","choices":["purchasing","have purchased","can purchase","can be purchased"],"answer":3,"explanation":"티켓은 구매되는 대상이고 뒤에 목적어가 없으므로 수동태 can be purchased가 정답이다. can purchase와 have purchased는 능동태라 목적어가 필요하고, purchasing은 동사 자리에 올 수 없다.","translation":"콘서트 티켓은 다음 주 월요일부터 온라인으로 구매할 수 있다.","part":5},{"id":"p5-079","level":3,"type":"전치사","question":"------- the renovation, the museum will be closed to visitors.","choices":["Between","During","Although","While"],"answer":1,"explanation":"빈칸 뒤에 명사구 the renovation만 있으므로 전치사가 필요하고, '보수 공사 기간 동안'이라는 의미의 During이 정답이다. While과 Although는 접속사라 주어·동사가 있는 절을 이끌어야 하며, Between은 두 대상이 필요하다.","translation":"보수 공사 기간 동안 박물관은 방문객에게 개방되지 않는다.","part":5},{"id":"p5-080","level":3,"type":"전치사","question":"The shuttle bus runs every 20 minutes ------- the airport and the convention center.","choices":["between","along","among","beside"],"answer":0,"explanation":"'A and B' 두 장소 사이를 오가는 것이므로 between이 정답이다. among은 셋 이상에 쓰고, along(~을 따라)과 beside(~옆에)는 A and B 구조와 결합하지 않는다.","translation":"셔틀버스는 공항과 컨벤션 센터 사이를 20분마다 운행한다.","part":5},{"id":"p5-081","level":3,"type":"접속사","question":"Please notify us at least 48 hours in advance ------- you need to cancel your reservation.","choices":["although","if","unless","so that"],"answer":1,"explanation":"'예약을 취소해야 할 경우 미리 알려 달라'는 조건의 의미이므로 if가 정답이다. unless(~하지 않으면)는 반대 조건이 되고, so that(~하도록)은 목적, although(~이지만)는 양보라 문맥에 맞지 않는다.","translation":"예약을 취소해야 할 경우 최소 48시간 전에 저희에게 알려 주십시오.","part":5},{"id":"p5-082","level":3,"type":"접속사","question":"The seminar was postponed ------- the guest speaker was ill.","choices":["despite","because of","so","because"],"answer":3,"explanation":"빈칸 뒤에 주어와 동사(the guest speaker was ill)가 있는 절이 오고 연기의 이유를 나타내므로 접속사 because가 정답이다. because of와 despite는 전치사라 절을 이끌 수 없고, so는 결과를 나타내어 인과 관계가 뒤바뀐다.","translation":"초청 연사가 아파서 세미나가 연기되었다.","part":5},{"id":"p5-083","level":3,"type":"접속사","question":"------- Mr. Diaz nor his assistant was available to attend the meeting.","choices":["Both","Either","Not only","Neither"],"answer":3,"explanation":"빈칸 뒤의 nor와 짝을 이루는 상관접속사는 neither A nor B이므로 Neither가 정답이다. Either는 or, Both는 and, Not only는 but (also)와 짝을 이룬다.","translation":"디아즈 씨와 그의 비서 모두 회의에 참석할 수 없었다.","part":5},{"id":"p5-084","level":3,"type":"관계사","question":"The candidates ------- were selected for interviews will be contacted by e-mail.","choices":["whose","which","whom","who"],"answer":3,"explanation":"선행사 The candidates가 사람이고 빈칸 뒤에 주어 없이 동사 were selected가 오므로 주격 관계대명사 who가 정답이다. whom은 목적격, whose는 뒤에 명사가 필요하며, which는 사물에 쓴다.","translation":"면접 대상자로 선발된 지원자들에게는 이메일로 연락이 갈 것이다.","part":5},{"id":"p5-085","level":3,"type":"관계사","question":"Rosewood Park, ------- is located near City Hall, will host the festival.","choices":["what","which","where","that"],"answer":1,"explanation":"콤마 뒤 계속적 용법이며 빈칸 뒤에 주어가 없는 불완전한 절(is located)이 오므로 주격 관계대명사 which가 정답이다. where는 완전한 절이 뒤따라야 하고, that은 콤마 뒤 계속적 용법에 쓸 수 없으며, what은 선행사를 가질 수 없다.","translation":"시청 근처에 있는 로즈우드 공원에서 축제가 열릴 것이다.","part":5},{"id":"p5-086","level":3,"type":"준동사(to부정사·동명사·분사)","question":"Employees ------- to attend the workshop must register by Friday.","choices":["wishing","wishes","wished","wish"],"answer":0,"explanation":"문장의 본동사는 must register이므로 빈칸은 Employees를 뒤에서 꾸미는 분사 자리다. 직원들이 '원하는' 능동 관계이므로 현재분사 wishing이 정답이며, wish와 wishes는 동사가 둘이 되어 틀리고, wished는 수동 의미가 된다.","translation":"워크숍에 참석하기를 원하는 직원들은 금요일까지 등록해야 한다.","part":5},{"id":"p5-087","level":3,"type":"준동사(to부정사·동명사·분사)","question":"The goal of the campaign is ------- brand awareness among young consumers.","choices":["to increase","increase","increased","increases"],"answer":0,"explanation":"be동사 is 뒤에서 '목표는 ~하는 것이다'라는 주격 보어가 필요하고, 뒤에 목적어 brand awareness가 있으므로 to부정사 to increase가 정답이다. increase와 increases는 is 뒤에 바로 올 수 없고, increased는 수동태가 되어 목적어와 맞지 않는다.","translation":"캠페인의 목표는 젊은 소비자들 사이에서 브랜드 인지도를 높이는 것이다.","part":5},{"id":"p5-088","level":3,"type":"대명사","question":"The prices at Martin's Grocery are lower than ------- at other stores in the area.","choices":["that","them","those","it"],"answer":2,"explanation":"비교 대상은 앞의 복수 명사 The prices이며, 반복을 피하면서 뒤에 수식어(at other stores)를 받는 대명사는 복수형 those다. that은 단수 명사를 대신하고, them과 it은 뒤에 수식어구를 받아 이런 비교 구문에 쓰지 않는다.","translation":"마틴스 식료품점의 가격은 이 지역 다른 매장들의 가격보다 낮다.","part":5},{"id":"p5-089","level":3,"type":"수 일치","question":"The number of applicants for the position ------- increased this year.","choices":["have","were","has","are"],"answer":2,"explanation":"'The number of + 복수 명사'는 '~의 수'라는 뜻으로 핵심 주어가 단수 number이므로 단수 동사 has가 정답이다. have는 복수 주어에 쓰고, are/were는 뒤의 increased와 수동태가 되어 의미가 맞지 않는다. (a number of는 '많은'이라는 뜻으로 복수 동사를 쓴다.)","translation":"올해 그 직책에 대한 지원자 수가 증가했다.","part":5},{"id":"p5-090","level":3,"type":"비교","question":"The new printer operates ------- than the previous model.","choices":["efficiency","more efficiently","more efficient","most efficiently"],"answer":1,"explanation":"than이 있으므로 비교급이 필요하고, 자동사 operates를 꾸미는 부사 자리이므로 more efficiently가 정답이다. more efficient는 형용사 비교급이라 동사를 꾸밀 수 없고, most efficiently는 최상급, efficiency는 명사다.","translation":"새 프린터는 이전 모델보다 더 효율적으로 작동한다.","part":5},{"id":"p5-091","level":4,"type":"품사","question":"The proposal to extend store hours was ------- received by the board.","choices":["favorite","favorable","favor","favorably"],"answer":3,"explanation":"수동태 was received 사이에서 과거분사 received를 꾸미는 부사 자리이므로 favorably가 정답이다(favorably received: 호의적인 반응을 얻은). favorable과 favorite은 형용사, favor는 명사·동사라 분사를 수식할 수 없다.","translation":"매장 영업시간을 연장하자는 제안은 이사회에서 호의적인 반응을 얻었다.","part":5},{"id":"p5-092","level":4,"type":"품사","question":"Mr. Olsen is ------- qualified for the position, having managed three similar projects.","choices":["exceptional","exception","exceptionally","except"],"answer":2,"explanation":"be동사 is와 형용사 qualified 사이에서 형용사의 정도를 꾸미는 부사 자리이므로 exceptionally가 정답이다. exceptional은 형용사라 다른 형용사를 꾸밀 수 없고, exception은 명사, except는 전치사·접속사다.","translation":"올슨 씨는 비슷한 프로젝트를 세 건 관리한 경험이 있어 그 직책에 매우 적합한 자격을 갖추고 있다.","part":5},{"id":"p5-093","level":4,"type":"품사","question":"The ------- of the two companies is expected to be finalized in March.","choices":["merges","merger","merged","merge"],"answer":1,"explanation":"The 뒤, of 앞에서 동사 is expected의 주어가 되는 명사 자리이므로 merger(합병)가 정답이다. merge와 merges는 동사, merged는 과거·과거분사라 관사 The 뒤 주어 자리에 올 수 없다.","translation":"두 회사의 합병은 3월에 마무리될 것으로 예상된다.","part":5},{"id":"p5-094","level":4,"type":"품사","question":"Please be ------- of other passengers and keep your voice down.","choices":["considerable","considering","consideration","considerate"],"answer":3,"explanation":"be동사 뒤 보어 자리에 형용사가 필요한데, 다른 승객을 '배려하는'이라는 뜻의 considerate가 정답이다. considerable은 '(양·정도가) 상당한'이라는 뜻이라 문맥에 맞지 않고, consideration은 명사, considering은 전치사·분사라 be ~ of 구조에 맞지 않는다.","translation":"다른 승객들을 배려하여 목소리를 낮춰 주십시오.","part":5},{"id":"p5-095","level":4,"type":"품사","question":"The firm has hired an independent ------- to review its financial records.","choices":["audit","auditor","audited","auditing"],"answer":1,"explanation":"형용사 independent의 꾸밈을 받는 명사 자리이면서 동사 hired(고용했다)의 목적어이므로 사람 명사 auditor(감사인)가 정답이다. audit도 명사지만 '감사(행위)'라서 고용의 대상이 될 수 없고, audited와 auditing은 관사 an + 형용사 뒤 명사 자리에 맞지 않는다.","translation":"그 회사는 재무 기록을 검토하기 위해 외부 감사인을 고용했다.","part":5},{"id":"p5-096","level":4,"type":"품사","question":"Sales representatives must respond to client inquiries in a ------- manner.","choices":["time","timing","timely","timelessly"],"answer":2,"explanation":"관사 a와 명사 manner 사이에서 명사를 꾸미는 형용사 자리이므로 timely(시기적절한, 신속한)가 정답이다. timely는 -ly로 끝나지만 형용사라는 점이 함정이다. time과 timing은 명사, timelessly는 부사라 manner를 수식하지 못한다.","translation":"영업 담당자는 고객 문의에 신속하게 응답해야 한다.","part":5},{"id":"p5-097","level":4,"type":"품사","question":"The museum's collection is ------- diverse, featuring artwork from over 40 countries.","choices":["remarked","remark","remarkable","remarkably"],"answer":3,"explanation":"형용사 diverse 앞에서 그 정도를 꾸미는 부사 자리이므로 remarkably가 정답이다. remarkable은 형용사라 다른 형용사를 수식할 수 없고, remark는 명사·동사, remarked는 과거형이라 맞지 않는다.","translation":"그 박물관의 소장품은 40개국 이상의 작품을 선보일 만큼 놀라울 정도로 다양하다.","part":5},{"id":"p5-098","level":4,"type":"어휘","question":"The contract will be ------- automatically unless either party gives written notice.","choices":["revised","resumed","retained","renewed"],"answer":3,"explanation":"unless either party gives written notice(어느 한쪽이 서면 통지를 하지 않는 한)와 어울려 '계약이 자동 갱신된다'는 뜻의 renewed가 정답이다. revised(수정된)는 자동으로 일어나지 않고, resumed(재개된)와 retained(보유된)는 계약 기간 연장과 맞지 않는다.","translation":"어느 한쪽이 서면으로 통지하지 않는 한 계약은 자동으로 갱신된다.","part":5},{"id":"p5-099","level":4,"type":"어휘","question":"To ------- the risk of data loss, back up your files regularly.","choices":["withdraw","omit","minimize","deprive"],"answer":2,"explanation":"the risk(위험)를 목적어로 받아 '위험을 최소화하다'라는 뜻이 되는 minimize가 정답이다. omit(생략하다), deprive(빼앗다, of 필요), withdraw(철회하다·인출하다)는 risk와 자연스럽게 결합하지 않는다.","translation":"데이터 손실 위험을 최소화하려면 파일을 정기적으로 백업하십시오.","part":5},{"id":"p5-100","level":4,"type":"어휘","question":"All expense reports must be ------- by a department head before payment is issued.","choices":["authorized","authored","assured","attributed"],"answer":0,"explanation":"지급 전에 부서장이 경비 보고서를 '승인해야 한다'는 문맥이므로 authorized가 정답이다. authored(저술된), assured(보장된), attributed(~의 탓으로 여겨진)는 결재 절차와 맞지 않는다.","translation":"모든 경비 보고서는 지급 전에 부서장의 승인을 받아야 한다.","part":5},{"id":"p5-101","level":4,"type":"어휘","question":"Because of a ------- in the supply chain, deliveries will be delayed by several days.","choices":["disruption","disclosure","distraction","disposal"],"answer":0,"explanation":"배송 지연의 원인으로 '공급망 차질'이 자연스러우므로 disruption이 정답이다. distraction(주의 산만), disposal(처분), disclosure(공개)는 supply chain과 어울려 지연의 원인이 되지 않는다.","translation":"공급망 차질로 인해 배송이 며칠 지연될 것이다.","part":5},{"id":"p5-102","level":4,"type":"어휘","question":"Mr. Hassan will ------- the sales team while Ms. Ford is on leave.","choices":["overlook","overcome","oversee","overtake"],"answer":2,"explanation":"포드 씨가 휴가 중인 동안 영업팀을 '감독하다, 관리하다'라는 뜻의 oversee가 정답이다. overlook은 '간과하다, 내려다보다'라는 뜻이라 형태가 비슷한 함정이고, overcome(극복하다)과 overtake(추월하다)도 문맥에 맞지 않는다.","translation":"포드 씨가 휴가 중인 동안 하산 씨가 영업팀을 총괄할 것이다.","part":5},{"id":"p5-103","level":4,"type":"어휘","question":"The factory has always ------- to strict safety standards.","choices":["observed","adhered","followed","obeyed"],"answer":1,"explanation":"빈칸 뒤 전치사 to와 함께 '(규칙을) 준수하다'라는 뜻이 되는 자동사는 adhere(adhere to)이다. followed, obeyed, observed도 의미는 비슷하지만 타동사라 to 없이 바로 목적어를 받아야 한다.","translation":"그 공장은 항상 엄격한 안전 기준을 준수해 왔다.","part":5},{"id":"p5-104","level":4,"type":"어휘","question":"Please ------- that all windows are closed before leaving the building.","choices":["inform","remind","ensure","assure"],"answer":2,"explanation":"'that절 내용이 확실히 되도록 하다'라는 뜻으로 that절을 바로 목적어로 받는 ensure가 정답이다. assure, inform, remind는 모두 '사람 목적어 + that절' 구조로 써야 하므로 사람 목적어 없이 that절을 바로 받을 수 없다.","translation":"건물을 떠나기 전에 모든 창문이 닫혀 있는지 반드시 확인해 주세요.","part":5},{"id":"p5-105","level":4,"type":"동사 시제·태","question":"Only after the budget ------- will the construction work begin.","choices":["approving","approves","has been approved","has approved"],"answer":2,"explanation":"Only after 뒤의 절은 시간 부사절이라 미래 대신 현재(완료) 시제를 쓰며, 예산은 승인되는 대상이므로 수동태 has been approved가 정답이다. approves와 has approved는 능동태라 예산이 무언가를 승인하는 뜻이 되고, approving은 동사 자리에 올 수 없다. 주절은 Only after로 인해 도치되었다.","translation":"예산이 승인된 후에야 공사가 시작될 것이다.","part":5},{"id":"p5-106","level":4,"type":"동사 시제·태","question":"The keynote speaker ------- to arrive at 9 A.M., but her flight was delayed.","choices":["is scheduling","scheduled","had scheduled","was scheduled"],"answer":3,"explanation":"연사는 일정이 '잡힌' 대상이므로 'be scheduled to do(~할 예정이다)'의 수동태가 필요하고, 뒤의 was delayed와 시제를 맞춰 과거형 was scheduled가 정답이다. scheduled와 had scheduled는 능동태라 연사가 일정을 잡은 뜻이 되고, is scheduling은 현재진행 능동태다.","translation":"기조연설자는 오전 9시에 도착할 예정이었지만 항공편이 지연되었다.","part":5},{"id":"p5-107","level":4,"type":"동사 시제·태","question":"By the end of this month, Ms. Nakamura ------- the Seoul office for three years.","choices":["manages","will have managed","had managed","has managed"],"answer":1,"explanation":"By the end of this month(이번 달 말이면)라는 미래 기준 시점까지 계속된 기간(for three years)을 나타내므로 미래완료 will have managed가 정답이다. has managed는 현재 기준, had managed는 과거 기준이며, manages는 기간의 완료를 나타내지 못한다.","translation":"이번 달 말이면 나카무라 씨는 서울 사무소를 3년째 관리하게 된다.","part":5},{"id":"p5-108","level":4,"type":"동사 시제·태","question":"Customers ------- that the store will be closed for inventory on Sunday.","choices":["are reminded","reminding","have reminded","remind"],"answer":0,"explanation":"remind는 'remind + 사람 + that절' 구조인데, 빈칸 뒤에 사람 목적어 없이 바로 that절이 오므로 사람이 주어로 나간 수동태 are reminded가 정답이다. remind와 have reminded는 능동태라 사람 목적어가 필요하고, reminding은 동사 자리에 올 수 없다.","translation":"일요일에는 재고 조사로 매장이 문을 닫는다는 점을 고객 여러분께 알려 드립니다.","part":5},{"id":"p5-109","level":4,"type":"전치사","question":"------- the heavy snowfall, all flights departed on time.","choices":["Despite","Although","However","Even"],"answer":0,"explanation":"빈칸 뒤에 명사구 the heavy snowfall만 오고, '폭설에도 불구하고'라는 양보의 의미이므로 전치사 Despite가 정답이다. Although는 접속사라 절이 필요하고, However는 접속부사, Even은 부사라 명사구를 이끌 수 없다.","translation":"폭설에도 불구하고 모든 항공편이 정시에 출발했다.","part":5},{"id":"p5-110","level":4,"type":"전치사","question":"All new staff must complete safety training ------- their first week of employment.","choices":["except","within","despite","besides"],"answer":1,"explanation":"their first week(첫 주)라는 기간과 함께 '~이내에'라는 기한을 나타내는 within이 정답이다. besides(~외에도), despite(~에도 불구하고), except(~을 제외하고)는 기간 표현과 어울려 의미가 통하지 않는다.","translation":"모든 신입 직원은 근무 첫 주 이내에 안전 교육을 이수해야 한다.","part":5},{"id":"p5-111","level":4,"type":"접속사","question":"Visitors must remain in the lobby ------- they are escorted to the laboratory.","choices":["until","during","by","despite"],"answer":0,"explanation":"빈칸 뒤에 주어와 동사(they are escorted)가 있는 절이 오므로 접속사가 필요하고, '안내받을 때까지 로비에 머물러야 한다'는 의미의 until이 정답이다. by, during, despite는 모두 전치사라 절을 이끌 수 없다.","translation":"방문객은 실험실로 안내받을 때까지 로비에 머물러야 한다.","part":5},{"id":"p5-112","level":4,"type":"접속사","question":"Please submit your application by May 5 ------- it can be reviewed before the board meeting.","choices":["because of","such as","so that","in order to"],"answer":2,"explanation":"빈칸 뒤에 절(it can be reviewed)이 오고 '검토될 수 있도록'이라는 목적을 나타내므로 접속사 so that이 정답이다. in order to는 뒤에 동사원형이 와야 하고, because of와 such as는 전치사 역할이라 절을 이끌 수 없다.","translation":"이사회 전에 검토될 수 있도록 5월 5일까지 지원서를 제출해 주십시오.","part":5},{"id":"p5-113","level":4,"type":"관계사","question":"The conference, ------- more than 500 delegates participated, was held in Singapore.","choices":["which","whom","what","in which"],"answer":3,"explanation":"participate는 자동사라 participate in 형태로 쓰므로, 빈칸 뒤 절(more than 500 delegates participated)은 완전한 절이다. 따라서 '전치사 + 관계대명사' in which가 정답이며, which만 쓰면 in이 빠져 틀리고, whom은 사람, what은 선행사를 가질 수 없다.","translation":"500명 이상의 대표단이 참가한 그 회의는 싱가포르에서 열렸다.","part":5},{"id":"p5-114","level":4,"type":"관계사","question":"We will hire ------- is best qualified for the position, regardless of experience.","choices":["whoever","whomever","whose","anyone"],"answer":0,"explanation":"빈칸은 hire의 목적어가 되는 명사절을 이끌면서 동시에 is의 주어 역할을 해야 하므로 복합관계대명사 주격 whoever(~하는 사람은 누구든)가 정답이다. whomever는 목적격이라 주어 역할을 못 하고, whose는 뒤에 명사가 필요하며, anyone은 관계사 없이 is를 연결할 수 없다.","translation":"경력과 관계없이 그 직책에 가장 적합한 사람이라면 누구든 채용할 것이다.","part":5},{"id":"p5-115","level":4,"type":"준동사(to부정사·동명사·분사)","question":"------- the budget report, Ms. Choi noticed several errors.","choices":["Reviewing","To be reviewed","Review","Reviewed"],"answer":0,"explanation":"주절의 주어 Ms. Choi가 보고서를 '검토하는' 능동 관계이고 뒤에 목적어 the budget report가 있으므로 현재분사로 시작하는 분사구문 Reviewing이 정답이다. Reviewed와 To be reviewed는 수동 의미라 목적어를 받을 수 없고, Review는 동사원형이라 명령문처럼 되어 문장이 성립하지 않는다.","translation":"예산 보고서를 검토하던 중 최 씨는 몇 가지 오류를 발견했다.","part":5},{"id":"p5-116","level":4,"type":"준동사(to부정사·동명사·분사)","question":"The documents ------- at the meeting are available on the shared drive.","choices":["were discussed","discusses","discussing","discussed"],"answer":3,"explanation":"본동사가 are이므로 빈칸은 The documents를 뒤에서 꾸미는 분사 자리이며, 문서는 '논의된' 대상이므로 과거분사 discussed가 정답이다. discussing은 능동 의미라 목적어가 필요하고, discusses와 were discussed는 동사라 문장에 동사가 둘이 된다.","translation":"회의에서 논의된 문서들은 공유 드라이브에서 볼 수 있다.","part":5},{"id":"p5-117","level":4,"type":"준동사(to부정사·동명사·분사)","question":"The company is committed to ------- the highest level of customer service.","choices":["provide","providing","provided","be provided"],"answer":1,"explanation":"be committed to의 to는 전치사이므로 뒤에 명사나 동명사가 와야 한다. 따라서 목적어 the highest level을 받는 동명사 providing이 정답이며, to부정사로 착각하게 하는 provide와 be provided, 그리고 provided는 맞지 않다.","translation":"그 회사는 최고 수준의 고객 서비스를 제공하는 데 전념하고 있다.","part":5},{"id":"p5-118","level":4,"type":"대명사","question":"Although both proposals had merits, the committee found ------- of them fully convincing.","choices":["either","neither","each","nobody"],"answer":1,"explanation":"두 개(both proposals) 중 '어느 것도 ~아니다'라는 부정은 neither of를 쓴다. each는 '각각 모두 설득력 있다'는 긍정이 되어 Although(양보)의 흐름과 맞지 않고, either는 긍정문에서 '둘 중 어느 하나'라서 '장점이 있었지만'이라는 양보와 맞지 않으며, nobody는 of them과 쓰지 않는다.","translation":"두 제안 모두 장점이 있었지만, 위원회는 어느 쪽도 완전히 설득력 있다고 보지 않았다.","part":5},{"id":"p5-119","level":4,"type":"수 일치","question":"Neither the manager nor the employees ------- aware of the change in schedule.","choices":["was","were","is","has been"],"answer":1,"explanation":"'neither A nor B'가 주어일 때 동사는 B(가까운 쪽)에 수를 맞추므로 복수 명사 the employees에 맞춰 were가 정답이다. was, is, has been은 단수 동사라 맞지 않는다.","translation":"관리자도 직원들도 일정 변경을 알지 못했다.","part":5},{"id":"p5-120","level":4,"type":"비교","question":"The second quarter's profits were ------- higher than expected.","choices":["considerably","more","very","most"],"answer":0,"explanation":"비교급 higher를 강조하는 부사는 much, far, considerably 등이므로 considerably가 정답이다. very는 원급만 꾸밀 수 있고, more와 most는 이미 비교급인 higher 앞에 중복해서 쓸 수 없다.","translation":"2분기 이익은 예상보다 상당히 높았다.","part":5},{"id":"p5-121","level":5,"type":"품사","question":"The new regulations are intended to make the approval process more ------- for small businesses.","choices":["manage","manageably","management","manageable"],"answer":3,"explanation":"'make + 목적어 + 목적격 보어' 구조에서 more의 꾸밈을 받아 목적어 the approval process의 상태를 나타내는 형용사 자리이므로 manageable이 정답이다. manageably는 부사라 보어가 될 수 없고, management는 명사, manage는 동사다.","translation":"새 규정은 소규모 기업들이 승인 절차를 더 수월하게 처리할 수 있도록 하기 위한 것이다.","part":5},{"id":"p5-122","level":5,"type":"품사","question":"Despite rising costs, the company has remained ------- profitable over the past decade.","choices":["consistently","consistent","consistency","consist"],"answer":0,"explanation":"remain의 보어인 형용사 profitable 앞에서 그것을 꾸미는 부사 자리이므로 consistently가 정답이다. consistent를 보어로 착각하기 쉽지만 이미 profitable이 보어이고 형용사는 형용사를 꾸밀 수 없다. consistency는 명사, consist는 동사다.","translation":"비용 상승에도 불구하고 그 회사는 지난 10년간 꾸준히 수익을 내 왔다.","part":5},{"id":"p5-123","level":5,"type":"품사","question":"The committee praised the report for its ------- analysis of market trends.","choices":["comprehend","comprehensively","comprehension","comprehensive"],"answer":3,"explanation":"소유격 its와 명사 analysis 사이에서 명사를 꾸미는 형용사 자리이므로 comprehensive(포괄적인)가 정답이다. comprehension은 명사로 복합명사를 이루지 않고, comprehensively는 부사, comprehend는 동사다.","translation":"위원회는 시장 동향을 포괄적으로 분석했다는 점에서 그 보고서를 칭찬했다.","part":5},{"id":"p5-124","level":5,"type":"품사","question":"Ms. Abara's ------- to sustainability has earned her recognition across the industry.","choices":["commit","committing","commitment","committed"],"answer":2,"explanation":"소유격 Ms. Abara's 뒤에서 단수 동사 has earned의 주어가 되는 명사 자리이므로 commitment가 정답이다(commitment to: ~에 대한 헌신). commit은 동사, committed는 형용사·과거분사이며, committing은 동명사지만 목적어 없이 to와 이어지는 이 구조에서 쓰이지 않는다.","translation":"지속 가능성에 대한 아바라 씨의 헌신은 업계 전반에서 인정을 받았다.","part":5},{"id":"p5-125","level":5,"type":"품사","question":"Employees who wish to work remotely must obtain ------- from their supervisors in advance.","choices":["authorization","authorized","authorize","authoritative"],"answer":0,"explanation":"타동사 obtain의 목적어가 되는 명사 자리이므로 authorization(허가)이 정답이다. authorize는 동사, authoritative(권위 있는)는 형용사이며, authorized는 과거분사로 목적어가 될 수 없다.","translation":"재택근무를 원하는 직원은 사전에 상사의 허가를 받아야 한다.","part":5},{"id":"p5-126","level":5,"type":"품사","question":"Our analysts continually monitor the market to identify ------- profitable investment opportunities.","choices":["potentially","potential","potentials","potentiality"],"answer":0,"explanation":"형용사 profitable 앞에서 그것을 꾸미는 부사 자리이므로 potentially(잠재적으로)가 정답이다. potential은 형용사라 '잠재적인 수익성 있는 기회'처럼 형용사가 겹쳐 어색하고 profitable을 수식하지 못하며, potentials와 potentiality는 명사다.","translation":"우리 분석가들은 잠재적으로 수익성이 있는 투자 기회를 찾기 위해 시장을 지속적으로 관찰한다.","part":5},{"id":"p5-127","level":5,"type":"어휘","question":"The merger is ------- on approval from regulatory authorities.","choices":["exempt","eligible","indicative","contingent"],"answer":3,"explanation":"be contingent on은 '~에 달려 있다, ~을 조건으로 하다'라는 뜻으로 전치사 on과 결합한다. eligible은 for, indicative와 exempt는 of/from과 쓰이므로 on과 어울리지 않으며 의미도 맞지 않는다.","translation":"그 합병은 규제 당국의 승인 여부에 달려 있다.","part":5},{"id":"p5-128","level":5,"type":"어휘","question":"Profits for the third quarter ------- analysts' expectations by a wide margin.","choices":["exceeded","overcame","outgrew","excelled"],"answer":0,"explanation":"'기대치를 넘어서다'는 exceed expectations로 표현하므로 exceeded가 정답이다. overcame(극복했다)과 outgrew(~보다 커져서 맞지 않게 되다)는 expectations와 이런 의미로 결합하지 않고, excel은 주로 자동사(excel in/at)로 쓰인다.","translation":"3분기 이익은 분석가들의 예상을 큰 폭으로 웃돌았다.","part":5},{"id":"p5-129","level":5,"type":"어휘","question":"The new CEO has pledged to ------- the company's struggling retail division.","choices":["reimburse","reiterate","reciprocate","revitalize"],"answer":3,"explanation":"struggling(고전하는) 사업부를 목적어로 받아 '활성화하다, 되살리다'라는 뜻이 되는 revitalize가 정답이다. reiterate(되풀이해 말하다), reimburse(환급하다), reciprocate(보답하다)는 사업부를 목적어로 쓰기에 의미가 맞지 않는다.","translation":"신임 CEO는 고전하고 있는 회사의 소매 사업부를 되살리겠다고 약속했다.","part":5},{"id":"p5-130","level":5,"type":"어휘","question":"Please note that prices are ------- to change without prior notice.","choices":["considerate","probable","tentative","subject"],"answer":3,"explanation":"be subject to change는 '변경될 수 있다'는 뜻의 관용 표현이며, 여기서 to는 전치사라 뒤에 명사 change가 온다. tentative(잠정적인), probable(개연성 있는), considerate(배려하는)는 to change와 결합해 이런 의미를 만들지 못한다.","translation":"가격은 사전 통지 없이 변경될 수 있음을 알려 드립니다.","part":5},{"id":"p5-131","level":5,"type":"어휘","question":"Ms. Fontaine's proposal was ------- rejected by the board, with all nine members voting against it.","choices":["respectively","exclusively","unanimously","mutually"],"answer":2,"explanation":"with all nine members voting against it(아홉 명 전원이 반대)이라는 단서에서 '만장일치로'를 뜻하는 unanimously가 정답이다. mutually(상호 간에), respectively(각각), exclusively(오로지)는 투표 결과를 나타내지 않는다.","translation":"퐁텐 씨의 제안은 이사 아홉 명 전원이 반대표를 던져 만장일치로 부결되었다.","part":5},{"id":"p5-132","level":5,"type":"어휘","question":"The software company has been ------- about releasing details of its upcoming product.","choices":["eloquent","reticent","prominent","imminent"],"answer":1,"explanation":"be reticent about은 '~에 대해 말을 아끼다'라는 뜻으로, 신제품 정보 공개에 대한 태도를 나타내기에 알맞다. eloquent(웅변적인)는 about releasing과 어울리지 않고, prominent(저명한)와 imminent(임박한)는 회사의 태도를 설명하지 못한다.","translation":"그 소프트웨어 회사는 곧 출시될 제품의 세부 사항 공개에 대해 말을 아껴 왔다.","part":5},{"id":"p5-133","level":5,"type":"어휘","question":"In ------- of your many years of service, the board would like to present you with this award.","choices":["recognition","response","reference","regard"],"answer":0,"explanation":"in recognition of는 '~을 인정하여, ~의 공로로'라는 뜻의 관용 표현이다. in response는 to와, in reference와 in regard는 to와 결합하여 '~에 관하여'라는 뜻이 되므로 of와 쓰는 이 문장에 맞지 않는다.","translation":"오랜 근속의 공로를 인정하여 이사회는 귀하에게 이 상을 수여하고자 합니다.","part":5},{"id":"p5-134","level":5,"type":"어휘","question":"The construction firm has a ------- track record of delivering projects on time and within budget.","choices":["provisional","proven","probable","prolonged"],"answer":1,"explanation":"a proven track record는 '검증된 실적'이라는 뜻으로 자주 쓰이는 연어다. probable(있을 법한), provisional(임시의), prolonged(장기화된)는 track record와 어울려 이런 의미를 만들지 못한다.","translation":"그 건설 회사는 프로젝트를 기한 내에 예산 범위 안에서 완수해 온 검증된 실적을 보유하고 있다.","part":5},{"id":"p5-135","level":5,"type":"동사 시제·태","question":"Had the shipment arrived on schedule, the store ------- the product line last week.","choices":["had launched","would have launched","will have launched","would launch"],"answer":1,"explanation":"Had the shipment arrived는 If the shipment had arrived에서 if를 생략하고 도치한 가정법 과거완료이므로 주절은 'would have p.p.'가 되어야 한다. would launch는 가정법 과거, had launched와 will have launched는 가정법 주절 형태가 아니다.","translation":"배송품이 예정대로 도착했다면 그 매장은 지난주에 제품군을 출시했을 것이다.","part":5},{"id":"p5-136","level":5,"type":"동사 시제·태","question":"It is essential that every employee ------- the revised safety guidelines.","choices":["will follow","followed","follow","follows"],"answer":2,"explanation":"essential처럼 필요·중요를 나타내는 형용사 뒤 that절에서는 '(should) + 동사원형'을 쓰므로 주어가 단수여도 동사원형 follow가 정답이다. follows는 수 일치만 보고 고르기 쉬운 함정이고, followed와 will follow도 이 구문에 맞지 않는다.","translation":"모든 직원이 개정된 안전 지침을 따르는 것이 필수적이다.","part":5},{"id":"p5-137","level":5,"type":"동사 시제·태","question":"The results of the clinical trial ------- by an independent panel before being published.","choices":["are reviewing","review","are being reviewed","have reviewed"],"answer":2,"explanation":"주어 The results는 검토되는 대상이고 by an independent panel이 행위자를 나타내므로 수동태가 필요하며, 현재 진행 중인 과정을 나타내는 are being reviewed가 정답이다. are reviewing, have reviewed, review는 모두 능동태라 목적어가 필요하다.","translation":"임상 시험 결과는 발표되기 전에 독립 위원회의 검토를 받고 있다.","part":5},{"id":"p5-138","level":5,"type":"동사 시제·태","question":"Should you ------- any difficulties accessing the portal, please contact IT support.","choices":["encountering","encounter","encountered","will encounter"],"answer":1,"explanation":"Should you ~는 If you should ~에서 if를 생략하고 도치한 가정 구문이므로 조동사 should 뒤에 동사원형 encounter가 와야 한다. encountered, encountering, will encounter는 조동사 뒤에 올 수 없다.","translation":"포털 접속에 어려움이 있으시면 IT 지원팀에 연락해 주십시오.","part":5},{"id":"p5-139","level":5,"type":"전치사","question":"The outdoor festival will proceed as planned ------- inclement weather.","choices":["even though","in case","regardless of","owing to"],"answer":2,"explanation":"빈칸 뒤에 명사구 inclement weather(악천후)만 오므로 전치사가 필요하고, '악천후와 관계없이 예정대로 진행한다'는 의미이므로 regardless of가 정답이다. in case와 even though는 접속사라 절이 필요하고, owing to(~ 때문에)는 예정대로 진행한다는 내용과 논리가 맞지 않는다.","translation":"야외 축제는 궂은 날씨와 관계없이 예정대로 진행될 것이다.","part":5},{"id":"p5-140","level":5,"type":"전치사","question":"------- the terms of the agreement, the supplier must provide 30 days' notice before raising prices.","choices":["Over","Under","Onto","Upon"],"answer":1,"explanation":"under the terms of the agreement는 '계약 조건에 따라'라는 뜻의 관용 표현이다. Upon은 '~하자마자·~에 근거하여'의 뜻으로 terms와 이렇게 결합하지 않고, Over와 Onto는 규정·조건의 근거를 나타내지 않는다.","translation":"계약 조건에 따라 공급업체는 가격을 인상하기 30일 전에 통지해야 한다.","part":5},{"id":"p5-141","level":5,"type":"접속사","question":"------- the renovation is completed ahead of schedule, the grand reopening will take place in June.","choices":["Provided that","In case of","Notwithstanding","Whereas"],"answer":0,"explanation":"빈칸 뒤에 절이 오고 '보수 공사가 예정보다 일찍 끝난다면 6월에 재개장한다'는 조건의 의미이므로 Provided that(~라면)이 정답이다. Notwithstanding과 In case of는 명사(구)를 이끄는 전치사로 쓰이고, Whereas(~인 반면)는 대조라 의미가 맞지 않는다.","translation":"보수 공사가 예정보다 일찍 끝난다면 재개장 행사는 6월에 열릴 것이다.","part":5},{"id":"p5-142","level":5,"type":"접속사","question":"The new model is ------- more affordable but also more energy-efficient.","choices":["either","not only","neither","both"],"answer":1,"explanation":"뒤에 나오는 but also와 짝을 이루는 상관접속사는 not only A but also B이므로 not only가 정답이다. either는 or, both는 and, neither는 nor와 짝을 이룬다.","translation":"새 모델은 가격이 더 저렴할 뿐만 아니라 에너지 효율도 더 높다.","part":5},{"id":"p5-143","level":5,"type":"접속사","question":"Mr. Reyes will accept the position ------- the company agrees to cover his relocation expenses.","choices":["on condition that","so as to","as though","in spite of"],"answer":0,"explanation":"빈칸 뒤에 절이 오고 '회사가 이전 비용을 부담하는 조건으로 수락한다'는 의미이므로 on condition that이 정답이다. in spite of는 전치사, so as to는 뒤에 동사원형이 오며, as though(마치 ~처럼)는 의미가 맞지 않는다.","translation":"레예스 씨는 회사가 이전 비용을 부담하는 데 동의한다는 조건으로 그 직책을 수락할 것이다.","part":5},{"id":"p5-144","level":5,"type":"관계사","question":"The board will appoint a committee, the members of ------- will be chosen from each department.","choices":["them","what","which","that"],"answer":2,"explanation":"콤마 뒤에서 앞 절과 뒤 절을 연결해야 하므로 관계사가 필요하고, 선행사 a committee는 사물(조직)이므로 'the members of which'가 정답이다. what은 선행사를 포함한 관계대명사라 선행사 뒤에 쓸 수 없고, them은 접속 기능이 없어 문장이 두 개가 되며, that은 전치사 뒤에 올 수 없다.","translation":"이사회는 위원회를 구성할 것이며, 그 위원들은 각 부서에서 선발될 것이다.","part":5},{"id":"p5-145","level":5,"type":"관계사","question":"Employees may choose ------- training program best suits their career goals.","choices":["wherever","however","whichever","whoever"],"answer":2,"explanation":"빈칸 뒤 명사 training program을 꾸미면서 choose의 목적어가 되는 명사절을 이끌어야 하므로 복합관계형용사 whichever(어느 ~이든)가 정답이다. whoever는 사람을 가리키며 명사를 꾸미지 않고, wherever와 however는 부사절을 이끌어 목적어가 될 수 없다.","translation":"직원들은 자신의 경력 목표에 가장 잘 맞는 교육 프로그램을 어느 것이든 선택할 수 있다.","part":5},{"id":"p5-146","level":5,"type":"준동사(to부정사·동명사·분사)","question":"------- in 1952, Halvorsen Industries is one of the oldest manufacturers in the region.","choices":["Founding","To found","Having founded","Founded"],"answer":3,"explanation":"주절의 주어 Halvorsen Industries는 '설립된' 대상이므로 수동 의미의 과거분사 Founded로 시작하는 분사구문이 정답이다. Founding과 Having founded는 능동이라 회사가 무언가를 설립했다는 뜻이 되고, To found는 목적(설립하기 위해)을 나타내 의미가 맞지 않는다.","translation":"1952년에 설립된 핼보슨 인더스트리는 이 지역에서 가장 오래된 제조업체 중 하나이다.","part":5},{"id":"p5-147","level":5,"type":"준동사(to부정사·동명사·분사)","question":"The CEO is said ------- the proposal before it was presented to the board.","choices":["having reviewed","reviewing","to review","to have reviewed"],"answer":3,"explanation":"be said to do 구문에서, 검토한 시점(이사회 제출 전, 과거)이 말해지는 시점(현재 is)보다 앞서므로 완료부정사 to have reviewed가 정답이다. to review는 같은 시점을 나타내 before 절과 시제가 맞지 않고, reviewing과 having reviewed는 be said 뒤에 올 수 없다.","translation":"CEO는 그 제안서가 이사회에 제출되기 전에 검토했다고 한다.","part":5},{"id":"p5-148","level":5,"type":"대명사","question":"Participants are encouraged to bring laptops of ------- own to the workshop.","choices":["their","theirs","them","they"],"answer":0,"explanation":"'of + 소유격 + own'은 '자기 자신의'라는 뜻의 관용 표현이므로 소유격 their가 정답이다. own 앞에는 반드시 소유격이 와야 하므로 목적격 them, 주격 they, 소유대명사 theirs는 올 수 없다.","translation":"참가자들은 워크숍에 각자의 노트북을 가져오도록 권장된다.","part":5},{"id":"p5-149","level":5,"type":"수 일치","question":"Only a fraction of the proposed budget cuts ------- been implemented so far.","choices":["is","have","has","are"],"answer":1,"explanation":"'a fraction of + 명사'처럼 부분을 나타내는 표현은 of 뒤 명사에 수를 맞춘다. of 뒤의 the proposed budget cuts가 복수이므로 have가 정답이며, has는 단수 동사이고, is/are는 뒤의 been과 결합할 수 없다.","translation":"제안된 예산 삭감안 중 지금까지 시행된 것은 일부에 불과하다.","part":5},{"id":"p5-150","level":5,"type":"비교","question":"The more thoroughly you prepare for the negotiation, ------- your chances of success will be.","choices":["better","the better","best","the best"],"answer":1,"explanation":"'The + 비교급 ~, the + 비교급 …'은 '~할수록 더 …하다'라는 구문이므로 앞의 The more thoroughly에 맞춰 the better가 정답이다. better만 쓰면 the가 빠져 구문이 성립하지 않고, the best와 best는 최상급이라 맞지 않는다.","translation":"협상 준비를 철저히 할수록 성공할 가능성은 더 높아질 것이다.","part":5},{"id":"p5-151","level":1,"type":"어휘","question":"Passengers must show their ------- at the gate before boarding.","choices":["recipes","menus","tickets","salaries"],"answer":2,"explanation":"탑승(boarding) 전에 게이트에서 보여 줘야 하는 것은 항공권이므로 tickets가 알맞다. recipes(요리법), menus(메뉴), salaries(급여)는 탑승 게이트 상황과 어울리지 않는다.","translation":"승객들은 탑승 전에 게이트에서 항공권을 보여 주어야 한다.","part":5},{"id":"p5-152","level":1,"type":"어휘","question":"Please ------- the red button to stop the machine.","choices":["borrow","taste","press","wear"],"answer":2,"explanation":"버튼(button)과 짝을 이루는 동사는 '누르다'라는 뜻의 press이다. wear(입다), borrow(빌리다), taste(맛보다)는 기계를 멈추기 위해 버튼에 하는 동작이 아니다.","translation":"기계를 멈추려면 빨간 버튼을 누르세요.","part":5},{"id":"p5-153","level":1,"type":"어휘","question":"The farmers' market sells fresh ------- every Saturday morning.","choices":["vegetables","computers","tickets","furniture"],"answer":0,"explanation":"farmers' market(농산물 직판장)에서 파는 fresh(신선한) 물건은 채소이므로 vegetables가 정답이다. computers, furniture, tickets는 fresh와 어울리지 않고 농산물 시장의 상품도 아니다.","translation":"그 농산물 직판장은 매주 토요일 아침 신선한 채소를 판다.","part":5},{"id":"p5-154","level":1,"type":"어휘","question":"The mechanic will ------- the brakes on your car this afternoon.","choices":["teach","rent","repair","cook"],"answer":2,"explanation":"정비공(mechanic)이 자동차 브레이크에 하는 일은 '수리하다'이므로 repair가 알맞다. cook(요리하다), teach(가르치다), rent(빌리다)는 brakes를 목적어로 자연스럽게 쓸 수 없다.","translation":"정비사가 오늘 오후에 당신 차의 브레이크를 수리할 것이다.","part":5},{"id":"p5-155","level":1,"type":"어휘","question":"Our online store offers free ------- on all orders over $50.","choices":["shipping","sleeping","weather","history"],"answer":0,"explanation":"온라인 상점이 50달러 이상 주문에 무료로 제공하는 것은 배송이므로 free shipping(무료 배송)이 정답이다. weather, history, sleeping은 주문(orders)과 관련된 서비스가 아니다.","translation":"저희 온라인 상점은 50달러가 넘는 모든 주문에 무료 배송을 제공합니다.","part":5},{"id":"p5-156","level":1,"type":"어휘","question":"Guests can ------- out of the hotel until noon.","choices":["turn","look","check","run"],"answer":2,"explanation":"호텔에서 '퇴실하다'는 check out이므로 check가 정답이다. look out(조심하다), turn out(판명되다), run out(다 떨어지다)은 호텔 퇴실 시간과 맞지 않는다.","translation":"투숙객은 정오까지 호텔에서 체크아웃할 수 있다.","part":5},{"id":"p5-157","level":1,"type":"어휘","question":"The bank will be ------- on Sunday for the national holiday.","choices":["tired","short","empty","closed"],"answer":3,"explanation":"국경일(national holiday) 때문에 은행이 '문을 닫는다'는 흐름이므로 closed가 알맞다. empty(비어 있는), tired(피곤한), short(짧은)는 휴일에 은행의 영업 상태를 나타내지 못한다.","translation":"그 은행은 국경일이라 일요일에 문을 닫을 것이다.","part":5},{"id":"p5-158","level":1,"type":"어휘","question":"Ms. Svensson is ------- a new dress for the fashion show.","choices":["designing","sleeping","driving","eating"],"answer":0,"explanation":"패션쇼를 위해 새 드레스를 '디자인하고 있다'가 자연스러우므로 designing이 정답이다. eating, sleeping, driving은 dress를 목적어로 쓸 수 없거나 의미가 맞지 않는다.","translation":"스벤슨 씨는 패션쇼를 위해 새 드레스를 디자인하고 있다.","part":5},{"id":"p5-159","level":1,"type":"어휘","question":"Students must ------- the class fee before the course begins.","choices":["cost","pay","earn","spend"],"answer":1,"explanation":"fee(수강료)는 '내다'라는 뜻의 pay와 짝을 이룬다. spend는 spend money on처럼 쓰고, cost는 사물이 주어로 와서 '비용이 들다'라는 뜻이며, earn(벌다)은 의미가 반대다.","translation":"학생들은 강좌가 시작되기 전에 수강료를 내야 한다.","part":5},{"id":"p5-160","level":1,"type":"어휘","question":"The newspaper ------- a story about the new city library yesterday.","choices":["cooked","hired","washed","published"],"answer":3,"explanation":"신문이 기사(story)를 '실었다, 게재했다'는 뜻이므로 published가 알맞다. hired(고용했다), cooked(요리했다), washed(씻었다)는 기사와 어울리지 않는다.","translation":"그 신문은 어제 새 시립 도서관에 관한 기사를 실었다.","part":5},{"id":"p5-161","level":1,"type":"품사","question":"------- to the science museum is free for children under 12.","choices":["Admissible","Admission","Admitted","Admit"],"answer":1,"explanation":"문장의 주어 자리이고 뒤에 동사 is가 있으므로 명사 Admission(입장)이 와야 한다. Admit은 동사원형, Admitted는 과거분사, Admissible은 형용사라 주어가 될 수 없다.","translation":"12세 미만 어린이는 과학관 입장이 무료이다.","part":5},{"id":"p5-162","level":1,"type":"품사","question":"The nurse spoke ------- to the young patient.","choices":["gentler","gently","gentleness","gentle"],"answer":1,"explanation":"자동사 spoke를 꾸며 주는 자리이므로 부사 gently가 알맞다. gentle과 gentler는 형용사, gentleness는 명사라서 동사를 수식할 수 없다.","translation":"간호사는 어린 환자에게 부드럽게 말했다.","part":5},{"id":"p5-163","level":1,"type":"품사","question":"The new delivery trucks are very -------.","choices":["quietness","quietly","quiets","quiet"],"answer":3,"explanation":"be동사 are 뒤 very의 꾸밈을 받는 보어 자리이므로 형용사 quiet이 정답이다. quietly는 부사, quietness는 명사, quiets는 동사 형태라 보어로 알맞지 않다.","translation":"새 배송 트럭들은 매우 조용하다.","part":5},{"id":"p5-164","level":1,"type":"품사","question":"Please make a ------- before the end of the month.","choices":["payment","pay","paid","payable"],"answer":0,"explanation":"관사 a 뒤, make의 목적어 자리이므로 명사 payment가 와야 한다. make a payment(지불하다)는 자주 쓰는 표현이다. pay는 동사로 주로 쓰이고, paid와 payable은 형용사 성격이라 관사 뒤 단독으로 쓸 수 없다.","translation":"월말 전에 납부해 주세요.","part":5},{"id":"p5-165","level":1,"type":"품사","question":"Customers were ------- with the fast service at the new café.","choices":["please","pleased","pleasure","pleasing"],"answer":1,"explanation":"고객이 '기뻐한' 것이므로 감정을 느끼는 사람 주어에는 과거분사형 형용사 pleased가 온다(be pleased with). pleasing은 '기쁘게 하는'이라는 뜻이라 사물 주어에 쓰고, please는 동사, pleasure는 명사다.","translation":"고객들은 새 카페의 빠른 서비스에 만족했다.","part":5},{"id":"p5-166","level":1,"type":"품사","question":"The factory ------- produces 500 bicycles a day.","choices":["used","usually","usual","use"],"answer":1,"explanation":"주어와 동사 produces 사이에서 동사를 꾸미는 자리이므로 빈도부사 usually가 알맞다. usual은 형용사, use는 동사·명사, used는 과거분사라 이 자리에 올 수 없다.","translation":"그 공장은 보통 하루에 자전거 500대를 생산한다.","part":5},{"id":"p5-167","level":1,"type":"품사","question":"Our new banking app is easy to -------.","choices":["usefully","usage","use","useful"],"answer":2,"explanation":"to부정사의 to 뒤에는 동사원형이 오므로 use가 정답이다. useful은 형용사, usefully는 부사, usage는 명사라 to 뒤에 올 수 없다.","translation":"저희 새 은행 앱은 사용하기 쉽습니다.","part":5},{"id":"p5-168","level":1,"type":"품사","question":"Chef Moreau prepares every dish with great -------.","choices":["skilled","skill","skillfully","skillful"],"answer":1,"explanation":"전치사 with와 형용사 great 뒤에는 명사가 와야 하므로 skill이 알맞다. skillful과 skilled는 형용사, skillfully는 부사라 형용사 뒤 명사 자리에 올 수 없다.","translation":"모로 셰프는 모든 요리를 뛰어난 솜씨로 준비한다.","part":5},{"id":"p5-169","level":1,"type":"품사","question":"The teacher's explanation of the new exam was very -------.","choices":["clearly","clarity","clarify","clear"],"answer":3,"explanation":"be동사 was 뒤 very가 꾸미는 보어 자리이므로 형용사 clear가 정답이다. clearly는 부사, clarity는 명사, clarify는 동사라 이 자리에 맞지 않는다.","translation":"새 시험에 대한 선생님의 설명은 매우 명확했다.","part":5},{"id":"p5-170","level":1,"type":"동사 시제·태","question":"Mr. Haddad ------- the invoice to the client yesterday.","choices":["emailing","emails","emailed","will email"],"answer":2,"explanation":"과거 시점 부사 yesterday가 있으므로 과거시제 emailed가 알맞다. emails는 현재, will email은 미래라 시제가 맞지 않고, emailing은 동사 역할을 혼자 할 수 없다.","translation":"하다드 씨는 어제 고객에게 청구서를 이메일로 보냈다.","part":5},{"id":"p5-171","level":1,"type":"동사 시제·태","question":"The airline ------- a new route to Hanoi next month.","choices":["will start","has started","started","starting"],"answer":0,"explanation":"미래 시점 부사 next month가 있으므로 미래시제 will start가 정답이다. started와 has started는 이미 일어난 일을 나타내고, starting은 조동사 없이 동사 자리에 올 수 없다.","translation":"그 항공사는 다음 달 하노이행 신규 노선을 시작할 것이다.","part":5},{"id":"p5-172","level":1,"type":"동사 시제·태","question":"The workers ------- a new sign above the store right now.","choices":["are installing","have installed","install","installed"],"answer":0,"explanation":"right now(지금)는 진행 중인 동작을 나타내므로 현재진행형 are installing이 알맞다. install은 습관, installed는 과거, have installed는 완료를 나타내 right now와 어울리지 않는다.","translation":"인부들이 지금 가게 위에 새 간판을 설치하고 있다.","part":5},{"id":"p5-173","level":1,"type":"동사 시제·태","question":"Mr. Novak ------- in the accounting department now.","choices":["works","to work","have worked","working"],"answer":0,"explanation":"주어가 3인칭 단수이고 현재(now)의 사실을 말하므로 works가 정답이다. working과 to work는 혼자 동사 역할을 할 수 없고, have worked는 3인칭 단수 주어와 수가 맞지 않는다.","translation":"노박 씨는 지금 회계부에서 일한다.","part":5},{"id":"p5-174","level":1,"type":"동사 시제·태","question":"These leather chairs ------- in Italy.","choices":["made","make","were made","making"],"answer":2,"explanation":"의자는 '만들어진' 대상이므로 수동태 were made가 알맞다. made와 make는 능동이라 의자가 무엇을 만든다는 뜻이 되고, making은 동사 역할을 할 수 없다.","translation":"이 가죽 의자들은 이탈리아에서 만들어졌다.","part":5},{"id":"p5-175","level":1,"type":"접속사","question":"The main printer is broken, ------- please use the one in Room 204.","choices":["because","unless","so","although"],"answer":2,"explanation":"'프린터가 고장 났다, 그래서 204호 것을 써 달라'는 원인과 결과 흐름이므로 so가 알맞다. because는 이유를 뒤에 붙이고, although(비록 ~지만)와 unless(~하지 않으면)는 의미가 맞지 않는다.","translation":"주 프린터가 고장 났으니 204호에 있는 것을 사용해 주세요.","part":5},{"id":"p5-176","level":1,"type":"접속사","question":"Ms. Ito speaks both Japanese ------- Korean.","choices":["and","or","but","so"],"answer":0,"explanation":"both A and B(A와 B 둘 다)는 짝을 이루는 표현이므로 and가 정답이다. or는 either와, but은 not only 등과 짝을 이루고, so는 결과를 나타낸다.","translation":"이토 씨는 일본어와 한국어를 둘 다 한다.","part":5},{"id":"p5-177","level":1,"type":"접속사","question":"We will ship your order ------- we receive your payment.","choices":["and","after","so","but"],"answer":1,"explanation":"'결제를 받은 후에 주문품을 발송한다'는 시간 관계이므로 부사절 접속사 after가 알맞다. but, so, and는 등위접속사라 시간 순서를 나타내지 못하고 의미도 어색하다.","translation":"결제를 받은 후에 주문품을 발송하겠습니다.","part":5},{"id":"p5-178","level":1,"type":"전치사","question":"The weekly sales meeting is ------- Tuesday.","choices":["in","to","on","at"],"answer":2,"explanation":"요일 앞에는 전치사 on을 쓴다. at은 시각, in은 월·연도 같은 긴 기간 앞에 쓰고, to는 방향을 나타내므로 요일과 어울리지 않는다.","translation":"주간 영업 회의는 화요일에 있다.","part":5},{"id":"p5-179","level":1,"type":"전치사","question":"The first-aid workshop will last ------- two hours.","choices":["since","for","on","at"],"answer":1,"explanation":"two hours 같은 기간 앞에서 '~ 동안'을 나타내는 전치사는 for이다. since는 시작 시점 앞에, on은 날짜 앞에, at은 시각 앞에 쓴다.","translation":"응급처치 워크숍은 두 시간 동안 진행될 것이다.","part":5},{"id":"p5-180","level":1,"type":"전치사","question":"This express train goes ------- Seoul to Busan.","choices":["at","on","with","from"],"answer":3,"explanation":"from A to B(A에서 B까지)의 짝 표현이므로 from이 정답이다. at, on, with는 뒤의 to와 짝을 이루어 출발지를 나타내지 못한다.","translation":"이 급행열차는 서울에서 부산까지 간다.","part":5},{"id":"p5-181","level":1,"type":"준동사(to부정사·동명사·분사)","question":"Mr. Chowdhury wants ------- a new laptop for work.","choices":["buying","to buy","buys","bought"],"answer":1,"explanation":"want는 목적어로 to부정사를 취하므로 to buy가 알맞다. buying은 동명사라 want 뒤에 쓰지 않고, bought와 buys는 이미 동사 wants가 있어 올 수 없다.","translation":"차우두리 씨는 업무용 새 노트북을 사고 싶어 한다.","part":5},{"id":"p5-182","level":1,"type":"준동사(to부정사·동명사·분사)","question":"Ms. Park enjoys ------- with customers from other countries.","choices":["to talk","talks","talked","talking"],"answer":3,"explanation":"enjoy는 동명사를 목적어로 취하므로 talking이 정답이다. to talk는 enjoy 뒤에 쓰지 않으며, talked와 talks는 동사 형태라 목적어 자리에 올 수 없다.","translation":"박 씨는 다른 나라에서 온 고객들과 이야기하는 것을 즐긴다.","part":5},{"id":"p5-183","level":1,"type":"준동사(to부정사·동명사·분사)","question":"Construction workers wear helmets ------- their heads.","choices":["protected","to protect","protect","protects"],"answer":1,"explanation":"'머리를 보호하기 위해'라는 목적을 나타내므로 to부정사 to protect가 알맞다. protect와 protects는 이미 동사 wear가 있어 올 수 없고, protected는 '보호된'이라는 수동 의미라 뒤에 목적어를 둘 수 없다.","translation":"건설 노동자들은 머리를 보호하기 위해 안전모를 쓴다.","part":5},{"id":"p5-184","level":1,"type":"관계사","question":"This is the hotel ------- we stayed during the trade fair.","choices":["what","which","where","who"],"answer":2,"explanation":"선행사가 장소(the hotel)이고 뒤 문장(we stayed)이 완전하므로 관계부사 where가 정답이다. which는 뒤 문장에 빠진 성분이 있어야 하고(stayed at이면 가능), who는 사람, what은 선행사 없이 쓴다.","translation":"여기가 무역 박람회 기간에 우리가 묵었던 호텔이다.","part":5},{"id":"p5-185","level":1,"type":"관계사","question":"The package ------- arrived this morning is for Mr. Wong.","choices":["whom","where","who","which"],"answer":3,"explanation":"선행사가 사물(the package)이고 뒤에 주어가 빠져 있으므로 주격 관계대명사 which가 알맞다. who와 whom은 사람에게 쓰고, where는 뒤에 완전한 문장이 와야 한다.","translation":"오늘 아침에 도착한 소포는 웡 씨 앞으로 온 것이다.","part":5},{"id":"p5-186","level":1,"type":"대명사","question":"The shoe company changed ------- logo last year.","choices":["its","it","it's","itself"],"answer":0,"explanation":"명사 logo 앞에서 '그것의'를 뜻하는 소유격이 필요하므로 its가 정답이다. it은 주격·목적격, it's는 it is의 줄임말, itself는 재귀대명사라 명사를 꾸밀 수 없다.","translation":"그 신발 회사는 작년에 로고를 바꿨다.","part":5},{"id":"p5-187","level":1,"type":"대명사","question":"Mr. Silva has two new interns, and he trains ------- every morning.","choices":["theirs","they","their","them"],"answer":3,"explanation":"동사 trains의 목적어 자리이므로 목적격 them이 알맞다. they는 주격, their는 소유격, theirs는 소유대명사라 '그들을 훈련시킨다'는 의미를 만들 수 없다.","translation":"실바 씨에게는 새 인턴이 두 명 있고, 그는 매일 아침 그들을 교육한다.","part":5},{"id":"p5-188","level":1,"type":"수 일치","question":"The price of the concert tickets ------- $20.","choices":["is","being","be","are"],"answer":0,"explanation":"주어의 중심 명사는 단수 The price이고 of the concert tickets는 수식어이므로 단수 동사 is가 알맞다. are는 tickets에 맞춘 오답이고, be와 being은 동사 자리에 단독으로 쓸 수 없다.","translation":"콘서트 티켓 가격은 20달러이다.","part":5},{"id":"p5-189","level":1,"type":"수 일치","question":"Our head chef ------- fresh fish at the market every day.","choices":["buying","buy","to buy","buys"],"answer":3,"explanation":"주어 Our head chef가 3인칭 단수이고 반복되는 습관(every day)이므로 buys가 정답이다. buy는 복수 주어에 쓰며, buying과 to buy는 문장의 동사가 될 수 없다.","translation":"우리 수석 셰프는 매일 시장에서 신선한 생선을 산다.","part":5},{"id":"p5-190","level":1,"type":"비교","question":"Summer is the ------- season for our beach resort.","choices":["busyness","busily","busier","busiest"],"answer":3,"explanation":"the와 명사 season 사이에서 '가장 바쁜'을 나타내는 최상급 형용사 busiest가 알맞다. busyness는 명사라 season을 꾸밀 수 없고, busier는 than과 쓰는 비교급이며, busily는 부사라 명사 season을 꾸밀 수 없다.","translation":"여름은 우리 해변 리조트의 가장 바쁜 시즌이다.","part":5},{"id":"p5-191","level":2,"type":"어휘","question":"Please ------- your seat belt while the airplane is taxiing.","choices":["hang","fasten","button","fold"],"answer":1,"explanation":"seat belt(안전벨트)와 짝을 이루는 동사는 '매다'라는 뜻의 fasten이다. button(단추를 채우다), hang(걸다), fold(접다)는 안전벨트와 어울리지 않는다.","translation":"비행기가 지상 이동하는 동안 안전벨트를 매 주십시오.","part":5},{"id":"p5-192","level":2,"type":"어휘","question":"The Harborview Inn ------- breakfast free of charge to all guests.","choices":["attends","borrows","spends","serves"],"answer":3,"explanation":"호텔이 투숙객에게 아침 식사를 '제공하다'는 serves가 알맞다. spends(쓰다), attends(참석하다), borrows(빌리다)는 breakfast를 손님에게 준다는 의미를 만들지 못한다.","translation":"하버뷰 인은 모든 투숙객에게 아침 식사를 무료로 제공한다.","part":5},{"id":"p5-193","level":2,"type":"어휘","question":"Customers may ------- unused items within 30 days for a full refund.","choices":["remain","return","repeat","reply"],"answer":1,"explanation":"전액 환불(full refund)을 받으려면 물건을 '반품하다'가 자연스러우므로 return이 정답이다. reply는 to가 필요하고, remain은 자동사이며, repeat(반복하다)은 의미가 맞지 않는다.","translation":"고객은 사용하지 않은 물품을 30일 이내에 반품하고 전액 환불받을 수 있다.","part":5},{"id":"p5-194","level":2,"type":"어휘","question":"Take one tablet ------- a day, once in the morning and once at night.","choices":["second","twice","pair","double"],"answer":1,"explanation":"뒤에 '아침에 한 번, 밤에 한 번'이라고 했으므로 '하루 두 번'을 뜻하는 twice가 알맞다. double(두 배의), second(두 번째), pair(한 쌍)는 횟수를 나타내는 부사로 쓰이지 않는다.","translation":"하루 두 번, 아침에 한 번 밤에 한 번 한 알씩 복용하세요.","part":5},{"id":"p5-195","level":2,"type":"어휘","question":"Your antivirus software ------- will expire at the end of the year.","choices":["vacancy","license","appointment","audience"],"answer":1,"explanation":"소프트웨어와 함께 쓰여 '만료되다(expire)'의 주어가 될 수 있는 것은 사용권인 license이다. audience(청중), vacancy(공석), appointment(약속)는 소프트웨어와 어울리지 않는다.","translation":"귀하의 백신 소프트웨어 사용권은 연말에 만료됩니다.","part":5},{"id":"p5-196","level":2,"type":"어휘","question":"Ms. Nkemelu ------- for a small business loan at Fairway Bank.","choices":["requested","submitted","borrowed","applied"],"answer":3,"explanation":"빈칸 뒤 전치사 for와 함께 '~을 신청하다'는 apply for이므로 applied가 정답이다. requested, submitted, borrowed는 타동사라 for 없이 바로 목적어를 취한다.","translation":"은케멜루 씨는 페어웨이 은행에 소상공인 대출을 신청했다.","part":5},{"id":"p5-197","level":2,"type":"어휘","question":"Construction of the Riverside Bridge is ------- to finish in October.","choices":["hoped","wished","expected","waited"],"answer":2,"explanation":"be expected to(~할 것으로 예상되다)는 수동태로 자주 쓰는 표현이므로 expected가 알맞다. hope, wish, wait는 'be p.p. to' 형태의 수동태로 쓰지 않는다.","translation":"리버사이드 다리 공사는 10월에 끝날 것으로 예상된다.","part":5},{"id":"p5-198","level":2,"type":"어휘","question":"Please ------- in your timesheet to the payroll team by Friday.","choices":["break","look","hand","stand"],"answer":2,"explanation":"hand in은 '제출하다'라는 구동사이므로 hand가 정답이다. look in(잠깐 들르다), stand in(대신하다), break in(침입하다)은 근무 시간표를 제출한다는 의미가 되지 않는다.","translation":"금요일까지 근무 시간표를 급여팀에 제출해 주세요.","part":5},{"id":"p5-199","level":2,"type":"어휘","question":"Trend Weekly magazine has more than 50,000 -------.","choices":["patients","passengers","tenants","subscribers"],"answer":3,"explanation":"잡지와 관련해 수를 셀 수 있는 사람은 구독자이므로 subscribers가 알맞다. passengers(승객), patients(환자), tenants(세입자)는 잡지와 어울리지 않는다.","translation":"트렌드 위클리 잡지는 구독자가 5만 명이 넘는다.","part":5},{"id":"p5-200","level":2,"type":"어휘","question":"The city council will ------- a public meeting to discuss the new park.","choices":["do","carry","keep","hold"],"answer":3,"explanation":"meeting과 짝을 이루어 '회의를 열다'는 hold a meeting이므로 hold가 정답이다. do, keep, carry는 meeting과 함께 '개최하다'라는 뜻을 만들지 않는다.","translation":"시의회는 새 공원에 대해 논의하기 위해 공청회를 열 것이다.","part":5},{"id":"p5-201","level":2,"type":"품사","question":"Mr. Laurent works as a ------- for a travel magazine.","choices":["photographic","photograph","photographed","photographer"],"answer":3,"explanation":"'~로서 일하다(work as)' 뒤에는 사람을 나타내는 명사가 와야 하므로 photographer(사진작가)가 알맞다. photograph는 사진이라는 사물 명사라 사람의 직업이 될 수 없고, photographic은 형용사, photographed는 과거분사다.","translation":"로랑 씨는 여행 잡지사에서 사진작가로 일한다.","part":5},{"id":"p5-202","level":2,"type":"품사","question":"The factory's safety rules have been ------- updated.","choices":["recency","recent","recently","more recent"],"answer":2,"explanation":"have been과 과거분사 updated 사이에서 동사를 꾸미는 자리이므로 부사 recently가 정답이다. recent와 more recent는 형용사, recency는 명사라 이 자리에 올 수 없다.","translation":"공장의 안전 규정이 최근에 개정되었다.","part":5},{"id":"p5-203","level":2,"type":"품사","question":"The hotel staff were very ------- to our needs.","choices":["responsive","response","respond","responsively"],"answer":0,"explanation":"be동사 were 뒤 very의 꾸밈을 받는 보어 자리이므로 형용사 responsive(잘 반응하는)가 알맞다. respond는 동사, response는 명사, responsively는 부사다.","translation":"호텔 직원들은 우리의 요구에 매우 신속하게 응대했다.","part":5},{"id":"p5-204","level":2,"type":"품사","question":"Thank you for your ------- in Clearwave Solar's energy products.","choices":["interest","interested","interestingly","interesting"],"answer":0,"explanation":"소유격 your 뒤에는 명사가 와야 하므로 interest(관심)가 정답이다. interested와 interesting은 형용사, interestingly는 부사라 소유격 뒤 단독으로 올 수 없다.","translation":"클리어웨이브 솔라의 에너지 제품에 관심을 가져 주셔서 감사합니다.","part":5},{"id":"p5-205","level":2,"type":"품사","question":"The tour guide explained the history of the castle -------.","choices":["clearness","clarify","clear","clearly"],"answer":3,"explanation":"완전한 문장(주어+동사+목적어) 뒤에서 동사 explained를 꾸미는 부사 clearly가 알맞다. clear는 형용사, clearness는 명사, clarify는 동사라 이 자리에 맞지 않는다.","translation":"관광 가이드는 그 성의 역사를 알기 쉽게 설명했다.","part":5},{"id":"p5-206","level":2,"type":"품사","question":"The results of the customer survey were -------.","choices":["surprisingly","surprise","surprising","surprised"],"answer":2,"explanation":"주어가 사물(results)이고 '놀라게 하는'이라는 뜻이 필요하므로 -ing형 형용사 surprising이 알맞다. surprised는 사람이 놀란 감정을 나타내고, surprise는 명사·동사, surprisingly는 부사라 보어가 될 수 없다.","translation":"고객 설문 조사 결과는 놀라웠다.","part":5},{"id":"p5-207","level":2,"type":"품사","question":"For help with your order, please contact our customer ------- team.","choices":["serve","service","served","serving"],"answer":1,"explanation":"customer service team(고객 서비스팀)은 명사가 명사를 꾸미는 복합명사이므로 service가 정답이다. serve는 동사, served와 serving은 분사라 복합명사를 만들지 못한다.","translation":"주문 관련 도움이 필요하시면 고객 서비스팀에 연락해 주세요.","part":5},{"id":"p5-208","level":2,"type":"품사","question":"Ms. Obi became ------- with the new accounting program after only a week.","choices":["familiar","familiarize","familiarity","familiarly"],"answer":0,"explanation":"become 뒤는 주격 보어 자리이므로 형용사 familiar(익숙한)가 알맞다. be/become familiar with는 자주 쓰는 표현이다. familiarly는 부사, familiarity는 명사, familiarize는 동사다.","translation":"오비 씨는 불과 일주일 만에 새 회계 프로그램에 익숙해졌다.","part":5},{"id":"p5-209","level":2,"type":"품사","question":"Brightfield Farms made a large ------- in new harvesting equipment.","choices":["investor","investment","invested","invest"],"answer":1,"explanation":"관사 a와 형용사 large 뒤 명사 자리이며 '투자를 하다(make an investment)'라는 뜻이 필요하므로 investment가 정답이다. investor도 명사지만 '투자자'라 의미가 맞지 않고, invest는 동사, invested는 분사다.","translation":"브라이트필드 농장은 새 수확 장비에 많은 투자를 했다.","part":5},{"id":"p5-210","level":2,"type":"동사 시제·태","question":"Ms. Andersen ------- in Toronto since 2019.","choices":["has lived","is living","lived","lives"],"answer":0,"explanation":"since 2019(2019년 이후로)는 과거부터 지금까지 이어지는 기간을 나타내므로 현재완료 has lived가 알맞다. lives와 is living은 현재, lived는 과거라 since와 함께 쓰기 어렵다.","translation":"안데르센 씨는 2019년부터 토론토에 살고 있다.","part":5},{"id":"p5-211","level":2,"type":"동사 시제·태","question":"The new lunch menu ------- by our head chef last week.","choices":["was created","created","is creating","creates"],"answer":0,"explanation":"메뉴는 '만들어진' 대상이고 last week가 과거이므로 과거 수동태 was created가 정답이다. created는 능동이라 뒤에 목적어가 필요하고, creates와 is creating은 현재이면서 능동이다.","translation":"새 점심 메뉴는 지난주에 우리 수석 셰프가 만들었다.","part":5},{"id":"p5-212","level":2,"type":"동사 시제·태","question":"At the moment, the IT team ------- the company's network system.","choices":["upgrades","is upgrading","upgraded","has been upgraded"],"answer":1,"explanation":"at the moment(지금)는 진행 중인 일을 나타내므로 현재진행 is upgrading이 알맞다. upgrades는 습관, upgraded는 과거를 나타내고, has been upgraded는 수동태라 뒤에 목적어를 둘 수 없다.","translation":"지금 IT팀이 회사 네트워크 시스템을 업그레이드하고 있다.","part":5},{"id":"p5-213","level":2,"type":"동사 시제·태","question":"If it rains tomorrow, the organizers ------- the concert indoors.","choices":["will move","have moved","moving","moved"],"answer":0,"explanation":"조건절(If it rains tomorrow)은 현재시제로 미래를 나타내고, 주절에는 미래시제가 오므로 will move가 정답이다. moved와 have moved는 과거·완료라 tomorrow와 맞지 않고, moving은 동사가 될 수 없다.","translation":"내일 비가 오면 주최 측은 콘서트를 실내로 옮길 것이다.","part":5},{"id":"p5-214","level":2,"type":"동사 시제·태","question":"All sales staff ------- to attend the product training next Friday.","choices":["requiring","require","are required","have required"],"answer":2,"explanation":"직원들이 참석하도록 '요구받는' 것이므로 be required to(~해야 한다)의 수동태 are required가 알맞다. require와 have required는 능동이라 뒤에 목적어가 필요하고, requiring은 동사 역할을 할 수 없다.","translation":"모든 영업 직원은 다음 주 금요일 제품 교육에 참석해야 한다.","part":5},{"id":"p5-215","level":2,"type":"접속사","question":"Please fill out this medical history form ------- you wait.","choices":["so","while","during","because"],"answer":1,"explanation":"뒤에 절(you wait)이 오고 '기다리는 동안'이라는 뜻이므로 접속사 while이 알맞다. during은 전치사라 절을 이끌 수 없고, because(~ 때문에)와 so(그래서)는 의미가 맞지 않는다.","translation":"기다리시는 동안 이 병력 기록지를 작성해 주세요.","part":5},{"id":"p5-216","level":2,"type":"접속사","question":"Subscribers can choose ------- a monthly plan or a yearly plan.","choices":["either","neither","both","so"],"answer":0,"explanation":"뒤의 or와 짝을 이루는 것은 either A or B(A나 B 중 하나)이므로 either가 정답이다. both는 and, neither는 nor와 짝을 이루고, so는 이런 상관 구조를 만들지 않는다.","translation":"구독자는 월간 요금제나 연간 요금제 중 하나를 선택할 수 있다.","part":5},{"id":"p5-217","level":2,"type":"접속사","question":"Mr. Castillo will call you back ------- he finishes his meeting.","choices":["so that","even though","as soon as","as well as"],"answer":2,"explanation":"'회의가 끝나자마자 전화하겠다'는 시간 관계이므로 as soon as가 알맞다. as well as(~뿐 아니라)는 절을 연결하는 접속사가 아니고, so that(~하도록)과 even though(비록 ~일지라도)는 의미가 맞지 않는다.","translation":"카스티요 씨는 회의가 끝나는 대로 다시 전화드릴 것입니다.","part":5},{"id":"p5-218","level":2,"type":"전치사","question":"The distribution warehouse has been closed ------- last Tuesday.","choices":["ago","from","for","since"],"answer":3,"explanation":"현재완료(has been closed)와 함께 과거 시작 시점(last Tuesday)을 나타내는 전치사는 since이다. for는 기간 앞에, from은 보통 to와 함께 쓰며, ago는 기간 뒤에 오는 부사다.","translation":"물류 창고는 지난 화요일부터 문을 닫은 상태다.","part":5},{"id":"p5-219","level":2,"type":"전치사","question":"Please do not enter the laboratory ------- safety glasses.","choices":["among","beside","without","except"],"answer":2,"explanation":"'보안경 없이 실험실에 들어가지 마라'가 자연스러우므로 without이 정답이다. except(~을 제외하고), beside(~ 옆에), among(~ 사이에)은 의미가 통하지 않는다.","translation":"보안경을 쓰지 않고 실험실에 들어가지 마세요.","part":5},{"id":"p5-220","level":2,"type":"전치사","question":"The Coral Bay Resort is only a five-minute walk ------- the beach.","choices":["of","at","on","from"],"answer":3,"explanation":"'해변에서 걸어서 5분 거리'라는 뜻으로 거리의 기준점을 나타내는 전치사 from이 알맞다. at, on, of는 a five-minute walk와 함께 출발 기준을 나타내지 못한다.","translation":"코랄 베이 리조트는 해변에서 걸어서 5분 거리밖에 되지 않는다.","part":5},{"id":"p5-221","level":2,"type":"준동사(to부정사·동명사·분사)","question":"Mr. Adeyemi is interested in ------- a small bakery downtown.","choices":["starting","to start","start","started"],"answer":0,"explanation":"전치사 in 뒤에는 동명사가 오므로 starting이 알맞다. to start는 전치사 뒤에 쓸 수 없고, start와 started는 동사 형태라 전치사의 목적어가 될 수 없다.","translation":"아데예미 씨는 시내에 작은 빵집을 여는 데 관심이 있다.","part":5},{"id":"p5-222","level":2,"type":"준동사(to부정사·동명사·분사)","question":"The budget report ------- by the finance team contains several errors.","choices":["preparing","prepares","prepared","to prepare"],"answer":2,"explanation":"보고서는 재무팀에 의해 '작성된' 것이므로 명사를 뒤에서 꾸미는 과거분사 prepared가 정답이다. preparing은 능동이라 by와 맞지 않고, prepares는 이미 동사 contains가 있어 올 수 없으며, to prepare는 의미가 어색하다.","translation":"재무팀이 작성한 예산 보고서에 몇 가지 오류가 있다.","part":5},{"id":"p5-223","level":2,"type":"준동사(to부정사·동명사·분사)","question":"It is important ------- your password every three months.","choices":["changing","changed","change","to change"],"answer":3,"explanation":"가주어 It의 진주어 자리이므로 to부정사 to change가 알맞다(It is important to ~). changing은 이 구문에서 진주어로 쓰지 않고, changed와 change는 동사 형태라 올 수 없다.","translation":"비밀번호를 석 달마다 바꾸는 것이 중요하다.","part":5},{"id":"p5-224","level":2,"type":"관계사","question":"The candidate ------- we interviewed on Monday has accepted our offer.","choices":["whose","whom","which","what"],"answer":1,"explanation":"선행사가 사람(The candidate)이고 관계절에서 interviewed의 목적어가 빠져 있으므로 목적격 관계대명사 whom이 알맞다. whose는 뒤에 명사가 와야 하고, which는 사물, what은 선행사가 없을 때 쓴다.","translation":"우리가 월요일에 면접을 본 지원자가 제안을 수락했다.","part":5},{"id":"p5-225","level":2,"type":"관계사","question":"Please tell the catering team ------- you need for the awards dinner.","choices":["what","where","whom","that"],"answer":0,"explanation":"tell의 직접목적어 자리이며 선행사가 없고 need의 목적어가 빠져 있으므로 '~하는 것'을 뜻하는 what이 정답이다. that은 선행사가 필요하거나 완전한 절을 이끌고, whom은 사람, where는 완전한 절과 쓴다.","translation":"시상식 만찬에 필요한 것을 케이터링 팀에 알려 주세요.","part":5},{"id":"p5-226","level":2,"type":"대명사","question":"If you forgot your ID card, you may borrow ------- from the security desk.","choices":["it","ones","one","other"],"answer":2,"explanation":"특정한 그 카드가 아니라 같은 종류의 '하나'를 빌리는 것이므로 부정대명사 one이 알맞다. it은 앞에 나온 바로 그 카드를 가리키게 되어 의미가 어색하고, ones는 복수, other는 단독으로 명사 자리에 쓰지 않는다.","translation":"신분증을 잊고 왔다면 보안 데스크에서 하나 빌릴 수 있습니다.","part":5},{"id":"p5-227","level":2,"type":"대명사","question":"We prepared all the food for the charity fundraiser -------.","choices":["ours","us","our","ourselves"],"answer":3,"explanation":"완전한 문장 뒤에서 '우리가 직접'이라고 주어를 강조하는 재귀대명사 ourselves가 정답이다. our는 소유격이라 명사가 필요하고, us와 ours는 문장 끝에서 강조 역할을 하지 못한다.","translation":"우리는 자선 모금 행사 음식을 모두 직접 준비했다.","part":5},{"id":"p5-228","level":2,"type":"수 일치","question":"One of the new nurses ------- from Brazil.","choices":["comes","come","to come","coming"],"answer":0,"explanation":"One of + 복수명사가 주어일 때 핵심 주어는 One이므로 단수 동사 comes가 알맞다. come은 nurses에 맞춘 오답이고, coming과 to come은 동사가 될 수 없다.","translation":"새로 온 간호사 중 한 명은 브라질 출신이다.","part":5},{"id":"p5-229","level":2,"type":"수 일치","question":"The information on these Web pages ------- updated weekly.","choices":["are","is","were","have"],"answer":1,"explanation":"information은 셀 수 없는 명사로 단수 취급하므로 is가 정답이다. are와 were는 복수 동사이며 Web pages에 맞춘 함정이고, have는 뒤에 been이 없어 수동태가 되지 않는다.","translation":"이 웹페이지의 정보는 매주 업데이트된다.","part":5},{"id":"p5-230","level":2,"type":"비교","question":"Please arrive as ------- as possible for the factory tour.","choices":["earliest","earliness","early","earlier"],"answer":2,"explanation":"as ~ as possible(가능한 한 ~하게) 사이에는 원급이 오므로 early가 알맞다. earlier는 비교급, earliest는 최상급이라 as ~ as 사이에 쓸 수 없고, earliness는 명사다.","translation":"공장 견학에 가능한 한 일찍 도착해 주세요.","part":5},{"id":"p5-231","level":3,"type":"어휘","question":"When it opens next spring, the new wing of St. Clement Hospital will ------- 80 additional beds.","choices":["accommodate","accumulate","accompany","accomplish"],"answer":0,"explanation":"병동이 병상 80개를 '수용하다'라는 뜻이 필요하므로 accommodate가 알맞다. accompany(동행하다), accomplish(성취하다), accumulate(축적하다)는 형태가 비슷하지만 의미가 맞지 않는다.","translation":"내년 봄에 문을 열면 세인트 클레멘트 병원의 새 병동은 병상 80개를 추가로 수용할 것이다.","part":5},{"id":"p5-232","level":3,"type":"어휘","question":"The shipment was held at the border because the customs ------- was incomplete.","choices":["reputation","occupation","declaration","celebration"],"answer":2,"explanation":"세관(customs)과 짝을 이루어 화물이 통관되지 못한 이유가 되는 것은 세관 신고서, 즉 customs declaration이다. reputation(평판), occupation(직업), celebration(축하)은 customs와 어울리지 않는다.","translation":"세관 신고서가 미비해서 그 화물은 국경에서 보류되었다.","part":5},{"id":"p5-233","level":3,"type":"어휘","question":"Please ------- the attached invoice and let us know if you find any errors.","choices":["arrange","examine","reply","apply"],"answer":1,"explanation":"첨부된 청구서에서 오류를 찾으려면 '검토하다'라는 뜻의 examine이 필요하다. apply(적용하다·지원하다), arrange(준비하다·배열하다)는 의미가 어색하고, reply는 자동사라 to가 필요하다.","translation":"첨부된 청구서를 검토하시고 오류가 있으면 알려 주십시오.","part":5},{"id":"p5-234","level":3,"type":"어휘","question":"After her successful product launch, Ms. Kowalski was ------- to lead the design team.","choices":["retired","selected","resigned","rejected"],"answer":1,"explanation":"성공적인 출시 이후 디자인팀을 이끌도록 '선발되었다'는 흐름이므로 selected가 알맞다. retired와 resigned는 '은퇴·사임했다'는 자동사라 수동태로 to lead와 쓰기 어렵고, rejected(거절당한)는 문맥과 반대다.","translation":"성공적인 제품 출시 이후 코발스키 씨는 디자인팀을 이끌 사람으로 선발되었다.","part":5},{"id":"p5-235","level":3,"type":"어휘","question":"The client's order was shipped ------- after the payment was confirmed.","choices":["lately","promptly","hardly","formerly"],"answer":1,"explanation":"결제 확인 '직후 신속히' 발송되었다는 뜻이 되어야 하므로 promptly가 정답이다. hardly(거의 ~않다)는 의미가 어색하고, lately(최근에)와 formerly(이전에)는 after절과 논리가 맞지 않는다.","translation":"고객의 주문품은 결제가 확인된 후 즉시 발송되었다.","part":5},{"id":"p5-236","level":3,"type":"어휘","question":"Greenleaf Farms plans to ------- its operations into three new provinces.","choices":["expire","exhibit","expand","exclude"],"answer":2,"explanation":"사업(operations)을 새 지역으로 '확장하다'는 expand가 알맞다. exhibit(전시하다), expire(만료되다), exclude(제외하다)는 새로운 지역으로 사업을 넓힌다는 의미가 되지 않는다.","translation":"그린리프 농장은 세 개의 새 지방으로 사업을 확장할 계획이다.","part":5},{"id":"p5-237","level":3,"type":"어휘","question":"The law firm of Mendez & Kaur ------- clients in both civil and commercial cases.","choices":["reserves","resolves","resembles","represents"],"answer":3,"explanation":"법률 사무소가 소송에서 고객을 '대리하다'는 represents가 알맞다. resembles(닮다), reserves(예약하다), resolves(해결하다)는 clients를 목적어로 할 때 의미가 맞지 않는다.","translation":"멘데스 앤드 카우르 법률 사무소는 민사 사건과 상사 사건 모두에서 고객을 대리한다.","part":5},{"id":"p5-238","level":3,"type":"어휘","question":"Energy ------- at the plant has dropped by 15 percent since new lighting was installed.","choices":["condition","construction","consumption","competition"],"answer":2,"explanation":"새 조명 설치 후 15퍼센트 줄어든 것은 에너지 '소비량'이므로 energy consumption이 정답이다. construction(건설), competition(경쟁), condition(상태)은 수치가 줄어드는 대상으로 energy와 어울리지 않는다.","translation":"새 조명이 설치된 이후 공장의 에너지 소비량이 15퍼센트 감소했다.","part":5},{"id":"p5-239","level":3,"type":"어휘","question":"Applicants must have at least three years of ------- experience in pharmaceutical sales.","choices":["reluctant","relevant","redundant","reliant"],"answer":1,"explanation":"지원 자격으로 '관련된' 경력을 요구하는 것이므로 relevant가 알맞다. reluctant(꺼리는), redundant(불필요한), reliant(의존하는)는 experience를 꾸미는 조건으로 어울리지 않는다.","translation":"지원자는 제약 영업 분야의 관련 경력이 최소 3년 이상 있어야 한다.","part":5},{"id":"p5-240","level":3,"type":"어휘","question":"Skyward Airlines apologized for the ------- caused by the sudden schedule change.","choices":["insurance","instruction","inconvenience","intention"],"answer":2,"explanation":"갑작스러운 일정 변경이 초래한 것에 대해 사과하므로 '불편'을 뜻하는 inconvenience가 정답이다. intention(의도), instruction(지시), insurance(보험)는 caused by와 사과의 대상으로 맞지 않는다.","translation":"스카이워드 항공은 갑작스러운 일정 변경으로 인한 불편에 대해 사과했다.","part":5},{"id":"p5-241","level":3,"type":"품사","question":"The chemical plant's new filters have ------- reduced harmful emissions.","choices":["dramatic","dramatize","dramatically","drama"],"answer":2,"explanation":"have와 과거분사 reduced 사이에서 동사를 꾸미는 부사 자리이므로 dramatically가 알맞다. dramatic은 형용사, drama는 명사, dramatize는 동사라 이 자리에 올 수 없다.","translation":"화학 공장의 새 필터는 유해 배출물을 극적으로 줄였다.","part":5},{"id":"p5-242","level":3,"type":"품사","question":"The company spokesperson gave a ------- statement to reporters outside the courthouse.","choices":["briefly","briefness","briefs","brief"],"answer":3,"explanation":"관사 a와 명사 statement 사이에서 명사를 꾸미는 형용사 자리이므로 brief(짧은)가 정답이다. briefly는 부사, briefness와 briefs는 명사라 statement를 수식하기에 알맞지 않다.","translation":"회사 대변인은 법원 밖에서 기자들에게 짧은 성명을 발표했다.","part":5},{"id":"p5-243","level":3,"type":"품사","question":"Customers have praised the ------- of Westbrook Bank's new mobile app.","choices":["simplicity","simple","simply","simplify"],"answer":0,"explanation":"관사 the 뒤이며 of의 수식을 받는 praised의 목적어 자리이므로 명사 simplicity가 알맞다. simple은 형용사, simply는 부사, simplify는 동사라 명사 자리에 올 수 없다.","translation":"고객들은 웨스트브룩 은행 새 모바일 앱의 간편함을 칭찬했다.","part":5},{"id":"p5-244","level":3,"type":"품사","question":"The ------- of our passengers is always our top priority.","choices":["safety","saves","safely","safe"],"answer":0,"explanation":"The와 of 사이, 문장의 주어 자리이므로 명사 safety가 정답이다. safe는 형용사(명사로 쓰면 '금고'라 의미가 맞지 않음), safely는 부사, saves는 동사다.","translation":"승객의 안전은 언제나 저희의 최우선 사항입니다.","part":5},{"id":"p5-245","level":3,"type":"품사","question":"The redesigned Web site makes online shopping more ------- for students.","choices":["affordably","afford","affordability","affordable"],"answer":3,"explanation":"make + 목적어 + 목적격 보어 구조에서 보어 자리이므로 형용사 affordable이 알맞다. affordably는 부사라 보어가 될 수 없고, afford는 동사, affordability는 명사라 more와 함께 목적어의 상태를 설명하지 못한다.","translation":"새로 디자인된 웹사이트 덕분에 학생들이 온라인 쇼핑을 더 저렴하게 할 수 있다.","part":5},{"id":"p5-246","level":3,"type":"품사","question":"The ------- customers were offered a full refund and a discount coupon.","choices":["disappointed","disappointment","disappointing","disappoint"],"answer":0,"explanation":"고객들이 '실망한' 감정을 느낀 것이므로 과거분사형 형용사 disappointed가 알맞다. disappointing은 '실망스럽게 하는'이라 고객을 꾸미면 의미가 어색하고, disappoint는 동사, disappointment는 명사다.","translation":"실망한 고객들에게 전액 환불과 할인 쿠폰이 제공되었다.","part":5},{"id":"p5-247","level":3,"type":"품사","question":"The new pricing plan has been ------- popular with small restaurant owners.","choices":["particularly","particular","particularity","particulars"],"answer":0,"explanation":"형용사 popular를 앞에서 꾸미는 부사 자리이므로 particularly가 정답이다. particular는 형용사라 다른 형용사를 꾸밀 수 없고, particularity와 particulars는 명사다.","translation":"새 요금제는 소규모 식당 주인들에게 특히 인기가 있다.","part":5},{"id":"p5-248","level":3,"type":"품사","question":"Please submit your ------- request at least two weeks in advance.","choices":["vacationer","vacationed","vacationing","vacation"],"answer":3,"explanation":"request와 결합해 '휴가 신청'이라는 복합명사를 만드는 vacation이 알맞다. vacationed와 vacationing은 분사라 의미가 어색하고, vacationer는 '휴가객'이라는 사람 명사라 request와 어울리지 않는다.","translation":"휴가 신청서는 적어도 2주 전에 제출해 주세요.","part":5},{"id":"p5-249","level":3,"type":"품사","question":"All warehouse staff received ------- on the new inventory scanners.","choices":["trained","trainer","training","trains"],"answer":2,"explanation":"received의 목적어 자리이며 관사 없이 쓰는 불가산 명사 training(교육)이 정답이다. trainer는 가산명사라 관사가 필요하고 의미도 맞지 않으며, trained는 분사, trains는 동사 또는 '기차'라 어울리지 않는다.","translation":"모든 창고 직원은 새 재고 스캐너에 대한 교육을 받았다.","part":5},{"id":"p5-250","level":3,"type":"동사 시제·태","question":"The shipment ------- at the warehouse when the power went out.","choices":["will unload","unloaded","is unloading","was being unloaded"],"answer":3,"explanation":"정전이 된 과거 시점(when the power went out)에 화물이 '내려지는 중'이었으므로 과거진행 수동태 was being unloaded가 알맞다. unloaded는 능동이라 목적어가 필요하고, is unloading과 will unload는 시제가 맞지 않는다.","translation":"정전이 되었을 때 화물은 창고에서 하역되는 중이었다.","part":5},{"id":"p5-251","level":3,"type":"동사 시제·태","question":"Over the past five years, online bookings at Solana Travel ------- steadily.","choices":["grows","have grown","are grown","will grow"],"answer":1,"explanation":"over the past five years는 과거부터 현재까지의 기간을 나타내므로 현재완료 have grown이 정답이다. will grow는 미래, grows는 단수 동사라 bookings와 맞지 않고, grow는 자동사라 are grown처럼 수동태로 쓰지 않는다.","translation":"지난 5년 동안 솔라나 여행사의 온라인 예약은 꾸준히 증가했다.","part":5},{"id":"p5-252","level":3,"type":"동사 시제·태","question":"Dr. Reinholt ------- the keynote speech at next week's medical conference.","choices":["delivering","will deliver","delivered","has delivered"],"answer":1,"explanation":"next week's conference는 미래의 일이므로 미래시제 will deliver가 알맞다. delivered와 has delivered는 이미 일어난 일을 나타내고, delivering은 동사 역할을 할 수 없다.","translation":"라인홀트 박사는 다음 주 의학 학회에서 기조연설을 할 것이다.","part":5},{"id":"p5-253","level":3,"type":"동사 시제·태","question":"The assembly line's old machines ------- with robotic equipment last year.","choices":["were replaced","have been replaced","replaced","are replacing"],"answer":0,"explanation":"기계가 '교체된' 것이므로 수동태이고, last year라는 과거 시점이 있어 과거 수동태 were replaced가 정답이다. have been replaced는 현재완료라 last year와 함께 쓸 수 없고, replaced와 are replacing은 능동이다.","translation":"조립 라인의 낡은 기계들은 작년에 로봇 장비로 교체되었다.","part":5},{"id":"p5-254","level":3,"type":"동사 시제·태","question":"Ms. Liang ------- the market analysis by the time her manager asked for it.","choices":["will already finish","already finishes","had already finished","has already finished"],"answer":2,"explanation":"관리자가 요청한 과거 시점(asked)보다 먼저 끝낸 일이므로 과거완료 had already finished가 알맞다. has finished는 현재완료, finishes는 현재, will finish는 미래라 과거 기준 시점과 맞지 않는다.","translation":"리앙 씨는 관리자가 요청했을 때 이미 시장 분석을 끝낸 상태였다.","part":5},{"id":"p5-255","level":3,"type":"접속사","question":"------- your loan application is approved, the funds will be transferred within two days.","choices":["Unless","Once","Whereas","Despite"],"answer":1,"explanation":"'일단 승인되면 이틀 안에 송금된다'는 흐름이므로 접속사 Once(일단 ~하면)가 알맞다. Despite는 전치사라 절을 이끌 수 없고, Unless(~하지 않으면)와 Whereas(반면에)는 논리가 맞지 않는다.","translation":"대출 신청이 승인되면 자금은 이틀 안에 송금됩니다.","part":5},{"id":"p5-256","level":3,"type":"접속사","question":"The rooftop pool at the Meridian Hotel is closed ------- repairs are being made.","choices":["during","whether","while","so"],"answer":2,"explanation":"뒤에 절(repairs are being made)이 오고 '수리하는 동안'이라는 뜻이므로 접속사 while이 정답이다. during은 전치사라 절 앞에 쓸 수 없고, whether(~인지)와 so(그래서)는 의미가 맞지 않는다.","translation":"메리디언 호텔의 옥상 수영장은 수리가 진행되는 동안 문을 닫는다.","part":5},{"id":"p5-257","level":3,"type":"접속사","question":"Mr. Delgado asked ------- the replacement parts could be delivered earlier.","choices":["unless","which","what","whether"],"answer":3,"explanation":"asked의 목적어로 '~인지 아닌지'를 묻는 명사절이 필요하고 뒤 절이 완전하므로 whether가 알맞다. what과 which는 뒤에 빠진 성분이 있어야 하고, unless는 부사절 접속사라 목적어절을 이끌 수 없다.","translation":"델가도 씨는 교체 부품을 더 일찍 배송받을 수 있는지 물었다.","part":5},{"id":"p5-258","level":3,"type":"전치사","question":"Please direct any questions about reimbursement ------- Ms. Varga in Accounting.","choices":["to","at","for","on"],"answer":0,"explanation":"direct A to B(A를 B에게 보내다·문의하다)의 구조이므로 to가 정답이다. for, at, on은 direct와 함께 문의 대상을 나타내지 못한다.","translation":"환급 관련 질문은 회계팀 바르가 씨에게 문의해 주세요.","part":5},{"id":"p5-259","level":3,"type":"전치사","question":"All visitors must sign in at the front desk ------- entering the laboratory.","choices":["in spite of","instead of","because of","prior to"],"answer":3,"explanation":"'실험실에 들어가기 전에' 서명해야 한다는 뜻이므로 '~ 전에'를 뜻하는 prior to가 알맞다. because of(~ 때문에), in spite of(~에도 불구하고), instead of(~ 대신에)는 의미가 맞지 않는다.","translation":"모든 방문객은 실험실에 들어가기 전에 안내 데스크에서 서명해야 한다.","part":5},{"id":"p5-260","level":3,"type":"전치사","question":"The two publishers have worked together closely ------- the past decade.","choices":["among","between","beside","throughout"],"answer":3,"explanation":"the past decade라는 기간 '내내'를 나타내는 throughout이 정답이다. among과 between은 대상 사이의 위치·관계를 나타내고, beside(~ 옆에)는 기간과 함께 쓰지 않는다.","translation":"두 출판사는 지난 10년 내내 긴밀히 협력해 왔다.","part":5},{"id":"p5-261","level":3,"type":"준동사(to부정사·동명사·분사)","question":"The consultant recommended ------- the product launch until the spring.","choices":["to postpone","postpone","postponing","postponed"],"answer":2,"explanation":"recommend는 동명사를 목적어로 취하므로 postponing이 알맞다. recommend 뒤에 to부정사를 바로 쓰지 않으며(recommend + 사람 + to부정사는 가능), postpone과 postponed는 목적어 자리에 올 수 없다.","translation":"컨설턴트는 제품 출시를 봄까지 연기할 것을 권했다.","part":5},{"id":"p5-262","level":3,"type":"준동사(to부정사·동명사·분사)","question":"The hotel's free shuttle helps guests ------- the city center in about ten minutes.","choices":["reach","reached","reaches","reaching"],"answer":0,"explanation":"help + 목적어 + (to) 동사원형 구조이므로 동사원형 reach가 정답이다. reaching과 reached는 help의 목적격 보어로 쓰지 않고, reaches는 이미 동사 helps가 있어 올 수 없다.","translation":"호텔의 무료 셔틀은 투숙객이 약 10분 만에 시내 중심가에 갈 수 있도록 돕는다.","part":5},{"id":"p5-263","level":3,"type":"준동사(to부정사·동명사·분사)","question":"Anyone ------- in joining the volunteer program should contact Ms. Hale.","choices":["to interest","interests","interesting","interested"],"answer":3,"explanation":"Anyone을 뒤에서 꾸미며 '관심이 있는' 사람을 뜻하므로 과거분사 interested가 알맞다(be interested in). interesting은 '흥미를 주는'이라 의미가 반대이고, interests는 동사라 should와 충돌하며, to interest는 '관심을 끌기 위해'라는 뜻이 된다.","translation":"자원봉사 프로그램에 참여하는 데 관심이 있는 사람은 누구든지 헤일 씨에게 연락하세요.","part":5},{"id":"p5-264","level":3,"type":"관계사","question":"Ms. Obuya, ------- the board appointed last month, has already introduced several changes.","choices":["whom","which","whose","what"],"answer":0,"explanation":"선행사가 사람(Ms. Obuya)이고 관계절에서 appointed의 목적어가 빠져 있으므로 목적격 whom이 알맞다. which는 사물에 쓰고, whose는 뒤에 명사가 필요하며, what은 선행사를 가질 수 없고 콤마 뒤에 쓰지 않는다.","translation":"지난달 이사회가 임명한 오부야 씨는 이미 여러 변화를 도입했다.","part":5},{"id":"p5-265","level":3,"type":"관계사","question":"The city ------- our new factory is located offers generous tax benefits.","choices":["who","which","where","that"],"answer":2,"explanation":"선행사가 장소(The city)이고 관계절(our new factory is located)이 완전하므로 관계부사 where가 정답이다. which와 that은 뒤에 빠진 성분이 있어야 하고(located in which는 가능), who는 사람에게 쓴다.","translation":"우리 새 공장이 있는 도시는 넉넉한 세금 혜택을 제공한다.","part":5},{"id":"p5-266","level":3,"type":"대명사","question":"If this model is out of stock, we can order ------- one for you from our supplier.","choices":["other","others","the others","another"],"answer":3,"explanation":"단수 명사 one 앞에서 '또 하나의, 다른 하나의'를 뜻하는 another가 알맞다. other는 단수 가산명사 앞에 단독으로 쓰지 않고, others와 the others는 대명사라 뒤에 명사를 둘 수 없다.","translation":"이 모델이 품절이면 공급업체에 다른 제품을 하나 주문해 드릴 수 있습니다.","part":5},{"id":"p5-267","level":3,"type":"대명사","question":"On their first day, interns are asked to introduce ------- to the team.","choices":["their","themselves","them","theirs"],"answer":1,"explanation":"introduce의 목적어가 주어인 interns 자신이므로 재귀대명사 themselves가 정답이다. them은 주어와 다른 사람을 가리키게 되고, their는 소유격, theirs는 소유대명사라 의미가 맞지 않는다.","translation":"첫날 인턴들은 팀원들에게 자기소개를 하도록 요청받는다.","part":5},{"id":"p5-268","level":3,"type":"수 일치","question":"A list of approved suppliers ------- attached to this e-mail.","choices":["being","is","are","have"],"answer":1,"explanation":"주어의 중심 명사는 단수 A list이고 of approved suppliers는 수식어이므로 단수 동사 is가 알맞다. are는 suppliers에 맞춘 함정이고, have는 복수형이며 뒤에 been이 필요하고, being은 동사가 될 수 없다.","translation":"승인된 공급업체 목록이 이 이메일에 첨부되어 있습니다.","part":5},{"id":"p5-269","level":3,"type":"수 일치","question":"The results of the user survey ------- that most people prefer the new design.","choices":["show","showing","has shown","shows"],"answer":0,"explanation":"주어의 중심 명사가 복수 The results이므로 복수 동사 show가 정답이다. shows와 has shown은 단수 주어에 맞는 형태이고(survey에 맞춘 함정), showing은 동사가 될 수 없다.","translation":"사용자 설문 조사 결과는 대부분의 사람들이 새 디자인을 선호한다는 것을 보여 준다.","part":5},{"id":"p5-270","level":3,"type":"비교","question":"This quarter, ------- customers complained about delivery times than last quarter.","choices":["least","fewer","less","little"],"answer":1,"explanation":"뒤에 than이 있어 비교급이 필요하고, customers는 셀 수 있는 복수명사이므로 fewer가 알맞다. less는 셀 수 없는 명사에 쓰고, little은 원급, least는 최상급이다.","translation":"이번 분기에는 지난 분기보다 배송 시간에 대해 불평한 고객이 더 적었다.","part":5},{"id":"p5-271","level":4,"type":"어휘","question":"Ms. Brennan has ------- agreed to speak at the logistics summit, pending approval from her employer.","choices":["tentatively","accurately","densely","equally"],"answer":0,"explanation":"pending approval(승인을 기다리는 중)이라는 조건이 붙어 있으므로 '잠정적으로' 동의했다는 tentatively가 알맞다. accurately(정확하게), densely(빽빽하게), equally(동등하게)는 agreed를 꾸미기에 문맥이 맞지 않는다.","translation":"브레넌 씨는 고용주의 승인을 조건으로 물류 정상 회의에서 연설하기로 잠정 동의했다.","part":5},{"id":"p5-272","level":4,"type":"어휘","question":"Veltrix Pharmaceuticals has received regulatory ------- to sell its allergy drug in Europe.","choices":["closure","compliance","clearance","conclusion"],"answer":2,"explanation":"규제 당국으로부터 판매 '허가'를 받았다는 뜻이므로 regulatory clearance가 정답이다. closure(폐쇄), conclusion(결론)은 의미가 맞지 않고, compliance(준수)는 회사가 지키는 것이지 받는 허가가 아니며 to부정사와도 어울리지 않는다.","translation":"벨트릭스 제약은 유럽에서 알레르기 약을 판매할 수 있는 규제 당국의 허가를 받았다.","part":5},{"id":"p5-273","level":4,"type":"어휘","question":"Due to a scheduling -------, your interview has been moved to Thursday afternoon.","choices":["contest","contrast","conflict","context"],"answer":2,"explanation":"일정이 겹쳐 면접이 옮겨졌다는 뜻이므로 scheduling conflict(일정 충돌)가 알맞다. contrast(대조), contest(대회), context(맥락)는 scheduling과 결합해 일정 변경의 이유를 나타내지 못한다.","translation":"일정이 겹쳐 귀하의 면접이 목요일 오후로 변경되었습니다.","part":5},{"id":"p5-274","level":4,"type":"어휘","question":"Our financial advisors can help you ------- a retirement plan that suits your needs.","choices":["devote","derive","deviate","devise"],"answer":3,"explanation":"필요에 맞는 은퇴 계획을 '고안하다, 세우다'는 devise가 알맞다. deviate(벗어나다)는 자동사이고, devote는 devote A to B로 쓰며, derive(끌어내다)는 plan과 어울리지 않는다.","translation":"저희 재무 상담사들이 고객님의 필요에 맞는 은퇴 계획을 세우도록 도와드릴 수 있습니다.","part":5},{"id":"p5-275","level":4,"type":"어휘","question":"The Aldridge Hotel is ------- located near both the convention center and the subway station.","choices":["mutually","eventually","conveniently","accidentally"],"answer":2,"explanation":"컨벤션 센터와 지하철역 근처에 있다는 것은 '편리하게' 위치했다는 의미이므로 conveniently가 정답이다. conveniently located는 자주 쓰는 짝 표현이다. accidentally(우연히), eventually(결국), mutually(서로)는 located와 어울리지 않는다.","translation":"올드리지 호텔은 컨벤션 센터와 지하철역 모두에 가까운 편리한 곳에 있다.","part":5},{"id":"p5-276","level":4,"type":"어휘","question":"Sales of electric scooters have ------- over the past two years as fuel prices have risen.","choices":["surrendered","surged","surrounded","supervised"],"answer":1,"explanation":"연료비가 오르면서 전동 스쿠터 판매가 '급증했다'가 자연스러우므로 자동사 surged가 알맞다. surrendered(항복했다)는 의미가 맞지 않고, supervised와 surrounded는 타동사라 목적어가 필요하다.","translation":"연료 가격이 오르면서 지난 2년간 전동 스쿠터 판매가 급증했다.","part":5},{"id":"p5-277","level":4,"type":"어휘","question":"The contractor must ------- a detailed cost estimate before any work begins.","choices":["prevail","proceed","pertain","provide"],"answer":3,"explanation":"견적서(estimate)를 '제공하다'라는 타동사가 필요하므로 provide가 정답이다. proceed(진행하다), prevail(우세하다), pertain(관련되다)은 모두 자동사라 목적어를 바로 취할 수 없다.","translation":"시공업체는 작업을 시작하기 전에 상세한 비용 견적서를 제출해야 한다.","part":5},{"id":"p5-278","level":4,"type":"어휘","question":"The marketing director will ------- with the design agency to finalize the holiday campaign.","choices":["commence","collaborate","compile","comprise"],"answer":1,"explanation":"뒤의 with와 함께 '~와 협력하다'를 뜻하는 collaborate가 알맞다. compile(편집하다), commence(시작하다), comprise(구성하다)는 with와 짝을 이루어 협업을 나타내지 못한다.","translation":"마케팅 이사는 연말 캠페인을 마무리하기 위해 디자인 대행사와 협력할 것이다.","part":5},{"id":"p5-279","level":4,"type":"어휘","question":"The Harbor Literacy Project relies ------- on donations from local businesses.","choices":["heavily","narrowly","briefly","sharply"],"answer":0,"explanation":"rely heavily on(~에 크게 의존하다)은 자주 쓰는 짝 표현이므로 heavily가 정답이다. sharply(급격히), narrowly(간신히), briefly(잠시)는 relies on과 어울리지 않는다.","translation":"하버 문해 교육 프로젝트는 지역 기업의 기부금에 크게 의존한다.","part":5},{"id":"p5-280","level":4,"type":"어휘","question":"Maison Leclair plans to ------- its flagship store on the Champs-Élysées next spring.","choices":["recite","reclaim","revoke","renovate"],"answer":3,"explanation":"매장을 '개조하다, 보수하다'라는 뜻의 renovate가 알맞다. reclaim(되찾다), recite(암송하다), revoke(취소하다)는 매장을 목적어로 할 때 문맥에 맞지 않는다.","translation":"메종 르클레르는 내년 봄 샹젤리제 거리의 플래그십 매장을 개조할 계획이다.","part":5},{"id":"p5-281","level":4,"type":"품사","question":"The new CFO has taken several steps to make the company more financially -------.","choices":["stably","stable","stabilize","stability"],"answer":1,"explanation":"make + 목적어 + 목적격 보어 구조이며 부사 financially의 꾸밈을 받으므로 형용사 stable이 알맞다. stably는 부사라 보어가 될 수 없고, stability는 명사라 부사의 수식을 받지 못하며, stabilize는 동사다.","translation":"새 최고재무책임자는 회사를 재정적으로 더 안정되게 만들기 위해 여러 조치를 취했다.","part":5},{"id":"p5-282","level":4,"type":"품사","question":"Ms. Chandra's ------- as a negotiator helped the firm close the acquisition.","choices":["expertly","experts","expert","expertise"],"answer":3,"explanation":"소유격 Ms. Chandra's 뒤 주어 자리이며 '전문성'을 뜻하는 불가산 명사 expertise가 정답이다. expert는 사람을 뜻해 '협상가로서의 전문가'가 되어 의미가 어색하고, experts는 복수라 helped의 의미 주어로 맞지 않으며, expertly는 부사다.","translation":"찬드라 씨의 협상가로서의 전문성은 회사가 인수를 성사시키는 데 도움이 되었다.","part":5},{"id":"p5-283","level":4,"type":"품사","question":"Despite increased competition, our prices have remained ------- throughout the holiday season.","choices":["competitive","competition","compete","competitively"],"answer":0,"explanation":"remain은 보어를 취하는 동사이므로 형용사 competitive(경쟁력 있는)가 알맞다. competitively는 부사라 보어가 될 수 없고, compete는 동사, competition은 명사라 가격의 상태를 설명하지 못한다.","translation":"경쟁이 심해졌음에도 저희 가격은 연말 시즌 내내 경쟁력을 유지했습니다.","part":5},{"id":"p5-284","level":4,"type":"품사","question":"The grant proposal was ------- written, but it lacked supporting data.","choices":["persuasion","persuade","persuasive","persuasively"],"answer":3,"explanation":"be동사 was와 과거분사 written 사이에서 동사를 꾸미는 부사 자리이므로 persuasively가 정답이다. persuasive는 형용사, persuasion은 명사, persuade는 동사라 과거분사를 수식할 수 없다.","translation":"보조금 제안서는 설득력 있게 작성되었지만 근거 자료가 부족했다.","part":5},{"id":"p5-285","level":4,"type":"품사","question":"The ------- of the new shipment-tracking system took nearly three months.","choices":["implementation","implement","implementing","implemented"],"answer":0,"explanation":"The와 of 사이의 주어 자리이므로 명사 implementation(도입, 시행)이 알맞다. implement는 명사로 쓰면 '도구'라는 뜻이라 의미가 맞지 않고, implemented와 implementing은 분사 형태다.","translation":"새 배송 추적 시스템의 도입에는 거의 3개월이 걸렸다.","part":5},{"id":"p5-286","level":4,"type":"품사","question":"Coastline Air introduced a new ------- program for its frequent flyers.","choices":["loyalist","loyally","loyal","loyalty"],"answer":3,"explanation":"program과 결합해 '고객 보상 프로그램'을 뜻하는 복합명사 loyalty program이므로 loyalty가 정답이다. loyal은 형용사라 '충성스러운 프로그램'이 되어 어색하고, loyally는 부사, loyalist는 '충성파'라는 사람 명사다.","translation":"코스트라인 항공은 단골 승객을 위한 새 마일리지 보상 프로그램을 도입했다.","part":5},{"id":"p5-287","level":4,"type":"품사","question":"Applicants who are ------- in both Spanish and Portuguese will be given preference.","choices":["fluence","fluency","fluently","fluent"],"answer":3,"explanation":"are 뒤 보어 자리이며 in과 함께 '~에 유창한'을 뜻하는 형용사 fluent가 알맞다. fluency는 명사, fluently는 부사라 보어로 쓰지 않고, fluence는 일상 영어에서 쓰지 않는 단어다.","translation":"스페인어와 포르투갈어에 모두 능통한 지원자를 우대합니다.","part":5},{"id":"p5-288","level":4,"type":"품사","question":"Quarterly profits at Norvane Motors rose ------- despite weak demand in Asia.","choices":["modestly","modesty","modest","more modest"],"answer":0,"explanation":"자동사 rose를 꾸미는 부사 자리이므로 modestly(소폭으로)가 정답이다. modest와 more modest는 형용사라 동사를 수식할 수 없고, modesty는 명사다.","translation":"아시아 지역 수요 부진에도 노베인 모터스의 분기 이익은 소폭 증가했다.","part":5},{"id":"p5-289","level":4,"type":"품사","question":"Lakeside Medical Center is looking for ------- nurses to work night shifts.","choices":["experiencing","experiences","experienced","experience"],"answer":2,"explanation":"명사 nurses를 앞에서 꾸며 '경험이 풍부한'을 뜻하는 과거분사형 형용사 experienced가 알맞다. experiencing은 '경험하고 있는'이라 목적어가 필요하고, experience와 experiences는 명사·동사라 이 자리에서 의미가 맞지 않는다.","translation":"레이크사이드 의료 센터는 야간 근무를 할 경력 간호사를 찾고 있다.","part":5},{"id":"p5-290","level":4,"type":"동사 시제·태","question":"Ms. Greer ------- the Singapore office since it opened in 2018.","choices":["headed","heads","will head","has been heading"],"answer":3,"explanation":"since it opened in 2018(2018년 문을 연 이후로)은 과거부터 지금까지 계속되는 일을 나타내므로 현재완료진행 has been heading이 정답이다. heads는 현재, headed는 과거, will head는 미래라 since와 맞지 않는다.","translation":"그리어 씨는 싱가포르 사무소가 2018년 문을 연 이후로 계속 그곳을 이끌고 있다.","part":5},{"id":"p5-291","level":4,"type":"동사 시제·태","question":"The conference room is unavailable this morning because it ------- for the board meeting.","choices":["has prepared","is being prepared","prepares","is preparing"],"answer":1,"explanation":"회의실은 '준비되는' 대상이고 this morning 지금 진행 중이므로 현재진행 수동태 is being prepared가 알맞다. prepares, has prepared, is preparing은 모두 능동이라 회의실이 무언가를 준비한다는 뜻이 된다.","translation":"이사회 회의 준비가 진행 중이라 오늘 오전에는 회의실을 사용할 수 없다.","part":5},{"id":"p5-292","level":4,"type":"동사 시제·태","question":"Since the new chatbot was launched, customer complaints ------- by almost half.","choices":["have decreased","were decreased","decrease","had decreased"],"answer":0,"explanation":"since절이 과거 시작점을 나타내고 주절은 그때부터 지금까지의 변화이므로 현재완료 have decreased가 정답이다. decrease는 현재, had decreased는 과거완료라 기준 시점이 맞지 않고, decrease는 자동사로 주로 쓰여 were decreased는 부자연스럽다.","translation":"새 챗봇이 도입된 이후 고객 불만이 거의 절반으로 줄었다.","part":5},{"id":"p5-293","level":4,"type":"동사 시제·태","question":"By next March, Harmon Freight ------- in business for fifty years.","choices":["has been","will have been","was","had been"],"answer":1,"explanation":"By next March(내년 3월이면)는 미래 기준 시점까지의 지속을 나타내므로 미래완료 will have been이 알맞다. has been은 현재, was와 had been은 과거 기준이라 미래 시점과 맞지 않는다.","translation":"내년 3월이면 하몬 화물은 창업 50주년을 맞게 된다.","part":5},{"id":"p5-294","level":4,"type":"동사 시제·태","question":"Every applicant's references ------- before a formal job offer is made.","choices":["checking","are checked","have checked","check"],"answer":1,"explanation":"추천인 정보(references)는 '확인되는' 대상이므로 수동태 are checked가 정답이다. check와 have checked는 능동이라 목적어가 필요하고, checking은 동사 역할을 할 수 없다.","translation":"정식 채용 제안을 하기 전에 모든 지원자의 추천인 정보를 확인한다.","part":5},{"id":"p5-295","level":4,"type":"접속사","question":"Please keep your receipt ------- you need to exchange the item later.","choices":["even if","so that","whereas","in case"],"answer":3,"explanation":"'나중에 교환해야 할 경우에 대비해' 영수증을 보관하라는 뜻이므로 in case가 알맞다. even if(설령 ~라도)와 whereas(반면에)는 논리가 맞지 않고, so that(~하도록)은 교환이 필요하게 만든다는 이상한 의미가 된다.","translation":"나중에 제품을 교환해야 할 경우에 대비해 영수증을 보관하세요.","part":5},{"id":"p5-296","level":4,"type":"접속사","question":"The plant will stay open during the holiday ------- orders remain at their current level.","choices":["as long as","in order to","rather than","as well as"],"answer":0,"explanation":"'주문이 현재 수준을 유지하는 한' 공장을 계속 연다는 조건이므로 as long as가 정답이다. as well as와 rather than은 절과 절을 잇는 부사절 접속사가 아니고, in order to는 뒤에 동사원형이 온다.","translation":"주문량이 현재 수준을 유지하는 한 공장은 연휴 기간에도 계속 가동될 것이다.","part":5},{"id":"p5-297","level":4,"type":"접속사","question":"------- the Lyon branch focuses on retail clients, the Paris branch serves mainly corporations.","choices":["Whereas","Despite","Therefore","Unless"],"answer":0,"explanation":"리옹 지점과 파리 지점의 고객층을 대조하므로 '반면에'를 뜻하는 접속사 Whereas가 알맞다. Unless는 조건이라 의미가 맞지 않고, Therefore는 부사라 절을 연결하지 못하며, Despite는 전치사다.","translation":"리옹 지점은 개인 고객에 집중하는 반면 파리 지점은 주로 기업을 상대한다.","part":5},{"id":"p5-298","level":4,"type":"전치사","question":"------- the merger, the two banks will operate under a single brand name.","choices":["Except","Unlike","Following","Toward"],"answer":2,"explanation":"'합병 후에' 하나의 브랜드로 운영된다는 뜻이므로 '~ 이후에'를 뜻하는 전치사 Following이 정답이다. Unlike(~와 달리), Except(~을 제외하고), Toward(~ 쪽으로)는 의미가 통하지 않는다.","translation":"합병 이후 두 은행은 단일 브랜드로 운영될 것이다.","part":5},{"id":"p5-299","level":4,"type":"전치사","question":"All employees, ------- those currently on medical leave, must complete the online survey.","choices":["across","beneath","except","among"],"answer":2,"explanation":"'병가 중인 사람을 제외한' 모든 직원이라는 뜻이므로 except가 알맞다. among(~ 사이에), beneath(~ 아래에), across(~을 가로질러)는 이 문맥에서 의미가 통하지 않는다.","translation":"현재 병가 중인 사람을 제외한 모든 직원은 온라인 설문을 작성해야 한다.","part":5},{"id":"p5-300","level":4,"type":"전치사","question":"The new stadium in Porto Alegre was completed two months ------- schedule.","choices":["instead of","prior","ahead of","in front of"],"answer":2,"explanation":"ahead of schedule(예정보다 앞서)은 굳어진 표현이므로 ahead of가 정답이다. in front of는 공간상 앞을 나타내고, prior는 to가 있어야 전치사처럼 쓰이며, instead of(~ 대신)는 의미가 맞지 않는다.","translation":"포르투알레그리의 새 경기장은 예정보다 두 달 앞서 완공되었다.","part":5},{"id":"p5-301","level":4,"type":"준동사(to부정사·동명사·분사)","question":"Mr. Sato is responsible for ------- that all outgoing shipments meet quality standards.","choices":["to verify","verifies","verifying","verified"],"answer":2,"explanation":"전치사 for 뒤에는 동명사가 오므로 verifying이 알맞다. to verify는 전치사 뒤에 올 수 없고, verified와 verifies는 동사 형태라 전치사의 목적어가 될 수 없다.","translation":"사토 씨는 출고되는 모든 화물이 품질 기준을 충족하는지 확인하는 일을 맡고 있다.","part":5},{"id":"p5-302","level":4,"type":"준동사(to부정사·동명사·분사)","question":"------- by the positive reviews, the owner of Casa Lucía opened a second restaurant.","choices":["Encourages","Encouraged","Encouraging","To encourage"],"answer":1,"explanation":"주절의 주어(the owner)가 좋은 평에 의해 '고무된' 것이므로 수동 의미의 분사구문 Encouraged가 정답이다. Encouraging은 능동이라 뒤에 목적어가 필요하고, To encourage는 목적을 나타내 의미가 어색하며, Encourages는 동사라 분사구문을 만들 수 없다.","translation":"좋은 평가에 힘입어 카사 루시아의 주인은 두 번째 식당을 열었다.","part":5},{"id":"p5-303","level":4,"type":"준동사(to부정사·동명사·분사)","question":"The zoning committee has yet ------- a final decision on the housing project.","choices":["reaching","reach","to reach","reached"],"answer":2,"explanation":"have yet to + 동사원형은 '아직 ~하지 않았다'는 표현이므로 to reach가 알맞다. reaching, reached, reach는 has yet 뒤에서 이 구문을 만들지 못한다.","translation":"용도지역 위원회는 그 주택 사업에 대해 아직 최종 결정을 내리지 못했다.","part":5},{"id":"p5-304","level":4,"type":"관계사","question":"The resort has 200 guest rooms, most of ------- overlook the Aegean Sea.","choices":["what","which","whom","them"],"answer":1,"explanation":"콤마 뒤에 두 절을 연결하면서 전치사 of의 목적어가 되는 관계대명사가 필요하고 선행사가 사물(rooms)이므로 which가 정답이다. them은 접속 기능이 없어 문장이 두 개로 이어지는 오류가 되고, whom은 사람, what은 선행사를 가질 수 없다.","translation":"그 리조트에는 객실이 200개 있는데, 대부분이 에게해를 내려다본다.","part":5},{"id":"p5-305","level":4,"type":"관계사","question":"The company has introduced a system ------- employees can report safety concerns anonymously.","choices":["what","whereby","whereas","which"],"answer":1,"explanation":"뒤의 절이 완전하고 '그 제도를 통해'라는 의미이므로 관계부사 whereby(= by which)가 알맞다. whereas는 대조 접속사라 선행사를 꾸미지 못하고, which와 what은 뒤에 빠진 성분이 있어야 한다.","translation":"회사는 직원들이 익명으로 안전 문제를 신고할 수 있는 제도를 도입했다.","part":5},{"id":"p5-306","level":4,"type":"대명사","question":"Some staff members prefer to work from home, while ------- prefer the office.","choices":["the other","others","other","another"],"answer":1,"explanation":"'어떤 사람들은 ~, 다른 사람들은 ~'이라는 Some ~ others 구조이며 동사 prefer가 복수형이므로 others가 알맞다. another와 the other는 단수라 prefer와 수가 맞지 않고, other는 단독으로 대명사로 쓰지 않는다.","translation":"일부 직원은 재택근무를 선호하는 반면 다른 직원들은 사무실을 선호한다.","part":5},{"id":"p5-307","level":4,"type":"대명사","question":"------- who wishes to attend the awards gala must register by Friday.","choices":["Everything","Whoever","Those","Anyone"],"answer":3,"explanation":"단수 동사 wishes와 관계대명사 who의 선행사가 되는 사람 대명사는 Anyone이다. Those는 복수라 wishes와 수가 맞지 않고, Whoever 뒤에 who를 또 쓸 수 없으며, Everything은 사물이라 who와 맞지 않는다.","translation":"시상식 갈라에 참석하려는 사람은 누구든 금요일까지 등록해야 한다.","part":5},{"id":"p5-308","level":4,"type":"수 일치","question":"Either the regional managers or the director ------- the final budget each year.","choices":["approves","approve","approving","to approve"],"answer":0,"explanation":"either A or B가 주어이면 동사는 B(the director)에 수를 맞추므로 단수 approves가 정답이다. approve는 A(managers)에 맞춘 함정이고, approving과 to approve는 동사가 될 수 없다.","translation":"매년 지역 관리자들이나 이사 중 한쪽이 최종 예산을 승인한다.","part":5},{"id":"p5-309","level":4,"type":"수 일치","question":"Shoppers who ------- online before noon will receive their groceries the same day.","choices":["to order","orders","order","ordering"],"answer":2,"explanation":"주격 관계대명사 who 뒤 동사는 선행사 Shoppers(복수)에 수를 맞추므로 order가 알맞다. orders는 단수 주어에 맞는 형태이고, ordering과 to order는 관계절의 동사가 될 수 없다.","translation":"정오 전에 온라인으로 주문하는 쇼핑객은 당일에 식료품을 받게 된다.","part":5},{"id":"p5-310","level":4,"type":"비교","question":"Tokyo Station handles more passengers than any ------- station in Japan.","choices":["other","else","others","another"],"answer":0,"explanation":"비교급 + than any other + 단수명사는 최상급 의미를 나타내는 구문이므로 other가 정답이다. others는 명사를 꾸밀 수 없고, another는 any와 함께 쓰지 않으며, else는 명사 앞에서 수식하지 않는다.","translation":"도쿄역은 일본의 다른 어떤 역보다 많은 승객을 처리한다.","part":5},{"id":"p5-311","level":5,"type":"어휘","question":"The internal auditors concluded that the regional office's travel claims were ------- with company policy.","choices":["constant","consecutive","constituent","consistent"],"answer":3,"explanation":"be consistent with(~와 일치하다, 부합하다)는 짝 표현으로 출장비 청구가 회사 정책에 '부합했다'는 뜻이 되므로 consistent가 알맞다. constant(끊임없는), constituent(구성하는), consecutive(연속적인)는 with와 함께 정책 준수 여부를 나타내지 못한다.","translation":"내부 감사관들은 지역 사무소의 출장비 청구가 회사 정책에 부합한다고 결론 내렸다.","part":5},{"id":"p5-312","level":5,"type":"어휘","question":"The transit authority voted to ------- the outdated fare regulation, which had been in place since 1998.","choices":["rescind","recede","rebound","relent"],"answer":0,"explanation":"오래된(outdated) 규정을 '폐지하다, 철회하다'라는 타동사가 필요하므로 rescind가 정답이다. recede(물러나다), rebound(반등하다), relent(누그러지다)는 모두 자동사라 목적어를 바로 취할 수 없다.","translation":"교통 당국은 1998년부터 시행되어 온 낡은 요금 규정을 폐지하기로 의결했다.","part":5},{"id":"p5-313","level":5,"type":"어휘","question":"The new division head wasted no time in ------- sweeping changes to the hiring process.","choices":["instituting","inhabiting","insisting","inheriting"],"answer":0,"explanation":"changes를 목적어로 '(제도·변화를) 도입하다, 시행하다'라는 뜻의 instituting이 알맞다. inhabiting(거주하다), inheriting(물려받다)은 changes와 의미가 맞지 않고, insisting은 on이 필요하다.","translation":"새 부서장은 지체 없이 채용 절차에 대대적인 변화를 도입했다.","part":5},{"id":"p5-314","level":5,"type":"어휘","question":"Because the trial results are only -------, further studies will be needed before any conclusions are drawn.","choices":["prestigious","preliminary","predominant","perpetual"],"answer":1,"explanation":"결론을 내리기 전에 추가 연구가 필요하다는 것은 결과가 아직 '예비적'이라는 뜻이므로 preliminary가 정답이다. predominant(지배적인), perpetual(영구적인), prestigious(명망 있는)는 추가 연구가 필요한 이유가 되지 못한다.","translation":"임상시험 결과가 예비 단계에 불과하므로 결론을 내리기 전에 추가 연구가 필요할 것이다.","part":5},{"id":"p5-315","level":5,"type":"어휘","question":"The upper-deck lounge is reserved ------- for first-class passengers and elite members.","choices":["extensively","exclusively","excessively","expressively"],"answer":1,"explanation":"라운지가 일등석 승객과 우수 회원 '전용'으로 마련되었다는 뜻이므로 exclusively가 알맞다. be reserved exclusively for는 자주 쓰는 표현이다. extensively(광범위하게), excessively(지나치게), expressively(표현력 있게)는 reserved for와 어울리지 않는다.","translation":"위층 라운지는 일등석 승객과 우수 회원 전용으로 마련되어 있다.","part":5},{"id":"p5-316","level":5,"type":"어휘","question":"Unless both parties agree to an extension, the supply agreement will remain in ------- only until December 31.","choices":["motion","force","range","stock"],"answer":1,"explanation":"remain in force(효력이 유지되다)는 계약·법규에 쓰는 굳어진 표현이므로 force가 정답이다. in motion(움직이는 중), in stock(재고가 있는), in range(범위 안에)는 계약의 효력을 나타내지 못한다.","translation":"양측이 연장에 합의하지 않으면 공급 계약은 12월 31일까지만 효력이 유지된다.","part":5},{"id":"p5-317","level":5,"type":"어휘","question":"Weeks of unusually heavy rainfall have ------- this year's coffee harvest in the highland region.","choices":["alleviated","persuaded","commended","jeopardized"],"answer":3,"explanation":"이례적 폭우가 수확을 '위태롭게 했다'는 부정적 결과가 자연스러우므로 jeopardized가 알맞다. commended(칭찬했다), persuaded(설득했다)는 harvest와 의미가 맞지 않고, alleviated(완화했다)는 문맥과 반대다.","translation":"몇 주간 이어진 이례적인 폭우로 고지대 지역의 올해 커피 수확이 위태로워졌다.","part":5},{"id":"p5-318","level":5,"type":"어휘","question":"Ms. Ivanova will ------- in for the communications director at tomorrow's press briefing.","choices":["bring","give","stand","turn"],"answer":2,"explanation":"stand in for는 '~을 대신하다'라는 구동사이므로 stand가 정답이다. turn in(제출하다), bring in(들여오다), give in(굴복하다)은 for와 함께 대리 역할을 나타내지 못한다.","translation":"이바노바 씨가 내일 언론 브리핑에서 홍보 이사를 대신할 것이다.","part":5},{"id":"p5-319","level":5,"type":"어휘","question":"The merger will create a media group with a ------- share of the European streaming market.","choices":["dormant","diligent","docile","dominant"],"answer":3,"explanation":"합병으로 시장에서 '지배적인' 점유율을 갖게 된다는 뜻이므로 dominant가 알맞다. dormant(휴면 중인), diligent(부지런한), docile(유순한)은 share(점유율)를 꾸미기에 의미가 맞지 않는다.","translation":"이번 합병으로 유럽 스트리밍 시장에서 지배적인 점유율을 가진 미디어 그룹이 탄생할 것이다.","part":5},{"id":"p5-320","level":5,"type":"어휘","question":"The riverside film festival is funded ------- by private donations and receives no money from the city.","choices":["lately","closely","hardly","entirely"],"answer":3,"explanation":"시로부터 돈을 전혀 받지 않는다고 했으므로 '전적으로' 개인 기부로 운영된다는 entirely가 정답이다. hardly(거의 ~않다)는 뒤 내용과 모순되고, lately(최근에), closely(면밀히)는 funded by와 의미가 맞지 않는다.","translation":"그 강변 영화제는 전적으로 개인 기부금으로 운영되며 시로부터는 자금을 받지 않는다.","part":5},{"id":"p5-321","level":5,"type":"품사","question":"Following several complaints, the agency conducted a thorough ------- of its recruitment practices.","choices":["reassessment","reassess","reassessed","reassessing"],"answer":0,"explanation":"관사 a와 형용사 thorough 뒤, conducted의 목적어 자리이므로 명사 reassessment가 알맞다. reassess는 동사이고, reassessed와 reassessing은 분사라 관사와 형용사의 꾸밈을 받는 명사 자리에 적합하지 않다.","translation":"여러 건의 불만이 제기된 후 그 기관은 채용 관행을 철저히 재평가했다.","part":5},{"id":"p5-322","level":5,"type":"품사","question":"Ms. Kagame is ------- the most accomplished textile designer the company has ever employed.","choices":["arguably","arguable","argue","argument"],"answer":0,"explanation":"최상급 표현 the most accomplished 앞에서 '거의 틀림없이'라는 뜻으로 수식하는 부사 arguably가 정답이다. arguable은 형용사, argument는 명사, argue는 동사라 이 위치에 올 수 없다.","translation":"카가메 씨는 아마도 회사가 고용해 온 직물 디자이너 중 가장 뛰어난 사람일 것이다.","part":5},{"id":"p5-323","level":5,"type":"품사","question":"Over the last decade, rural clinics have become ------- dependent on government grants.","choices":["increasing","increased","increase","increasingly"],"answer":3,"explanation":"형용사 dependent를 앞에서 꾸미는 부사 자리이므로 increasingly가 알맞다. increasing과 increased는 형용사·분사라 다른 형용사를 꾸밀 수 없고, increase는 명사·동사다.","translation":"지난 10년간 농촌 진료소들은 정부 보조금에 점점 더 의존하게 되었다.","part":5},{"id":"p5-324","level":5,"type":"품사","question":"Participants described the leadership workshop as both informative and -------.","choices":["engage","engaging","engaged","engagement"],"answer":1,"explanation":"both A and B는 같은 품사를 연결하므로 형용사 informative와 짝을 이루며 '흥미를 끄는'이라는 뜻의 engaging이 정답이다. engaged는 '몰두한, 약혼한'이라 워크숍을 설명하기 어색하고, engagement는 명사, engage는 동사다.","translation":"참가자들은 리더십 워크숍이 유익하고도 흥미로웠다고 말했다.","part":5},{"id":"p5-325","level":5,"type":"품사","question":"After months of talks, the two logistics firms signed a ------- beneficial partnership agreement.","choices":["mutually","mutualize","mutual","mutuality"],"answer":0,"explanation":"형용사 beneficial을 앞에서 꾸미는 부사 자리이므로 mutually가 알맞다(mutually beneficial: 상호 이익이 되는). mutual은 형용사라 다른 형용사를 꾸밀 수 없고, mutuality는 명사, mutualize는 동사다.","translation":"수개월의 협상 끝에 두 물류 회사는 상호 이익이 되는 제휴 계약을 체결했다.","part":5},{"id":"p5-326","level":5,"type":"품사","question":"The consultant's report questions the ------- of expanding into three new markets at once.","choices":["feasible","feasibility","feasibly","infeasible"],"answer":1,"explanation":"관사 the와 전치사 of 사이, questions의 목적어 자리이므로 명사 feasibility(실현 가능성)가 알맞다. feasible은 형용사, feasibly는 부사, infeasible은 '실현 불가능한'이라는 형용사라 명사 자리에 올 수 없다.","translation":"컨설턴트의 보고서는 세 개의 새 시장에 한꺼번에 진출하는 것의 실현 가능성에 의문을 제기한다.","part":5},{"id":"p5-327","level":5,"type":"품사","question":"The firmware upgrade has been postponed ------- because of unresolved compatibility issues.","choices":["indefiniteness","indefinite","definite","indefinitely"],"answer":3,"explanation":"수동태 has been postponed를 꾸미는 부사 자리이므로 indefinitely(무기한으로)가 정답이다. indefinite와 definite는 형용사, indefiniteness는 명사라 동사를 수식할 수 없다.","translation":"해결되지 않은 호환성 문제로 펌웨어 업그레이드가 무기한 연기되었다.","part":5},{"id":"p5-328","level":5,"type":"품사","question":"Rising fuel surcharges have made long-haul flights ------- expensive for many budget travelers.","choices":["prohibit","prohibitively","prohibitive","prohibition"],"answer":1,"explanation":"make + 목적어 + 형용사(expensive) 구조에서 형용사 expensive를 꾸미는 부사 자리이므로 prohibitively(엄두를 못 낼 만큼)가 알맞다. prohibitive는 형용사라 다른 형용사를 꾸밀 수 없고, prohibition은 명사, prohibit는 동사다.","translation":"유류할증료가 오르면서 많은 저예산 여행객에게 장거리 항공편이 엄두를 못 낼 만큼 비싸졌다.","part":5},{"id":"p5-329","level":5,"type":"품사","question":"Since opening its Jakarta office, the agency's ------- in Southeast Asia has grown steadily.","choices":["presence","present","presently","presentable"],"answer":0,"explanation":"소유격 the agency's 뒤 주어 자리이며 '입지, 존재감'을 뜻하는 명사 presence가 정답이다. present는 명사로 쓰면 '선물·현재'라 의미가 맞지 않고, presently는 부사, presentable은 형용사다.","translation":"자카르타 사무소를 연 이후 그 대행사의 동남아시아 내 입지는 꾸준히 커졌다.","part":5},{"id":"p5-330","level":5,"type":"동사 시제·태","question":"The board recommended that the expansion proposal ------- until more reliable cost data is available.","choices":["was postponing","postpones","be postponed","to postpone"],"answer":2,"explanation":"recommend 같은 제안·요구 동사 뒤 that절에는 (should) + 동사원형을 쓰며, 제안서는 '연기되는' 대상이므로 be postponed가 알맞다. postpones와 was postponing은 능동이고 형태도 맞지 않으며, to postpone은 that절의 동사가 될 수 없다.","translation":"이사회는 더 신뢰할 만한 비용 자료가 나올 때까지 확장 제안을 연기할 것을 권고했다.","part":5},{"id":"p5-331","level":5,"type":"동사 시제·태","question":"Were sufficient funds available, the city ------- the new public library this year.","choices":["has built","will build","would build","builds"],"answer":2,"explanation":"Were ~ available은 If가 생략되고 도치된 가정법 과거(= If sufficient funds were available)이므로 주절에는 would + 동사원형인 would build가 정답이다. will build, builds, has built는 가정법 주절의 형태가 아니다.","translation":"충분한 자금이 있다면 시는 올해 새 공공 도서관을 지을 텐데.","part":5},{"id":"p5-332","level":5,"type":"동사 시제·태","question":"Not until the safety inspection ------- will the plant be allowed to resume production.","choices":["completing","completes","is completed","will be completed"],"answer":2,"explanation":"Not until이 이끄는 시간 부사절에서는 미래 대신 현재시제를 쓰고, 점검은 '완료되는' 대상이므로 현재 수동태 is completed가 알맞다. will be completed는 시간절에 미래시제를 쓴 오류이고, completes는 능동이며, completing은 동사가 될 수 없다.","translation":"안전 점검이 끝나야만 공장은 생산을 재개할 수 있다.","part":5},{"id":"p5-333","level":5,"type":"동사 시제·태","question":"The acquisition, which ------- in secret for several months, was finally announced on Monday.","choices":["has been negotiated","had been negotiated","negotiates","was negotiating"],"answer":1,"explanation":"월요일에 발표된 과거 시점보다 앞서 몇 달간 '협상되어 온' 것이므로 과거완료 수동태 had been negotiated가 정답이다. has been negotiated는 현재완료라 과거 기준과 맞지 않고, was negotiating과 negotiates는 능동이라 인수가 협상을 했다는 뜻이 된다.","translation":"몇 달간 비밀리에 협상되어 온 그 인수 건이 마침내 월요일에 발표되었다.","part":5},{"id":"p5-334","level":5,"type":"동사 시제·태","question":"Ms. Dlamini ------- to the Johannesburg office if the restructuring plan is approved next week.","choices":["has been transferred","had transferred","will be transferred","was transferred"],"answer":2,"explanation":"조건절(if ~ is approved next week)이 미래 상황을 나타내므로 주절은 미래이고, 직원은 '전근되는' 대상이므로 will be transferred가 알맞다. was transferred와 has been transferred는 이미 일어난 일이고, had transferred는 과거완료 능동이다.","translation":"다음 주 구조조정안이 승인되면 들라미니 씨는 요하네스버그 사무소로 전근될 것이다.","part":5},{"id":"p5-335","level":5,"type":"접속사","question":"------- the replacement parts arrive by Friday, the assembly plant will have to halt production.","choices":["Once","Because","Whereas","Unless"],"answer":3,"explanation":"'금요일까지 부품이 도착하지 않으면 생산을 중단해야 한다'는 조건이므로 Unless가 정답이다. Once(일단 ~하면)와 Because(~ 때문에)는 부품 도착이 생산 중단의 원인이 되어 논리가 맞지 않고, Whereas(반면에)는 대조라 어울리지 않는다.","translation":"교체 부품이 금요일까지 도착하지 않으면 조립 공장은 생산을 중단해야 할 것이다.","part":5},{"id":"p5-336","level":5,"type":"접속사","question":"The analytics platform is extremely powerful; -------, its interface can be confusing for new users.","choices":["therefore","moreover","however","otherwise"],"answer":2,"explanation":"앞 절은 장점, 뒤 절은 단점으로 서로 대조되므로 however가 알맞다. therefore(그러므로)와 moreover(게다가)는 대조를 나타내지 못하고, otherwise(그렇지 않으면)는 조건의 의미라 맞지 않는다.","translation":"그 분석 플랫폼은 매우 강력하지만, 인터페이스는 신규 사용자에게 헷갈릴 수 있다.","part":5},{"id":"p5-337","level":5,"type":"접속사","question":"------- costly the renovation may be, it is necessary to meet the revised fire code.","choices":["Whatever","However","Although","Even"],"answer":1,"explanation":"However + 형용사 + 주어 + 동사는 '아무리 ~하더라도'라는 양보 구문이므로 However가 정답이다. Although는 바로 뒤에 형용사를 둘 수 없고, Whatever는 명사와 함께 쓰며, Even은 부사라 절을 이끌지 못한다.","translation":"보수 공사 비용이 아무리 많이 들더라도 개정된 소방 규정을 충족하려면 반드시 필요하다.","part":5},{"id":"p5-338","level":5,"type":"전치사","question":"Reimbursement will be processed ------- receipt of all required supporting documents.","choices":["above","along","upon","beside"],"answer":2,"explanation":"upon receipt of(~을 받는 즉시)는 굳어진 표현이므로 upon이 알맞다. above(~ 위에), along(~을 따라), beside(~ 옆에)는 receipt와 함께 '받는 즉시'라는 시간 의미를 만들지 못한다.","translation":"필요한 증빙 서류가 모두 접수되는 즉시 비용이 환급 처리됩니다.","part":5},{"id":"p5-339","level":5,"type":"전치사","question":"The package tour to Patagonia costs $2,400 per person, ------- international airfare.","choices":["in favor of","exclusive of","by means of","on behalf of"],"answer":1,"explanation":"여행 요금에서 국제선 항공료는 '제외하고'라는 뜻이므로 exclusive of가 정답이다. on behalf of(~을 대신하여), in favor of(~에 찬성하여), by means of(~을 수단으로)는 가격 조건을 나타내지 못한다.","translation":"파타고니아 패키지 여행은 국제선 항공료를 제외하고 1인당 2,400달러이다.","part":5},{"id":"p5-340","level":5,"type":"전치사","question":"The harvest festival was postponed ------- growing concerns about the approaching typhoon.","choices":["amid","versus","beside","among"],"answer":0,"explanation":"amid는 '(어떤 상황·분위기) 속에서'라는 뜻으로 concerns 같은 추상명사와 잘 어울리므로 정답이다. among은 셋 이상의 구체적 대상 사이를 나타내고, beside(~ 옆에)와 versus(~ 대)는 의미가 맞지 않는다.","translation":"다가오는 태풍에 대한 우려가 커지는 가운데 추수 축제가 연기되었다.","part":5},{"id":"p5-341","level":5,"type":"준동사(to부정사·동명사·분사)","question":"The sustainability report, ------- next month, will outline the company's carbon reduction targets.","choices":["having released","releases","to be released","to release"],"answer":2,"explanation":"보고서는 앞으로 '발표될' 것이므로 미래·수동의 의미를 가진 to be released가 알맞다. releases는 이미 동사 will outline이 있어 쓸 수 없고, having released와 to release는 능동이라 보고서가 무언가를 발표한다는 뜻이 된다.","translation":"다음 달 발표될 지속가능경영 보고서에는 회사의 탄소 감축 목표가 담길 것이다.","part":5},{"id":"p5-342","level":5,"type":"준동사(to부정사·동명사·분사)","question":"------- all the licensing requirements, the applicant was invited to the final interview.","choices":["Having met","Met","To be met","Having been met"],"answer":0,"explanation":"지원자가 요건을 '충족한' 것이 초대받기 이전의 일이고 능동이므로 완료 분사구문 Having met이 정답이다. Having been met과 To be met은 수동이라 뒤에 목적어를 둘 수 없고, Met은 수동 의미라 지원자가 충족되었다는 뜻이 된다.","translation":"모든 자격 요건을 갖춘 그 지원자는 최종 면접에 초대받았다.","part":5},{"id":"p5-343","level":5,"type":"준동사(to부정사·동명사·분사)","question":"The new printing policy is aimed at ------- paper waste across all regional offices.","choices":["to reduce","reduced","reduce","reducing"],"answer":3,"explanation":"be aimed at의 at은 전치사이므로 뒤에 동명사 reducing이 와야 한다. reduce와 reduced는 전치사의 목적어가 될 수 없고, to reduce는 전치사 at 뒤에 쓸 수 없다.","translation":"새 인쇄 정책은 모든 지역 사무소의 종이 낭비를 줄이는 것을 목표로 한다.","part":5},{"id":"p5-344","level":5,"type":"관계사","question":"This year's leadership award goes to Dr. Oyelaran, ------- the research institute owes much of its recent success.","choices":["who","whom","to which","to whom"],"answer":3,"explanation":"관계절이 owe A to B(A를 B 덕분으로 여기다) 구조이므로 전치사 to가 관계대명사 앞으로 온 to whom이 알맞고, 선행사가 사람(Dr. Oyelaran)이다. whom과 who만 쓰면 owe ~ to의 to가 빠져 불완전하고, to which는 사물 선행사에 쓴다.","translation":"올해 리더십상은 연구소의 최근 성공이 상당 부분 그 덕분인 오옐라란 박사에게 돌아간다.","part":5},{"id":"p5-345","level":5,"type":"관계사","question":"------- impressed the judges most was the simplicity of the app's design.","choices":["That","What","Which","Whose"],"answer":1,"explanation":"문장 전체의 주어가 되는 명사절을 이끌면서 관계절 안에서 impressed의 주어 역할도 하는 what(~하는 것)이 알맞다. That은 완전한 절을 이끌어야 하고, Which와 Whose는 선행사 없이 이 구조를 만들지 못한다.","translation":"심사위원들에게 가장 깊은 인상을 준 것은 그 앱 디자인의 단순함이었다.","part":5},{"id":"p5-346","level":5,"type":"대명사","question":"Of the five grant proposals submitted, ------- met all of the foundation's funding criteria.","choices":["none","neither","nothing","no"],"answer":0,"explanation":"'다섯 개 제안서 중 어느 것도 ~않았다'는 뜻으로 of 이하 셋 이상의 대상을 받는 대명사 none이 정답이다. nothing은 of 구문의 범위를 받지 않고, no는 한정사라 단독으로 주어가 될 수 없으며, neither는 둘 중에서만 쓴다.","translation":"제출된 다섯 건의 보조금 제안서 중 어느 것도 재단의 지원 기준을 모두 충족하지 못했다.","part":5},{"id":"p5-347","level":5,"type":"대명사","question":"The headquarters building ------- is modest, but the surrounding gardens are spectacular.","choices":["itself","themselves","its","it"],"answer":0,"explanation":"주어 The headquarters building을 바로 뒤에서 강조해 '건물 자체는'이라는 뜻을 만드는 재귀대명사 itself가 알맞다. its는 소유격이라 명사가 필요하고, it은 주어가 겹쳐 비문이 되며, themselves는 복수라 단수 주어와 맞지 않는다.","translation":"본사 건물 자체는 수수하지만 주변 정원은 장관이다.","part":5},{"id":"p5-348","level":5,"type":"수 일치","question":"Implementing the new data-protection procedures across all branches ------- careful coordination.","choices":["have required","requiring","require","requires"],"answer":3,"explanation":"동명사구(Implementing ~ branches)가 주어이면 단수 취급하므로 requires가 정답이다. require와 have required는 복수 명사 procedures·branches에 맞춘 함정이고, requiring은 동사가 될 수 없다.","translation":"모든 지점에 새 데이터 보호 절차를 시행하려면 신중한 조율이 필요하다.","part":5},{"id":"p5-349","level":5,"type":"수 일치","question":"The quality of the components that the supplier ships to its overseas plants ------- a concern for the board.","choices":["remain","remaining","remains","have remained"],"answer":2,"explanation":"주어의 핵심은 단수 The quality이고 of 이하와 관계절(that ~ plants)은 수식어이므로 단수 동사 remains가 알맞다. remain과 have remained는 components나 plants에 맞춘 함정이고, remaining은 동사가 될 수 없다.","translation":"공급업체가 해외 공장으로 보내는 부품의 품질은 여전히 이사회의 걱정거리다.","part":5},{"id":"p5-350","level":5,"type":"비교","question":"In terms of battery life, the X9 tablet is clearly ------- to its predecessor.","choices":["higher","better","superior","more"],"answer":2,"explanation":"뒤에 than이 아니라 to가 오므로 라틴어 비교 형용사 superior(~보다 우수한)가 정답이다. better, more, higher는 비교급이라 than과 함께 써야 하므로 to와 맞지 않는다.","translation":"배터리 수명 면에서 X9 태블릿은 이전 모델보다 확실히 우수하다.","part":5},{"id":"p5-351","level":1,"type":"어휘","question":"Please ------- your coat on the hook by the door.","choices":["cook","drive","sell","hang"],"answer":3,"explanation":"'코트를 문 옆 고리에 ~하다'이므로 '걸다'라는 뜻의 hang이 알맞다. cook(요리하다), drive(운전하다), sell(팔다)은 코트를 고리에 두는 동작과 어울리지 않는다.","translation":"코트는 문 옆 고리에 걸어 주세요.","part":5},{"id":"p5-352","level":1,"type":"어휘","question":"The dentist's office will ------- you the day before your appointment to confirm the time.","choices":["eat","wear","grow","call"],"answer":3,"explanation":"예약 시간을 확인하려고 병원이 환자에게 하는 행동이므로 '전화하다'라는 뜻의 call이 알맞다. eat(먹다), wear(입다), grow(기르다)는 사람을 목적어로 두고 시간을 확인하는 상황에 맞지 않는다.","translation":"치과에서 예약 전날 시간을 확인하기 위해 전화를 드릴 것입니다.","part":5},{"id":"p5-353","level":1,"type":"어휘","question":"Please turn ------- your mobile phone during the job interview.","choices":["off","into","across","behind"],"answer":0,"explanation":"면접 중에는 휴대 전화를 '끄는' 것이 자연스러우므로 turn off(끄다)를 만드는 off가 정답이다. turn into는 '~으로 변하다'라는 뜻이고, across와 behind는 turn과 함께 휴대 전화를 끄는 의미를 만들지 못한다.","translation":"취업 면접 중에는 휴대 전화를 꺼 주세요.","part":5},{"id":"p5-354","level":1,"type":"어휘","question":"The ------- at the front desk will give you a room key.","choices":["pilot","farmer","receptionist","dentist"],"answer":2,"explanation":"호텔 프런트 데스크(front desk)에서 객실 열쇠를 주는 사람은 접수 직원이므로 receptionist가 알맞다. pilot(조종사), farmer(농부), dentist(치과 의사)는 프런트 데스크에서 일하는 사람이 아니다.","translation":"프런트 데스크 직원이 객실 열쇠를 드릴 것입니다.","part":5},{"id":"p5-355","level":1,"type":"어휘","question":"Our office is closed on weekends, so please visit us on a -------.","choices":["holiday","weekday","vacation","season"],"answer":1,"explanation":"주말(weekends)에 문을 닫으니 '평일'에 방문하라는 흐름이므로 weekday가 정답이다. holiday(휴일)는 앞 내용과 모순되고, vacation(휴가)과 season(계절)은 방문 날짜를 가리키지 못한다.","translation":"저희 사무실은 주말에 문을 닫으니 평일에 방문해 주세요.","part":5},{"id":"p5-356","level":1,"type":"어휘","question":"Mr. Nguyen ------- the bus to work every day.","choices":["rides","wears","reads","cooks"],"answer":0,"explanation":"목적어가 the bus이고 '출근하다(to work)'가 이어지므로 '타다'라는 뜻의 rides가 알맞다. wears(입다), reads(읽다), cooks(요리하다)는 버스를 목적어로 쓸 수 없다.","translation":"응우옌 씨는 매일 버스를 타고 출근한다.","part":5},{"id":"p5-357","level":1,"type":"어휘","question":"The printer is out of -------, so please add more before you print the report.","choices":["water","money","time","paper"],"answer":3,"explanation":"프린터에 '더 넣고(add more)' 보고서를 인쇄하라는 말이므로 떨어진 것은 종이, 즉 paper이다. water와 money는 프린터에 넣는 것이 아니고, out of time(시간이 없다)은 add more와 연결되지 않는다.","translation":"프린터에 종이가 떨어졌으니 보고서를 인쇄하기 전에 더 넣어 주세요.","part":5},{"id":"p5-358","level":1,"type":"어휘","question":"Please ------- the door when you leave the storage room.","choices":["fold","lock","pour","plant"],"answer":1,"explanation":"창고를 나갈 때 문(the door)에 하는 동작이므로 '잠그다'라는 뜻의 lock이 알맞다. fold(접다), pour(붓다), plant(심다)는 문과 어울리지 않는 동사이다.","translation":"창고를 나갈 때 문을 잠가 주세요.","part":5},{"id":"p5-359","level":1,"type":"어휘","question":"The hotel's swimming pool is on the ------- of the building.","choices":["menu","ticket","price","roof"],"answer":3,"explanation":"수영장이 건물의 어디에 있는지 말하므로 '옥상'을 뜻하는 roof가 정답이다. menu(메뉴), ticket(표), price(가격)는 건물 안의 위치를 나타내지 않는다.","translation":"호텔 수영장은 건물 옥상에 있다.","part":5},{"id":"p5-360","level":1,"type":"어휘","question":"Mr. Petrov is ------- because he worked late last night.","choices":["empty","tired","expensive","wooden"],"answer":1,"explanation":"어젯밤 늦게까지 일했기 때문에(because) 생기는 사람의 상태이므로 tired(피곤한)가 알맞다. empty(비어 있는), expensive(비싼), wooden(나무로 된)은 사람의 상태를 나타내지 않는다.","translation":"페트로프 씨는 어젯밤 늦게까지 일해서 피곤하다.","part":5},{"id":"p5-361","level":1,"type":"어휘","question":"Ms. Lindqvist will ------- a presentation about our new products tomorrow.","choices":["spend","ask","give","pay"],"answer":2,"explanation":"presentation(발표)과 어울리는 동사는 give로, give a presentation은 '발표하다'라는 뜻이다. spend(쓰다), ask(묻다), pay(지불하다)는 presentation과 함께 쓰지 않는다.","translation":"린드크비스트 씨는 내일 우리 신제품에 대해 발표할 것이다.","part":5},{"id":"p5-362","level":1,"type":"어휘","question":"Please wash your ------- before you handle food in the kitchen.","choices":["hands","keys","shoes","chairs"],"answer":0,"explanation":"주방에서 음식을 다루기 전에 씻어야 하는 것은 손이므로 hands가 정답이다. keys(열쇠), shoes(신발), chairs(의자)는 음식을 만지기 전에 씻는 대상으로 어색하다.","translation":"주방에서 음식을 다루기 전에 손을 씻어 주세요.","part":5},{"id":"p5-363","level":1,"type":"품사","question":"The museum guide gave a very ------- tour.","choices":["interested","interesting","interest","interestingly"],"answer":1,"explanation":"관사 a와 명사 tour 사이, very 뒤에는 형용사가 온다. 투어가 '흥미를 주는' 것이므로 -ing 형태의 interesting이 알맞고, interested는 사람이 흥미를 느낄 때 쓴다. interest는 명사·동사, interestingly는 부사라 명사를 꾸밀 수 없다.","translation":"박물관 가이드는 매우 흥미로운 투어를 해 주었다.","part":5},{"id":"p5-364","level":1,"type":"품사","question":"Please speak ------- in the library.","choices":["quiet","quietness","quieter","quietly"],"answer":3,"explanation":"동사 speak를 꾸미는 자리이므로 부사 quietly가 정답이다. quiet와 quieter는 형용사이고, quietness는 명사라 동사를 수식하지 못한다.","translation":"도서관에서는 조용히 말해 주세요.","part":5},{"id":"p5-365","level":1,"type":"품사","question":"Our new café has a ------- view of the river.","choices":["beauty","beautifully","beautify","beautiful"],"answer":3,"explanation":"관사 a와 명사 view 사이에서 명사를 꾸미는 자리이므로 형용사 beautiful이 알맞다. beauty는 명사, beautifully는 부사, beautify는 동사라 이 자리에 올 수 없다.","translation":"우리 새 카페에서는 강의 아름다운 경치가 보인다.","part":5},{"id":"p5-366","level":1,"type":"품사","question":"Mr. Mbeki is the ------- of this small bookstore.","choices":["own","owner","owned","owning"],"answer":1,"explanation":"관사 the 뒤, 전치사 of 앞은 명사 자리이므로 '주인'을 뜻하는 owner가 정답이다. own은 동사·형용사, owned와 owning은 동사의 변화형이라 the 뒤에서 사람을 나타낼 수 없다.","translation":"음베키 씨는 이 작은 서점의 주인이다.","part":5},{"id":"p5-367","level":1,"type":"품사","question":"The staff at the front desk are always very -------.","choices":["friend","friends","friendly","friendship"],"answer":2,"explanation":"be동사 are 뒤, 부사 very의 수식을 받는 자리이므로 형용사가 와야 한다. friendly는 -ly로 끝나지만 '친절한'이라는 형용사이다. friend, friends, friendship은 명사라 very의 수식을 받을 수 없다.","translation":"프런트 데스크 직원들은 언제나 매우 친절하다.","part":5},{"id":"p5-368","level":1,"type":"품사","question":"The children waited ------- for the show to begin.","choices":["patient","patiently","patience","patients"],"answer":1,"explanation":"자동사 waited를 꾸미는 자리이므로 부사 patiently가 알맞다. patient는 형용사 또는 '환자'라는 명사이고, patience와 patients는 명사라 동사를 수식하지 못한다.","translation":"아이들은 공연이 시작되기를 참을성 있게 기다렸다.","part":5},{"id":"p5-369","level":1,"type":"품사","question":"We will hire a new ------- for the accounting team.","choices":["accountant","account","accounting","accounted"],"answer":0,"explanation":"a new 뒤에는 명사가 오며, 고용(hire)하는 대상은 사람이므로 '회계사'인 accountant가 정답이다. account(계좌)와 accounting(회계)은 사람이 아니고, accounted는 동사 과거형이다.","translation":"우리는 회계팀에 새 회계사를 채용할 것이다.","part":5},{"id":"p5-370","level":1,"type":"품사","question":"The ------- of the package took three days.","choices":["deliver","delivered","delivery","delivering"],"answer":2,"explanation":"관사 the와 전치사 of 사이는 주어가 되는 명사 자리이므로 delivery(배송)가 알맞다. deliver는 동사원형, delivered는 과거형·과거분사, delivering은 -ing형이라 the ~ of 구조의 명사로 쓰기 어렵다.","translation":"소포 배송은 3일이 걸렸다.","part":5},{"id":"p5-371","level":1,"type":"품사","question":"This coffee machine is very ------- to clean.","choices":["ease","easily","easiness","easy"],"answer":3,"explanation":"be동사 뒤 very의 수식을 받는 보어 자리이므로 형용사 easy가 정답이다. ease와 easiness는 명사, easily는 부사라 보어로 쓸 수 없다.","translation":"이 커피 머신은 청소하기가 아주 쉽다.","part":5},{"id":"p5-372","level":1,"type":"품사","question":"Please read this ------- letter from our customer.","choices":["important","importance","importantly","import"],"answer":0,"explanation":"지시어 this와 명사 letter 사이에서 명사를 꾸미는 형용사 자리이므로 important가 알맞다. importance는 명사, importantly는 부사, import는 명사·동사라 letter를 수식할 수 없다.","translation":"고객이 보낸 이 중요한 편지를 읽어 주세요.","part":5},{"id":"p5-373","level":1,"type":"품사","question":"Thank you for your ------- during the fire drill.","choices":["cooperate","cooperative","cooperation","cooperatively"],"answer":2,"explanation":"소유격 your 뒤에는 명사가 오므로 cooperation(협조)이 정답이다. cooperate는 동사, cooperative는 형용사, cooperatively는 부사라 소유격 뒤에 올 수 없다.","translation":"화재 대피 훈련 동안 협조해 주셔서 감사합니다.","part":5},{"id":"p5-374","level":1,"type":"동사 시제·태","question":"Ms. Okafor ------- lunch with a client yesterday.","choices":["ate","eats","will eat","eating"],"answer":0,"explanation":"yesterday(어제)가 있으므로 과거 시제 ate가 알맞다. eats는 현재, will eat은 미래라 시간 표현과 맞지 않고, eating은 동사 자리에 혼자 쓸 수 없다.","translation":"오카포르 씨는 어제 고객과 점심을 먹었다.","part":5},{"id":"p5-375","level":1,"type":"동사 시제·태","question":"Our team ------- a new product next spring.","choices":["launched","will launch","has launched","launching"],"answer":1,"explanation":"next spring(내년 봄)은 미래를 나타내므로 will launch가 정답이다. launched와 has launched는 이미 일어난 일을 나타내 미래 표현과 맞지 않고, launching은 동사 역할을 할 수 없다.","translation":"우리 팀은 내년 봄에 신제품을 출시할 것이다.","part":5},{"id":"p5-376","level":1,"type":"동사 시제·태","question":"Mr. Kovac ------- on the phone with a customer at the moment.","choices":["talks","is talking","talked","will talk"],"answer":1,"explanation":"at the moment(지금)는 현재 진행 중인 일을 나타내므로 현재진행형 is talking이 알맞다. talks는 습관, talked는 과거, will talk는 미래를 나타내 '지금'과 어울리지 않는다.","translation":"코바치 씨는 지금 고객과 통화 중이다.","part":5},{"id":"p5-377","level":1,"type":"동사 시제·태","question":"The first museum in this town ------- in 1950.","choices":["built","was built","builds","is building"],"answer":1,"explanation":"박물관은 '지어지는' 대상이고 1950년이라는 과거 시점이 있으므로 과거 수동태 was built가 정답이다. built와 builds는 능동태라 목적어가 필요하고, is building은 현재진행 능동이라 맞지 않는다.","translation":"이 마을의 첫 박물관은 1950년에 지어졌다.","part":5},{"id":"p5-378","level":1,"type":"동사 시제·태","question":"These days, Ms. Rahman usually ------- to work by subway.","choices":["went","gone","going","goes"],"answer":3,"explanation":"These days(요즘)와 usually(보통)는 현재의 습관을 나타내므로 3인칭 단수 현재형 goes가 알맞다. went는 과거라 These days와 맞지 않고, gone과 going은 혼자 동사 자리에 올 수 없다.","translation":"요즘 라만 씨는 보통 지하철로 출근한다.","part":5},{"id":"p5-379","level":1,"type":"동사 시제·태","question":"Your new sofa ------- to your home tomorrow.","choices":["delivered","delivers","will be delivered","was delivered"],"answer":2,"explanation":"소파는 '배달되는' 대상이고 tomorrow(내일)가 있으므로 미래 수동태 will be delivered가 정답이다. delivered와 delivers는 능동이며, was delivered는 과거라 tomorrow와 맞지 않는다.","translation":"새 소파는 내일 댁으로 배달될 것입니다.","part":5},{"id":"p5-380","level":1,"type":"접속사","question":"Mr. Lopez was late for work ------- his train was delayed.","choices":["but","because","or","so"],"answer":1,"explanation":"기차가 늦은 것이 지각의 '이유'이므로 because가 알맞다. but은 대조, or는 선택을 나타내고, so를 쓰면 '지각해서 기차가 늦었다'라는 반대 인과가 된다.","translation":"로페스 씨는 기차가 지연되어서 회사에 지각했다.","part":5},{"id":"p5-381","level":1,"type":"접속사","question":"------- you have any questions, please call our help desk.","choices":["If","But","So","And"],"answer":0,"explanation":"'질문이 있으면 전화하라'는 조건을 나타내므로 If가 정답이다. But, So, And는 두 절을 가운데에서 잇는 접속사라 문장 맨 앞에서 이런 조건 의미를 만들 수 없다.","translation":"질문이 있으시면 저희 안내 데스크로 전화해 주세요.","part":5},{"id":"p5-382","level":1,"type":"접속사","question":"Please wait here ------- the doctor is ready to see you.","choices":["until","but","or","so"],"answer":0,"explanation":"의사가 진료할 준비가 될 '때까지' 기다리라는 뜻이므로 until이 알맞다. but, or, so는 '기다리다'와 '준비되다' 사이의 시간 관계를 나타내지 못한다.","translation":"의사 선생님이 진료할 준비가 될 때까지 여기서 기다려 주세요.","part":5},{"id":"p5-383","level":1,"type":"접속사","question":"Ms. Brandt has worked here ------- she graduated from college.","choices":["during","for","since","ago"],"answer":2,"explanation":"빈칸 뒤에 주어와 동사(she graduated)가 있고 현재완료(has worked)가 쓰였으므로 '~한 이후로'를 뜻하는 접속사 since가 정답이다. during과 for는 전치사라 절을 이끌 수 없고, ago는 부사이다.","translation":"브란트 씨는 대학을 졸업한 이후로 이곳에서 일해 왔다.","part":5},{"id":"p5-384","level":1,"type":"전치사","question":"Please put your bags ------- your seat on the airplane.","choices":["during","since","under","until"],"answer":2,"explanation":"가방을 좌석 '아래에' 두라는 위치를 나타내므로 under가 알맞다. during, since, until은 시간을 나타내는 말이라 장소 앞에 쓸 수 없다.","translation":"비행기에서는 가방을 좌석 아래에 두세요.","part":5},{"id":"p5-385","level":1,"type":"전치사","question":"The post office is ------- the bank.","choices":["during","until","next to","since"],"answer":2,"explanation":"우체국의 위치를 나타내는 자리이므로 '~ 옆에'라는 뜻의 next to가 정답이다. during, until, since는 시간 전치사(접속사)라 장소를 나타낼 수 없다.","translation":"우체국은 은행 옆에 있다.","part":5},{"id":"p5-386","level":1,"type":"전치사","question":"Mr. Mensah walked ------- the street to the café.","choices":["across","during","since","among"],"answer":0,"explanation":"길을 '건너서' 카페로 걸어갔다는 뜻이므로 across가 알맞다. during과 since는 시간을 나타내고, among은 셋 이상의 '사이에'라는 뜻이라 street 하나와 어울리지 않는다.","translation":"멘사 씨는 길을 건너 카페로 걸어갔다.","part":5},{"id":"p5-387","level":1,"type":"전치사","question":"Ms. Anand wrote a book ------- healthy cooking.","choices":["during","until","behind","about"],"answer":3,"explanation":"책의 주제를 나타내므로 '~에 관한'이라는 뜻의 about이 정답이다. during과 until은 시간, behind는 위치를 나타내 책의 주제와 연결되지 않는다.","translation":"아난드 씨는 건강한 요리에 관한 책을 썼다.","part":5},{"id":"p5-388","level":1,"type":"준동사(to부정사·동명사·분사)","question":"We plan ------- a party for Ms. Sato's retirement.","choices":["having","had","have","to have"],"answer":3,"explanation":"plan은 to부정사를 목적어로 취하므로 to have가 알맞다. having은 동명사로 plan 뒤에 쓰지 않고, had와 have는 이미 동사 plan이 있어 또 올 수 없다.","translation":"우리는 사토 씨의 은퇴 기념 파티를 열 계획이다.","part":5},{"id":"p5-389","level":1,"type":"준동사(to부정사·동명사·분사)","question":"Mr. Obi finished ------- the report at 5 P.M.","choices":["to write","write","wrote","writing"],"answer":3,"explanation":"finish는 동명사를 목적어로 취하므로 writing이 정답이다. to write는 finish 뒤에 쓰지 않으며, write와 wrote는 동사라 finished 바로 뒤에 올 수 없다.","translation":"오비 씨는 오후 5시에 보고서 작성을 끝냈다.","part":5},{"id":"p5-390","level":1,"type":"준동사(to부정사·동명사·분사)","question":"The ------- door in the lobby needs repair.","choices":["break","broken","breaking","breaks"],"answer":1,"explanation":"명사 door를 꾸미는 자리이며, 문은 '고장 난' 상태이므로 과거분사 broken이 알맞다. break와 breaks는 동사·명사, breaking은 '깨고 있는'이라는 능동 의미라 문의 상태와 맞지 않는다.","translation":"로비에 있는 고장 난 문은 수리가 필요하다.","part":5},{"id":"p5-391","level":1,"type":"준동사(to부정사·동명사·분사)","question":"It is easy ------- the train station from here.","choices":["find","found","to find","finds"],"answer":2,"explanation":"'It is + 형용사 + to부정사' 구조에서 가주어 It의 진주어가 필요하므로 to find가 정답이다. find, found, finds는 동사 형태라 이미 is가 있는 문장에 올 수 없다.","translation":"여기서 기차역을 찾기는 쉽다.","part":5},{"id":"p5-392","level":1,"type":"관계사","question":"The bus ------- goes to the airport leaves every hour.","choices":["who","that","what","where"],"answer":1,"explanation":"선행사 The bus(사물)를 받으며 뒤에 주어가 빠진 절(goes to ...)이 오므로 주격 관계대명사 that이 알맞다. who는 사람에게 쓰고, what은 선행사를 포함하며, where는 뒤에 완전한 절이 와야 한다.","translation":"공항으로 가는 버스는 매시간 출발한다.","part":5},{"id":"p5-393","level":1,"type":"관계사","question":"Ms. Bello has a friend ------- father owns a restaurant.","choices":["who","which","whose","what"],"answer":2,"explanation":"빈칸 뒤 father가 선행사 a friend의 아버지이므로 소유격 관계대명사 whose가 정답이다. who와 which는 뒤에 주어나 목적어가 빠진 절이 와야 하는데 여기서는 완전한 절이고, what은 선행사가 있을 때 쓸 수 없다.","translation":"벨로 씨에게는 아버지가 식당을 운영하는 친구가 있다.","part":5},{"id":"p5-394","level":1,"type":"관계사","question":"Friday is the day ------- we get paid.","choices":["when","where","who","what"],"answer":0,"explanation":"선행사 the day가 시간을 나타내고 뒤에 완전한 절(we get paid)이 오므로 관계부사 when이 알맞다. where는 장소, who는 사람에 쓰며, what은 선행사와 함께 쓸 수 없다.","translation":"금요일은 우리가 급여를 받는 날이다.","part":5},{"id":"p5-395","level":1,"type":"대명사","question":"Ms. Conti, is this pen -------?","choices":["you","yours","your","yourself"],"answer":1,"explanation":"'이 펜은 당신의 것인가요?'라는 뜻으로 be동사 뒤에 '~의 것'이 와야 하므로 소유대명사 yours가 정답이다. you는 의미가 맞지 않고, your는 뒤에 명사가 필요하며, yourself는 재귀대명사이다.","translation":"콘티 씨, 이 펜이 당신 것인가요?","part":5},{"id":"p5-396","level":1,"type":"대명사","question":"Ms. Farah and ------- work in the same office.","choices":["me","my","I","mine"],"answer":2,"explanation":"빈칸은 Ms. Lee와 함께 동사 work의 주어가 되는 자리이므로 주격 I가 알맞다. me는 목적격, my는 소유격, mine은 소유대명사라 주어로 쓰기에 맞지 않는다.","translation":"파라 씨와 나는 같은 사무실에서 일한다.","part":5},{"id":"p5-397","level":1,"type":"수 일치","question":"The store's two managers ------- every Monday.","choices":["meet","meets","meeting","to meet"],"answer":0,"explanation":"주어 The store's two managers가 복수이므로 복수 동사 meet이 정답이다. meets는 단수 주어에 쓰고, meeting과 to meet은 동사 자리에 혼자 올 수 없다.","translation":"그 가게의 매니저 두 명은 매주 월요일에 만난다.","part":5},{"id":"p5-398","level":1,"type":"수 일치","question":"Everyone in the office ------- the new coffee machine.","choices":["likes","like","liking","to like"],"answer":0,"explanation":"Everyone은 단수 취급하므로 단수 동사 likes가 알맞다. like는 복수 주어에 쓰며, liking과 to like는 문장의 동사가 될 수 없다.","translation":"사무실의 모든 사람이 새 커피 머신을 좋아한다.","part":5},{"id":"p5-399","level":1,"type":"비교","question":"The blue bag is ------- than the red one.","choices":["cheap","cheapest","cheaply","cheaper"],"answer":3,"explanation":"뒤에 than이 있으므로 비교급 cheaper가 정답이다. cheap은 원급, cheapest는 최상급이라 than과 쓸 수 없고, cheaply는 부사이다.","translation":"파란 가방이 빨간 가방보다 더 싸다.","part":5},{"id":"p5-400","level":1,"type":"비교","question":"The new office is as ------- as the old one.","choices":["big","bigger","biggest","bigness"],"answer":0,"explanation":"as ~ as 원급 비교 구문이므로 사이에는 형용사 원급 big이 와야 한다. bigger와 biggest는 비교급·최상급이라 as ~ as 사이에 쓸 수 없고, bigness는 명사이다.","translation":"새 사무실은 예전 사무실만큼 크다.","part":5},{"id":"p5-401","level":2,"type":"어휘","question":"Members can ------- their reward points for gift cards at any Stellar Mart branch.","choices":["exchange","describe","arrive","borrow"],"answer":0,"explanation":"'포인트를 상품권으로 ~하다'는 exchange A for B(A를 B로 교환하다) 구문이 알맞다. describe(묘사하다)와 borrow(빌리다)는 for와 이런 의미를 만들지 못하고, arrive는 자동사라 목적어를 취할 수 없다.","translation":"회원들은 스텔라 마트 어느 지점에서나 적립 포인트를 상품권으로 교환할 수 있다.","part":5},{"id":"p5-402","level":2,"type":"어휘","question":"Each passenger may bring one piece of carry-on ------- onto the plane.","choices":["furniture","luggage","equipment","clothing"],"answer":1,"explanation":"비행기에 들고 타는 짐을 carry-on luggage(기내 수하물)라고 하므로 luggage가 정답이다. furniture(가구), equipment(장비), clothing(의류)은 carry-on과 짝을 이루어 기내 짐을 뜻하지 않는다.","translation":"승객 한 명당 기내 수하물 한 개를 비행기에 가지고 탈 수 있다.","part":5},{"id":"p5-403","level":2,"type":"어휘","question":"Ms. Vargas ------- her colleagues to a dinner at her home.","choices":["attended","visited","joined","invited"],"answer":3,"explanation":"'동료들을 자기 집 저녁 식사에 ~했다'는 invite A to B(A를 B에 초대하다) 구문이므로 invited가 알맞다. attended, visited, joined는 사람을 목적어로 두고 'to 행사'로 이어지는 초대의 의미를 만들지 못한다.","translation":"바르가스 씨는 동료들을 자기 집 저녁 식사에 초대했다.","part":5},{"id":"p5-404","level":2,"type":"어휘","question":"The ------- for the new position include a university degree and two years of experience.","choices":["receipts","directions","requirements","reservations"],"answer":2,"explanation":"학위와 2년 경력은 직책의 '자격 요건'이므로 requirements가 정답이다. receipts(영수증), directions(길 안내), reservations(예약)는 채용 조건을 나타내지 않는다.","translation":"새 직책의 자격 요건에는 대학 학위와 2년 경력이 포함된다.","part":5},{"id":"p5-405","level":2,"type":"어휘","question":"Please keep the ------- in case you want to return the item.","choices":["agenda","receipt","schedule","license"],"answer":1,"explanation":"물건을 반품할 때 필요한 것은 영수증이므로 receipt가 알맞다. agenda(안건), schedule(일정), license(면허)는 반품과 관련이 없다.","translation":"물건을 반품하고 싶으실 경우를 대비해 영수증을 보관해 주세요.","part":5},{"id":"p5-406","level":2,"type":"어휘","question":"The bus was very ------- this morning, so many passengers had to stand.","choices":["empty","quiet","crowded","early"],"answer":2,"explanation":"많은 승객이 서 있어야 했던 이유이므로 버스가 '붐볐다'는 crowded가 정답이다. empty(텅 빈)와 quiet(조용한)는 결과와 모순되고, early(이른)는 서서 가야 하는 이유가 되지 않는다.","translation":"오늘 아침 버스가 매우 붐벼서 많은 승객이 서서 가야 했다.","part":5},{"id":"p5-407","level":2,"type":"어휘","question":"The new concert hall has ------- for up to 2,000 people.","choices":["lighting","seating","catering","heating"],"answer":1,"explanation":"공연장이 최대 2,000명을 수용할 수 있는 것은 '좌석'이므로 seating이 알맞다. lighting(조명), catering(출장 요리), heating(난방)은 인원수와 연결해 수용 규모를 나타내지 않는다.","translation":"새 공연장에는 최대 2,000명이 앉을 수 있는 좌석이 있다.","part":5},{"id":"p5-408","level":2,"type":"어휘","question":"Mr. Horvath's flight from Budapest is scheduled to ------- at 7 P.M.","choices":["land","pack","book","miss"],"answer":0,"explanation":"비행기가 오후 7시에 '착륙하다'라는 뜻이 자연스러우므로 land가 정답이다. pack(짐을 싸다), book(예약하다), miss(놓치다)는 타동사로 목적어가 필요하고 비행기가 주어일 때 의미가 맞지 않는다.","translation":"부다페스트에서 오는 호르바트 씨의 항공편은 오후 7시에 착륙할 예정이다.","part":5},{"id":"p5-409","level":2,"type":"어휘","question":"For security reasons, please ------- your old password with a new one.","choices":["collect","attach","replace","enter"],"answer":2,"explanation":"replace A with B는 'A를 B로 교체하다'라는 뜻이므로 replace가 알맞다. collect(모으다), attach(첨부하다), enter(입력하다)는 with a new one과 결합해 '새것으로 바꾸다'라는 의미를 만들지 못한다.","translation":"보안상의 이유로 예전 비밀번호를 새 비밀번호로 바꿔 주세요.","part":5},{"id":"p5-410","level":2,"type":"어휘","question":"This discount coupon is ------- only until the end of the month.","choices":["eager","aware","valid","polite"],"answer":2,"explanation":"쿠폰이 월말까지만 '유효하다'라는 뜻이므로 valid가 정답이다. eager(열망하는), aware(알고 있는), polite(예의 바른)는 사람의 태도·상태를 나타내 쿠폰과 어울리지 않는다.","translation":"이 할인 쿠폰은 이달 말까지만 유효하다.","part":5},{"id":"p5-411","level":2,"type":"어휘","question":"Ms. Kaplan is a ------- customer who has shopped at our store for 20 years.","choices":["loyal","sudden","narrow","empty"],"answer":0,"explanation":"20년 동안 꾸준히 쇼핑해 온 고객은 '충성스러운 단골' 고객이므로 loyal이 알맞다. sudden(갑작스러운), narrow(좁은), empty(비어 있는)는 고객을 묘사하는 말로 맞지 않는다.","translation":"캐플런 씨는 20년 동안 우리 가게에서 쇼핑해 온 단골 고객이다.","part":5},{"id":"p5-412","level":2,"type":"어휘","question":"The Wi-Fi password is ------- on the back of your room key card.","choices":["folded","printed","washed","grown"],"answer":1,"explanation":"비밀번호가 카드 뒷면에 '인쇄되어' 있다는 뜻이므로 printed가 정답이다. folded(접힌), washed(씻긴), grown(재배된)은 글자나 번호가 카드에 표시된 상태를 나타내지 못한다.","translation":"와이파이 비밀번호는 객실 키 카드 뒷면에 인쇄되어 있다.","part":5},{"id":"p5-413","level":2,"type":"품사","question":"Mr. Ansah is ------- of leading the new research project.","choices":["capable","capability","capably","capacity"],"answer":0,"explanation":"be동사 뒤 보어 자리이며 be capable of(~할 능력이 있다)라는 표현이므로 형용사 capable이 정답이다. capability와 capacity는 명사라 주어와 동격이 되지 않고, capably는 부사라 보어가 될 수 없다.","translation":"안사 씨는 새 연구 프로젝트를 이끌 능력이 있다.","part":5},{"id":"p5-414","level":2,"type":"품사","question":"The ------- of the new bridge will begin in March.","choices":["construction","construct","constructive","constructed"],"answer":0,"explanation":"관사 the와 of 사이 주어 자리이므로 명사 construction(건설)이 알맞다. construct는 동사, constructive는 형용사, constructed는 과거분사라 주어가 될 수 없다.","translation":"새 다리 건설은 3월에 시작될 것이다.","part":5},{"id":"p5-415","level":2,"type":"품사","question":"The bookstore offers a ------- selection of travel guides.","choices":["wide","widely","width","widen"],"answer":0,"explanation":"관사 a와 명사 selection 사이에서 명사를 꾸미는 형용사 자리이므로 wide가 정답이다. widely는 부사, width는 명사, widen은 동사라 명사를 수식하지 못한다.","translation":"그 서점은 다양한 여행 안내서를 갖추고 있다.","part":5},{"id":"p5-416","level":2,"type":"품사","question":"Our marketing team will ------- the survey results next week.","choices":["analysis","analyze","analytical","analyst"],"answer":1,"explanation":"조동사 will 뒤에는 동사원형이 오므로 analyze가 알맞다. analysis와 analyst는 명사, analytical은 형용사라 동사 자리에 올 수 없다.","translation":"우리 마케팅팀은 다음 주에 설문 조사 결과를 분석할 것이다.","part":5},{"id":"p5-417","level":2,"type":"품사","question":"The instructions for the new software are written -------.","choices":["simple","simplify","simplicity","simply"],"answer":3,"explanation":"수동태 are written 뒤에서 동사를 꾸미는 자리이므로 부사 simply가 정답이다. simple은 형용사, simplify는 동사, simplicity는 명사라 동사를 수식할 수 없다.","translation":"새 소프트웨어의 설명서는 간단하게 쓰여 있다.","part":5},{"id":"p5-418","level":2,"type":"품사","question":"Visitors must show a valid form of ------- at the security desk.","choices":["identify","identification","identifiable","identified"],"answer":1,"explanation":"전치사 of 뒤에는 명사가 오므로 identification(신분증, 신원 확인)이 알맞다. identify는 동사, identifiable은 형용사, identified는 과거분사라 전치사의 목적어가 될 수 없다.","translation":"방문객은 보안 데스크에서 유효한 신분증을 제시해야 한다.","part":5},{"id":"p5-419","level":2,"type":"품사","question":"Weather forecasts for the mountain region are not always -------.","choices":["accuracy","accurately","accurate","accurateness"],"answer":2,"explanation":"be동사 are 뒤 보어 자리로 주어의 성질을 설명하므로 형용사 accurate가 정답이다. accuracy와 accurateness는 명사라 '예보=정확성'이 되어 어색하고, accurately는 부사라 보어가 될 수 없다.","translation":"산간 지역의 일기 예보가 항상 정확한 것은 아니다.","part":5},{"id":"p5-420","level":2,"type":"품사","question":"Ms. Fischer ------- recommended the new Thai restaurant to her coworkers.","choices":["high","height","higher","highly"],"answer":3,"explanation":"동사 recommended를 꾸미는 부사 자리이며 highly recommend는 '적극 추천하다'라는 표현이므로 highly가 알맞다. high와 higher는 형용사(또는 부사로는 '높이'라는 물리적 의미), height는 명사라 이 의미를 만들지 못한다.","translation":"피셔 씨는 새로 생긴 태국 음식점을 동료들에게 적극 추천했다.","part":5},{"id":"p5-421","level":2,"type":"품사","question":"The hotel received several ------- about the noise from the construction site.","choices":["complain","complaints","complained","complaining"],"answer":1,"explanation":"several 뒤에는 복수 명사가 오고 동사 received의 목적어 자리이므로 complaints가 정답이다. complain은 동사, complained는 과거형, complaining은 -ing형이라 several 뒤에 올 수 없다.","translation":"호텔은 공사 현장 소음에 대해 여러 건의 불만을 접수했다.","part":5},{"id":"p5-422","level":2,"type":"품사","question":"A sales ------- will contact you within 24 hours.","choices":["represent","represented","representing","representative"],"answer":3,"explanation":"관사 A와 명사 sales 뒤에서 주어가 되는 명사 자리이며, 연락하는 주체는 사람이므로 representative(직원, 대리인)가 알맞다. represent는 동사, represented와 representing은 동사 변화형이라 주어가 될 수 없다.","translation":"영업 담당자가 24시간 안에 연락드릴 것입니다.","part":5},{"id":"p5-423","level":2,"type":"품사","question":"The outdoor tour was ------- canceled because of the storm.","choices":["unexpected","expect","expectation","unexpectedly"],"answer":3,"explanation":"be동사와 과거분사 canceled 사이에서 동사를 꾸미는 자리이므로 부사 unexpectedly가 정답이다. unexpected는 형용사, expect는 동사, expectation은 명사라 이 자리에 들어갈 수 없다.","translation":"야외 투어는 폭풍 때문에 예기치 않게 취소되었다.","part":5},{"id":"p5-424","level":2,"type":"동사 시제·태","question":"The two companies ------- business partners since 2012.","choices":["were","are","will be","have been"],"answer":3,"explanation":"since 2012(2012년 이후로)는 과거부터 현재까지 이어지는 기간을 나타내므로 현재완료 have been이 알맞다. were는 과거, are는 현재, will be는 미래라 since와 함께 쓸 수 없다.","translation":"두 회사는 2012년부터 사업 파트너로 지내 왔다.","part":5},{"id":"p5-425","level":2,"type":"동사 시제·태","question":"New employees ------- a tour of the factory tomorrow morning.","choices":["gave","have given","will be given","were giving"],"answer":2,"explanation":"신입 사원은 투어를 '제공받는' 입장이고 tomorrow morning이 있으므로 미래 수동태 will be given이 정답이다. gave, have given, were giving은 능동이면서 과거·완료 시제라 내일과 맞지 않는다.","translation":"신입 사원들은 내일 아침 공장 견학을 하게 될 것이다.","part":5},{"id":"p5-426","level":2,"type":"동사 시제·태","question":"When I called Ms. Quach, she ------- a meeting with her team.","choices":["has","was having","will have","have"],"answer":1,"explanation":"'내가 전화했을 때(과거 시점)' 진행 중이던 일을 나타내므로 과거진행형 was having이 알맞다. has와 have는 현재, will have는 미래라 과거 시점과 맞지 않으며 have는 주어 she와 수도 맞지 않는다.","translation":"내가 꾸악 씨에게 전화했을 때 그녀는 팀과 회의 중이었다.","part":5},{"id":"p5-427","level":2,"type":"동사 시제·태","question":"The winners of the photo contest ------- on our Web site last Friday.","choices":["were announced","announced","will announce","are announcing"],"answer":0,"explanation":"수상자는 '발표되는' 대상이고 last Friday가 있으므로 과거 수동태 were announced가 정답이다. announced는 능동이라 목적어가 필요하고, will announce와 are announcing은 시제와 태가 모두 맞지 않는다.","translation":"사진 공모전 수상자들은 지난 금요일 우리 웹사이트에 발표되었다.","part":5},{"id":"p5-428","level":2,"type":"동사 시제·태","question":"Ms. Adler ------- the budget report before she left for vacation.","choices":["finishes","finished","will finish","finishing"],"answer":1,"explanation":"before she left라는 과거 시점 이전의 일이므로 과거 시제 finished가 알맞다. finishes는 현재, will finish는 미래라 과거 상황과 맞지 않고, finishing은 동사 자리에 혼자 올 수 없다.","translation":"애들러 씨는 휴가를 떠나기 전에 예산 보고서를 끝냈다.","part":5},{"id":"p5-429","level":2,"type":"동사 시제·태","question":"Ridgeway Outlet ------- its biggest sale of the year every July.","choices":["holding","is held","to hold","holds"],"answer":3,"explanation":"every July는 매년 반복되는 일을 나타내므로 현재 시제이고, 주어가 할인 행사를 '여는' 주체이며 뒤에 목적어가 있으므로 능동 holds가 정답이다. is held는 수동태라 목적어를 취할 수 없고, holding과 to hold는 동사 자리에 올 수 없다.","translation":"리지웨이 아웃렛은 매년 7월에 연중 가장 큰 할인 행사를 연다.","part":5},{"id":"p5-430","level":2,"type":"접속사","question":"------- it was raining, the tour group visited the old castle.","choices":["Because","Even though","Unless","So"],"answer":1,"explanation":"비가 오는데도 견학을 갔다는 양보의 의미이므로 Even though가 알맞다. Because는 이유, Unless는 '~하지 않는 한'이라 뜻이 맞지 않고, So는 문장 맨 앞에서 종속절을 이끌 수 없다.","translation":"비가 오고 있었지만 여행단은 옛 성을 방문했다.","part":5},{"id":"p5-431","level":2,"type":"접속사","question":"------- Mr. Chu was sick, he could not attend the seminar.","choices":["As","Though","Unless","Or"],"answer":0,"explanation":"아파서 세미나에 참석하지 못했다는 이유를 나타내므로 '~ 때문에'라는 뜻의 접속사 As가 정답이다. Though는 양보, Unless는 조건이라 의미가 맞지 않고, Or는 문장 맨 앞에서 부사절을 이끌 수 없다.","translation":"추 씨는 아팠기 때문에 세미나에 참석할 수 없었다.","part":5},{"id":"p5-432","level":2,"type":"접속사","question":"The Casa Verde Inn has only twelve rooms, ------- it attracts guests from all over the world.","choices":["so","because","unless","yet"],"answer":3,"explanation":"객실이 12개뿐이지만 전 세계에서 손님이 온다는 대조의 흐름이므로 '그런데도'라는 뜻의 등위접속사 yet이 알맞다. so는 결과, because는 이유, unless는 조건을 나타내 앞뒤 내용의 대조를 표현하지 못한다.","translation":"카사 베르데 인은 객실이 12개뿐이지만 전 세계에서 손님이 찾아온다.","part":5},{"id":"p5-433","level":2,"type":"접속사","question":"Mr. Singh updates the delivery schedule ------- a new order comes in.","choices":["whenever","however","whatever","wherever"],"answer":0,"explanation":"'새 주문이 들어올 때마다' 일정을 갱신한다는 뜻이므로 whenever가 정답이다. however는 '아무리 ~해도', whatever는 '무엇이든', wherever는 '어디든'이라 시간의 반복을 나타내지 못한다.","translation":"싱 씨는 새 주문이 들어올 때마다 배송 일정을 갱신한다.","part":5},{"id":"p5-434","level":2,"type":"전치사","question":"Cherry trees have been planted ------- the river.","choices":["during","since","between","along"],"answer":3,"explanation":"강을 '따라' 나무가 심어져 있다는 뜻이므로 along이 알맞다. during과 since는 시간을 나타내고, between은 두 대상 사이를 나타내 river 하나만 있을 때 쓸 수 없다.","translation":"강을 따라 벚나무가 심어져 있다.","part":5},{"id":"p5-435","level":2,"type":"전치사","question":"The flight to Lisbon was canceled ------- bad weather.","choices":["because","due to","although","despite"],"answer":1,"explanation":"뒤에 명사구 bad weather가 오고 취소의 '이유'를 나타내므로 전치사 due to가 정답이다. because와 although는 접속사라 절이 필요하고, despite는 '~에도 불구하고'라는 뜻이라 의미가 맞지 않는다.","translation":"리스본행 항공편은 악천후로 취소되었다.","part":5},{"id":"p5-436","level":2,"type":"전치사","question":"Visitors must enter the stadium ------- the main gate.","choices":["through","among","during","onto"],"answer":0,"explanation":"정문을 '통과하여' 들어간다는 뜻이므로 through가 알맞다. among은 셋 이상 사이, during은 기간, onto는 '~ 위로'라 문을 통해 들어가는 의미를 나타내지 못한다.","translation":"방문객은 정문을 통해 경기장에 입장해야 한다.","part":5},{"id":"p5-437","level":2,"type":"전치사","question":"The new team leader is very popular ------- the staff.","choices":["between","during","among","onto"],"answer":2,"explanation":"여러 직원(the staff)들 '사이에서' 인기가 있다는 뜻이므로 among이 정답이다. between은 보통 둘 사이에 쓰고, during은 기간, onto는 방향을 나타내 의미가 맞지 않는다.","translation":"새 팀장은 직원들 사이에서 인기가 아주 많다.","part":5},{"id":"p5-438","level":2,"type":"준동사(to부정사·동명사·분사)","question":"Ms. Chandra avoided ------- during rush hour.","choices":["to drive","drive","driving","drove"],"answer":2,"explanation":"avoid는 동명사를 목적어로 취하므로 driving이 알맞다. to drive는 avoid 뒤에 쓰지 않고, drive와 drove는 이미 동사 avoided가 있어 올 수 없다.","translation":"찬드라 씨는 출퇴근 시간대에 운전하는 것을 피했다.","part":5},{"id":"p5-439","level":2,"type":"준동사(to부정사·동명사·분사)","question":"The staff were ------- about the move to the new office.","choices":["excited","exciting","excite","excitement"],"answer":0,"explanation":"주어 The staff가 '신이 난' 감정을 느끼는 것이므로 과거분사 excited가 정답이다. exciting은 감정을 불러일으키는 대상에 쓰고, excite는 동사, excitement는 명사라 be동사 뒤 보어로 맞지 않는다.","translation":"직원들은 새 사무실로의 이전에 들떠 있었다.","part":5},{"id":"p5-440","level":2,"type":"준동사(to부정사·동명사·분사)","question":"Mr. Sanchez asked his assistant ------- the meeting room for Thursday.","choices":["booking","book","to book","booked"],"answer":2,"explanation":"ask + 목적어 + to부정사는 '~에게 …해 달라고 부탁하다'라는 구문이므로 to book이 알맞다. booking, book, booked는 ask 목적어 뒤 목적격 보어 형태로 쓰지 않는다.","translation":"산체스 씨는 비서에게 목요일에 쓸 회의실을 예약해 달라고 부탁했다.","part":5},{"id":"p5-441","level":2,"type":"준동사(to부정사·동명사·분사)","question":"The man ------- next to Ms. Lindahl is our new chief executive.","choices":["sits","sat","to sit","sitting"],"answer":3,"explanation":"문장의 동사는 is이므로 빈칸은 The man을 뒤에서 꾸미는 자리이다. 남자가 '앉아 있는' 능동 상태이므로 현재분사 sitting이 정답이다. sits와 sat은 동사라 동사가 두 개가 되고, to sit은 '앉을'이라는 미래 의미라 어색하다.","translation":"린달 씨 옆에 앉아 있는 남자가 우리의 새 최고 경영자이다.","part":5},{"id":"p5-442","level":2,"type":"관계사","question":"Nobody knows the reason ------- the store closed early yesterday.","choices":["what","which","who","why"],"answer":3,"explanation":"선행사 the reason 뒤에 완전한 절(the store closed early)이 오므로 이유를 나타내는 관계부사 why가 알맞다. what은 선행사와 함께 쓸 수 없고, which와 who는 뒤에 주어나 목적어가 빠진 절이 와야 한다.","translation":"어제 가게가 일찍 문을 닫은 이유를 아무도 모른다.","part":5},{"id":"p5-443","level":2,"type":"관계사","question":"The client with ------- Mr. Obeid met yesterday wants to sign a new contract.","choices":["who","which","whom","whose"],"answer":2,"explanation":"전치사 with 뒤에서 사람 선행사 The client를 받는 목적격 관계대명사는 whom이다. 전치사 바로 뒤에는 who를 쓰지 않고, which는 사물에, whose는 뒤에 명사가 필요할 때 쓴다.","translation":"오베이드 씨가 어제 만난 고객이 새 계약을 맺고 싶어 한다.","part":5},{"id":"p5-444","level":2,"type":"대명사","question":"Ms. Hill's laptop is newer than -------.","choices":["me","mine","my","I"],"answer":1,"explanation":"힐 씨의 노트북과 '나의 노트북'을 비교하므로 소유대명사 mine(= my laptop)이 정답이다. me와 I는 사람 자체를 가리켜 노트북과 비교가 되지 않고, my는 뒤에 명사가 필요하다.","translation":"힐 씨의 노트북은 내 것보다 더 최신이다.","part":5},{"id":"p5-445","level":2,"type":"대명사","question":"Please help ------- to coffee and snacks in the lounge.","choices":["yourself","you","your","yours"],"answer":0,"explanation":"help oneself to는 '~을 마음껏 드시다'라는 표현으로, 명령문의 생략된 주어 you와 목적어가 같으므로 재귀대명사 yourself가 알맞다. you, your, yours는 이 관용 표현을 만들지 못한다.","translation":"라운지에 있는 커피와 간식을 마음껏 드세요.","part":5},{"id":"p5-446","level":2,"type":"대명사","question":"All of the rooms face the sea, and ------- has its own balcony.","choices":["each","all","both","these"],"answer":0,"explanation":"빈칸 뒤 동사가 단수형 has이고 its own이 쓰였으므로 단수 대명사 each(각각)가 정답이다. all, both, these는 복수로 쓰여 has와 수가 맞지 않는다.","translation":"모든 객실은 바다를 향해 있고, 각 객실에는 전용 발코니가 있다.","part":5},{"id":"p5-447","level":2,"type":"수 일치","question":"The books on the top shelf ------- to Ms. Sato.","choices":["belongs","belong","belonging","to belong"],"answer":1,"explanation":"주어의 핵심은 The books(복수)이며 on the top shelf는 수식어이므로 복수 동사 belong이 알맞다. belongs는 shelf에 수를 맞춘 오답이고, belonging과 to belong은 동사 자리에 올 수 없다.","translation":"맨 위 선반에 있는 책들은 사토 씨의 것이다.","part":5},{"id":"p5-448","level":2,"type":"수 일치","question":"Every room in the hotel ------- a coffee maker and a small refrigerator.","choices":["have","having","has","to have"],"answer":2,"explanation":"Every + 단수 명사는 단수 취급하므로 단수 동사 has가 정답이다. have는 복수 주어에 쓰고, having과 to have는 문장의 동사가 될 수 없다.","translation":"그 호텔의 모든 객실에는 커피 메이커와 소형 냉장고가 있다.","part":5},{"id":"p5-449","level":2,"type":"비교","question":"This year's sales were ------- than last year's.","choices":["high","highest","highly","higher"],"answer":3,"explanation":"뒤에 than이 있으므로 비교급 higher가 알맞다. high는 원급, highest는 최상급이라 than과 쓰지 않고, highly는 '매우'라는 뜻의 부사라 보어 자리에 맞지 않는다.","translation":"올해 매출은 작년보다 더 높았다.","part":5},{"id":"p5-450","level":2,"type":"비교","question":"The Saturday night market is the ------- popular event in our town.","choices":["more","much","most","very"],"answer":2,"explanation":"앞에 the가 있고 in our town이라는 범위가 있으므로 최상급을 만드는 most가 정답이다. more는 비교급이라 than이 필요하고, much와 very는 the ~ popular 사이에서 최상급을 만들지 못한다.","translation":"토요일 야시장은 우리 마을에서 가장 인기 있는 행사이다.","part":5},{"id":"p5-451","level":3,"type":"어휘","question":"The Kessler plant in Stuttgart ------- more than 3,000 tires each day for export.","choices":["attends","hires","invites","manufactures"],"answer":3,"explanation":"공장(plant)이 매일 타이어 3,000개 이상을 '생산한다'는 뜻이므로 manufactures가 알맞다. attends(참석하다), hires(고용하다), invites(초대하다)는 타이어를 목적어로 쓸 수 없다.","translation":"슈투트가르트의 케슬러 공장은 매일 수출용 타이어를 3,000개 넘게 생산한다.","part":5},{"id":"p5-452","level":3,"type":"어휘","question":"The two-hour seminar will ------- how small businesses can build a strong online presence.","choices":["explain","attend","agree","arrive"],"answer":0,"explanation":"세미나가 '어떻게 온라인 입지를 다질 수 있는지'를 설명한다는 의미이므로 명사절 how ~를 목적어로 취하는 explain이 정답이다. attend는 how절을 목적어로 쓰지 않고, agree와 arrive는 자동사라 바로 목적어를 둘 수 없다.","translation":"두 시간짜리 세미나에서는 소규모 업체가 어떻게 탄탄한 온라인 입지를 구축할 수 있는지 설명할 것이다.","part":5},{"id":"p5-453","level":3,"type":"어휘","question":"Ms. Takahashi received a ------- for her outstanding sales performance this quarter.","choices":["fare","fee","toll","bonus"],"answer":3,"explanation":"뛰어난 영업 실적에 대한 보상으로 받는 것은 bonus(상여금)이다. fare(운임), fee(수수료), toll(통행료)은 모두 지불하는 요금이라 실적 보상의 의미가 없다.","translation":"다카하시 씨는 이번 분기의 뛰어난 영업 실적으로 상여금을 받았다.","part":5},{"id":"p5-454","level":3,"type":"어휘","question":"The restaurant's new spring menu ------- several vegetarian dishes.","choices":["reminds","features","applies","delays"],"answer":1,"explanation":"메뉴가 채식 요리를 '특별히 포함한다, 선보인다'는 의미이므로 features가 알맞다. reminds(상기시키다), applies(적용하다·지원하다), delays(지연시키다)는 메뉴와 요리의 관계를 나타내지 못한다.","translation":"그 식당의 새 봄 메뉴에는 채식 요리가 여러 가지 있다.","part":5},{"id":"p5-455","level":3,"type":"어휘","question":"Last week's storm caused ------- damage to the coastal warehouses.","choices":["eager","polite","severe","punctual"],"answer":2,"explanation":"damage(피해)를 수식해 '심각한 피해'를 나타내는 severe가 정답이다. eager(열렬한), polite(공손한), punctual(시간을 잘 지키는)은 사람의 성질이라 피해를 꾸미지 않는다.","translation":"지난주 폭풍은 해안 창고들에 심각한 피해를 입혔다.","part":5},{"id":"p5-456","level":3,"type":"어휘","question":"Our accounting firm ------- small businesses with tax preparation.","choices":["assists","prevents","informs","relies"],"answer":0,"explanation":"assist A with B는 'A가 B하는 것을 돕다'라는 뜻으로 문맥에 맞는다. prevents는 from과, informs는 of/about과 함께 쓰고, relies는 on이 필요한 자동사라 이 구조에 맞지 않는다.","translation":"우리 회계 법인은 소규모 업체의 세무 신고 준비를 돕는다.","part":5},{"id":"p5-457","level":3,"type":"어휘","question":"Zenith Apparel's ------- has been moved to a larger building downtown.","choices":["ingredients","belongings","surroundings","headquarters"],"answer":3,"explanation":"회사의 무엇이 더 큰 건물로 옮겨졌는지 묻고 있으므로 headquarters(본사)가 알맞다. ingredients(재료), belongings(소지품), surroundings(환경)는 회사가 건물을 옮기는 대상으로 어울리지 않는다.","translation":"제니스 어패럴의 본사는 시내의 더 큰 건물로 이전했다.","part":5},{"id":"p5-458","level":3,"type":"어휘","question":"Mr. Ramos was hired as a ------- to help the hospital reduce its operating costs.","choices":["consultant","tenant","passenger","resident"],"answer":0,"explanation":"비용 절감을 돕기 위해 고용된 사람은 consultant(자문 위원)이다. tenant(세입자), passenger(승객), resident(주민)는 고용되어 조언하는 직무를 나타내지 않는다.","translation":"라모스 씨는 병원의 운영비 절감을 돕기 위해 자문 위원으로 채용되었다.","part":5},{"id":"p5-459","level":3,"type":"어휘","question":"Due to high demand, tickets for the jazz festival were ------- out within an hour.","choices":["run","sold","given","turned"],"answer":1,"explanation":"be sold out은 '매진되다'라는 뜻으로 높은 수요의 결과에 맞는다. run out은 자동사 표현이라 be run out 형태로 쓰지 않고, be given out(배부되다)과 be turned out(쫓겨나다)은 수요가 많아서 생긴 결과로 맞지 않는다.","translation":"높은 수요로 인해 재즈 축제 표는 한 시간 만에 매진되었다.","part":5},{"id":"p5-460","level":3,"type":"어휘","question":"Employees must ------- their travel expense reports by the fifth of each month.","choices":["submit","appear","occur","belong"],"answer":0,"explanation":"보고서를 기한까지 '제출하다'라는 뜻의 타동사 submit이 정답이다. appear, occur, belong은 모두 자동사라 목적어 reports를 바로 취할 수 없다.","translation":"직원들은 매달 5일까지 출장 경비 보고서를 제출해야 한다.","part":5},{"id":"p5-461","level":3,"type":"어휘","question":"The Bayside Hotel offers a free airport ------- service for all of its guests.","choices":["shuttle","crew","gate","terminal"],"answer":0,"explanation":"호텔이 투숙객에게 무료로 제공하는 공항 교통편은 airport shuttle service(공항 셔틀 서비스)이다. crew(승무원), gate(탑승구), terminal(터미널)은 호텔이 제공하는 서비스가 아니다.","translation":"베이사이드 호텔은 모든 투숙객에게 무료 공항 셔틀 서비스를 제공한다.","part":5},{"id":"p5-462","level":3,"type":"어휘","question":"The new policy will ------- employees to work from home two days a week.","choices":["let","allow","make","have"],"answer":1,"explanation":"빈칸 뒤에 목적어 + to부정사(employees to work)가 오므로 이 구조를 취하는 allow가 정답이다. let, make, have는 사역동사로 목적어 뒤에 to 없는 동사원형을 쓴다.","translation":"새 정책은 직원들이 일주일에 이틀 재택근무를 할 수 있게 해 줄 것이다.","part":5},{"id":"p5-463","level":3,"type":"품사","question":"The branch manager handled the customer's complaint -------.","choices":["professional","profession","professionally","professionalism"],"answer":2,"explanation":"목적어까지 갖춘 완전한 문장 뒤에서 동사 handled를 꾸미는 자리이므로 부사 professionally가 알맞다. professional은 형용사·명사, profession과 professionalism은 명사라 동사를 수식하지 못한다.","translation":"지점장은 고객의 불만을 전문적으로 처리했다.","part":5},{"id":"p5-464","level":3,"type":"품사","question":"Mr. Kovalenko's ------- to the project was greatly appreciated by the team.","choices":["contribution","contribute","contributor","contributed"],"answer":0,"explanation":"소유격 뒤 주어 자리이므로 명사가 와야 하며, '프로젝트에 대한 기여'가 감사받은 것이므로 contribution이 정답이다. contributor는 사람이라 소유격 사람과 겹쳐 의미가 어색하고, contribute와 contributed는 동사이다.","translation":"코발렌코 씨의 프로젝트 기여에 팀 전체가 크게 고마워했다.","part":5},{"id":"p5-465","level":3,"type":"품사","question":"Harlow Logistics is ------- expanding its operations in Southeast Asia.","choices":["rapidly","rapid","rapidity","rapidness"],"answer":0,"explanation":"진행형 is expanding 사이에서 동사를 꾸미는 자리이므로 부사 rapidly가 알맞다. rapid는 형용사, rapidity와 rapidness는 명사라 동사를 수식할 수 없다.","translation":"할로 물류는 동남아시아에서 사업을 빠르게 확장하고 있다.","part":5},{"id":"p5-466","level":3,"type":"품사","question":"Customers can choose from a ------- of payment options at checkout.","choices":["variety","various","vary","variously"],"answer":0,"explanation":"관사 a와 전치사 of 사이는 명사 자리이며, a variety of는 '다양한'이라는 표현이므로 variety가 정답이다. various는 형용사, vary는 동사, variously는 부사라 이 자리에 올 수 없다.","translation":"고객은 계산할 때 다양한 결제 방법 중에서 선택할 수 있다.","part":5},{"id":"p5-467","level":3,"type":"품사","question":"Ms. Oduya's workshop on contract law was clear and -------.","choices":["inform","information","informatively","informative"],"answer":3,"explanation":"and로 형용사 clear와 나란히 연결되는 보어 자리이므로 형용사 informative가 알맞다. inform은 동사, information은 명사, informatively는 부사라 clear와 대등하게 연결될 수 없다.","translation":"오두야 씨의 계약법 워크숍은 명확하고 유익했다.","part":5},{"id":"p5-468","level":3,"type":"품사","question":"The HR director will ------- the new leave policy at Friday's meeting.","choices":["clarify","clarity","clarification","clarified"],"answer":0,"explanation":"조동사 will 뒤에는 동사원형이 오므로 clarify가 정답이다. clarity와 clarification은 명사, clarified는 과거형·과거분사라 will 뒤에 쓸 수 없다.","translation":"인사 이사는 금요일 회의에서 새 휴가 정책을 명확히 설명할 것이다.","part":5},{"id":"p5-469","level":3,"type":"품사","question":"All ------- to the chemical plant must wear safety glasses.","choices":["visit","visitors","visited","visiting"],"answer":1,"explanation":"All 뒤에서 문장의 주어가 되며 보안경을 착용해야 하는 사람을 나타내므로 명사 visitors가 알맞다. visit은 '방문'이라는 뜻이라 보안경을 쓸 수 없고, visited와 visiting은 수식할 명사가 없다.","translation":"화학 공장의 모든 방문객은 보안경을 착용해야 한다.","part":5},{"id":"p5-470","level":3,"type":"품사","question":"Chef Dimitriou's first cookbook has been ------- successful.","choices":["huge","hugeness","hug","hugely"],"answer":3,"explanation":"has been과 형용사 successful 사이에서 형용사를 꾸미는 자리이므로 부사 hugely가 정답이다. huge는 형용사라 다른 형용사를 꾸미지 못하고, hugeness는 명사, hug는 동사·명사이다.","translation":"디미트리우 셰프의 첫 요리책은 크게 성공했다.","part":5},{"id":"p5-471","level":3,"type":"품사","question":"Please make sure that your online banking password is -------.","choices":["security","secure","securely","securing"],"answer":1,"explanation":"be동사 is 뒤 보어 자리로 비밀번호의 상태를 설명하므로 형용사 secure가 알맞다. security는 명사라 '비밀번호=보안'이 되어 어색하고, securely는 부사, securing은 목적어가 필요한 -ing형이다.","translation":"온라인 뱅킹 비밀번호가 안전한지 꼭 확인해 주세요.","part":5},{"id":"p5-472","level":3,"type":"품사","question":"There has been a steady ------- in online sales since January.","choices":["grow","grown","growth","growing"],"answer":2,"explanation":"관사 a와 형용사 steady 뒤는 명사 자리이므로 growth가 정답이다. grow는 동사, grown은 과거분사, growing은 형용사·동명사라 steady의 꾸밈을 받는 명사로 쓰지 않는다.","translation":"1월 이후 온라인 매출이 꾸준히 증가해 왔다.","part":5},{"id":"p5-473","level":3,"type":"품사","question":"The mayor spoke ------- about the city's plans for the new waterfront park.","choices":["enthusiastically","enthusiastic","enthusiasm","enthusiast"],"answer":0,"explanation":"자동사 spoke를 꾸미는 부사 자리이므로 enthusiastically가 알맞다. enthusiastic은 형용사, enthusiasm과 enthusiast는 명사라 동사를 수식할 수 없다.","translation":"시장은 새 수변 공원에 관한 시의 계획을 열정적으로 이야기했다.","part":5},{"id":"p5-474","level":3,"type":"동사 시제·태","question":"Ms. Ferreira ------- at the Lisbon branch until she transferred to Madrid last year.","choices":["has worked","worked","works","will work"],"answer":1,"explanation":"until she transferred last year는 과거에 끝난 기간이므로 과거 시제 worked가 정답이다. has worked는 현재까지 이어지는 일에 쓰고, works와 will work는 현재·미래라 과거 기간과 맞지 않는다.","translation":"페헤이라 씨는 작년에 마드리드로 전근하기 전까지 리스본 지점에서 일했다.","part":5},{"id":"p5-475","level":3,"type":"동사 시제·태","question":"The revised safety manual ------- to all employees by next Monday.","choices":["distributed","has distributed","is distributing","will be distributed"],"answer":3,"explanation":"매뉴얼은 '배포되는' 대상이고 by next Monday라는 미래 기한이 있으므로 미래 수동태 will be distributed가 알맞다. 나머지는 모두 능동태라 목적어가 필요하며, distributed와 has distributed는 시제도 맞지 않는다.","translation":"개정된 안전 매뉴얼은 다음 주 월요일까지 전 직원에게 배포될 것이다.","part":5},{"id":"p5-476","level":3,"type":"동사 시제·태","question":"So far this year, the Olive Tree Bistro ------- several positive reviews in the local press.","choices":["receives","will receive","has received","is received"],"answer":2,"explanation":"So far this year(올해 지금까지)는 과거부터 현재까지의 결과를 나타내므로 현재완료 has received가 정답이다. receives는 반복적 현재, will receive는 미래라 맞지 않고, is received는 수동태라 목적어를 취할 수 없다.","translation":"올해 지금까지 올리브 트리 비스트로는 지역 언론에서 여러 차례 호평을 받았다.","part":5},{"id":"p5-477","level":3,"type":"동사 시제·태","question":"The staff parking lot ------- at the moment, so please use the garage on Elm Street.","choices":["repaves","has repaved","was repaving","is being repaved"],"answer":3,"explanation":"주차장은 '재포장되는' 대상이고 at the moment는 지금 진행 중인 일이므로 현재진행 수동태 is being repaved가 알맞다. repaves와 has repaved는 능동이라 목적어가 필요하고, was repaving은 과거라 at the moment와 맞지 않는다.","translation":"직원 주차장은 현재 재포장 공사 중이니 엘름가에 있는 주차 건물을 이용해 주세요.","part":5},{"id":"p5-478","level":3,"type":"동사 시제·태","question":"Mr. Liu ------- the advanced Excel course next month if his manager approves it.","choices":["took","will take","has taken","taking"],"answer":1,"explanation":"next month는 미래이므로 주절에 will take가 알맞다. 조건절(if ~ approves)은 현재 시제로 미래를 나타내지만 주절에는 미래 시제를 쓴다. took과 has taken은 과거·완료이고, taking은 동사 자리에 올 수 없다.","translation":"류 씨는 관리자가 승인하면 다음 달에 엑셀 고급 과정을 수강할 것이다.","part":5},{"id":"p5-479","level":3,"type":"동사 시제·태","question":"Each branch's sales figures ------- by the finance team every quarter.","choices":["analyze","are analyzed","analyzing","have analyzed"],"answer":1,"explanation":"매출 수치는 재무팀에 의해(by the finance team) '분석되는' 대상이므로 수동태가 필요하며, every quarter는 반복되는 일이므로 현재 수동태 are analyzed가 정답이다. analyze와 have analyzed는 능동이고, analyzing은 동사 자리에 올 수 없다.","translation":"각 지점의 매출 수치는 매 분기 재무팀이 분석한다.","part":5},{"id":"p5-480","level":3,"type":"접속사","question":"------- the budget was approved, the renovation of the lobby had already been postponed twice.","choices":["As if","Whether","Despite","By the time"],"answer":3,"explanation":"예산이 승인된 시점에는 이미 공사가 두 번 연기된 상태였다는 뜻이며, 주절의 과거완료(had been postponed)와 어울리는 By the time(~할 무렵)이 알맞다. As if(마치 ~인 것처럼)는 의미가 통하지 않고, Whether는 양자택일을 나타내며, Despite는 전치사라 절을 이끌 수 없다.","translation":"예산이 승인되었을 무렵 로비 보수 공사는 이미 두 번 연기된 상태였다.","part":5},{"id":"p5-481","level":3,"type":"접속사","question":"------- the new software has been installed, staff can access their files from home.","choices":["Even if","In order that","Rather than","Now that"],"answer":3,"explanation":"'새 소프트웨어가 설치되었으니 이제' 집에서 파일에 접근할 수 있다는 이유를 나타내므로 Now that이 정답이다. Even if는 양보, In order that은 목적이라 뜻이 맞지 않고, Rather than은 두 대상을 대조할 때 쓴다.","translation":"새 소프트웨어가 설치되었으므로 이제 직원들은 집에서도 파일에 접근할 수 있다.","part":5},{"id":"p5-482","level":3,"type":"접속사","question":"The warehouse will be closed on Monday; -------, all orders will be shipped on Tuesday.","choices":["although","because","unless","therefore"],"answer":3,"explanation":"세미콜론 뒤에서 앞 문장의 결과를 이어 주는 접속부사 자리이며, 월요일 휴무 '그래서' 화요일에 발송한다는 흐름이므로 therefore가 알맞다. although, because, unless는 접속사라 쉼표와 함께 혼자 쓸 수 없고 의미도 맞지 않는다.","translation":"창고는 월요일에 문을 닫으므로 모든 주문은 화요일에 발송될 것이다.","part":5},{"id":"p5-483","level":3,"type":"접속사","question":"The photography workshop is designed for ------- beginners and experienced users.","choices":["either","both","neither","whether"],"answer":1,"explanation":"뒤에 and가 있으므로 both A and B(A와 B 둘 다)가 알맞다. either는 or와, neither는 nor와 짝을 이루고, whether는 or와 함께 쓰여 and와 맞지 않는다.","translation":"그 사진 워크숍은 초보자와 숙련자 모두를 위해 만들어졌다.","part":5},{"id":"p5-484","level":3,"type":"전치사","question":"------- the new policy, employees may work from home on Fridays.","choices":["According to","In spite of","Instead of","Rather"],"answer":0,"explanation":"새 정책'에 따르면' 금요일 재택근무가 가능하다는 뜻이므로 According to가 정답이다. In spite of(~에도 불구하고)와 Instead of(~ 대신)는 의미가 맞지 않고, Rather는 부사라 명사구를 이끌 수 없다.","translation":"새 정책에 따르면 직원들은 금요일에 재택근무를 할 수 있다.","part":5},{"id":"p5-485","level":3,"type":"전치사","question":"Mr. Chen took the train to the trade fair ------- driving his own car.","choices":["because of","according to","instead of","in case of"],"answer":2,"explanation":"기차를 탄 것이 자기 차를 운전하는 것 '대신'이라는 뜻이므로 instead of가 알맞다. because of(~ 때문에), according to(~에 따르면), in case of(~의 경우에)는 두 교통수단을 대체하는 의미를 만들지 못한다.","translation":"천 씨는 자기 차를 운전하는 대신 기차를 타고 무역 박람회에 갔다.","part":5},{"id":"p5-486","level":3,"type":"전치사","question":"The annual report was completed ------- the help of three summer interns.","choices":["on","at","of","with"],"answer":3,"explanation":"with the help of는 '~의 도움으로'라는 관용 표현이므로 with가 정답이다. on, at, of는 the help of와 결합해 이런 의미를 만들지 않는다.","translation":"연간 보고서는 여름 인턴 세 명의 도움으로 완성되었다.","part":5},{"id":"p5-487","level":3,"type":"전치사","question":"Smoking is not permitted anywhere ------- the building.","choices":["among","between","inside","during"],"answer":2,"explanation":"건물 '안'의 어디에서도 흡연이 금지된다는 장소의 의미이므로 inside가 알맞다. among과 between은 여러 대상의 사이를 나타내고, during은 기간을 나타내 building 하나와 어울리지 않는다.","translation":"건물 안 어디에서도 흡연은 허용되지 않는다.","part":5},{"id":"p5-488","level":3,"type":"준동사(to부정사·동명사·분사)","question":"Ms. Bhatt is looking forward to ------- the new clients in Mumbai.","choices":["meet","met","meeting","have met"],"answer":2,"explanation":"look forward to의 to는 전치사이므로 뒤에 동명사 meeting이 와야 한다. meet과 have met은 to부정사로 착각하게 만드는 오답이고, met은 과거형이라 전치사 뒤에 올 수 없다.","translation":"바트 씨는 뭄바이의 새 고객들을 만나기를 고대하고 있다.","part":5},{"id":"p5-489","level":3,"type":"준동사(to부정사·동명사·분사)","question":"Northgate Bank has a policy of ------- employees for overtime work.","choices":["compensating","compensate","compensated","compensation"],"answer":0,"explanation":"전치사 of 뒤에 오면서 뒤의 employees를 목적어로 취해야 하므로 동명사 compensating이 정답이다. compensation은 명사라 바로 목적어를 둘 수 없고, compensate와 compensated는 전치사 뒤에 올 수 없다.","translation":"노스게이트 은행에는 직원들의 초과 근무에 대해 보상하는 정책이 있다.","part":5},{"id":"p5-490","level":3,"type":"준동사(to부정사·동명사·분사)","question":"Mr. Ahn was the first designer ------- the award in two categories.","choices":["receiving","to receive","received","receives"],"answer":1,"explanation":"the first + 명사 뒤에는 '~한 최초의'라는 뜻으로 to부정사를 쓰는 것이 일반적이므로 to receive가 알맞다. received와 receives는 동사 형태로 이미 was가 있는 문장에 올 수 없고, receiving은 the first 뒤의 관용적 형태가 아니다.","translation":"안 씨는 두 부문에서 상을 받은 최초의 디자이너였다.","part":5},{"id":"p5-491","level":3,"type":"준동사(to부정사·동명사·분사)","question":"Items ------- during the clearance sale cannot be returned or exchanged.","choices":["purchased","purchasing","purchase","to purchase"],"answer":0,"explanation":"문장의 동사는 cannot be returned이므로 빈칸은 Items를 뒤에서 꾸미는 분사 자리이다. 물건은 '구입되는' 대상이므로 과거분사 purchased가 정답이다. purchasing은 능동, purchase는 동사원형, to purchase는 '구입할'이라는 뜻이라 맞지 않는다.","translation":"재고 정리 세일 기간에 구입한 물품은 반품이나 교환이 불가능하다.","part":5},{"id":"p5-492","level":3,"type":"관계사","question":"Mr. Wood explained ------- the new inventory system works.","choices":["what","how","which","who"],"answer":1,"explanation":"explained의 목적어가 되는 명사절을 이끌며, 뒤에 완전한 절(the new inventory system works)이 오므로 방법을 나타내는 how가 알맞다. what, which, who는 뒤에 주어나 목적어가 빠진 불완전한 절을 이끈다.","translation":"우드 씨는 새 재고 관리 시스템이 어떻게 작동하는지 설명했다.","part":5},{"id":"p5-493","level":3,"type":"관계사","question":"Customers may choose ------- color they prefer for the seat covers.","choices":["whoever","however","wherever","whatever"],"answer":3,"explanation":"빈칸 뒤 명사 color를 꾸미며 '어떤 색이든'이라는 뜻을 만드는 복합관계형용사 whatever가 정답이다. whoever는 사람, wherever는 장소를 나타내고, however는 형용사·부사와 함께 쓰여 명사를 꾸미지 못한다.","translation":"고객은 시트 커버를 원하는 어떤 색으로든 고를 수 있다.","part":5},{"id":"p5-494","level":3,"type":"관계사","question":"Visitors ------- plan to tour the factory must wear closed-toe shoes.","choices":["whom","whose","who","which"],"answer":2,"explanation":"선행사 Visitors(사람) 뒤에 주어가 빠진 절(plan to tour ...)이 오므로 주격 관계대명사 who가 알맞다. whom은 목적격, whose는 뒤에 명사가 필요하고, which는 사물에 쓴다.","translation":"공장을 견학할 방문객은 앞이 막힌 신발을 신어야 한다.","part":5},{"id":"p5-495","level":3,"type":"대명사","question":"Mr. Castellano has two assistants; one works in the morning, and ------- works in the afternoon.","choices":["another","other","the other","others"],"answer":2,"explanation":"두 명 중 하나(one)를 말한 뒤 나머지 하나를 가리킬 때는 the other를 쓴다. another는 셋 이상 중 또 다른 하나, others는 복수라 works와 맞지 않으며, other는 대명사로 혼자 쓰지 않는다.","translation":"카스텔라노 씨에게는 비서가 두 명 있는데, 한 명은 오전에, 나머지 한 명은 오후에 일한다.","part":5},{"id":"p5-496","level":3,"type":"대명사","question":"Our competitors' offices are much larger than -------.","choices":["us","our","ours","we"],"answer":2,"explanation":"경쟁사 사무실과 '우리 사무실'을 비교하므로 소유대명사 ours(= our offices)가 정답이다. us와 we는 사람을 가리켜 사무실과 비교가 되지 않고, our는 뒤에 명사가 있어야 한다.","translation":"경쟁사들의 사무실은 우리 사무실보다 훨씬 더 크다.","part":5},{"id":"p5-497","level":3,"type":"수 일치","question":"The price of the new tablets ------- depending on the storage size.","choices":["vary","varies","varying","to vary"],"answer":1,"explanation":"주어의 핵심은 The price(단수)이며 of the new tablets는 수식어이므로 단수 동사 varies가 알맞다. vary는 tablets에 수를 맞춘 오답이고, varying과 to vary는 동사 자리에 올 수 없다.","translation":"새 태블릿의 가격은 저장 용량에 따라 다르다.","part":5},{"id":"p5-498","level":3,"type":"수 일치","question":"Technicians who work in the clean room ------- special protective clothing.","choices":["needs","need","needing","to need"],"answer":1,"explanation":"관계절 who work in the clean room을 빼면 주어는 Technicians(복수)이므로 복수 동사 need가 정답이다. needs는 room에 수를 맞춘 오답이고, needing과 to need는 문장의 동사가 될 수 없다.","translation":"클린룸에서 일하는 기술자들은 특수 보호복이 필요하다.","part":5},{"id":"p5-499","level":3,"type":"비교","question":"The upgraded model is ------- more expensive than the standard one.","choices":["very","many","much","most"],"answer":2,"explanation":"비교급 more expensive를 강조하는 부사는 much이다. very는 원급을 꾸미고, many는 셀 수 있는 명사를 꾸미며, most는 최상급을 만들어 비교급 앞에 쓸 수 없다.","translation":"업그레이드 모델은 표준 모델보다 훨씬 더 비싸다.","part":5},{"id":"p5-500","level":3,"type":"비교","question":"This year's food festival attracted twice ------- many visitors as last year's.","choices":["so","more","as","than"],"answer":2,"explanation":"배수 표현은 '배수 + as ~ as' 형태로 쓰므로 as가 알맞다. 뒤에 as last year's가 있어 so, more, than은 이 구문을 완성하지 못한다.","translation":"올해 음식 축제에는 작년보다 두 배 많은 방문객이 찾아왔다.","part":5},{"id":"p5-501","level":4,"type":"어휘","question":"To reduce its reliance on coffee sales, Brewline Co. plans to ------- its product line with a range of organic snacks.","choices":["diversify","deduct","withstand","resign"],"answer":0,"explanation":"커피 매출 의존도를 줄이려고 유기농 간식을 더해 제품군을 '다각화하다'라는 뜻이므로 diversify가 알맞다. deduct(공제하다), withstand(견디다), resign(사임하다)은 제품군을 넓히는 의미와 맞지 않는다.","translation":"브루라인사는 커피 매출 의존도를 줄이기 위해 유기농 간식류를 더해 제품군을 다각화할 계획이다.","part":5},{"id":"p5-502","level":4,"type":"어휘","question":"All branches must ------- with the new data protection regulations by the end of the year.","choices":["obey","comply","respect","abide"],"answer":1,"explanation":"빈칸 뒤에 전치사 with가 있으므로 comply with(~을 준수하다)가 정답이다. obey와 respect는 타동사라 with 없이 목적어를 바로 취하고, abide는 abide by 형태로 써야 한다.","translation":"모든 지점은 연말까지 새 개인정보 보호 규정을 준수해야 한다.","part":5},{"id":"p5-503","level":4,"type":"어휘","question":"Ms. Delacroix was ------- at the industry awards for her work on the Solara ad campaign.","choices":["recognized","occupied","estimated","consumed"],"answer":0,"explanation":"업계 시상식에서 광고 캠페인 성과로 '인정받았다'는 뜻이므로 recognized가 알맞다. occupied(점유된), estimated(추정된), consumed(소비된)는 사람의 성과를 칭찬하는 문맥과 맞지 않는다.","translation":"들라크루아 씨는 솔라라 광고 캠페인 작업으로 업계 시상식에서 인정을 받았다.","part":5},{"id":"p5-504","level":4,"type":"어휘","question":"The shipment of laptops was delayed because of a ------- of computer chips.","choices":["surplus","margin","venue","shortage"],"answer":3,"explanation":"부품 때문에 배송이 지연되었다면 반도체가 '부족'했다는 뜻이므로 shortage가 정답이다. surplus(과잉)는 지연의 원인이 되기 어렵고, margin(이윤, 여백)과 venue(장소)는 문맥과 관계가 없다.","translation":"컴퓨터 칩 부족으로 노트북 배송이 지연되었다.","part":5},{"id":"p5-505","level":4,"type":"어휘","question":"Please ------- your registration for the webinar by replying to this e-mail.","choices":["attend","confirm","accompany","proceed"],"answer":1,"explanation":"이메일에 회신함으로써 등록을 '확정하다'라는 뜻이므로 confirm이 알맞다. attend(참석하다)와 accompany(동반하다)는 registration을 목적어로 쓰기 어색하고, proceed는 자동사라 목적어를 바로 둘 수 없다.","translation":"이 이메일에 회신하여 웨비나 등록을 확정해 주세요.","part":5},{"id":"p5-506","level":4,"type":"어휘","question":"The new CEO is expected to ------- a more flexible remote work policy.","choices":["adapt","accord","attach","adopt"],"answer":3,"explanation":"새 정책을 '채택하다'라는 뜻이므로 adopt가 정답이다. 형태가 비슷한 adapt는 '적응하다, 개조하다'라는 뜻이고, accord(부합하다)와 attach(붙이다)도 정책을 도입한다는 의미가 없다.","translation":"새 최고 경영자는 더 유연한 재택근무 정책을 채택할 것으로 예상된다.","part":5},{"id":"p5-507","level":4,"type":"어휘","question":"After three hours of discussion, the committee finally reached a -------.","choices":["conference","concern","consensus","condition"],"answer":2,"explanation":"긴 토론 끝에 reach a consensus(합의에 이르다)가 자연스러우므로 consensus가 알맞다. conference(회의), concern(우려), condition(조건)은 reach와 함께 토론의 결론을 나타내지 않는다.","translation":"세 시간의 토론 끝에 위원회는 마침내 합의에 도달했다.","part":5},{"id":"p5-508","level":4,"type":"어휘","question":"The Grand Palmyra Hotel offers ------- rates for groups of ten or more.","choices":["exhausted","discounted","relieved","attended"],"answer":1,"explanation":"10명 이상 단체에 제공하는 요금이므로 '할인된'이라는 뜻의 discounted가 정답이다. exhausted(지친), relieved(안도한), attended(참석한)는 요금을 수식하지 않는다.","translation":"그랜드 팔미라 호텔은 10명 이상 단체에 할인 요금을 제공한다.","part":5},{"id":"p5-509","level":4,"type":"어휘","question":"All responses to the employee satisfaction survey will be kept strictly -------.","choices":["incidental","eventual","occasional","confidential"],"answer":3,"explanation":"설문 응답을 '기밀로' 유지한다는 뜻으로 be kept strictly confidential이 관용적으로 쓰인다. incidental(부수적인), eventual(최종적인), occasional(가끔의)은 kept strictly와 어울려 비밀 유지를 나타내지 못한다.","translation":"직원 만족도 조사의 모든 응답은 철저히 기밀로 유지될 것이다.","part":5},{"id":"p5-510","level":4,"type":"어휘","question":"Mr. Obeng has been ------- to the position of chief engineer at the Accra plant.","choices":["appointed","applied","inspected","reserved"],"answer":0,"explanation":"be appointed to the position(그 직책에 임명되다)이 자연스러우므로 appointed가 알맞다. applied는 'apply for a position'처럼 능동으로 쓰며, inspected(점검된)와 reserved(예약된)는 사람의 직책과 맞지 않는다.","translation":"오벵 씨는 아크라 공장의 수석 엔지니어로 임명되었다.","part":5},{"id":"p5-511","level":4,"type":"어휘","question":"The terminal expansion project is ------- to be completed by next summer.","choices":["dedicated","anticipated","reluctant","attentive"],"answer":1,"explanation":"be anticipated to do는 '~할 것으로 예상되다'라는 뜻이므로 문맥상 anticipated가 정답이다. dedicated는 to 뒤에 명사·동명사가 오고, reluctant(꺼리는)와 attentive(주의 깊은)는 사람의 태도라 공사 프로젝트와 맞지 않는다.","translation":"터미널 확장 공사는 내년 여름까지 완공될 것으로 예상된다.","part":5},{"id":"p5-512","level":4,"type":"어휘","question":"The new social media strategy has already ------- positive results for the brand.","choices":["relied","yielded","inclined","occurred"],"answer":1,"explanation":"전략이 좋은 결과를 '낳았다'는 뜻으로 yield results가 자연스러우므로 yielded가 알맞다. relied는 on이 필요한 자동사이고, occurred는 목적어를 취하지 않으며, inclined(마음이 기울게 하다)는 결과를 목적어로 쓰지 않는다.","translation":"새 소셜 미디어 전략은 이미 브랜드에 긍정적인 결과를 가져왔다.","part":5},{"id":"p5-513","level":4,"type":"품사","question":"Ms. Horvath has been ------- involved in community outreach programs for many years.","choices":["actively","active","activity","activate"],"answer":0,"explanation":"has been과 과거분사 involved 사이에서 분사를 꾸미는 부사 자리이므로 actively가 정답이다. active는 형용사, activity는 명사, activate는 동사라 분사를 수식할 수 없다.","translation":"호르바트 씨는 여러 해 동안 지역 봉사 프로그램에 적극적으로 참여해 왔다.","part":5},{"id":"p5-514","level":4,"type":"품사","question":"An ------- of the survey data showed that customers want longer weekend hours.","choices":["analyze","analytical","analytically","analysis"],"answer":3,"explanation":"관사 An과 전치사 of 사이에서 동사 showed의 주어가 되는 명사 자리이므로 analysis가 알맞다. analyze는 동사, analytical은 형용사, analytically는 부사라 주어가 될 수 없다.","translation":"설문 자료를 분석한 결과, 고객들은 주말 영업시간 연장을 원하는 것으로 나타났다.","part":5},{"id":"p5-515","level":4,"type":"품사","question":"The revised travel policy is ------- to all full-time and part-time employees.","choices":["apply","applicable","application","applicably"],"answer":1,"explanation":"be동사 뒤 보어 자리이며 be applicable to(~에 적용되다)라는 표현이므로 형용사 applicable이 정답이다. apply는 동사, application은 명사라 '정책=지원서'라는 어색한 뜻이 되고, applicably는 부사이다.","translation":"개정된 출장 정책은 모든 정규직과 시간제 직원에게 적용된다.","part":5},{"id":"p5-516","level":4,"type":"품사","question":"Despite a two-week delay, the software migration was completed -------.","choices":["satisfactorily","satisfactory","satisfaction","satisfy"],"answer":0,"explanation":"수동태 was completed 뒤에서 동사를 꾸미는 부사 자리이므로 satisfactorily가 알맞다. satisfactory는 형용사, satisfaction은 명사, satisfy는 동사라 동사를 수식하지 못한다.","translation":"2주 지연에도 불구하고 소프트웨어 이전 작업은 만족스럽게 완료되었다.","part":5},{"id":"p5-517","level":4,"type":"품사","question":"The hotel's ------- to the international airport makes it popular with business travelers.","choices":["proximate","approximate","proximity","approximately"],"answer":2,"explanation":"소유격 뒤에서 동사 makes의 주어가 되는 명사 자리이므로 proximity(가까움)가 정답이다. proximate와 approximate는 형용사, approximately는 부사라 주어가 될 수 없다.","translation":"그 호텔은 국제공항과 가까워서 출장객들에게 인기가 있다.","part":5},{"id":"p5-518","level":4,"type":"품사","question":"Staff are asked to dispose of used batteries -------.","choices":["responsible","responsibly","responsibility","responsibleness"],"answer":1,"explanation":"dispose of + 목적어까지 갖춘 완전한 절 뒤에서 동사를 꾸미는 부사 자리이므로 responsibly가 알맞다. responsible은 형용사, responsibility와 responsibleness는 명사라 동사를 수식할 수 없다.","translation":"직원들은 다 쓴 배터리를 책임감 있게 폐기해 달라는 요청을 받는다.","part":5},{"id":"p5-519","level":4,"type":"품사","question":"Publication of the quarterly report was ------- delayed because of the external audit.","choices":["slight","slighted","slightly","slightness"],"answer":2,"explanation":"be동사와 과거분사 delayed 사이에서 분사를 꾸미는 부사 자리이므로 slightly가 정답이다. slight는 형용사, slighted는 '무시당한'이라는 과거분사, slightness는 명사라 이 자리에 맞지 않는다.","translation":"분기 보고서의 발간은 외부 감사 때문에 약간 지연되었다.","part":5},{"id":"p5-520","level":4,"type":"품사","question":"The new CFO is known for her ------- approach to cost control.","choices":["innovation","innovate","innovative","innovatively"],"answer":2,"explanation":"소유격 her와 명사 approach 사이에서 명사를 꾸미는 형용사 자리이므로 innovative가 알맞다. innovation은 명사, innovate는 동사, innovatively는 부사라 명사를 수식할 수 없다.","translation":"새 최고 재무 책임자는 비용 관리에 대한 혁신적인 접근 방식으로 알려져 있다.","part":5},{"id":"p5-521","level":4,"type":"품사","question":"Greenhill Foods' ------- to reduce plastic packaging was praised by environmental groups.","choices":["initiate","initial","initiative","initially"],"answer":2,"explanation":"소유격 뒤 주어 자리이므로 명사가 와야 하며, 뒤의 to부정사의 수식을 받아 '줄이려는 계획'을 뜻하는 initiative가 정답이다. initiate는 동사, initial은 형용사, initially는 부사이다.","translation":"플라스틱 포장을 줄이려는 그린힐 푸드의 계획은 환경 단체들의 칭찬을 받았다.","part":5},{"id":"p5-522","level":4,"type":"품사","question":"The board asked for a ------- explanation of the increase in marketing costs.","choices":["detail","detailing","detailed","details"],"answer":2,"explanation":"관사 a와 명사 explanation 사이에서 명사를 꾸미는 형용사 자리이므로 '상세한'이라는 뜻의 분사형 형용사 detailed가 알맞다. detail과 details는 명사이며, detailing은 '세부 작업'이라는 뜻이라 explanation을 꾸미기에 부적절하다.","translation":"이사회는 마케팅 비용 증가에 대한 상세한 설명을 요청했다.","part":5},{"id":"p5-523","level":4,"type":"품사","question":"The pressure valves must be inspected ------- to ensure that they operate safely.","choices":["periodic","period","periodical","periodically"],"answer":3,"explanation":"수동태 must be inspected 뒤에서 동사를 꾸미는 부사 자리이므로 periodically가 정답이다. periodic은 형용사, period는 명사, periodical은 형용사·명사(정기 간행물)라 동사를 수식할 수 없다.","translation":"압력 밸브는 안전하게 작동하도록 주기적으로 점검해야 한다.","part":5},{"id":"p5-524","level":4,"type":"동사 시제·태","question":"By the time the auditors arrived, Mr. Rahimi ------- all of the relevant files.","choices":["had organized","has organized","organizes","will organize"],"answer":0,"explanation":"By the time + 과거 시제(arrived)는 그 과거 시점 이전에 완료된 일을 나타내므로 과거완료 had organized가 알맞다. has organized는 현재완료, organizes는 현재, will organize는 미래라 과거 기준 시점과 맞지 않는다.","translation":"감사관들이 도착했을 무렵 라히미 씨는 관련 파일을 모두 정리해 두었다.","part":5},{"id":"p5-525","level":4,"type":"동사 시제·태","question":"The factory ------- for three weeks when the replacement parts finally arrived.","choices":["has been closed","had been closed","is closed","closes"],"answer":1,"explanation":"부품이 도착한 과거 시점까지 3주 동안 이어진 상태이므로 과거완료 수동 had been closed가 정답이다. has been closed는 현재까지의 기간, is closed와 closes는 현재 시제라 과거 시점(arrived)과 맞지 않는다.","translation":"교체 부품이 마침내 도착했을 때 공장은 3주째 가동을 멈춘 상태였다.","part":5},{"id":"p5-526","level":4,"type":"동사 시제·태","question":"The survey results ------- until all of the data has been checked for errors.","choices":["will not be released","did not release","are not releasing","have not released"],"answer":0,"explanation":"결과는 '공개되는' 대상이므로 수동태가 필요하고, until절의 현재완료가 미래의 완료를 나타내므로 주절은 미래 수동 will not be released가 알맞다. 나머지는 모두 능동태라 목적어가 필요하다.","translation":"모든 자료의 오류 점검이 끝날 때까지 설문 결과는 공개되지 않을 것이다.","part":5},{"id":"p5-527","level":4,"type":"동사 시제·태","question":"At this time tomorrow, Ms. Nakata ------- to Berlin for the trade show.","choices":["flies","has flown","will be flying","flew"],"answer":2,"explanation":"At this time tomorrow(내일 이 시간)는 미래의 특정 시점에 진행 중일 일을 나타내므로 미래진행형 will be flying이 정답이다. flies는 현재, has flown은 현재완료, flew는 과거라 미래 시점과 맞지 않는다.","translation":"내일 이 시간에 나카타 씨는 무역 박람회 참석차 베를린으로 날아가고 있을 것이다.","part":5},{"id":"p5-528","level":4,"type":"동사 시제·태","question":"The service agreement ------- by both parties before the project can start.","choices":["must sign","signed","must be signed","signing"],"answer":2,"explanation":"계약서는 양측에 의해(by both parties) '서명되는' 대상이므로 수동태 must be signed가 알맞다. must sign은 능동이라 목적어가 필요하고, signed는 과거 시제로 before절의 미래 상황과 맞지 않으며, signing은 동사 자리에 올 수 없다.","translation":"프로젝트가 시작되기 전에 서비스 계약서에 양측이 서명해야 한다.","part":5},{"id":"p5-529","level":4,"type":"동사 시제·태","question":"If the weather ------- clear tomorrow, the outdoor ceremony will proceed as planned.","choices":["will stay","stayed","stays","staying"],"answer":2,"explanation":"시간·조건 부사절에서는 미래 대신 현재 시제를 쓰므로 if절의 동사는 stays가 정답이다. will stay는 조건절에 쓰지 않고, stayed는 과거라 tomorrow와 맞지 않으며, staying은 동사 자리에 올 수 없다.","translation":"내일 날씨가 계속 맑으면 야외 행사는 예정대로 진행될 것이다.","part":5},{"id":"p5-530","level":4,"type":"접속사","question":"------- Marvella Cosmetics' revenue rose sharply last year, its stock price fell.","choices":["Despite","Though","During","Because"],"answer":1,"explanation":"매출은 올랐지만 주가는 떨어졌다는 대조의 의미이며 뒤에 절이 오므로 접속사 Though가 알맞다. Despite와 During은 전치사라 절을 이끌 수 없고, Because는 이유를 나타내 의미가 맞지 않는다.","translation":"마르벨라 화장품의 매출은 작년에 급증했지만 주가는 하락했다.","part":5},{"id":"p5-531","level":4,"type":"접속사","question":"Ms. Omar will approve the training budget ------- it includes funding for online courses.","choices":["whereas","as if","what if","only if"],"answer":3,"explanation":"온라인 강좌 비용이 포함된 '경우에만' 승인한다는 제한 조건이므로 only if가 정답이다. whereas(~인 반면)는 대조를 나타내 의미가 통하지 않고, as if(마치 ~처럼)와 what if(~라면 어떨까)도 의미가 통하지 않는다.","translation":"오마르 씨는 온라인 강좌 비용이 포함된 경우에만 교육 예산을 승인할 것이다.","part":5},{"id":"p5-532","level":4,"type":"접속사","question":"The new office is spacious and modern; -------, it is quite far from the subway station.","choices":["nevertheless","therefore","because","although"],"answer":0,"explanation":"세미콜론 뒤에서 앞 내용(넓고 현대적임)과 반대되는 내용(역에서 멂)을 잇는 접속부사가 필요하므로 nevertheless가 알맞다. therefore는 결과를 나타내 흐름이 맞지 않고, because와 although는 접속사라 쉼표와 함께 부사처럼 쓸 수 없다.","translation":"새 사무실은 넓고 현대적이지만, 그럼에도 지하철역에서 꽤 멀다.","part":5},{"id":"p5-533","level":4,"type":"접속사","question":"------- the budget is limited this year, we must choose our suppliers carefully.","choices":["In spite of","Given that","Despite","Owing to"],"answer":1,"explanation":"빈칸 뒤에 주어와 동사(the budget is limited)가 있으므로 접속사가 필요하며, '~을 고려하면'이라는 뜻의 Given that이 정답이다. In spite of, Despite, Owing to는 모두 전치사(구)라 절을 이끌 수 없다.","translation":"올해 예산이 제한적이라는 점을 고려하면 우리는 공급업체를 신중하게 골라야 한다.","part":5},{"id":"p5-534","level":4,"type":"전치사","question":"------- her extensive experience in mergers, Ms. Grant was hired as a senior consultant.","choices":["Although","Because","Despite","Owing to"],"answer":3,"explanation":"뒤에 명사구(her extensive experience)가 오고 채용의 이유를 나타내므로 전치사구 Owing to(~ 덕분에)가 알맞다. Although와 Because는 접속사라 절이 필요하고, Despite는 '~에도 불구하고'라는 양보의 의미라 맞지 않는다.","translation":"그랜트 씨는 인수 합병 분야의 폭넓은 경험 덕분에 선임 컨설턴트로 채용되었다.","part":5},{"id":"p5-535","level":4,"type":"전치사","question":"The package tour includes three nights of accommodation ------- daily breakfast.","choices":["in addition to","as well","furthermore","moreover"],"answer":0,"explanation":"명사구 daily breakfast 앞에서 '~에 더하여'라는 뜻을 나타내는 전치사구 in addition to가 정답이다. as well은 문장 끝에 쓰는 부사이고, furthermore와 moreover는 접속부사라 명사구를 이끌 수 없다.","translation":"그 패키지여행에는 매일 조식에 더해 3박 숙박이 포함되어 있다.","part":5},{"id":"p5-536","level":4,"type":"전치사","question":"Please contact Ms. Ruiz ------- any changes to your travel itinerary.","choices":["because","regarding","although","whether"],"answer":1,"explanation":"명사구 any changes 앞에서 '~에 관해'라는 뜻의 전치사 regarding이 알맞다. because, although, whether는 접속사라 뒤에 절이 와야 한다.","translation":"여행 일정 변경에 관해서는 루이스 씨에게 연락해 주세요.","part":5},{"id":"p5-537","level":4,"type":"전치사","question":"The east entrance of the gallery will remain closed ------- further notice.","choices":["until","by","within","since"],"answer":0,"explanation":"until further notice는 '추후 공지가 있을 때까지'라는 관용 표현으로, 계속 닫혀 있는 상태의 기한을 나타내므로 until이 정답이다. by는 완료 기한, within은 기간 이내, since는 과거 시작점을 나타내 remain closed와 어울리지 않는다.","translation":"미술관 동쪽 입구는 추후 공지가 있을 때까지 계속 폐쇄된다.","part":5},{"id":"p5-538","level":4,"type":"준동사(to부정사·동명사·분사)","question":"Ms. Chu is considering ------- her contract with the agency for another year.","choices":["renewing","to renew","renew","renewed"],"answer":0,"explanation":"consider는 동명사를 목적어로 취하므로 renewing이 알맞다. to renew는 consider 뒤에 쓰지 않으며, renew와 renewed는 is considering 뒤에 동사로 올 수 없다.","translation":"추 씨는 에이전시와의 계약을 1년 더 연장하는 것을 고려하고 있다.","part":5},{"id":"p5-539","level":4,"type":"준동사(to부정사·동명사·분사)","question":"------- properly, industrial sewing machines can last for decades.","choices":["Maintaining","Maintained","Maintain","To maintaining"],"answer":1,"explanation":"주절의 주어 sewing machines는 '관리되는' 대상이므로 수동 의미의 분사구문을 이끄는 과거분사 Maintained가 정답이다. Maintaining은 기계가 무언가를 관리한다는 능동 의미가 되고, Maintain은 명령문 형태, To maintaining은 문법적으로 틀린 형태이다.","translation":"적절하게 관리되면 산업용 재봉틀은 수십 년 동안 쓸 수 있다.","part":5},{"id":"p5-540","level":4,"type":"준동사(to부정사·동명사·분사)","question":"The CEO announced her decision ------- the company's Osaka office.","choices":["closing","to close","closed","close"],"answer":1,"explanation":"명사 decision은 to부정사의 수식을 받아 '~하겠다는 결정'이라는 뜻을 나타내므로 to close가 알맞다. closing과 closed는 decision을 꾸미는 형태로 적절하지 않고, close는 동사원형이라 명사 뒤에 바로 올 수 없다.","translation":"최고 경영자는 회사의 오사카 사무소를 폐쇄하겠다는 결정을 발표했다.","part":5},{"id":"p5-541","level":4,"type":"준동사(to부정사·동명사·분사)","question":"The number of complaints ------- from customers has dropped since the new manager arrived.","choices":["received","receiving","receive","receives"],"answer":0,"explanation":"문장의 동사는 has dropped이므로 빈칸은 complaints를 뒤에서 꾸미는 분사 자리이다. 불만은 '접수되는' 대상이므로 과거분사 received가 정답이다. receiving은 능동 의미이고, receive와 receives는 동사라 동사가 두 개가 된다.","translation":"새 관리자가 온 이후로 고객들로부터 접수된 불만 건수가 줄었다.","part":5},{"id":"p5-542","level":4,"type":"관계사","question":"The hotel ------- we held last year's sales conference has been completely renovated.","choices":["which","what","whose","at which"],"answer":3,"explanation":"빈칸 뒤에 완전한 절(we held last year's sales conference)이 오므로 '전치사 + 관계대명사'인 at which가 알맞다. which는 뒤에 주어나 목적어가 빠진 절이 필요하고, what은 선행사와 함께 쓸 수 없으며, whose는 뒤에 명사가 와야 한다.","translation":"우리가 작년 영업 회의를 열었던 호텔은 전면 개조되었다.","part":5},{"id":"p5-543","level":4,"type":"관계사","question":"The three months ------- the factory was closed for upgrades cost the company millions of dollars.","choices":["which","what","during which","whose"],"answer":2,"explanation":"선행사 The three months 뒤에 완전한 절(the factory was closed)이 오므로 '~ 동안'의 의미를 담은 during which가 정답이다. which는 불완전한 절을 이끌고, what은 선행사와 쓸 수 없으며, whose는 뒤에 명사가 필요하다.","translation":"공장이 설비 개선을 위해 문을 닫았던 3개월 동안 회사는 수백만 달러의 손실을 보았다.","part":5},{"id":"p5-544","level":4,"type":"대명사","question":"The two suppliers charge similar prices, but ------- offers much faster delivery than the other.","choices":["another","others","either","one"],"answer":3,"explanation":"두 공급업체 중 하나를 one, 나머지 하나를 the other로 가리키는 구문이므로 one이 알맞다. another는 셋 이상에서 쓰고, others는 복수라 offers와 맞지 않으며, either(둘 중 어느 쪽이든)는 the other와 대비되는 특정한 하나를 가리키지 못한다.","translation":"두 공급업체의 가격은 비슷하지만 한 곳이 다른 곳보다 훨씬 빠르게 배송한다.","part":5},{"id":"p5-545","level":4,"type":"대명사","question":"The battery life of the new smartwatch is longer than ------- of the previous model.","choices":["those","it","one","that"],"answer":3,"explanation":"앞의 단수 명사 The battery life를 다시 가리키며 뒤에 of 수식어가 붙으므로 that이 정답이다. those는 복수 명사를 대신하고, it은 of 수식을 받지 않으며, one은 셀 수 있는 명사를 대신해 battery life와 맞지 않는다.","translation":"새 스마트워치의 배터리 수명은 이전 모델의 배터리 수명보다 길다.","part":5},{"id":"p5-546","level":4,"type":"대명사","question":"------- of the attendees had heard of Luminex before the fair, but many left with product samples.","choices":["Little","Much","Few","Every"],"answer":2,"explanation":"of the attendees(참석자들)는 셀 수 있는 복수 명사이고 '거의 없었다'는 뜻이 but 이하와 대조를 이루므로 Few가 알맞다. Little과 Much는 셀 수 없는 명사에 쓰고, Every는 대명사로 혼자 쓸 수 없다.","translation":"박람회 전에 루미넥스를 들어 본 참석자는 거의 없었지만 많은 사람이 제품 샘플을 가지고 돌아갔다.","part":5},{"id":"p5-547","level":4,"type":"수 일치","question":"A number of employees ------- requested more flexible working hours.","choices":["has","is","was","have"],"answer":3,"explanation":"A number of + 복수 명사는 '많은 ~'이라는 뜻으로 복수 취급하므로 have가 정답이다. has는 단수 동사이고, is와 was는 수동태나 진행형이 아닌 이 문장에서 requested와 결합하면 '요청받았다'는 틀린 의미가 되며 수도 맞지 않는다.","translation":"많은 직원이 더 유연한 근무 시간을 요청했다.","part":5},{"id":"p5-548","level":4,"type":"수 일치","question":"The regional manager, together with her team members, ------- attending the conference in Dubai.","choices":["are","be","being","is"],"answer":3,"explanation":"A together with B에서 동사의 수는 A에 맞추므로 단수 주어 The regional manager에 맞는 is가 알맞다. are는 team members에 수를 맞춘 오답이고, be와 being은 문장의 동사가 될 수 없다.","translation":"지역 관리자는 팀원들과 함께 두바이 회의에 참석한다.","part":5},{"id":"p5-549","level":4,"type":"비교","question":"Of the two proposals, the board preferred the -------, as it required less initial investment.","choices":["latter","later","lately","late"],"answer":0,"explanation":"두 가지 중 '후자'를 가리키는 명사 자리이므로 latter가 정답이다. later는 '나중에', lately는 '최근에'라는 부사이고, late는 '늦은'이라 두 제안 중 하나를 가리킬 수 없다.","translation":"두 제안 중 이사회는 초기 투자가 더 적게 드는 후자를 선호했다.","part":5},{"id":"p5-550","level":4,"type":"비교","question":"The spring campaign was ------- the most successful promotion in the company's history.","choices":["so","too","by far","more"],"answer":2,"explanation":"최상급 the most successful을 강조하는 표현은 by far이다. so와 too는 원급 형용사·부사를 꾸미므로 the most 앞에 올 수 없고, more는 최상급과 함께 쓸 수 없다.","translation":"봄 캠페인은 회사 역사상 단연 가장 성공적인 판촉 행사였다.","part":5},{"id":"p5-551","level":5,"type":"어휘","question":"To cut costs and avoid duplication, the two firms have agreed to ------- their research efforts in battery technology.","choices":["conform","confide","condone","consolidate"],"answer":3,"explanation":"비용 절감과 중복 방지를 위해 연구 활동을 '통합하다'라는 뜻이므로 consolidate가 알맞다. conform(따르다)은 to와 쓰는 자동사이고, confide(털어놓다)와 condone(용납하다)은 연구 활동을 합치는 의미가 없다.","translation":"비용을 줄이고 중복을 피하기 위해 두 회사는 배터리 기술 연구 활동을 통합하기로 합의했다.","part":5},{"id":"p5-552","level":5,"type":"어휘","question":"The new CFO has been tasked with ------- unnecessary spending across all divisions.","choices":["curbing","soliciting","exerting","fostering"],"answer":0,"explanation":"불필요한 지출(unnecessary spending)은 '억제해야' 하는 대상이므로 curbing이 정답이다. soliciting(간청하다), exerting(힘을 행사하다), fostering(조장하다)은 불필요한 지출과 결합하면 의미가 맞지 않는다.","translation":"새 최고 재무 책임자는 전 부서의 불필요한 지출을 억제하는 임무를 맡았다.","part":5},{"id":"p5-553","level":5,"type":"어휘","question":"The board's decision to restructure the company was ------- by a sharp decline in overseas sales.","choices":["prompted","postulated","pervaded","prescribed"],"answer":0,"explanation":"해외 매출 급감이 구조 조정 결정을 '촉발했다'는 뜻이므로 prompted가 알맞다. postulated(가정된), pervaded(스며든), prescribed(처방된, 규정된)는 결정이 생긴 원인을 나타내는 by와 어울리지 않는다.","translation":"회사를 구조 조정하기로 한 이사회의 결정은 해외 매출 급감으로 촉발되었다.","part":5},{"id":"p5-554","level":5,"type":"어휘","question":"The auditors noticed several ------- between the invoices and the shipping records.","choices":["proximities","precautions","affiliations","discrepancies"],"answer":3,"explanation":"송장과 선적 기록 '사이의' 무언가를 감사관이 발견했다면 '불일치'가 자연스러우므로 discrepancies가 정답이다. proximities(근접), precautions(예방 조치), affiliations(제휴)는 두 문서 사이에서 발견되는 문제를 나타내지 않는다.","translation":"감사관들은 송장과 선적 기록 사이에서 몇 가지 불일치를 발견했다.","part":5},{"id":"p5-555","level":5,"type":"어휘","question":"Local business owners have ------- the city council to reconsider the proposed parking fee increase.","choices":["insisted","demanded","suggested","urged"],"answer":3,"explanation":"빈칸 뒤 '목적어 + to부정사(the city council to reconsider)' 구조를 취하는 동사는 urge이므로 urged가 알맞다. insist는 on이나 that절, demand와 suggest는 that절이나 명사를 목적어로 취하며 목적어 뒤 to부정사를 쓰지 않는다.","translation":"지역 상인들은 시의회에 주차 요금 인상안을 재고해 달라고 촉구했다.","part":5},{"id":"p5-556","level":5,"type":"어휘","question":"Tickets are non-refundable but ------- to another person up to 24 hours before the performance.","choices":["perishable","negligible","inevitable","transferable"],"answer":3,"explanation":"환불은 안 되지만(but) 다른 사람에게 '양도할 수 있다'는 대조가 자연스러우므로 transferable이 정답이다. perishable(상하기 쉬운), negligible(무시해도 될), inevitable(불가피한)은 to another person과 어울리지 않는다.","translation":"입장권은 환불되지 않지만 공연 24시간 전까지 다른 사람에게 양도할 수 있다.","part":5},{"id":"p5-557","level":5,"type":"어휘","question":"The merger talks stalled over a ------- clause concerning executive compensation.","choices":["conscientious","contentious","contiguous","consecutive"],"answer":1,"explanation":"협상이 교착 상태에 빠진 원인이 된 조항이므로 '논란이 많은'이라는 뜻의 contentious가 알맞다. 형태가 비슷한 conscientious(양심적인), contiguous(인접한), consecutive(연속적인)는 조항이 분쟁을 일으킨다는 의미가 없다.","translation":"합병 협상은 경영진 보수에 관한 논란 많은 조항 때문에 교착 상태에 빠졌다.","part":5},{"id":"p5-558","level":5,"type":"어휘","question":"All inquiries from the media should be ------- to the corporate communications office.","choices":["deferred","inferred","conferred","referred"],"answer":3,"explanation":"언론 문의를 홍보실로 '넘기다, 회부하다'는 refer A to B이므로 수동태 referred가 정답이다. deferred(연기된), inferred(추론된), conferred(수여된)는 문의를 담당 부서로 보낸다는 의미를 만들지 못한다.","translation":"언론의 모든 문의는 기업 홍보실로 넘겨야 한다.","part":5},{"id":"p5-559","level":5,"type":"어휘","question":"Despite the company's aggressive expansion into new markets, its profits have remained -------.","choices":["vacant","stagnant","fluent","lenient"],"answer":1,"explanation":"공격적인 확장에도 불구하고(Despite) 수익이 늘지 않았다는 대조이므로 '정체된'이라는 뜻의 stagnant가 알맞다. vacant(비어 있는), fluent(유창한), lenient(관대한)는 수익의 상태를 나타내지 않는다.","translation":"새 시장으로의 공격적인 확장에도 불구하고 그 회사의 수익은 정체된 상태이다.","part":5},{"id":"p5-560","level":5,"type":"어휘","question":"The architect was praised for making ------- use of natural light in the library's design.","choices":["judicial","judicious","prejudiced","adjacent"],"answer":1,"explanation":"make judicious use of는 '~을 현명하게 활용하다'라는 표현이므로 judicious가 정답이다. 형태가 비슷한 judicial은 '사법의'라는 뜻이고, prejudiced(편견을 가진)와 adjacent(인접한)도 use를 꾸며 칭찬의 이유가 되지 못한다.","translation":"그 건축가는 도서관 설계에서 자연광을 현명하게 활용했다는 찬사를 받았다.","part":5},{"id":"p5-561","level":5,"type":"어휘","question":"Mr. Varga's sudden retirement will ------- a reshuffle of the senior management team.","choices":["neutralize","necessitate","negotiate","notify"],"answer":1,"explanation":"갑작스러운 은퇴가 경영진 개편을 '필요하게 만든다'는 뜻이므로 necessitate가 알맞다. neutralize(무력화하다)는 의미가 맞지 않고, negotiate(협상하다)와 notify(통지하다)는 사람이 주어일 때 쓰는 동사라 retirement와 어울리지 않는다.","translation":"바르가 씨의 갑작스러운 은퇴로 고위 경영진 개편이 불가피해질 것이다.","part":5},{"id":"p5-562","level":5,"type":"어휘","question":"The revised privacy policy will take effect ------- with its publication on the company's Web site.","choices":["conversely","consequently","confidently","concurrently"],"answer":3,"explanation":"concurrently with는 '~와 동시에'라는 뜻으로 공지와 동시에 효력이 발생한다는 문맥에 맞는다. conversely(반대로), consequently(그 결과), confidently(자신 있게)는 with와 결합해 시점의 일치를 나타내지 못한다.","translation":"개정된 개인정보 보호 정책은 회사 웹사이트에 게시되는 것과 동시에 효력이 발생한다.","part":5},{"id":"p5-563","level":5,"type":"품사","question":"The expansion plan was rejected on the grounds that it was financially -------.","choices":["unsustainably","unsustainability","unsustainable","sustain"],"answer":2,"explanation":"be동사 was 뒤 보어 자리이며 부사 financially의 수식을 받으므로 형용사 unsustainable이 정답이다. unsustainably는 부사라 보어가 될 수 없고, unsustainability는 명사라 부사의 수식을 받지 않으며, sustain은 동사이다.","translation":"그 확장 계획은 재정적으로 지속 불가능하다는 이유로 거부되었다.","part":5},{"id":"p5-564","level":5,"type":"품사","question":"The new COO's ------- of the supply chain has cut logistics costs by 12 percent.","choices":["overhauled","overhaul","to overhaul","overhauls"],"answer":1,"explanation":"소유격 뒤에서 단수 동사 has cut의 주어가 되는 명사 자리이므로 overhaul(전면 개편)이 알맞다. overhauled는 동사 과거형·분사이고, to overhaul은 소유격 뒤에 올 수 없으며, overhauls는 복수라 has와 수가 맞지 않는다.","translation":"새 최고 운영 책임자의 공급망 전면 개편으로 물류비가 12퍼센트 줄었다.","part":5},{"id":"p5-565","level":5,"type":"품사","question":"Lab technicians must follow the testing protocol -------, without exception.","choices":["meticulously","meticulous","meticulousness","more meticulous"],"answer":0,"explanation":"목적어까지 갖춘 절 뒤에서 동사 follow를 꾸미는 부사 자리이므로 meticulously가 정답이다. meticulous와 more meticulous는 형용사, meticulousness는 명사라 동사를 수식할 수 없다.","translation":"실험실 기술자들은 예외 없이 시험 절차를 꼼꼼하게 따라야 한다.","part":5},{"id":"p5-566","level":5,"type":"품사","question":"The consultant's report offers a ------- assessment of the region's economic outlook.","choices":["candidly","candor","candid","candidness"],"answer":2,"explanation":"관사 a와 명사 assessment 사이에서 명사를 꾸미는 형용사 자리이므로 candid(솔직한)가 알맞다. candidly는 부사, candor와 candidness는 명사라 assessment를 수식할 수 없다.","translation":"그 컨설턴트의 보고서는 지역 경제 전망에 대한 솔직한 평가를 담고 있다.","part":5},{"id":"p5-567","level":5,"type":"품사","question":"Public response to the exhibition was so ------- positive that the museum extended it by two weeks.","choices":["overwhelming","overwhelm","overwhelmed","overwhelmingly"],"answer":3,"explanation":"so와 형용사 positive 사이에서 형용사를 꾸미는 부사 자리이므로 overwhelmingly가 정답이다. overwhelming과 overwhelmed는 형용사(분사)라 다른 형용사를 꾸미지 못하고, overwhelm은 동사이다.","translation":"그 전시회에 대한 대중의 반응이 압도적으로 좋아서 박물관은 전시를 2주 연장했다.","part":5},{"id":"p5-568","level":5,"type":"품사","question":"The legal team reviewed the contract for any ------- that could expose the company to liability.","choices":["ambiguities","ambiguous","ambiguously","disambiguate"],"answer":0,"explanation":"any 뒤에서 전치사 for의 목적어가 되고 관계절 that ~의 수식을 받는 명사 자리이므로 ambiguities(모호한 부분)가 알맞다. ambiguous는 형용사, ambiguously는 부사, disambiguate는 동사라 명사 자리에 올 수 없다.","translation":"법무팀은 회사가 법적 책임을 질 수 있는 모호한 부분이 있는지 계약서를 검토했다.","part":5},{"id":"p5-569","level":5,"type":"품사","question":"Although both proposals aim to reduce costs, they are ------- different in their approach.","choices":["fundamentally","fundamental","fundamentals","fundamentalism"],"answer":0,"explanation":"be동사와 형용사 different 사이에서 형용사를 꾸미는 부사 자리이므로 fundamentally가 정답이다. fundamental은 형용사라 다른 형용사를 꾸밀 수 없고, fundamentals와 fundamentalism은 명사이다.","translation":"두 제안 모두 비용 절감을 목표로 하지만 접근 방식이 근본적으로 다르다.","part":5},{"id":"p5-570","level":5,"type":"품사","question":"Several senior staff members expressed ------- about relocating the head office to the suburbs.","choices":["reserved","reserving","reservations","reservedly"],"answer":2,"explanation":"동사 expressed의 목적어가 되는 명사 자리이며 express reservations about은 '~에 대해 우려를 표하다'라는 표현이므로 reservations가 알맞다. reserved는 형용사·분사, reserving은 목적어가 필요한 동명사, reservedly는 부사이다.","translation":"여러 고참 직원이 본사를 교외로 이전하는 것에 대해 우려를 표했다.","part":5},{"id":"p5-571","level":5,"type":"품사","question":"The newly appointed plant director is highly ------- to the concerns of front-line workers.","choices":["attention","attentively","attend","attentive"],"answer":3,"explanation":"be동사 뒤 보어 자리이며 부사 highly의 수식을 받으므로 형용사 attentive가 정답이다. attention은 명사라 highly의 꾸밈을 받을 수 없고, attentively는 부사, attend는 동사이다.","translation":"새로 임명된 공장장은 현장 근로자들의 고충에 매우 세심하게 귀를 기울인다.","part":5},{"id":"p5-572","level":5,"type":"품사","question":"Construction delays are almost ------- when working in remote mountain regions.","choices":["inevitably","inevitability","inevitable","inevitableness"],"answer":2,"explanation":"be동사 are 뒤 보어 자리로 주어 delays의 성질을 설명하므로 형용사 inevitable이 알맞다. inevitably는 부사라 보어가 될 수 없고, inevitability와 inevitableness는 명사라 '지연=불가피성'이 되어 어색하다.","translation":"외딴 산간 지역에서 작업할 때 공사 지연은 거의 불가피하다.","part":5},{"id":"p5-573","level":5,"type":"품사","question":"The new pricing guidelines have been applied ------- across all regional branches.","choices":["uniformly","uniform","uniformity","uniformed"],"answer":0,"explanation":"수동태 have been applied 뒤에서 동사를 꾸미는 부사 자리이므로 uniformly가 정답이다. uniform은 형용사·명사, uniformity는 명사, uniformed는 '제복을 입은'이라는 형용사라 동사를 수식할 수 없다.","translation":"새 가격 지침은 모든 지역 지점에 일률적으로 적용되었다.","part":5},{"id":"p5-574","level":5,"type":"동사 시제·태","question":"If Tovar Motors had invested in automation a decade ago, it ------- far more competitive today.","choices":["would have been","will be","would be","is"],"answer":2,"explanation":"if절은 과거 사실의 반대(had invested ~ a decade ago)이지만 주절은 today로 현재 상황을 말하는 혼합 가정법이므로 would be가 알맞다. would have been은 과거 결과를 나타내 today와 맞지 않고, will be와 is는 가정법이 아니다.","translation":"토바 자동차가 10년 전에 자동화에 투자했더라면 오늘날 훨씬 더 경쟁력이 있을 것이다.","part":5},{"id":"p5-575","level":5,"type":"동사 시제·태","question":"Hardly had the CEO finished her speech when reporters ------- asking questions.","choices":["begin","have begun","had begun","began"],"answer":3,"explanation":"Hardly had + 주어 + p.p. ~ when + 주어 + 과거 동사는 '~하자마자 …했다'라는 구문이므로 when절에는 과거형 began이 온다. begin과 have begun은 현재 시제라 맞지 않고, had begun은 연설이 끝나기 전에 질문이 시작되었다는 뜻이 되어 구문과 어긋난다.","translation":"최고 경영자가 연설을 마치자마자 기자들이 질문을 시작했다.","part":5},{"id":"p5-576","level":5,"type":"동사 시제·태","question":"The riverside warehouse ------- vacant for over a decade before a logistics firm purchased it last month.","choices":["had stood","has stood","stands","will stand"],"answer":0,"explanation":"지난달 매입된 과거 시점(purchased)보다 앞서 10년 넘게 이어진 상태이므로 과거완료 had stood가 정답이다. has stood와 stands는 현재까지의 상태, will stand는 미래를 나타내 과거의 매입 시점 이전과 맞지 않는다.","translation":"강가의 그 창고는 지난달 한 물류 회사가 매입하기 전까지 10년 넘게 비어 있었다.","part":5},{"id":"p5-577","level":5,"type":"동사 시제·태","question":"Sales ------- to recover by the third quarter, according to the latest industry forecast.","choices":["are projected","project","projecting","have projected"],"answer":0,"explanation":"매출은 예측을 '받는' 대상이므로 be projected to do(~할 것으로 예상되다)라는 수동 구문이 알맞다. project와 have projected는 능동이라 '매출이 예측한다'는 틀린 뜻이 되고, projecting은 동사 자리에 올 수 없다.","translation":"최신 업계 전망에 따르면 매출은 3분기까지 회복될 것으로 예상된다.","part":5},{"id":"p5-578","level":5,"type":"동사 시제·태","question":"Were the board ------- the proposal this week, construction could begin immediately.","choices":["approve","to approve","approved","approves"],"answer":1,"explanation":"if를 생략하고 도치한 'Were + 주어 + to부정사'는 미래에 대한 가정(If the board were to approve)을 나타내므로 to approve가 정답이다. approve, approved, approves는 Were 뒤에서 가정법 구문을 완성하지 못한다.","translation":"이사회가 이번 주에 그 안을 승인한다면 공사를 즉시 시작할 수 있을 것이다.","part":5},{"id":"p5-579","level":5,"type":"동사 시제·태","question":"The consultants ------- the merger proposal since early March and are expected to present their findings next week.","choices":["have been reviewing","had reviewed","will review","were reviewed"],"answer":0,"explanation":"since early March(3월 초부터)는 과거부터 지금까지 계속되는 동작을 나타내고, 뒤의 are expected가 현재 시점이므로 현재완료진행 have been reviewing이 알맞다. had reviewed는 과거 기준 시점이 필요하고, will review는 since와 쓸 수 없으며, were reviewed는 수동태라 목적어를 취할 수 없다.","translation":"컨설턴트들은 3월 초부터 합병안을 검토해 왔으며 다음 주에 결과를 발표할 예정이다.","part":5},{"id":"p5-580","level":5,"type":"접속사","question":"------- the contract is renewed or not, the supplier must deliver all pending orders.","choices":["Whether","Either","If","Unless"],"answer":0,"explanation":"뒤에 or not이 있고 '갱신되든 안 되든'이라는 양보의 부사절을 이끌므로 Whether가 정답이다. Either는 절을 이끌지 못하며, If는 문두의 양보 부사절에서 or not과 함께 쓰지 않고, Unless는 or not과 어울리지 않는다.","translation":"계약이 갱신되든 안 되든 공급업체는 미결 주문을 모두 납품해야 한다.","part":5},{"id":"p5-581","level":5,"type":"접속사","question":"The Brussels office will relocate in April, ------- the lease negotiations conclude successfully.","choices":["in spite of","assuming that","whereas","so that"],"answer":1,"explanation":"임대 협상이 성공적으로 끝난다는 '가정하에' 이전한다는 조건이므로 assuming that이 알맞다. in spite of는 전치사라 절을 이끌 수 없고, whereas는 대조, so that은 목적을 나타내 의미가 맞지 않는다.","translation":"임대 협상이 성공적으로 마무리된다면 브뤼셀 사무소는 4월에 이전할 것이다.","part":5},{"id":"p5-582","level":5,"type":"접속사","question":"The merger proposal was approved, ------- with several significant modifications.","choices":["despite","whereas","nor","albeit"],"answer":3,"explanation":"'비록 ~이긴 하지만'이라는 뜻으로 절 없이 전치사구나 형용사구를 바로 이끌 수 있는 접속사 albeit가 정답이다. despite는 뒤에 명사가 바로 와야 해 with구를 이끌 수 없고, whereas는 완전한 절이 필요하며, nor는 부정문 뒤에 쓴다.","translation":"합병안은 몇 가지 중대한 수정이 있긴 했지만 승인되었다.","part":5},{"id":"p5-583","level":5,"type":"접속사","question":"The warehouse is equipped with backup generators ------- production is not interrupted during power outages.","choices":["even if","as though","in order that","rather than"],"answer":2,"explanation":"정전 중에도 생산이 중단되지 '않도록' 발전기를 갖췄다는 목적의 의미이므로 in order that이 알맞다. even if(~라 할지라도)와 as though(마치 ~처럼)는 의미가 맞지 않고, rather than은 대등한 요소를 비교할 때 쓴다.","translation":"그 창고에는 정전 시에도 생산이 중단되지 않도록 비상 발전기가 갖춰져 있다.","part":5},{"id":"p5-584","level":5,"type":"전치사","question":"------- its modest size, the Parisian studio has produced three award-winning films.","choices":["Notwithstanding","Although","Whereas","Nonetheless"],"answer":0,"explanation":"명사구 its modest size 앞에서 '~에도 불구하고'라는 뜻을 나타내는 전치사 Notwithstanding이 정답이다. Although와 Whereas는 접속사라 절이 필요하고, Nonetheless는 접속부사라 명사구를 목적어로 취할 수 없다.","translation":"그 파리의 스튜디오는 작은 규모에도 불구하고 수상작 영화를 세 편이나 제작했다.","part":5},{"id":"p5-585","level":5,"type":"전치사","question":"------- approval from the board, the Nairobi branch will open in October.","choices":["Whereas","Pending","Unless","Provided"],"answer":1,"explanation":"명사구 approval from the board 앞에서 '~을 기다리는 동안, ~을 전제로'라는 뜻을 나타내는 전치사 Pending이 알맞다. Whereas와 Unless는 접속사라 절이 필요하고, Provided도 조건 접속사로 쓰여 뒤에 절이 와야 한다.","translation":"이사회의 승인을 전제로 나이로비 지점은 10월에 문을 열 것이다.","part":5},{"id":"p5-586","level":5,"type":"전치사","question":"Customers will receive store credit ------- a cash refund for the recalled heaters.","choices":["instead","in lieu of","rather","as opposed"],"answer":1,"explanation":"명사구 a cash refund 앞에서 '~ 대신에'라는 뜻의 전치사구 in lieu of가 정답이다. instead와 rather는 부사라 of나 than 없이 명사를 이끌 수 없고, as opposed도 to가 있어야 전치사 역할을 한다.","translation":"고객들은 리콜된 난방기에 대해 현금 환불 대신 매장 적립금을 받게 된다.","part":5},{"id":"p5-587","level":5,"type":"전치사","question":"Dr. Mwangi accepted the innovation award ------- the entire research team.","choices":["in charge of","on behalf of","in spite of","in case of"],"answer":1,"explanation":"연구팀 전체를 '대표하여' 상을 받았다는 뜻이므로 on behalf of가 알맞다. in charge of(~을 책임지는), in spite of(~에도 불구하고), in case of(~의 경우에)는 수상 상황과 의미가 맞지 않는다.","translation":"음왕기 박사는 연구팀 전체를 대표하여 혁신상을 받았다.","part":5},{"id":"p5-588","level":5,"type":"준동사(to부정사·동명사·분사)","question":"------- the tight budget constraints, the team decided to postpone the product launch.","choices":["Giving","To give","Gave","Given"],"answer":3,"explanation":"Given은 '~을 고려하면'이라는 뜻으로 명사구 앞에서 전치사처럼 쓰이는 분사이므로 정답이다. Giving은 '팀이 제약을 준다'는 능동 의미가 되어 맞지 않고, To give는 목적의 의미라 어색하며, Gave는 동사라 접속사 없이 쓸 수 없다.","translation":"빠듯한 예산 제약을 고려해 팀은 제품 출시를 연기하기로 했다.","part":5},{"id":"p5-589","level":5,"type":"준동사(to부정사·동명사·분사)","question":"Several board members objected to ------- the meeting without the finance director present.","choices":["holding","hold","be held","held"],"answer":0,"explanation":"object to의 to는 전치사이므로 뒤에 동명사 holding이 와야 한다. hold와 be held는 to부정사로 착각하게 하는 오답이며, held는 과거형·과거분사라 전치사의 목적어가 될 수 없다.","translation":"몇몇 이사는 재무 이사가 참석하지 않은 상태로 회의를 여는 것에 반대했다.","part":5},{"id":"p5-590","level":5,"type":"준동사(to부정사·동명사·분사)","question":"Consumer data, when properly -------, can reveal valuable insights into purchasing behavior.","choices":["analyzing","analyze","analyzed","analysis"],"answer":2,"explanation":"when (it is) properly analyzed에서 '주어 + be동사'가 생략된 구조이며, 데이터는 '분석되는' 대상이므로 과거분사 analyzed가 알맞다. analyzing은 능동 의미이고, analyze는 동사원형, analysis는 명사라 부사 properly 뒤에 올 수 없다.","translation":"소비자 데이터는 적절히 분석되면 구매 행동에 대한 귀중한 통찰을 제공할 수 있다.","part":5},{"id":"p5-591","level":5,"type":"준동사(to부정사·동명사·분사)","question":"There being no further business -------, the chair adjourned the meeting.","choices":["to discuss","discussing","discussed","discuss"],"answer":0,"explanation":"명사 business를 뒤에서 꾸며 '논의할 안건'이라는 뜻을 만드는 to부정사 to discuss가 정답이다. discussing은 안건이 무언가를 논의한다는 능동 의미가 되고, discussed는 '이미 논의된'이라는 뜻이라 문맥에 맞지 않으며, discuss는 명사를 수식할 수 없다.","translation":"더 논의할 안건이 없었으므로 의장은 회의를 폐회했다.","part":5},{"id":"p5-592","level":5,"type":"관계사","question":"Meridia Energy hired three new analysts, none of ------- had prior experience in the solar sector.","choices":["who","them","whom","which"],"answer":2,"explanation":"쉼표 뒤에서 두 절을 연결하면서 사람 선행사(analysts)를 받는 '부정대명사 + of + 관계대명사' 구조이므로 whom이 알맞다. 전치사 of 뒤에는 who를 쓰지 않고, them은 접속 기능이 없어 두 절을 연결하지 못하며, which는 사물에 쓴다.","translation":"메리디아 에너지는 새 분석가 세 명을 채용했는데, 그중 누구도 태양광 분야 경력이 없었다.","part":5},{"id":"p5-593","level":5,"type":"관계사","question":"The awards committee, ------- decision is final, will announce the winners next week.","choices":["which","whose","whom","that"],"answer":1,"explanation":"빈칸 뒤 명사 decision이 선행사 The awards committee의 결정이므로 소유격 관계대명사 whose가 정답이다. which와 whom은 뒤에 불완전한 절이 와야 하고, that은 쉼표 뒤 계속적 용법에 쓸 수 없다.","translation":"결정이 최종적인 시상 위원회는 다음 주에 수상자를 발표할 것이다.","part":5},{"id":"p5-594","level":5,"type":"관계사","question":"The two firms signed a licensing agreement ------- Kestrel Pharma may sell the drug in 40 countries.","choices":["which","under which","whose","whom"],"answer":1,"explanation":"빈칸 뒤에 완전한 절(Kestrel Pharma may sell the drug ...)이 오므로 '전치사 + 관계대명사'가 필요하고, 계약 '조건하에서'라는 뜻의 under which가 알맞다. which는 불완전한 절을 이끌고, whose는 뒤에 명사가 필요하며, whom은 사람을 받는다.","translation":"두 회사는 케스트럴 제약이 40개국에서 그 약을 판매할 수 있도록 하는 라이선스 계약을 체결했다.","part":5},{"id":"p5-595","level":5,"type":"대명사","question":"Although several colleagues offered to help, Ms. Esposito preferred to complete the audit on her -------.","choices":["alone","behalf","part","own"],"answer":3,"explanation":"on one's own은 '혼자서, 스스로'라는 뜻으로 동료들의 도움 제안과 대조를 이루므로 own이 정답이다. alone은 on her 뒤에 쓰지 않고, on her behalf는 '그녀를 대신하여', on her part는 '그녀 쪽에서는'이라는 뜻이라 문맥에 맞지 않는다.","translation":"여러 동료가 돕겠다고 했지만 에스포지토 씨는 혼자서 감사를 마치기를 원했다.","part":5},{"id":"p5-596","level":5,"type":"대명사","question":"Tallis Insurance offers two dental plans, ------- of which covers orthodontic treatment.","choices":["none","nobody","neither","nothing"],"answer":2,"explanation":"두 개(two dental plans) 중 어느 것도 아니라는 뜻이며 동사가 단수 covers이므로 neither가 알맞다. none은 셋 이상에 주로 쓰고, nobody는 사람, nothing은 of which와 결합해 대상을 가리킬 수 없다.","translation":"탈리스 보험은 치과 보험 두 가지를 제공하는데, 둘 다 교정 치료는 보장하지 않는다.","part":5},{"id":"p5-597","level":5,"type":"수 일치","question":"Included in the package ------- a user manual and a two-year warranty card.","choices":["is","being","are","has been"],"answer":2,"explanation":"보어(Included in the package)가 문두로 나가 주어와 동사가 도치된 구조로, 진짜 주어는 a user manual and a two-year warranty card(복수)이므로 are가 정답이다. is와 has been은 단수 동사이고, being은 동사 자리에 올 수 없다.","translation":"포장 안에는 사용 설명서와 2년 품질 보증서가 들어 있다.","part":5},{"id":"p5-598","level":5,"type":"수 일치","question":"The newly hired interns, as well as the supervisor who oversees their training, ------- expected to attend Monday's orientation.","choices":["is","be","are","being"],"answer":2,"explanation":"A as well as B에서 동사의 수는 A에 맞추므로 복수 주어 The newly hired interns에 맞는 are가 알맞다. is는 바로 앞의 supervisor나 training에 수를 맞춘 오답이고, be와 being은 문장의 동사가 될 수 없다.","translation":"새로 채용된 인턴들은 교육을 담당하는 감독자와 함께 월요일 오리엔테이션에 참석해야 한다.","part":5},{"id":"p5-599","level":5,"type":"비교","question":"Profits at the Lagos branch were three times ------- than those at the Accra branch.","choices":["as great","greater","greatest","great"],"answer":1,"explanation":"뒤에 than이 있으므로 '배수 + 비교급 + than' 구조의 greater가 정답이다. as great는 뒤에 as가 와야 하고, greatest는 최상급, great는 원급이라 than과 함께 쓸 수 없다.","translation":"라고스 지점의 수익은 아크라 지점의 세 배였다.","part":5},{"id":"p5-600","level":5,"type":"비교","question":"The second-quarter results were ------- than analysts had predicted.","choices":["least favorable","less favorably","less favorable","favorable"],"answer":2,"explanation":"be동사 뒤 보어 자리이고 뒤에 than이 있으므로 비교급 형용사 less favorable이 알맞다. least favorable은 최상급이라 than과 쓰지 않고, less favorably는 부사라 보어가 될 수 없으며, favorable은 원급이다.","translation":"2분기 실적은 분석가들의 예상보다 좋지 않았다.","part":5},{"id":"p5-601","level":1,"type":"어휘","question":"Please ------- the lights in the meeting room before you go home.","choices":["put off","get off","turn off","take off"],"answer":2,"explanation":"회의실 전등을 '끄다'는 turn off가 알맞다. take off는 (옷을) 벗다·이륙하다, put off는 미루다, get off는 (차에서) 내리다라는 뜻이라 전등과 어울리지 않는다.","translation":"퇴근하기 전에 회의실 전등을 꺼 주세요.","part":5},{"id":"p5-602","level":1,"type":"어휘","question":"The copy machine on the third floor is out of -------, so please use the one downstairs.","choices":["time","order","line","place"],"answer":1,"explanation":"out of order는 '고장 난'이라는 관용 표현이므로 order가 정답이다. out of place는 '어울리지 않는', out of time은 '시간이 다 된', out of line은 '선을 넘은'이라는 뜻이라 다른 복사기를 쓰라는 문맥과 맞지 않는다.","translation":"3층 복사기가 고장 나서 아래층 복사기를 사용해 주세요.","part":5},{"id":"p5-603","level":1,"type":"어휘","question":"Mr. Dubois will ------- the visitors at the airport on Thursday.","choices":["tell","say","speak","meet"],"answer":3,"explanation":"공항에서 방문객을 '맞이하다'는 meet가 알맞다. say와 tell은 말한 내용을 전하는 동사이고, speak는 자동사로 보통 speak to 형태로 써야 해서 목적어 the visitors를 바로 받을 수 없다.","translation":"뒤부아 씨가 목요일에 공항에서 방문객들을 맞이할 것이다.","part":5},{"id":"p5-604","level":1,"type":"어휘","question":"The bakery near our office bakes fresh ------- before it opens each day.","choices":["bread","fuel","paper","tools"],"answer":0,"explanation":"빵집(bakery)이 매일 문을 열기 전에 '굽는' 신선한 것은 bread(빵)이다. paper, tools, fuel은 bake(굽다)의 목적어가 될 수 없고 fresh와도 어울리지 않는다.","translation":"사무실 근처 빵집은 매일 문을 열기 전에 신선한 빵을 굽는다.","part":5},{"id":"p5-605","level":1,"type":"어휘","question":"Ms. Huang ------- her car in the parking garage next to the office.","choices":["sits","rides","walks","parks"],"answer":3,"explanation":"차를 주차장에 '세워 두다'는 park이므로 parks가 정답이다. walks와 sits는 자동사라 목적어 her car를 바로 받을 수 없고, ride는 자전거·말처럼 올라타는 것에 쓰며 자기 차를 주차장에 두는 의미가 아니다.","translation":"황 씨는 사무실 옆 주차 건물에 차를 주차한다.","part":5},{"id":"p5-606","level":1,"type":"어휘","question":"Please sign your name at the ------- of the form.","choices":["below","bottom","finish","last"],"answer":1,"explanation":"서식의 '맨 아래'에 서명하라는 뜻이므로 at the bottom of가 알맞다. finish와 last는 이 구조에서 명사로 쓰지 않고, below는 전치사·부사라 the와 of 사이 명사 자리에 올 수 없다.","translation":"서식 맨 아래에 이름을 서명해 주세요.","part":5},{"id":"p5-607","level":1,"type":"어휘","question":"Our store will ------- at 8 P.M. tonight because of the holiday.","choices":["close","end","stop","finish"],"answer":0,"explanation":"매장이 오늘 밤 8시에 '문을 닫다'는 close가 알맞다. end, stop, finish는 행사나 일이 '끝나다/멈추다'라는 뜻으로, 매장 영업을 마치고 문을 닫는다는 의미로는 쓰지 않는다.","translation":"휴일 때문에 오늘 밤 저희 매장은 오후 8시에 문을 닫습니다.","part":5},{"id":"p5-608","level":1,"type":"어휘","question":"You can ------- money from the machine in the hotel lobby.","choices":["take in","take on","take out","take up"],"answer":2,"explanation":"기계에서 돈을 '인출하다'는 take out이다. take in은 받아들이다·이해하다, take on은 (일을) 맡다, take up은 (공간·시간을) 차지하다라는 뜻이다.","translation":"호텔 로비에 있는 기계에서 돈을 인출할 수 있습니다.","part":5},{"id":"p5-609","level":1,"type":"어휘","question":"The ------- for the trip to Jeju is $300 per person.","choices":["cost","pay","money","sale"],"answer":0,"explanation":"여행의 '비용'이 1인당 300달러라는 뜻이므로 cost가 정답이다. pay는 주로 급여, money는 셀 수 없는 돈 자체, sale은 판매·할인이라 '여행 경비'를 나타내지 못한다.","translation":"제주 여행 경비는 1인당 300달러이다.","part":5},{"id":"p5-610","level":1,"type":"어휘","question":"Please ------- for a moment while I find your reservation.","choices":["spend","wait","keep","last"],"answer":1,"explanation":"예약을 찾는 동안 '잠시 기다려 달라'는 wait가 알맞다. keep은 목적어나 보어가 필요하고, spend는 (시간·돈을) 쓰다라서 목적어가 필요하며, last는 '지속되다'라는 뜻이라 사람에게 부탁하는 문장에 맞지 않는다.","translation":"예약 내역을 찾는 동안 잠시 기다려 주세요.","part":5},{"id":"p5-611","level":1,"type":"어휘","question":"The marketing team had a long ------- about the new advertisement.","choices":["word","speech","discussion","talking"],"answer":2,"explanation":"새 광고에 대해 '긴 논의'를 했다는 뜻이므로 discussion이 알맞다. talking은 관사 a와 함께 셀 수 있는 명사로 쓰지 않고, speech는 한 사람이 하는 연설, word는 단어라서 팀의 논의를 나타내지 못한다.","translation":"마케팅팀은 새 광고에 대해 오랫동안 논의했다.","part":5},{"id":"p5-612","level":1,"type":"어휘","question":"Ms. Ortiz will ------- the documents to the client by express mail.","choices":["carry","take","bring","send"],"answer":3,"explanation":"고객에게 속달 우편(express mail)으로 서류를 '보내다'는 send다. bring·carry·take는 사람이 직접 들고 가는 상황에 쓰여 우편 발송과 어울리지 않는다.","translation":"오르티스 씨는 서류를 속달 우편으로 고객에게 보낼 것이다.","part":5},{"id":"p5-613","level":1,"type":"품사","question":"Mr. Jensen gave a ------- answer to the customer's question.","choices":["quicken","quickly","quickness","quick"],"answer":3,"explanation":"관사 a와 명사 answer 사이는 명사를 꾸미는 형용사 자리이므로 quick이 정답이다. quickly는 부사, quickness는 명사, quicken은 동사라 명사를 수식할 수 없다.","translation":"젠슨 씨는 고객의 질문에 빠르게 답했다.","part":5},{"id":"p5-614","level":1,"type":"품사","question":"Please drive ------- in the parking lot.","choices":["slowed","slowly","slows","slowness"],"answer":1,"explanation":"완전한 명령문 Please drive 뒤에서 동사 drive를 꾸미는 부사 자리이므로 slowly가 정답이다. slowed와 slows는 동사, slowness는 명사라 동사를 꾸미지 못한다.","translation":"주차장에서는 천천히 운전해 주세요.","part":5},{"id":"p5-615","level":1,"type":"품사","question":"The ------- of the company is located in Seoul.","choices":["officer","officially","office","official"],"answer":2,"explanation":"정관사 The 뒤, 전치사 of 앞은 명사 자리다. 회사의 '사무실'이 서울에 있다는 뜻이므로 office가 정답이다. officer는 사람(임원·경찰관)이라 '위치해 있다'와 어색하고, official은 형용사(명사로는 공무원), officially는 부사다.","translation":"그 회사의 사무실은 서울에 있다.","part":5},{"id":"p5-616","level":1,"type":"품사","question":"Ms. Cruz is very ------- about the new project.","choices":["excited","exciting","excitement","excite"],"answer":0,"explanation":"사람 주어 Ms. Cruz가 '신이 난' 감정을 느끼므로 과거분사형 형용사 excited가 정답이다. exciting은 '흥미진진하게 만드는'으로 사물을 주어로 쓸 때 알맞고, excite는 동사, excitement는 명사다.","translation":"크루즈 씨는 새 프로젝트에 대해 매우 들떠 있다.","part":5},{"id":"p5-617","level":1,"type":"품사","question":"All staff members must wear their ID cards at work for ------- reasons.","choices":["secure","security","secured","securely"],"answer":1,"explanation":"for ------- reasons는 '보안상의 이유로'라는 표현으로, 명사 security가 명사 reasons를 꾸미는 복합명사다. secure는 '안전한'이라는 형용사여서 '안전한 이유'로 의미가 어색하고, securely는 부사, secured는 과거분사다.","translation":"모든 직원은 보안상의 이유로 근무 중 사원증을 착용해야 한다.","part":5},{"id":"p5-618","level":1,"type":"품사","question":"The restaurant on the top floor ------- serves Korean food.","choices":["mainly","mains","maintain","main"],"answer":0,"explanation":"주어 The restaurant와 동사 serves 사이에서 동사를 꾸미는 부사 자리이므로 mainly가 정답이다. main은 형용사, mains는 명사 복수형, maintain은 '유지하다'라는 다른 동사다.","translation":"꼭대기 층 식당은 주로 한식을 제공한다.","part":5},{"id":"p5-619","level":1,"type":"동사 시제·태","question":"Ms. Yamada ------- her parents in Osaka last weekend.","choices":["is visiting","will visit","visited","visits"],"answer":2,"explanation":"last weekend라는 과거 시점 표현이 있으므로 과거 시제 visited가 정답이다. visits는 현재, will visit는 미래, is visiting은 현재진행이라 지난 주말과 맞지 않는다.","translation":"야마다 씨는 지난 주말 오사카에 계신 부모님을 찾아뵈었다.","part":5},{"id":"p5-620","level":1,"type":"동사 시제·태","question":"The sales department ------- its annual party at a hotel next December.","choices":["was holding","has held","held","will hold"],"answer":3,"explanation":"next December라는 미래 시점 표현이 있으므로 미래 시제 will hold가 정답이다. held와 was holding은 과거, has held는 현재완료라 미래 시점과 함께 쓸 수 없다.","translation":"영업부는 내년 12월에 호텔에서 연례 파티를 열 것이다.","part":5},{"id":"p5-621","level":1,"type":"동사 시제·태","question":"Right now, Mr. Ali ------- the conference room for the meeting.","choices":["prepares","prepared","will prepare","is preparing"],"answer":3,"explanation":"Right now(지금)는 현재 진행 중인 동작을 나타내므로 현재진행형 is preparing이 정답이다. prepared는 과거, prepares는 습관적 현재, will prepare는 미래라 '지금 하고 있는' 의미가 아니다.","translation":"지금 알리 씨가 회의를 위해 회의실을 준비하고 있다.","part":5},{"id":"p5-622","level":1,"type":"동사 시제·태","question":"The new menu ------- by the chef every season.","choices":["is changed","to change","changing","changes"],"answer":0,"explanation":"주어 The new menu는 요리사에 의해 '바뀌는' 대상이고 뒤에 by the chef가 있으므로 수동태 is changed가 정답이다. changes는 능동형이라 by the chef와 맞지 않고, changing과 to change는 동사 자리에 단독으로 올 수 없다.","translation":"새 메뉴는 매 계절 요리사가 바꾼다.","part":5},{"id":"p5-623","level":1,"type":"수 일치","question":"The boxes in the storage room ------- very heavy.","choices":["was","be","are","is"],"answer":2,"explanation":"주어의 핵심은 복수명사 The boxes이고 in the storage room은 수식어일 뿐이므로 복수 동사 are가 정답이다. room에 맞춰 단수 is나 was를 고르면 틀린다. be는 동사원형이라 주어 뒤에 바로 올 수 없다.","translation":"창고에 있는 상자들은 매우 무겁다.","part":5},{"id":"p5-624","level":1,"type":"수 일치","question":"Each employee ------- a free lunch on Fridays.","choices":["get","gets","getting","have got"],"answer":1,"explanation":"Each 뒤에는 단수명사가 오고 단수 취급하므로 3인칭 단수 동사 gets가 정답이다. get과 have got은 복수형이고, getting은 동사 자리에 단독으로 올 수 없다.","translation":"모든 직원은 금요일마다 무료 점심을 받는다.","part":5},{"id":"p5-625","level":1,"type":"수 일치","question":"There ------- a message for you at the front desk.","choices":["were","are","be","is"],"answer":3,"explanation":"There is/are 구문에서는 뒤의 명사에 수를 맞춘다. a message가 단수이므로 is가 정답이다. are와 were는 복수형이고, be는 원형이라 이 자리에 쓸 수 없다.","translation":"프런트에 당신 앞으로 메시지가 와 있습니다.","part":5},{"id":"p5-626","level":1,"type":"대명사","question":"Mr. Romero lost ------- wallet on the train this morning.","choices":["his","him","he","himself"],"answer":0,"explanation":"명사 wallet 앞은 소유격 자리이므로 his가 정답이다. him은 목적격, he는 주격, himself는 재귀대명사라 명사 앞에서 '그의'라는 뜻을 나타내지 못한다.","translation":"로메로 씨는 오늘 아침 기차에서 지갑을 잃어버렸다.","part":5},{"id":"p5-627","level":1,"type":"대명사","question":"Ms. Adams called the clients and thanked ------- for their orders.","choices":["their","they","them","theirs"],"answer":2,"explanation":"동사 thanked의 목적어 자리이므로 목적격 them이 정답이다. they는 주격, their는 소유격, theirs는 소유대명사라 '그들에게 감사했다'의 목적어로 맞지 않는다.","translation":"애덤스 씨는 고객들에게 전화해 주문에 감사를 표했다.","part":5},{"id":"p5-628","level":1,"type":"대명사","question":"If you have any questions, please ask ------- at the information desk.","choices":["ours","us","our","we"],"answer":1,"explanation":"동사 ask의 목적어 자리이므로 목적격 us가 정답이다. we는 주격, our는 소유격이라 뒤에 명사가 필요하고, ours는 '우리의 것'이라 문맥에 맞지 않는다.","translation":"질문이 있으시면 안내 데스크에서 저희에게 물어보세요.","part":5},{"id":"p5-629","level":1,"type":"전치사","question":"The bank is open ------- Monday to Friday.","choices":["on","in","at","from"],"answer":3,"explanation":"from A to B는 'A부터 B까지'라는 기간 표현이므로 from이 정답이다. at, in, on은 뒤의 to와 짝을 이루어 범위를 나타내지 못한다.","translation":"은행은 월요일부터 금요일까지 문을 연다.","part":5},{"id":"p5-630","level":1,"type":"전치사","question":"Please leave the package ------- the front door.","choices":["to","in","at","on"],"answer":2,"explanation":"현관문 '앞에(에)' 두라는 특정 지점을 나타내므로 at이 알맞다. in the front door는 문 '안에', on the front door는 문 '표면 위에'라는 뜻이 되어 어색하고, to는 방향을 나타내 leave와 맞지 않는다.","translation":"소포는 현관문 앞에 놓아 주세요.","part":5},{"id":"p5-631","level":1,"type":"전치사","question":"The staff meeting will be held ------- the afternoon.","choices":["at","in","by","on"],"answer":1,"explanation":"아침·오후·저녁 같은 하루의 때는 in the morning/afternoon/evening처럼 in을 쓴다. at은 시각, on은 요일·날짜 앞에 쓰고, by는 '~까지'라는 기한을 나타낸다.","translation":"직원 회의는 오후에 열릴 것이다.","part":5},{"id":"p5-632","level":1,"type":"접속사","question":"Ms. Lim was tired, ------- she finished the report on time.","choices":["but","so","because","or"],"answer":0,"explanation":"'피곤했지만 보고서를 제시간에 끝냈다'는 대조 관계이므로 but이 정답이다. so는 결과(그래서), or는 선택, because는 이유를 나타내 앞뒤 내용과 논리가 맞지 않는다.","translation":"림 씨는 피곤했지만 보고서를 제시간에 끝냈다.","part":5},{"id":"p5-633","level":1,"type":"접속사","question":"Please check your e-mail ------- you get to the office.","choices":["but","or","when","so"],"answer":2,"explanation":"'사무실에 도착하면 이메일을 확인하라'는 시간 관계이므로 부사절 접속사 when이 정답이다. but, or, so는 등위접속사로 시간 조건을 나타내지 못한다.","translation":"사무실에 도착하면 이메일을 확인해 주세요.","part":5},{"id":"p5-634","level":1,"type":"접속사","question":"Would you like tea ------- coffee with your dessert?","choices":["or","and","so","but"],"answer":0,"explanation":"차와 커피 중 하나를 고르게 하는 선택 의문문이므로 or가 정답이다. and는 둘 다, but은 대조, so는 결과를 나타내 선택을 묻는 문장에 맞지 않는다.","translation":"디저트와 함께 차나 커피 중 무엇을 드시겠어요?","part":5},{"id":"p5-635","level":1,"type":"관계사","question":"The man ------- fixed our computer works for an IT company.","choices":["what","whose","which","who"],"answer":3,"explanation":"선행사가 사람(The man)이고 빈칸 뒤에 주어 없이 동사 fixed가 이어지므로 주격 관계대명사 who가 정답이다. which는 사물, whose는 뒤에 명사가 필요하고, what은 선행사를 포함해 앞에 명사가 있으면 쓸 수 없다.","translation":"우리 컴퓨터를 고쳐 준 남자는 IT 회사에서 일한다.","part":5},{"id":"p5-636","level":1,"type":"관계사","question":"This is the laptop ------- I bought for my new job.","choices":["who","that","where","whose"],"answer":1,"explanation":"선행사 the laptop이 사물이고, 빈칸 뒤 I bought에 목적어가 빠져 있으므로 목적격 관계대명사 that이 정답이다. who는 사람, where는 장소 뒤에서 완전한 절을 이끌고, whose는 뒤에 명사가 와야 한다.","translation":"이것은 내가 새 직장을 위해 산 노트북이다.","part":5},{"id":"p5-637","level":1,"type":"준동사(to부정사·동명사·분사)","question":"Mr. Okoye needs ------- the hotel before Friday.","choices":["called","to call","call","calling"],"answer":1,"explanation":"need는 to부정사를 목적어로 취해 'need to do(~해야 한다)'로 쓰므로 to call이 정답이다. calling은 need -ing가 '~될 필요가 있다'는 수동 의미라 사람 주어와 어색하고, call과 called는 need 뒤에 바로 올 수 없다.","translation":"오코예 씨는 금요일 전에 호텔에 전화해야 한다.","part":5},{"id":"p5-638","level":1,"type":"준동사(to부정사·동명사·분사)","question":"Thank you for ------- the survey about our service.","choices":["completed","to complete","completing","complete"],"answer":2,"explanation":"전치사 for 뒤에는 동명사가 오므로 completing이 정답이다. complete는 동사원형, completed는 과거형·과거분사, to complete는 to부정사라 전치사의 목적어가 될 수 없다.","translation":"저희 서비스에 대한 설문을 작성해 주셔서 감사합니다.","part":5},{"id":"p5-639","level":1,"type":"비교","question":"Taking the subway is ------- than driving to the stadium.","choices":["faster","more fast","fastest","fast"],"answer":0,"explanation":"뒤에 than이 있으므로 비교급이 와야 하고, fast의 비교급은 faster다. fast는 원급, fastest는 최상급이며, more fast는 1음절 형용사에 쓰지 않는 틀린 형태다.","translation":"경기장까지는 지하철을 타는 것이 운전하는 것보다 빠르다.","part":5},{"id":"p5-640","level":1,"type":"비교","question":"This is the ------- restaurant in our neighborhood.","choices":["more old","old","older","oldest"],"answer":3,"explanation":"the와 함께 '동네에서 가장 오래된'이라는 최상급 의미가 필요하므로 oldest가 정답이다. older는 비교급이라 than이 필요하고, old는 원급, more old는 틀린 형태다.","translation":"이곳은 우리 동네에서 가장 오래된 식당이다.","part":5},{"id":"p5-641","level":2,"type":"어휘","question":"Please ------- the enclosed form and return it in the envelope provided.","choices":["run out","fill out","find out","carry out"],"answer":1,"explanation":"서식을 '작성하다'는 fill out이다. carry out은 (계획을) 실행하다, find out은 알아내다, run out은 다 떨어지다라는 뜻이라 form을 목적어로 자연스럽게 받지 못한다.","translation":"동봉된 서식을 작성하여 제공된 봉투에 넣어 반송해 주세요.","part":5},{"id":"p5-642","level":2,"type":"어휘","question":"The hotel ------- guests a 10 percent discount on spa services.","choices":["provides","supplies","delivers","offers"],"answer":3,"explanation":"'offer + 사람 + 물건' 형태로 '~에게 …을 제공하다'를 나타내므로 offers가 정답이다. provides와 supplies는 provide A with B처럼 전치사가 필요해 목적어 두 개를 바로 받지 못하고, delivers는 물건을 배달한다는 뜻이다.","translation":"그 호텔은 투숙객에게 스파 서비스 10퍼센트 할인을 제공한다.","part":5},{"id":"p5-643","level":2,"type":"어휘","question":"Mr. Abbott is in charge of ------- new employees during their first week.","choices":["practicing","learning","training","studying"],"answer":2,"explanation":"신입 사원들을 '교육하다'는 train이므로 training이 정답이다. learning과 studying은 스스로 배우는 것이라 사람을 목적어로 받지 않고, practicing은 (기술을) 연습하다라는 뜻이라 사람을 목적어로 받지 않는다.","translation":"애벗 씨는 신입 사원들의 첫 주 교육을 맡고 있다.","part":5},{"id":"p5-644","level":2,"type":"어휘","question":"The flight was delayed for two hours because of a mechanical -------.","choices":["problem","subject","question","matter"],"answer":0,"explanation":"기계적인 '문제(고장)'는 mechanical problem이 자연스러운 조합이다. matter와 subject는 화제·주제, question은 질문이라는 뜻이라 기체 고장을 나타내지 못한다.","translation":"기계적 문제로 비행기가 두 시간 지연되었다.","part":5},{"id":"p5-645","level":2,"type":"어휘","question":"Ms. Novak has ------- a table for six at an Italian restaurant.","choices":["assigned","reserved","accepted","admitted"],"answer":1,"explanation":"식당에 자리를 '예약하다'는 reserve이므로 reserved가 정답이다. assigned는 배정하다, accepted는 받아들이다, admitted는 입장을 허락하다·인정하다라는 뜻이라 식당 테이블과 어울리지 않는다.","translation":"노박 씨는 이탈리안 식당에 6인 테이블을 예약했다.","part":5},{"id":"p5-646","level":2,"type":"어휘","question":"The ------- for the job fair will be posted on the company Web site.","choices":["details","matters","points","pieces"],"answer":0,"explanation":"채용 박람회의 '세부 사항'이 웹사이트에 게시된다는 뜻이므로 details가 정답이다. matters는 문제·사안, points는 요점·점수, pieces는 조각이라 행사 안내 내용을 나타내기에 어색하다.","translation":"채용 박람회에 관한 세부 사항은 회사 웹사이트에 게시될 것이다.","part":5},{"id":"p5-647","level":2,"type":"어휘","question":"Please ------- at least 30 minutes early for your job interview.","choices":["get","attend","reach","arrive"],"answer":3,"explanation":"arrive는 자동사라 목적어 없이 '도착하다'로 쓸 수 있으므로 정답이다. reach와 attend는 타동사라 목적어(장소·면접)가 필요하고, get은 get there처럼 장소 표현이 있어야 '도착하다'의 뜻이 된다.","translation":"면접에는 최소 30분 일찍 도착해 주세요.","part":5},{"id":"p5-648","level":2,"type":"어휘","question":"Our ------- hours are from 9 A.M. to 6 P.M., Monday through Saturday.","choices":["market","trade","business","company"],"answer":2,"explanation":"'영업시간'은 business hours라는 고정 표현이다. company hours, trade hours, market hours는 매장·사무실의 영업시간을 나타내는 일반적인 표현이 아니다.","translation":"저희 영업시간은 월요일부터 토요일까지 오전 9시부터 오후 6시까지입니다.","part":5},{"id":"p5-649","level":2,"type":"어휘","question":"The manager asked everyone to ------- their ideas at the next meeting.","choices":["divide","join","spend","share"],"answer":3,"explanation":"아이디어를 '공유하다'는 share가 알맞다. divide는 나누다(분할), spend는 (돈·시간을) 쓰다, join은 참여하다라는 뜻이라 ideas와 어울리지 않는다.","translation":"관리자는 모두에게 다음 회의 때 아이디어를 공유해 달라고 요청했다.","part":5},{"id":"p5-650","level":2,"type":"어휘","question":"Ms. Grant had to ------- her trip to London because of a family emergency.","choices":["delete","cancel","quit","remove"],"answer":1,"explanation":"여행을 '취소하다'는 cancel이다. remove는 제거하다, delete는 (파일 등을) 삭제하다, quit는 (일·습관을) 그만두다라는 뜻이라 trip과 함께 쓰지 않는다.","translation":"그랜트 씨는 집안의 급한 일 때문에 런던 출장을 취소해야 했다.","part":5},{"id":"p5-651","level":2,"type":"어휘","question":"The warehouse needs more ------- to handle the holiday orders.","choices":["workers","visitors","customers","guests"],"answer":0,"explanation":"연휴 주문을 '처리하기 위해' 더 필요한 사람은 workers(작업자)다. customers, guests, visitors는 주문을 처리하는 사람이 아니라 서비스를 받는 쪽이다.","translation":"창고는 연휴 주문을 처리하려면 작업자가 더 필요하다.","part":5},{"id":"p5-652","level":2,"type":"어휘","question":"The store is having a ------- sale on all winter jackets this week.","choices":["clean","clear","clearance","clearing"],"answer":2,"explanation":"재고 정리 할인은 clearance sale이라는 고정 표현이다. clean과 clear는 형용사라 '깨끗한/분명한 할인'이 되어 뜻이 맞지 않고, clearing은 '개간지·청산'이라는 뜻이어서 sale과 결합하지 않는다.","translation":"이번 주 그 매장은 모든 겨울 재킷을 재고 정리 할인한다.","part":5},{"id":"p5-653","level":2,"type":"품사","question":"The training session was ------- useful for new staff.","choices":["specialty","specialize","especially","especial"],"answer":2,"explanation":"be동사 was와 형용사 useful 사이에서 형용사를 꾸미는 부사 자리이므로 especially가 정답이다. especial은 형용사, specialty는 명사, specialize는 동사라 형용사를 수식하지 못한다.","translation":"그 교육은 신입 직원에게 특히 유용했다.","part":5},{"id":"p5-654","level":2,"type":"품사","question":"Ms. Moreno made an ------- to visit the factory next Tuesday.","choices":["arrangement","arrange","arranging","arranged"],"answer":0,"explanation":"관사 an과 to부정사 사이는 동사 made의 목적어가 되는 명사 자리이므로 arrangement가 정답이다. arrange는 동사, arranged와 arranging은 분사·동명사로 관사 an 뒤에 올 수 없다.","translation":"모레노 씨는 다음 주 화요일에 공장을 방문하기로 약속을 잡았다.","part":5},{"id":"p5-655","level":2,"type":"품사","question":"Please handle the glass items -------.","choices":["care","careful","careless","carefully"],"answer":3,"explanation":"handle the glass items라는 완전한 문장 뒤에서 동사를 꾸미는 부사가 필요하므로 carefully가 정답이다. careful과 careless는 형용사, care는 명사·동사라 이 자리에 맞지 않는다.","translation":"유리 제품은 조심해서 다뤄 주세요.","part":5},{"id":"p5-656","level":2,"type":"품사","question":"The company's new logo is simple but -------.","choices":["attractively","attractive","attraction","attract"],"answer":1,"explanation":"but으로 형용사 simple과 대등하게 연결되는 보어 자리이므로 형용사 attractive가 정답이다. attract는 동사, attraction은 명사, attractively는 부사라 be동사의 보어로 simple과 나란히 쓸 수 없다.","translation":"회사의 새 로고는 단순하지만 매력적이다.","part":5},{"id":"p5-657","level":2,"type":"품사","question":"The ------- of the two companies was announced this morning.","choices":["agreeably","agree","agreement","agreeable"],"answer":2,"explanation":"The 뒤, of 앞은 주어가 되는 명사 자리이므로 agreement가 정답이다. agree는 동사, agreeable은 형용사, agreeably는 부사다.","translation":"두 회사 간의 합의가 오늘 아침 발표되었다.","part":5},{"id":"p5-658","level":2,"type":"전치사","question":"Online orders are usually delivered ------- three business days.","choices":["among","onto","into","within"],"answer":3,"explanation":"'영업일 3일 이내에'라는 기간의 한도는 within이 나타낸다. onto는 표면 위로의 이동, into는 안으로의 이동, among은 셋 이상 사이를 나타내 기간 표현과 맞지 않는다.","translation":"온라인 주문은 보통 영업일 기준 3일 이내에 배송된다.","part":5},{"id":"p5-659","level":2,"type":"동사 시제·태","question":"Ms. Diallo ------- at this company for five years.","choices":["works","has worked","is working","will work"],"answer":1,"explanation":"for five years는 과거부터 지금까지 이어진 기간을 나타내므로 현재완료 has worked가 정답이다. works와 is working은 현재의 상태·동작만, will work는 미래를 나타내 지속 기간과 맞지 않는다.","translation":"디알로 씨는 이 회사에서 5년째 일하고 있다.","part":5},{"id":"p5-660","level":2,"type":"동사 시제·태","question":"The conference room ------- for a client meeting tomorrow afternoon.","choices":["has been reserved","has reserved","reserves","reserving"],"answer":0,"explanation":"회의실은 '예약되는' 대상이므로 수동태가 필요하고, 이미 예약이 끝난 상태를 나타내는 현재완료 수동 has been reserved가 정답이다. reserves와 has reserved는 능동형이라 목적어가 필요하고, reserving은 단독으로 동사 자리에 올 수 없다.","translation":"회의실은 내일 오후 고객 회의를 위해 예약되어 있다.","part":5},{"id":"p5-661","level":2,"type":"동사 시제·태","question":"When the client called, Mr. Wright ------- lunch.","choices":["eats","was eating","will eat","has eaten"],"answer":1,"explanation":"고객이 전화한 과거의 한 시점에 진행 중이던 동작이므로 과거진행형 was eating이 정답이다. eats는 현재, has eaten은 현재완료, will eat은 미래라 과거 시점 when절과 맞지 않는다.","translation":"고객이 전화했을 때 라이트 씨는 점심을 먹고 있었다.","part":5},{"id":"p5-662","level":2,"type":"동사 시제·태","question":"All the invitations ------- to guests last Friday.","choices":["are mailing","have mailed","mailed","were mailed"],"answer":3,"explanation":"초대장은 '발송되는' 대상이고 last Friday가 과거를 나타내므로 과거 수동태 were mailed가 정답이다. mailed와 have mailed는 능동이라 초대장이 무언가를 보낸 뜻이 되고, are mailing은 현재진행 능동이다.","translation":"모든 초대장은 지난 금요일 손님들에게 우편으로 발송되었다.","part":5},{"id":"p5-663","level":2,"type":"수 일치","question":"The list of participants ------- on the bulletin board.","choices":["is","are","have been","were"],"answer":0,"explanation":"주어의 핵심은 단수명사 The list이고 of participants는 수식어이므로 단수 동사 is가 정답이다. participants에 이끌려 are, were, have been 같은 복수 동사를 고르면 틀린다.","translation":"참가자 명단은 게시판에 붙어 있다.","part":5},{"id":"p5-664","level":2,"type":"수 일치","question":"Both the director and her assistant ------- to the trade show.","choices":["goes","has gone","are going","is going"],"answer":2,"explanation":"Both A and B는 복수 주어이므로 복수 동사 are going이 정답이다. is going, goes, has gone은 모두 단수 동사 형태다.","translation":"이사와 그녀의 비서 둘 다 무역 박람회에 간다.","part":5},{"id":"p5-665","level":2,"type":"수 일치","question":"Most of the furniture in the lobby ------- new.","choices":["is","were","are","have"],"answer":0,"explanation":"most of 뒤 명사의 수에 동사를 맞춘다. furniture는 셀 수 없는 명사이므로 단수 동사 is가 정답이다. are와 were는 복수 동사이고, have는 '가지다'라는 뜻이라 형용사 new 앞에서 쓸 수 없다.","translation":"로비의 가구 대부분은 새것이다.","part":5},{"id":"p5-666","level":2,"type":"대명사","question":"Mr. Hughes and I will present ------- findings at the meeting.","choices":["us","ours","our","we"],"answer":2,"explanation":"명사 findings 앞은 소유격 자리이고, 주어가 Mr. Hughes and I(우리)이므로 our가 정답이다. us는 목적격, we는 주격, ours는 소유대명사라 명사 앞에 올 수 없다.","translation":"휴스 씨와 나는 회의에서 우리의 조사 결과를 발표할 것이다.","part":5},{"id":"p5-667","level":2,"type":"대명사","question":"Ms. Choi designed the brochure by -------.","choices":["hers","her","she","herself"],"answer":3,"explanation":"by oneself는 '혼자서, 스스로'라는 뜻이므로 재귀대명사 herself가 정답이다. by her는 '그녀에 의해'라는 다른 사람을 가리키는 뜻이 되고, hers는 소유대명사, she는 주격이라 전치사 뒤에 올 수 없다.","translation":"최 씨는 혼자서 그 안내 책자를 디자인했다.","part":5},{"id":"p5-668","level":2,"type":"대명사","question":"These umbrellas belong to the hotel, so please return ------- to the front desk.","choices":["their","them","it","they"],"answer":1,"explanation":"앞의 복수명사 These umbrellas를 받는 목적어이므로 them이 정답이다. it은 단수라 수가 맞지 않고, they는 주격, their는 소유격이다.","translation":"이 우산들은 호텔 소유이므로 프런트에 돌려주세요.","part":5},{"id":"p5-669","level":2,"type":"전치사","question":"Our office is located ------- the second floor of the Lincoln Building.","choices":["at","in","by","on"],"answer":3,"explanation":"건물의 층은 on the second floor처럼 on을 쓴다. in과 at은 층 앞에 쓰지 않고, by는 '옆에'라는 뜻이라 층을 나타내지 못한다.","translation":"저희 사무실은 링컨 빌딩 2층에 있습니다.","part":5},{"id":"p5-670","level":2,"type":"전치사","question":"Please submit your expense report ------- the end of the month.","choices":["during","by","since","until"],"answer":1,"explanation":"'월말까지' 제출을 끝내야 하는 마감 시한은 by가 나타낸다. until은 그때까지 '계속' 이어지는 동작에 쓰이므로 submit 같은 한 번의 동작과 어울리지 않고, since는 '~이후로', during은 '~동안'이다.","translation":"월말까지 경비 보고서를 제출해 주세요.","part":5},{"id":"p5-671","level":2,"type":"전치사","question":"The speaker talked ------- the history of the company.","choices":["about","with","at","for"],"answer":0,"explanation":"'~에 대해 이야기하다'는 talk about이다. talk for는 '~을 대변하여/~시간 동안', talk with는 '~와 이야기하다', talk at은 일방적으로 말하다는 뜻이라 주제를 나타내지 못한다.","translation":"연사는 회사의 역사에 대해 이야기했다.","part":5},{"id":"p5-672","level":2,"type":"접속사","question":"------- you need help with your luggage, please ask our staff.","choices":["Because","Unless","If","Although"],"answer":2,"explanation":"'도움이 필요하면 직원에게 요청하라'는 조건이므로 If가 정답이다. Unless는 '~하지 않으면'이라 뜻이 반대가 되고, Although는 양보, Because는 이유를 나타내 문맥과 맞지 않는다.","translation":"짐 옮기는 데 도움이 필요하시면 저희 직원에게 요청하세요.","part":5},{"id":"p5-673","level":2,"type":"접속사","question":"The store will stay open late ------- many customers are expected.","choices":["until","unless","because","although"],"answer":2,"explanation":"'많은 고객이 예상되기 때문에 늦게까지 영업한다'는 이유 관계이므로 because가 정답이다. although는 양보(~에도 불구하고), unless는 부정 조건, until은 시간의 끝을 나타내 의미가 맞지 않는다.","translation":"많은 고객이 예상되기 때문에 매장은 늦게까지 문을 열 것이다.","part":5},{"id":"p5-674","level":2,"type":"접속사","question":"You can contact us ------- by phone or by e-mail.","choices":["either","both","neither","whether"],"answer":0,"explanation":"뒤의 or와 짝을 이루는 상관접속사는 either A or B(A 또는 B)이므로 either가 정답이다. both는 and, neither는 nor와 짝을 이루고, whether는 or와 쓰여도 '~이든 아니든'의 부사절·명사절을 이끌어 이 문장에 맞지 않는다.","translation":"전화나 이메일로 저희에게 연락하실 수 있습니다.","part":5},{"id":"p5-675","level":2,"type":"관계사","question":"Employees ------- want to join the tennis club should contact Mr. Bae.","choices":["which","who","whose","whom"],"answer":1,"explanation":"선행사 Employees가 사람이고 빈칸 뒤에 주어 없이 동사 want가 오므로 주격 관계대명사 who가 정답이다. which는 사물, whose는 뒤에 명사가 필요하며, whom은 목적격이라 주어 자리에 쓸 수 없다.","translation":"테니스 동호회에 가입하고 싶은 직원은 배 씨에게 연락해야 한다.","part":5},{"id":"p5-676","level":2,"type":"관계사","question":"The city ------- the conference will be held is famous for its seafood.","choices":["which","who","what","where"],"answer":3,"explanation":"빈칸 뒤 the conference will be held가 완전한 절이고 선행사가 장소(The city)이므로 관계부사 where가 정답이다. which는 뒤에 불완전한 절이 와야 하고, who는 사람, what은 선행사를 포함해 앞에 명사가 있으면 쓸 수 없다.","translation":"회의가 열릴 도시는 해산물로 유명하다.","part":5},{"id":"p5-677","level":2,"type":"준동사(to부정사·동명사·분사)","question":"Mr. Petrov decided ------- the earlier train to Moscow.","choices":["taking","taken","to take","take"],"answer":2,"explanation":"decide는 to부정사를 목적어로 취하는 동사이므로 to take가 정답이다. taking은 동명사라 decide의 목적어로 쓰지 않고, take와 taken은 decided 뒤에 바로 올 수 없다.","translation":"페트로프 씨는 모스크바행 이른 기차를 타기로 했다.","part":5},{"id":"p5-678","level":2,"type":"준동사(to부정사·동명사·분사)","question":"The ------- prices will appear on your receipt at checkout.","choices":["reduces","reducing","reduce","reduced"],"answer":3,"explanation":"가격은 '할인된' 대상이므로 수동·완료의 의미를 가진 과거분사 reduced가 명사 prices를 꾸민다. reducing은 '줄이는'이라는 능동 의미라 가격이 무언가를 줄이는 뜻이 되고, reduce와 reduces는 동사라 명사를 수식할 수 없다.","translation":"할인된 가격은 계산 시 영수증에 표시됩니다.","part":5},{"id":"p5-679","level":2,"type":"비교","question":"The second hotel was ------- expensive than the first one.","choices":["fewer","less","least","little"],"answer":1,"explanation":"뒤에 than과 형용사 expensive가 있으므로 '덜 비싼'을 나타내는 less가 정답이다. least는 최상급, little은 원급이며, fewer는 셀 수 있는 명사 앞에 쓰여 형용사를 꾸미지 못한다.","translation":"두 번째 호텔이 첫 번째 호텔보다 덜 비쌌다.","part":5},{"id":"p5-680","level":2,"type":"비교","question":"This is the ------- useful app for checking train times.","choices":["most","much","more","very"],"answer":0,"explanation":"the와 함께 '가장 유용한'이라는 최상급이 필요하고, useful은 2음절 이상이라 the most useful로 쓴다. more는 비교급이라 than이 필요하고, much와 very는 the ------- 자리의 최상급을 만들지 못한다.","translation":"이것은 기차 시간을 확인하기에 가장 유용한 앱이다.","part":5},{"id":"p5-681","level":3,"type":"어휘","question":"Before signing the lease, Ms. Barros asked the landlord to ------- the broken window.","choices":["respond","refer","renew","repair"],"answer":3,"explanation":"깨진 창문을 '수리하다'는 repair다. respond는 자동사로 respond to 형태가 필요하고, renew는 (계약을) 갱신하다, refer는 참조하다·소개하다라는 뜻이라 broken window와 어울리지 않는다.","translation":"임대 계약서에 서명하기 전에 바로스 씨는 집주인에게 깨진 창문을 수리해 달라고 요청했다.","part":5},{"id":"p5-682","level":3,"type":"어휘","question":"Fernhill Electronics will ------- a new line of wireless headphones in September.","choices":["involve","introduce","inform","invite"],"answer":1,"explanation":"새 제품군을 '출시하다(선보이다)'는 introduce가 알맞다. inform은 사람에게 알리다로 사람 목적어가 필요하고, involve는 포함하다·관련시키다, invite는 초대하다라는 뜻이다.","translation":"펀힐 일렉트로닉스는 9월에 새 무선 헤드폰 제품군을 출시할 것이다.","part":5},{"id":"p5-683","level":3,"type":"어휘","question":"Please keep this receipt as ------- of your payment.","choices":["price","promise","proof","profit"],"answer":2,"explanation":"영수증을 결제의 '증거'로 보관하라는 뜻이므로 proof가 정답이다. price는 가격, profit은 이익, promise는 약속이라 receipt와 의미가 맞지 않는다.","translation":"결제 증빙으로 이 영수증을 보관해 주세요.","part":5},{"id":"p5-684","level":3,"type":"어휘","question":"The orientation session will give new hires an ------- of the company's policies.","choices":["overview","outcome","outlook","output"],"answer":0,"explanation":"정책 전반에 대한 '개요'를 제공한다는 뜻이므로 overview가 정답이다. outlook은 전망, outcome은 결과, output은 생산량이라 '정책에 대한 설명'을 나타내지 못한다.","translation":"오리엔테이션은 신입 사원들에게 회사 정책의 개요를 알려 줄 것이다.","part":5},{"id":"p5-685","level":3,"type":"어휘","question":"Mr. Lindgren ------- the client's call to the sales department.","choices":["translated","transformed","transferred","transported"],"answer":2,"explanation":"전화를 다른 부서로 '돌려 연결하다'는 transfer이므로 transferred가 정답이다. transported는 (물건을) 운송하다, translated는 번역하다, transformed는 변형시키다라는 뜻이다.","translation":"린드그렌 씨는 고객의 전화를 영업부로 돌려 주었다.","part":5},{"id":"p5-686","level":3,"type":"어휘","question":"Due to heavy traffic, the shuttle bus may arrive a few minutes -------.","choices":["late","lateness","lately","latest"],"answer":0,"explanation":"'몇 분 늦게' 도착한다는 뜻의 부사 late가 정답이다. lately는 '최근에'라는 전혀 다른 뜻이고, latest는 최상급 형용사라 a few minutes 뒤에 올 수 없으며, lateness는 명사다.","translation":"교통 체증 때문에 셔틀버스가 몇 분 늦게 도착할 수 있다.","part":5},{"id":"p5-687","level":3,"type":"어휘","question":"The finance team will ------- the costs of the two shipping options.","choices":["compete","compare","complain","comply"],"answer":1,"explanation":"두 배송 방식의 비용을 '비교하다'는 compare다. compete(경쟁하다), complain(불평하다), comply(준수하다)는 모두 자동사로 전치사(with, about)가 필요하고 의미도 맞지 않는다.","translation":"재무팀은 두 가지 배송 방식의 비용을 비교할 것이다.","part":5},{"id":"p5-688","level":3,"type":"어휘","question":"Customers who sign up for our newsletter will receive ------- offers by e-mail.","choices":["extensive","expensive","excessive","exclusive"],"answer":3,"explanation":"뉴스레터 가입자만 받는 '독점(특별) 혜택'은 exclusive offers다. expensive(비싼)와 excessive(과도한)는 혜택을 나쁘게 묘사해 문맥에 어긋나고, extensive(광범위한)는 offers와 어울리지 않는다.","translation":"뉴스레터에 가입한 고객은 이메일로 독점 혜택을 받게 된다.","part":5},{"id":"p5-689","level":3,"type":"어휘","question":"The museum is ------- closed for renovations but will reopen in May.","choices":["eventually","temporarily","originally","previously"],"answer":1,"explanation":"'5월에 다시 연다'는 뒷부분과 이어지려면 '일시적으로' 문을 닫았다는 temporarily가 알맞다. previously(이전에)와 originally(원래)는 현재형 is closed와 어울리지 않고, eventually(결국)는 재개관 계획과 논리가 맞지 않는다.","translation":"박물관은 보수 공사로 일시 휴관 중이지만 5월에 다시 문을 연다.","part":5},{"id":"p5-690","level":3,"type":"어휘","question":"Ms. Kapoor's application was ------- because it arrived after the deadline.","choices":["reflected","retreated","rejected","resisted"],"answer":2,"explanation":"마감 후 도착한 지원서가 '불합격 처리되었다(받아들여지지 않았다)'는 rejected가 알맞다. reflected는 반영되다·반사되다, resisted는 저항을 받다라는 뜻이라 지원서 처리와 맞지 않고, retreated는 '물러나다'라는 자동사라 수동태로 쓸 수 없다.","translation":"카푸르 씨의 지원서는 마감 이후에 도착해서 반려되었다.","part":5},{"id":"p5-691","level":3,"type":"어휘","question":"The new coffee machine can ------- up to 50 cups at a time.","choices":["make","create","do","build"],"answer":0,"explanation":"커피를 '만들다(끓이다)'는 make coffee/cups가 자연스러운 조합이다. build는 짓다, do는 행동을 하다, create는 창작하다라는 뜻이라 커피와 결합하지 않는다.","translation":"새 커피 머신은 한 번에 최대 50잔을 만들 수 있다.","part":5},{"id":"p5-692","level":3,"type":"어휘","question":"All employees must attend the safety training, ------- of their position.","choices":["instead","because","despite","regardless"],"answer":3,"explanation":"'직위에 관계없이'는 regardless of가 고정 표현이다. despite는 뒤에 of 없이 명사가 오고, instead of는 '~ 대신에', because of는 '~ 때문에'라는 뜻이라 문맥에 맞지 않는다.","translation":"모든 직원은 직위에 관계없이 안전 교육에 참석해야 한다.","part":5},{"id":"p5-693","level":3,"type":"품사","question":"Ms. Ferraro's report was well organized and ------- written.","choices":["clarify","clarity","clear","clearly"],"answer":3,"explanation":"과거분사 written을 꾸미는 부사 자리이므로 clearly가 정답이다. well organized와 and로 대등하게 연결된 '부사+분사' 구조라는 점을 확인한다. clear는 형용사, clarity는 명사, clarify는 동사다.","translation":"페라로 씨의 보고서는 잘 정리되어 있고 명확하게 쓰여 있었다.","part":5},{"id":"p5-694","level":3,"type":"품사","question":"The hotel received ------- reviews from guests who stayed during the festival.","choices":["positivity","positive","positiveness","positively"],"answer":1,"explanation":"동사 received의 목적어 reviews를 앞에서 꾸미는 형용사 자리이므로 positive가 정답이다. positively는 부사라 명사를 수식하지 못하고, positiveness와 positivity는 명사다.","translation":"그 호텔은 축제 기간에 머문 투숙객들로부터 긍정적인 후기를 받았다.","part":5},{"id":"p5-695","level":3,"type":"품사","question":"The ------- of the new parking system has reduced waiting times.","choices":["introduction","introduced","introduce","introductory"],"answer":0,"explanation":"정관사 The와 전치사 of 사이는 주어가 되는 명사 자리이므로 introduction이 정답이다. introduce는 동사, introductory는 형용사, introduced는 과거형·과거분사라 명사 자리에 올 수 없다.","translation":"새 주차 시스템을 도입한 뒤로 대기 시간이 줄었다.","part":5},{"id":"p5-696","level":3,"type":"품사","question":"Applicants must be ------- in at least one foreign language.","choices":["proficiently","proficiencies","proficient","proficiency"],"answer":2,"explanation":"be동사 뒤 보어 자리이면서 in과 함께 '~에 능숙한'을 뜻하는 형용사가 필요하므로 proficient가 정답이다. proficiency는 명사라 주어와 동격이 되지 않고, proficiently는 부사, proficiencies는 복수명사다.","translation":"지원자는 외국어 하나 이상에 능숙해야 한다.","part":5},{"id":"p5-697","level":3,"type":"품사","question":"Our sales figures for May were ------- higher than those for April.","choices":["slightest","slight","slightly","slighted"],"answer":2,"explanation":"비교급 higher를 꾸미는 부사 자리이므로 slightly가 정답이다. slight와 slightest는 형용사라 비교급 형용사를 수식하지 못하고, slighted는 '무시당한'이라는 과거분사다.","translation":"5월 매출 수치는 4월보다 약간 높았다.","part":5},{"id":"p5-698","level":3,"type":"품사","question":"Mr. Osei is the ------- for organizing the company's year-end party.","choices":["coordinator","coordinating","coordination","coordinate"],"answer":0,"explanation":"the와 for 사이의 명사 자리이고, 주어 Mr. Osei와 같은 사람을 나타내야 하므로 coordinator(진행 담당자)가 정답이다. coordination도 명사지만 '조정·협력'이라는 행위라서 사람인 주어와 동격이 될 수 없다. coordinate는 동사, coordinating은 동명사·분사다.","translation":"오세이 씨는 회사 송년회 준비를 맡은 진행 담당자이다.","part":5},{"id":"p5-699","level":3,"type":"동사 시제·태","question":"The board ------- the budget proposal at next Tuesday's meeting.","choices":["discussed","had discussed","has discussed","will discuss"],"answer":3,"explanation":"at next Tuesday's meeting이라는 미래 시점이 있으므로 will discuss가 정답이다. discussed는 과거, has discussed는 현재완료, had discussed는 과거완료라 미래 시점과 함께 쓰지 않는다.","translation":"이사회는 다음 주 화요일 회의에서 예산안을 논의할 것이다.","part":5},{"id":"p5-700","level":3,"type":"동사 시제·태","question":"Since the new manager arrived, the department ------- several changes.","choices":["will make","has made","made","makes"],"answer":1,"explanation":"since가 이끄는 절(과거 시점)부터 지금까지 이어진 일을 나타내므로 주절은 현재완료 has made가 알맞다. makes는 현재, made는 단순 과거로 since절과 함께 쓰기 어렵고, will make는 미래다.","translation":"새 관리자가 온 이후로 그 부서는 몇 가지 변화를 주었다.","part":5},{"id":"p5-701","level":3,"type":"동사 시제·태","question":"The damaged items ------- with new ones at no extra cost.","choices":["are replacing","have replaced","will replace","will be replaced"],"answer":3,"explanation":"손상된 물품은 새것으로 '교체되는' 대상이므로 수동태가 필요하고, 앞으로의 처리를 안내하는 will be replaced가 정답이다. will replace, are replacing, have replaced는 모두 능동형이라 뒤에 목적어가 필요하다.","translation":"손상된 물품은 추가 비용 없이 새 제품으로 교체될 것이다.","part":5},{"id":"p5-702","level":3,"type":"동사 시제·태","question":"Mr. Castro ------- the report before his manager returned from lunch.","choices":["had finished","will have finished","has finished","finishes"],"answer":0,"explanation":"매니저가 돌아온 과거 시점(returned)보다 더 먼저 끝난 일이므로 과거완료 had finished가 정답이다. has finished는 현재완료라 과거 기준점과 맞지 않고, finishes는 현재, will have finished는 미래완료다.","translation":"카스트로 씨는 매니저가 점심 식사에서 돌아오기 전에 보고서를 끝냈다.","part":5},{"id":"p5-703","level":3,"type":"수 일치","question":"The results of the customer survey ------- surprising to the marketing team.","choices":["is","has been","were","was"],"answer":2,"explanation":"주어의 핵심은 복수명사 The results이고 of the customer survey는 수식어이므로 복수 동사 were가 정답이다. survey에 맞춰 was, is, has been 같은 단수 동사를 고르면 틀린다.","translation":"고객 설문 결과는 마케팅팀에게 의외였다.","part":5},{"id":"p5-704","level":3,"type":"수 일치","question":"Neither the printer nor the scanners ------- working this morning.","choices":["is","were","was","has been"],"answer":1,"explanation":"Neither A nor B는 동사를 B에 맞춘다. B인 the scanners가 복수이므로 were가 정답이다. 앞의 the printer에 맞춰 was를 고르는 것이 흔한 함정이다.","translation":"오늘 아침에는 프린터도 스캐너들도 작동하지 않았다.","part":5},{"id":"p5-705","level":3,"type":"수 일치","question":"Every room and suite at the Belmont Hotel ------- a balcony.","choices":["are having","has","having","have"],"answer":1,"explanation":"Every가 A and B를 함께 꾸미면 단수 취급하므로 has가 정답이다. and에 이끌려 복수 have를 고르기 쉽지만 Every가 붙으면 단수다. having은 동사 자리에 단독으로 쓸 수 없고, are having은 복수이며 상태 동사 have를 진행형으로 쓴 것이다.","translation":"벨몬트 호텔의 모든 객실과 스위트룸에는 발코니가 있다.","part":5},{"id":"p5-706","level":3,"type":"대명사","question":"The marketing director wants each team member to present ------- own idea.","choices":["his or her","himself or herself","him or her","he or she"],"answer":0,"explanation":"명사 own idea 앞은 소유격 자리이므로 his or her가 정답이다. him or her는 목적격, he or she는 주격, himself or herself는 재귀대명사라 own 앞에 올 수 없다.","translation":"마케팅 이사는 팀원 각자가 자신의 아이디어를 발표하기를 바란다.","part":5},{"id":"p5-707","level":3,"type":"대명사","question":"Our prices are lower than ------- of our competitors.","choices":["these","that","them","those"],"answer":3,"explanation":"앞의 복수명사 prices를 반복하지 않고 받는 대명사로 those가 정답이다. that은 단수명사를 받아 수가 맞지 않고, these는 of 수식을 받는 비교 대상 대명사로 쓰지 않으며, them은 뒤에 of 수식어를 붙일 수 없다.","translation":"저희 가격은 경쟁사들의 가격보다 낮습니다.","part":5},{"id":"p5-708","level":3,"type":"대명사","question":"Ms. Sato and Mr. Bell reviewed the contract and found no errors in -------.","choices":["them","itself","it","its"],"answer":2,"explanation":"앞의 단수명사 the contract를 받는 전치사 in의 목적어이므로 it이 정답이다. them은 복수라 계약서 하나를 받지 못하고, its는 소유격이라 뒤에 명사가 필요하며, itself는 주어가 계약서가 아니므로 재귀대명사를 쓸 수 없다.","translation":"사토 씨와 벨 씨는 계약서를 검토했고 그 안에서 오류를 발견하지 못했다.","part":5},{"id":"p5-709","level":3,"type":"전치사","question":"The parking garage will be closed ------- the renovation of the main entrance.","choices":["between","during","while","since"],"answer":1,"explanation":"뒤에 명사구 the renovation이 오고 '보수 공사 기간 동안'이라는 뜻이므로 전치사 during이 정답이다. while은 접속사라 뒤에 절이 와야 하고, between은 두 대상 '사이'를 나타내 명사 하나와 쓰지 않으며, since는 '~이래로'라 미래의 closed와 맞지 않는다.","translation":"정문 보수 공사 기간 동안 주차 건물은 폐쇄될 것이다.","part":5},{"id":"p5-710","level":3,"type":"전치사","question":"The new procedures will apply to all employees, ------- part-time workers.","choices":["include","included","includes","including"],"answer":3,"explanation":"'시간제 근로자를 포함하여'라는 뜻으로 명사 앞에서 전치사처럼 쓰이는 including이 정답이다. included는 명사 뒤에 쓰여야 하고(part-time workers included), include와 includes는 동사라 콤마 뒤에 접속사 없이 올 수 없다.","translation":"새 절차는 시간제 근로자를 포함한 모든 직원에게 적용된다.","part":5},{"id":"p5-711","level":3,"type":"전치사","question":"Ms. Novak received a promotion ------- her excellent sales record.","choices":["because of","even though","because","so that"],"answer":0,"explanation":"뒤에 명사구 her excellent sales record가 오므로 전치사구 because of가 정답이다. because, so that, even though는 접속사라 뒤에 주어와 동사를 갖춘 절이 와야 한다.","translation":"노박 씨는 뛰어난 영업 실적 덕분에 승진했다.","part":5},{"id":"p5-712","level":3,"type":"접속사","question":"------- the weather improves, the outdoor company picnic will be moved indoors.","choices":["Since","If","Unless","Because"],"answer":2,"explanation":"'날씨가 좋아지지 않으면 실내로 옮긴다'는 부정 조건이므로 Unless가 정답이다. If를 쓰면 '날씨가 좋아지면 실내로 옮긴다'가 되어 논리가 반대이고, Because와 Since는 이유를 나타내 마찬가지로 어색하다.","translation":"날씨가 좋아지지 않으면 야외 회사 야유회는 실내로 옮겨질 것이다.","part":5},{"id":"p5-713","level":3,"type":"접속사","question":"The training manual is long, ------- it is easy to understand.","choices":["or","so","for","yet"],"answer":3,"explanation":"'길지만 이해하기 쉽다'는 대조이므로 등위접속사 yet이 정답이다. so는 결과, for는 이유, or는 선택을 나타내 앞뒤 내용과 맞지 않는다.","translation":"교육 매뉴얼은 길지만 이해하기 쉽다.","part":5},{"id":"p5-714","level":3,"type":"접속사","question":"Please let us know ------- you will attend the awards dinner.","choices":["whether","that","which","what"],"answer":0,"explanation":"know의 목적어로 '참석할지 여부'를 나타내는 명사절이 필요하므로 whether가 정답이다. that은 '참석할 것이라는 사실'을 알려 달라는 뜻이 되어 상대가 참석 여부를 정하는 상황에 맞지 않고, what과 which는 뒤에 불완전한 절이 와야 하는데 이 절은 완전하다.","translation":"시상식 만찬에 참석하실지 알려 주세요.","part":5},{"id":"p5-715","level":3,"type":"관계사","question":"The supplier ------- prices were the lowest won the contract.","choices":["which","whose","who","whom"],"answer":1,"explanation":"빈칸 뒤 명사 prices가 '그 공급업체의 가격'이라는 소유 관계이므로 소유격 관계대명사 whose가 정답이다. who·which·whom은 뒤에 명사를 바로 연결해 소유 관계를 나타낼 수 없다.","translation":"가격이 가장 낮은 공급업체가 계약을 따냈다.","part":5},{"id":"p5-716","level":3,"type":"관계사","question":"Tomorrow is the day ------- the new branch officially opens.","choices":["what","where","when","which"],"answer":2,"explanation":"선행사가 시간(the day)이고 뒤의 절 the new branch officially opens가 완전하므로 관계부사 when이 정답이다. which는 불완전한 절을 이끌고, where는 장소 선행사에 쓰며, what은 선행사를 포함한다.","translation":"내일은 새 지점이 공식적으로 문을 여는 날이다.","part":5},{"id":"p5-717","level":3,"type":"준동사(to부정사·동명사·분사)","question":"The company is planning ------- its customer service hours.","choices":["to extend","extending","extended","extend"],"answer":0,"explanation":"plan은 to부정사를 목적어로 취하므로 to extend가 정답이다. extending은 plan의 목적어로 쓰지 않고, extend와 extended는 is planning 뒤에 바로 올 수 없다.","translation":"회사는 고객 서비스 시간을 연장할 계획이다.","part":5},{"id":"p5-718","level":3,"type":"준동사(to부정사·동명사·분사)","question":"------- the instructions carefully, Ms. Park assembled the shelf in an hour.","choices":["To be followed","Followed","Follow","Following"],"answer":3,"explanation":"주절의 주어 Ms. Park이 설명서를 '따르는' 능동 관계이므로 현재분사 Following으로 시작하는 분사구문이 정답이다. Followed는 수동이라 Ms. Park이 따라진다는 뜻이 되고, Follow는 명령문 형태라 콤마 뒤 절과 연결되지 않으며, To be followed도 수동 의미다.","translation":"설명서를 꼼꼼히 따라서 박 씨는 한 시간 만에 선반을 조립했다.","part":5},{"id":"p5-719","level":3,"type":"비교","question":"The new model is ------- lighter than the previous one.","choices":["very","more","much","most"],"answer":2,"explanation":"비교급 lighter를 강조하는 부사로 much가 정답이다. very는 원급을 꾸미고 비교급은 꾸미지 못하며, more는 이미 비교급인 lighter와 겹치고, most는 최상급이다.","translation":"새 모델은 이전 모델보다 훨씬 가볍다.","part":5},{"id":"p5-720","level":3,"type":"비교","question":"Of all the candidates, Ms. Reyes answered the questions -------.","choices":["confidently than","most confidently","most confident","more confident"],"answer":1,"explanation":"Of all the candidates(모든 지원자 중에서)는 최상급 범위이고, 동사 answered를 꾸미는 부사가 필요하므로 most confidently가 정답이다. most confident는 형용사라 동사를 꾸미지 못하고, more confident는 비교급 형용사, confidently than은 비교급 표지가 없다.","translation":"모든 지원자 중에서 레예스 씨가 질문에 가장 자신 있게 답했다.","part":5},{"id":"p5-721","level":4,"type":"어휘","question":"Orders placed after 3 P.M. will be ------- on the next business day.","choices":["processed","proceeded","progressed","produced"],"answer":0,"explanation":"주문이 '처리되다'는 process의 수동태 processed가 알맞다. proceed와 progress는 자동사라 수동태로 쓸 수 없고, produced는 '생산되다'로 이미 들어온 주문과 어울리지 않는다.","translation":"오후 3시 이후 접수된 주문은 다음 영업일에 처리됩니다.","part":5},{"id":"p5-722","level":4,"type":"어휘","question":"The CEO ------- the success of the product launch to the hard work of the design team.","choices":["admitted","distributed","contributed","attributed"],"answer":3,"explanation":"attribute A to B는 'A를 B의 덕분(탓)으로 돌리다'라는 뜻으로 정답이다. contribute A to B는 'A를 B에 기여(기부)하다'라 성공을 디자인팀에게 '기부했다'는 어색한 뜻이 되고, distributed는 배포하다, admitted는 인정하다·입장시키다이다.","translation":"CEO는 제품 출시의 성공을 디자인팀의 노고 덕분으로 돌렸다.","part":5},{"id":"p5-723","level":4,"type":"어휘","question":"Late checkout is available at no charge but is ------- on room availability.","choices":["responsive","decisive","dependent","reliable"],"answer":2,"explanation":"be dependent on은 '~에 달려 있다'라는 뜻으로, 늦은 체크아웃이 객실 상황에 따라 결정된다는 문맥에 맞는다. reliable(믿을 만한)은 on과 결합해 조건을 나타내지 못하고, decisive(결정적인)와 responsive(반응하는, to와 결합)도 의미와 전치사가 맞지 않는다.","translation":"늦은 체크아웃은 무료로 이용할 수 있지만 객실 사정에 따라 달라집니다.","part":5},{"id":"p5-724","level":4,"type":"어휘","question":"The workshop is ------- to employees who have worked here for at least one year.","choices":["wide","open","near","clear"],"answer":1,"explanation":"be open to는 '~에게 열려 있다(참가 자격이 있다)'라는 뜻으로 정답이다. near는 거리상 '가까운', clear to는 '~에게 분명한', wide는 '넓은'이라 워크숍의 참가 대상을 나타내지 못한다.","translation":"이 워크숍은 근무한 지 1년 이상 된 직원이 참가할 수 있다.","part":5},{"id":"p5-725","level":4,"type":"어휘","question":"The engineering team found a ------- solution to the overheating problem.","choices":["practice","practiced","practical","practicing"],"answer":2,"explanation":"과열 문제에 대한 '실용적인' 해결책이라는 뜻으로 practical이 정답이다. practiced는 '숙련된'이라 사람·기술에 쓰이고, practicing은 '현직의'(practicing lawyer), practice는 명사·동사라 solution을 적절히 꾸미지 못한다.","translation":"엔지니어링팀은 과열 문제에 대한 실용적인 해결책을 찾았다.","part":5},{"id":"p5-726","level":4,"type":"어휘","question":"Mr. Halvorsen will ------- the quarterly sales meeting in place of Ms. Duarte.","choices":["stand","chair","sit","seat"],"answer":1,"explanation":"회의를 '주재하다(의장을 맡다)'는 동사 chair다. seat는 '앉히다', sit와 stand는 자동사라 목적어 the meeting을 바로 받을 수 없다(sit in on, stand in for처럼 전치사가 필요).","translation":"할보르센 씨가 두아르테 씨를 대신해 분기 영업 회의를 주재할 것이다.","part":5},{"id":"p5-727","level":4,"type":"어휘","question":"The renovation project was completed well ------- the original budget.","choices":["among","beside","along","within"],"answer":3,"explanation":"well within budget은 '예산 범위 안에서 넉넉히'라는 뜻의 표현이므로 within이 정답이다. among은 여럿 사이, beside는 옆에, along은 ~을 따라라는 뜻이라 예산과 함께 쓰지 않는다.","translation":"보수 공사 프로젝트는 원래 예산 범위 내에서 넉넉히 완료되었다.","part":5},{"id":"p5-728","level":4,"type":"어휘","question":"To ------- the needs of a growing client base, Dunmore Bank is hiring 40 new tellers.","choices":["meet","pass","achieve","reach"],"answer":0,"explanation":"'요구를 충족하다'는 meet the needs가 고정 연어다. reach와 achieve는 목표·합의에 주로 쓰이고, pass는 지나가다·통과하다라는 뜻이라 needs와 결합하지 않는다.","translation":"늘어나는 고객층의 요구를 충족하기 위해 던모어 은행은 창구 직원 40명을 새로 채용하고 있다.","part":5},{"id":"p5-729","level":4,"type":"어휘","question":"Passengers are advised to keep their belongings within ------- at all times.","choices":["glance","look","notice","sight"],"answer":3,"explanation":"within sight는 '시야 안에, 보이는 곳에'라는 관용 표현이므로 sight가 정답이다. glance는 '흘끗 봄', look은 '봄·표정', notice는 '알아챔·공지'라는 뜻으로 within과 결합해 눈에 보이는 범위를 나타내지 못한다.","translation":"승객 여러분은 항상 소지품을 눈에 보이는 곳에 두시기 바랍니다.","part":5},{"id":"p5-730","level":4,"type":"어휘","question":"The company's annual revenue has ------- doubled since it entered the Asian market.","choices":["nearly","shortly","closely","hardly"],"answer":0,"explanation":"수치 표현 doubled 앞에서 '거의'를 뜻하는 nearly가 알맞다. closely는 '면밀히', shortly는 '곧', hardly는 '거의 ~않다'라는 부정 의미라 매출 증가 내용과 맞지 않는다.","translation":"아시아 시장에 진출한 이후 회사의 연간 매출은 거의 두 배가 되었다.","part":5},{"id":"p5-731","level":4,"type":"어휘","question":"Ms. Ahn has ------- experience in negotiating contracts with overseas suppliers.","choices":["expansive","extended","extensive","expensive"],"answer":2,"explanation":"'폭넓은(풍부한) 경험'은 extensive experience가 대표적인 연어다. expansive는 '광활한·개방적인', expensive는 '비싼', extended는 '연장된'이라 경험의 양을 나타내지 못한다.","translation":"안 씨는 해외 공급업체와의 계약 협상 경험이 풍부하다.","part":5},{"id":"p5-732","level":4,"type":"어휘","question":"Interested vendors must submit their ------- no later than June 30.","choices":["purposes","proposals","proportions","provisions"],"answer":1,"explanation":"관심 있는 업체가 마감일까지 제출하는 것은 '제안서'이므로 proposals가 정답이다. purposes는 목적, proportions는 비율, provisions는 조항·공급이라 제출 대상으로 어색하다.","translation":"관심 있는 납품업체는 늦어도 6월 30일까지 제안서를 제출해야 한다.","part":5},{"id":"p5-733","level":4,"type":"품사","question":"The new filing system has made document retrieval far more -------.","choices":["efficiently","efficiencies","efficiency","efficient"],"answer":3,"explanation":"make + 목적어 + 목적격 보어 구조에서 보어 자리에는 형용사가 오므로 efficient가 정답이다. far more가 있어 부사 efficiently를 고르기 쉽지만 부사는 목적격 보어가 될 수 없다. efficiency와 efficiencies는 명사다.","translation":"새 문서 정리 시스템 덕분에 문서를 찾는 일이 훨씬 효율적이 되었다.","part":5},{"id":"p5-734","level":4,"type":"품사","question":"Several ------- for the position have more than ten years of experience.","choices":["applications","applicants","applies","applicable"],"answer":1,"explanation":"Several 뒤 복수명사 자리이고, '10년 이상의 경력을 가진' 주체는 사람이어야 하므로 applicants(지원자)가 정답이다. applications(지원서)도 복수명사지만 서류가 경력을 가질 수는 없다. applies는 동사, applicable은 형용사다.","translation":"그 직책에 지원한 사람 중 몇 명은 10년 이상의 경력을 갖고 있다.","part":5},{"id":"p5-735","level":4,"type":"품사","question":"The inspector found the safety equipment to be in ------- condition.","choices":["excellent","excellence","excel","excellently"],"answer":0,"explanation":"전치사 in과 명사 condition 사이에서 명사를 꾸미는 형용사 자리이므로 excellent가 정답이다. excellence는 명사라 condition 앞에서 수식어로 어색하고, excel은 동사, excellently는 부사다.","translation":"검사관은 안전 장비가 매우 좋은 상태임을 확인했다.","part":5},{"id":"p5-736","level":4,"type":"품사","question":"Ms. Kaur responded ------- to every complaint the store received last month.","choices":["personal","personalize","personally","personality"],"answer":2,"explanation":"동사 responded를 꾸미는 부사 자리이므로 personally(직접)가 정답이다. personal은 형용사, personality는 명사, personalize는 동사라 동사를 수식할 수 없다.","translation":"카우르 씨는 지난달 매장에 접수된 모든 불만에 직접 응대했다.","part":5},{"id":"p5-737","level":4,"type":"품사","question":"The merger will result in significant cost ------- for both companies.","choices":["saves","savings","saved","saver"],"answer":1,"explanation":"cost savings는 '비용 절감'이라는 복합명사로, 형용사 significant의 수식을 받는 명사 자리에 맞다. saves는 동사, saved는 과거분사, saver는 '절약하는 사람(것)'이라 의미가 맞지 않는다.","translation":"합병으로 두 회사 모두 상당한 비용을 절감하게 될 것이다.","part":5},{"id":"p5-738","level":4,"type":"품사","question":"The two firms worked ------- to develop the new payment platform.","choices":["collaboration","collaborate","collaboratively","collaborative"],"answer":2,"explanation":"worked라는 자동사 뒤에서 동사를 꾸미는 부사 자리이므로 collaboratively가 정답이다. collaborative는 형용사, collaboration은 명사, collaborate는 동사라 이 자리에 올 수 없다.","translation":"두 회사는 새 결제 플랫폼을 개발하기 위해 협력하여 일했다.","part":5},{"id":"p5-739","level":4,"type":"동사 시제·태","question":"The new branch in Busan ------- next month, pending final approval from headquarters.","choices":["has been opened","scheduled to open","was opening","is scheduled to open"],"answer":3,"explanation":"next month라는 미래 일정을 나타내므로 be scheduled to do(~할 예정이다)가 정답이다. scheduled to open은 동사 be가 빠져 문장의 동사가 없고, has been opened는 이미 완료된 수동, was opening은 과거진행이라 미래 일정과 맞지 않는다.","translation":"부산 신규 지점은 본사의 최종 승인을 거쳐 다음 달 문을 열 예정이다.","part":5},{"id":"p5-740","level":4,"type":"동사 시제·태","question":"By the time the new software is installed, the staff ------- the training sessions.","choices":["will have completed","have completed","completed","had completed"],"answer":0,"explanation":"By the time + 현재시제 절은 미래의 기준 시점을 나타내므로 그때까지 완료될 일은 미래완료 will have completed가 알맞다. have completed는 현재완료, had completed와 completed는 과거 기준이라 미래 시점과 맞지 않는다.","translation":"새 소프트웨어가 설치될 무렵이면 직원들은 교육을 마쳤을 것이다.","part":5},{"id":"p5-741","level":4,"type":"동사 시제·태","question":"Applicants ------- of the hiring decision by the end of next week.","choices":["will notify","will be notified","have notified","notify"],"answer":1,"explanation":"지원자는 결과를 '통보받는' 대상이므로 notify A of B의 수동형이 필요하고, by the end of next week가 미래이므로 will be notified가 정답이다. will notify, notify, have notified는 능동형이라 뒤에 목적어가 와야 한다.","translation":"지원자들은 다음 주말까지 채용 결정을 통보받을 것이다.","part":5},{"id":"p5-742","level":4,"type":"동사 시제·태","question":"If the shipment ------- on time, we would not have missed the deadline.","choices":["arrived","has arrived","had arrived","would arrive"],"answer":2,"explanation":"주절이 would not have missed(가정법 과거완료)이므로 if절은 had + p.p.인 had arrived가 정답이다. arrived는 가정법 과거, has arrived는 현재완료, would arrive는 if절에 쓰지 않는 형태다.","translation":"배송품이 제때 도착했더라면 우리는 마감을 놓치지 않았을 것이다.","part":5},{"id":"p5-743","level":4,"type":"수 일치","question":"The number of visitors to the trade show ------- expected to exceed 10,000.","choices":["are","were","have been","is"],"answer":3,"explanation":"The number of(~의 수)는 단수 취급하므로 is가 정답이다. A number of(많은)는 복수 취급하므로 둘을 혼동해 are를 고르는 것이 함정이다. were와 have been도 복수형이다.","translation":"무역 박람회 방문객 수는 1만 명을 넘을 것으로 예상된다.","part":5},{"id":"p5-744","level":4,"type":"수 일치","question":"Twenty dollars ------- the fee for parking in the garage for a full day.","choices":["is","be","are","were"],"answer":0,"explanation":"금액·거리·시간처럼 하나의 단위로 보는 수량 표현은 단수 취급하므로 is가 정답이다. dollars가 복수형이라 are를 고르기 쉽지만 '20달러'라는 하나의 금액을 가리킨다. were는 복수 과거형, be는 원형이다.","translation":"주차 건물에 하루 종일 주차하는 요금은 20달러이다.","part":5},{"id":"p5-745","level":4,"type":"수 일치","question":"The manager, along with two engineers, ------- to inspect the plant next week.","choices":["is scheduled","have been scheduled","are scheduled","were scheduled"],"answer":0,"explanation":"along with, together with, as well as가 이끄는 부분은 수식어이므로 동사는 앞의 주어 The manager에 맞춘다. 단수이고 next week가 미래 일정이므로 is scheduled가 정답이다. two engineers에 맞춰 복수 동사를 고르면 틀린다.","translation":"관리자는 엔지니어 두 명과 함께 다음 주에 공장을 점검할 예정이다.","part":5},{"id":"p5-746","level":4,"type":"대명사","question":"Employees who have not yet registered for the seminar should do ------- by Friday.","choices":["such","as","so","too"],"answer":2,"explanation":"앞의 동사구 register for the seminar를 대신하는 표현은 do so(그렇게 하다)이므로 so가 정답이다. such와 as는 do 뒤에서 앞의 동작을 받는 대용어로 쓰이지 않고, too는 '또한'이라는 뜻이라 do too는 '나도 그렇다'는 다른 의미가 된다.","translation":"세미나에 아직 등록하지 않은 직원은 금요일까지 등록해야 한다.","part":5},{"id":"p5-747","level":4,"type":"대명사","question":"The two departments use different software, which makes sharing files between ------- difficult.","choices":["themselves","they","their","them"],"answer":3,"explanation":"전치사 between의 목적어로 앞의 The two departments를 받는 목적격 them이 정답이다. they는 주격, their는 소유격이며, themselves는 주어가 sharing(일반 행위)이어서 재귀대명사를 쓸 조건이 맞지 않는다.","translation":"두 부서가 서로 다른 소프트웨어를 써서 부서 간 파일 공유가 어렵다.","part":5},{"id":"p5-748","level":4,"type":"대명사","question":"Ms. Tanaka's design was chosen over ------- submitted by the other finalists.","choices":["them","those","theirs","it"],"answer":1,"explanation":"앞의 design을 받으면서 과거분사구 submitted by...의 수식을 받는 대명사는 that/those다. '다른 결선 진출자들이 낸 디자인들'이므로 복수 those가 정답이다. them과 it은 뒤에서 분사의 수식을 받지 못하고, theirs는 이미 '그들의 것'이라 by the other finalists와 의미가 겹친다.","translation":"다나카 씨의 디자인이 다른 결선 진출자들이 제출한 디자인들보다 선택되었다.","part":5},{"id":"p5-749","level":4,"type":"전치사","question":"Ms. Iqbal was promoted to regional manager ------- her outstanding performance.","choices":["in recognition of","in charge of","in spite of","in exchange for"],"answer":0,"explanation":"'뛰어난 실적을 인정받아' 승진했다는 뜻이므로 in recognition of가 정답이다. in exchange for는 '~의 대가로'라 거래의 뉘앙스가 되고, in charge of는 '~을 담당하는', in spite of는 '~에도 불구하고'라 문맥과 반대다.","translation":"이크발 씨는 뛰어난 실적을 인정받아 지역 관리자로 승진했다.","part":5},{"id":"p5-750","level":4,"type":"전치사","question":"Refunds will be issued only ------- presentation of the original receipt.","choices":["across","onto","above","upon"],"answer":3,"explanation":"upon presentation of는 '~을 제시하면(제시하는 즉시)'이라는 격식 표현이므로 upon이 정답이다. onto는 위로의 이동, above는 위쪽, across는 가로질러라는 공간 전치사라 의미가 맞지 않는다.","translation":"환불은 영수증 원본을 제시해야만 이루어집니다.","part":5},{"id":"p5-751","level":4,"type":"전치사","question":"The new policy applies to all contracts signed ------- January 1.","choices":["at or after","in or after","on or after","by or after"],"answer":2,"explanation":"특정 날짜 앞에는 on을 쓰므로 '1월 1일 당일 또는 그 이후'는 on or after가 정답이다. in은 월·연도, at은 시각 앞에 쓰고, by는 '~까지'라 after와 함께 범위를 만들지 못한다.","translation":"새 정책은 1월 1일 또는 그 이후에 체결된 모든 계약에 적용된다.","part":5},{"id":"p5-752","level":4,"type":"접속사","question":"------- the contract is signed, the construction team will begin work immediately.","choices":["Whereas","As soon as","So that","Even if"],"answer":1,"explanation":"'계약이 체결되자마자 즉시 공사를 시작한다'는 시간 관계이므로 As soon as가 정답이다. Even if는 양보, So that은 목적(앞에 결과 절이 와야 함), Whereas는 대조를 나타낸다.","translation":"계약이 체결되자마자 시공팀은 즉시 작업을 시작할 것이다.","part":5},{"id":"p5-753","level":4,"type":"접속사","question":"The seminar was rescheduled ------- more employees could attend.","choices":["so that","such that","as if","in case"],"answer":0,"explanation":"'더 많은 직원이 참석할 수 있도록' 일정을 바꿨다는 목적이므로 so that이 정답이다. in case는 '~할 경우에 대비해', as if는 '마치 ~인 것처럼', such that은 '~할 정도로'(정도·결과)라 목적을 나타내지 못한다.","translation":"더 많은 직원이 참석할 수 있도록 세미나 일정이 변경되었다.","part":5},{"id":"p5-754","level":4,"type":"접속사","question":"The marketing budget was cut this year; -------, the team exceeded its sales targets.","choices":["therefore","otherwise","moreover","nevertheless"],"answer":3,"explanation":"'예산이 삭감되었는데도 목표를 초과했다'는 대조이므로 접속부사 nevertheless(그럼에도 불구하고)가 정답이다. therefore는 결과, otherwise는 '그렇지 않으면', moreover는 '게다가'라 논리가 맞지 않는다.","translation":"올해 마케팅 예산이 삭감되었지만 팀은 판매 목표를 초과 달성했다.","part":5},{"id":"p5-755","level":4,"type":"관계사","question":"The workshop, ------- was led by a leading economist, drew over 300 participants.","choices":["what","which","where","that"],"answer":1,"explanation":"콤마 뒤 계속적 용법에서 사물 선행사 The workshop을 받고 빈칸 뒤에 주어가 빠져 있으므로 which가 정답이다. that은 계속적 용법(콤마 뒤)에 쓸 수 없고, what은 선행사를 포함하며, where는 완전한 절을 이끈다.","translation":"유명 경제학자가 진행한 그 워크숍에는 300명이 넘는 참가자가 모였다.","part":5},{"id":"p5-756","level":4,"type":"관계사","question":"The consultant recommended a strategy ------- the company could reduce its shipping costs.","choices":["of which","whom","by which","which"],"answer":2,"explanation":"빈칸 뒤 the company could reduce its shipping costs가 완전한 절이므로 '전치사 + 관계대명사'가 필요하고, '그 전략으로(그것에 의해) 비용을 줄인다'는 뜻이므로 by which가 정답이다. which만 쓰면 뒤에 불완전한 절이 와야 하고, of which는 의미가 맞지 않으며, whom은 사람 선행사에 쓴다.","translation":"컨설턴트는 회사가 배송비를 줄일 수 있는 전략을 제안했다.","part":5},{"id":"p5-757","level":4,"type":"준동사(to부정사·동명사·분사)","question":"Customers ------- in the loyalty program receive a 5 percent discount on every purchase.","choices":["to enroll","enroll","enrolls","enrolled"],"answer":3,"explanation":"멤버십 프로그램에 '등록된' 고객이라는 상태를 나타내는 과거분사 enrolled가 정답이다(be enrolled in). enroll과 enrolls는 동사라 주어 뒤 수식어가 될 수 없고 문장에 동사 receive가 이미 있으며, to enroll은 '등록할'이라는 미래 의미다.","translation":"멤버십 프로그램에 등록된 고객은 구매할 때마다 5퍼센트 할인을 받는다.","part":5},{"id":"p5-758","level":4,"type":"준동사(to부정사·동명사·분사)","question":"Several shareholders objected to ------- the annual dividend for a second year.","choices":["reduce","be reduced","reducing","reduced"],"answer":2,"explanation":"object to의 to는 전치사이므로 뒤에 동명사가 와야 한다. 따라서 reducing이 정답이다. to를 to부정사로 착각해 원형 reduce를 고르기 쉽지만 틀리며, reduced와 be reduced도 전치사의 목적어가 될 수 없다.","translation":"몇몇 주주는 2년 연속으로 연간 배당금을 줄이는 데 반대했다.","part":5},{"id":"p5-759","level":4,"type":"비교","question":"The second training session was not as ------- as the first one.","choices":["informative","informatively","most informative","more informative"],"answer":0,"explanation":"as ~ as 원급 비교 사이에는 원급이 오고, be동사 was의 보어이므로 형용사 원급 informative가 정답이다. more informative와 most informative는 비교급·최상급이라 as ~ as 사이에 올 수 없고, informatively는 부사다.","translation":"두 번째 교육은 첫 번째만큼 유익하지 않았다.","part":5},{"id":"p5-760","level":4,"type":"비교","question":"The sooner you submit your application, the ------- your chances of being selected.","choices":["greatly","greater","greatest","great"],"answer":1,"explanation":"'The 비교급 ~, the 비교급 …' 구문(~할수록 더 …하다)이므로 비교급 greater가 정답이다. great는 원급, greatest는 최상급, greatly는 부사라 구조에 맞지 않는다.","translation":"지원서를 빨리 제출할수록 선발될 가능성이 더 높아진다.","part":5},{"id":"p5-761","level":5,"type":"어휘","question":"The audit revealed that several expense claims had been paid twice, prompting a review of the firm's ------- procedures.","choices":["endorsement","enlargement","reimbursement","entitlement"],"answer":2,"explanation":"같은 비용 청구를 두 번 지급한 문제 때문에 검토할 대상은 비용 '상환 절차'이므로 reimbursement가 정답이다. entitlement는 자격·권리, enlargement는 확대, endorsement는 보증·지지라 절차의 대상으로 맞지 않는다.","translation":"감사 결과 비용 청구 여러 건이 이중으로 지급된 것이 드러나 회사의 비용 상환 절차를 검토하게 되었다.","part":5},{"id":"p5-762","level":5,"type":"어휘","question":"Ms. Ekwueme's ------- handling of the product recall helped the company retain customer trust.","choices":["adapt","adept","adopt","adverse"],"answer":1,"explanation":"리콜을 '능숙하게' 처리해 고객 신뢰를 지켰다는 뜻이므로 형용사 adept가 정답이다. adapt(적응하다)와 adopt(채택하다)는 철자가 비슷한 동사라 명사 handling을 꾸밀 수 없고, adverse(불리한)는 신뢰를 지켰다는 결과와 모순된다.","translation":"에크웨메 씨가 제품 리콜을 능숙하게 처리한 덕분에 회사는 고객의 신뢰를 지킬 수 있었다.","part":5},{"id":"p5-763","level":5,"type":"어휘","question":"The two companies agreed to ------- their dispute through independent arbitration.","choices":["resolve","reserve","revolve","resume"],"answer":0,"explanation":"분쟁을 '해결하다'는 resolve a dispute가 연어다. revolve는 회전하다(자동사), resume은 재개하다라 분쟁을 다시 시작한다는 반대 의미가 되고, reserve는 예약하다·보류하다이다.","translation":"두 회사는 독립적인 중재를 통해 분쟁을 해결하기로 합의했다.","part":5},{"id":"p5-764","level":5,"type":"어휘","question":"Due to ------- demand, the limited-edition watches sold out within hours of their release.","choices":["overturning","overlooking","overlapping","overwhelming"],"answer":3,"explanation":"몇 시간 만에 매진된 이유로 '압도적인' 수요가 알맞으므로 overwhelming이 정답이다. overlapping은 겹치는, overlooking은 내려다보는·간과하는, overturning은 뒤집는이라 demand를 적절히 꾸미지 못한다.","translation":"폭발적인 수요로 한정판 시계는 출시 몇 시간 만에 매진되었다.","part":5},{"id":"p5-765","level":5,"type":"어휘","question":"Board members must ------- any potential conflicts of interest before voting on a proposal.","choices":["disclose","dispose","disperse","discharge"],"answer":0,"explanation":"이해 충돌 가능성을 '공개하다(밝히다)'는 disclose가 정답이다. dispose는 dispose of 형태로 '처분하다', disperse는 흩어지게 하다, discharge는 방출하다·해고하다라 문맥에 맞지 않는다.","translation":"이사들은 안건에 투표하기 전에 잠재적인 이해 충돌을 모두 밝혀야 한다.","part":5},{"id":"p5-766","level":5,"type":"어휘","question":"Ms. Lund was hired to ------- the company's transition to a cloud-based accounting system.","choices":["formulate","facilitate","falsify","fabricate"],"answer":1,"explanation":"새 시스템으로의 전환을 '원활하게 하다(촉진하다)'는 facilitate가 알맞다. fabricate(조작하다·제작하다)와 falsify(위조하다)는 부정적 의미이고, formulate는 계획·정책을 '만들어 내다'라 transition을 목적어로 하기에 어색하다.","translation":"룬드 씨는 회사의 클라우드 기반 회계 시스템 전환을 원활히 진행하기 위해 채용되었다.","part":5},{"id":"p5-767","level":5,"type":"어휘","question":"The terms of the lease are ------- negotiable, so tenants are encouraged to discuss them with the landlord.","choices":["someday","sometime","somewhat","somewhere"],"answer":2,"explanation":"형용사 negotiable을 꾸며 '어느 정도' 협상 가능하다는 뜻의 정도 부사 somewhat이 정답이다. somewhere는 장소, sometime과 someday는 시간을 나타내 형용사를 수식하지 못한다.","translation":"임대 조건은 어느 정도 협상이 가능하므로 세입자는 집주인과 상의해 보기를 권한다.","part":5},{"id":"p5-768","level":5,"type":"어휘","question":"Because the figures in the draft report were -------, the analyst was asked to verify each source.","choices":["questioning","questionably","questionnaire","questionable"],"answer":3,"explanation":"수치가 '의심스러워서' 출처를 확인하라고 했다는 문맥이므로 형용사 questionable이 정답이다. questioning은 '의문을 제기하는'으로 사람의 태도에 쓰이고, questionably는 부사라 be동사의 보어가 될 수 없으며, questionnaire는 설문지라는 명사다.","translation":"보고서 초안의 수치가 의심스러워서 분석가는 출처를 하나하나 확인하라는 요청을 받았다.","part":5},{"id":"p5-769","level":5,"type":"어휘","question":"The new trade agreement is expected to ------- tariffs on agricultural imports.","choices":["eliminating","eliminate","nominate","illuminate"],"answer":1,"explanation":"관세를 '없애다(철폐하다)'는 eliminate가 정답이다. illuminate는 밝히다, nominate는 지명하다라 tariffs와 어울리지 않고, eliminating은 to 뒤에 올 수 없는 형태다.","translation":"새 무역 협정은 농산물 수입 관세를 철폐할 것으로 예상된다.","part":5},{"id":"p5-770","level":5,"type":"어휘","question":"The hotel chain plans to ------- its outdated reservation system with a mobile platform.","choices":["supply","suppress","surpass","replace"],"answer":3,"explanation":"오래된 예약 시스템을 모바일 플랫폼으로 '대체하다'는 replace A with B이므로 replace가 정답이다. surpass는 능가하다라 with B와 함께 쓰지 않고, supply는 공급하다, suppress는 억누르다라 문맥에 맞지 않는다.","translation":"그 호텔 체인은 낡은 예약 시스템을 모바일 플랫폼으로 대체할 계획이다.","part":5},{"id":"p5-771","level":5,"type":"전치사","question":"Employees are reminded that confidential files must not be removed from the premises ------- written permission.","choices":["except","unless","without","beyond"],"answer":2,"explanation":"뒤에 명사구 written permission이 오며 '서면 허가 없이'라는 뜻이므로 전치사 without이 정답이다. unless는 접속사라 뒤에 절이 필요하고, except는 '~을 제외하고'라 허가를 제외한다는 어색한 뜻이 되며, beyond는 '~을 넘어서'이다.","translation":"직원 여러분은 서면 허가 없이 기밀 파일을 사업장 밖으로 가지고 나가서는 안 된다는 점을 유념하기 바랍니다.","part":5},{"id":"p5-772","level":5,"type":"어휘","question":"After careful -------, the committee decided to award the contract to a local firm.","choices":["deliberation","delegation","delivery","declaration"],"answer":0,"explanation":"'신중한 심의 끝에' 결정했다는 뜻이므로 deliberation이 정답이다. delivery는 배달·전달, delegation은 대표단·위임, declaration은 선언이라 결정에 이르는 과정을 나타내지 못한다.","translation":"신중한 심의 끝에 위원회는 지역 업체에 계약을 주기로 결정했다.","part":5},{"id":"p5-773","level":5,"type":"품사","question":"The new regulations place ------- restrictions on the export of certain chemicals.","choices":["stringent","stringently","stringencies","stringency"],"answer":0,"explanation":"동사 place의 목적어 restrictions를 앞에서 꾸미는 형용사 자리이므로 stringent(엄격한)가 정답이다. stringently는 부사, stringency와 stringencies는 명사다.","translation":"새 규정은 특정 화학 물질의 수출에 엄격한 제한을 둔다.","part":5},{"id":"p5-774","level":5,"type":"품사","question":"The CEO's remarks were ------- misinterpreted by several news outlets.","choices":["wide","widely","width","widen"],"answer":1,"explanation":"수동태 were misinterpreted 사이에서 과거분사를 꾸미는 부사 자리이므로 widely(널리)가 정답이다. wide도 부사로 쓰이지만 '활짝'이라는 물리적 의미(wide open)라 '널리 오해되었다'는 뜻을 만들지 못한다. width는 명사, widen은 동사다.","translation":"CEO의 발언은 여러 언론사에 의해 널리 잘못 해석되었다.","part":5},{"id":"p5-775","level":5,"type":"품사","question":"Ms. Ozturk's ------- of the merger terms impressed even the most skeptical shareholders.","choices":["defensive","defend","defense","defensively"],"answer":2,"explanation":"소유격 Ms. Ozturk's 뒤, of 앞은 주어가 되는 명사 자리이므로 defense(옹호)가 정답이다. defend는 동사, defensive는 형용사, defensively는 부사라 소유격 뒤에 올 수 없다.","translation":"오즈투르크 씨가 합병 조건을 옹호하는 모습은 가장 회의적인 주주들까지 감동시켰다.","part":5},{"id":"p5-776","level":5,"type":"품사","question":"Responses to the survey were ------- favorable, with 92 percent of respondents rating the service as excellent.","choices":["overwhelmed","overwhelming","overwhelm","overwhelmingly"],"answer":3,"explanation":"형용사 favorable을 꾸미는 부사 자리이므로 overwhelmingly가 정답이다. overwhelming은 형용사라 다른 형용사를 꾸미지 못하고, overwhelm은 동사, overwhelmed는 과거분사다.","translation":"설문 응답은 압도적으로 호의적이었으며 응답자의 92퍼센트가 서비스를 '매우 좋음'으로 평가했다.","part":5},{"id":"p5-777","level":5,"type":"품사","question":"The firm is seeking a ------- who can manage relationships with institutional investors.","choices":["liaison","liaising","liaise","liaised"],"answer":0,"explanation":"관사 a 뒤, 관계사 who 앞은 사람을 나타내는 명사 자리이므로 liaison(연락 담당자)이 정답이다. liaise는 동사, liaising과 liaised는 동명사·분사 형태라 a 뒤 명사 자리에 올 수 없다.","translation":"그 회사는 기관 투자자와의 관계를 관리할 연락 담당자를 찾고 있다.","part":5},{"id":"p5-778","level":5,"type":"품사","question":"Visitors must be accompanied by an ------- employee at all times while in the laboratory.","choices":["authority","authorization","authorizing","authorized"],"answer":3,"explanation":"관사 an과 명사 employee 사이 형용사 자리로, 직원이 '권한을 부여받은' 상태이므로 과거분사 authorized가 정답이다. authorizing은 '권한을 주는'이라는 능동 의미라 맞지 않고, authorization과 authority는 명사다.","translation":"방문객은 실험실에 있는 동안 항상 승인된 직원과 동행해야 한다.","part":5},{"id":"p5-779","level":5,"type":"동사 시제·태","question":"The proposal ------- for weeks before the board finally voted on it last Friday.","choices":["has been debated","will have been debated","had been debated","was debating"],"answer":2,"explanation":"지난 금요일 투표(과거)보다 앞서 몇 주간 '논의되어 온' 일이므로 과거완료 수동 had been debated가 정답이다. has been debated는 현재완료라 과거 기준점과 맞지 않고, was debating은 능동이라 안건이 논의를 한 뜻이 되며, will have been debated는 미래완료다.","translation":"그 제안은 지난 금요일 이사회가 마침내 표결하기 전까지 몇 주 동안 논의되었다.","part":5},{"id":"p5-780","level":5,"type":"동사 시제·태","question":"It is imperative that the safety inspection ------- before the factory resumes operations.","choices":["is completed","be completed","was completed","will be completed"],"answer":1,"explanation":"imperative, essential, vital 같은 필요·당위의 형용사 뒤 that절에는 (should) + 동사원형을 쓴다. 점검은 '완료되는' 대상이므로 원형 수동태 be completed가 정답이다. is completed, will be completed, was completed는 직설법이라 이 구문에 맞지 않는다.","translation":"공장이 가동을 재개하기 전에 반드시 안전 점검이 완료되어야 한다.","part":5},{"id":"p5-781","level":5,"type":"동사 시제·태","question":"Had the marketing team known about the delay, it ------- the advertising campaign.","choices":["would have postponed","would postpone","had postponed","will postpone"],"answer":0,"explanation":"Had the team known은 If the team had known에서 if를 생략하고 도치한 가정법 과거완료이므로 주절은 would have p.p.인 would have postponed가 정답이다. would postpone은 가정법 과거, had postponed와 will postpone은 가정법 주절 형태가 아니다.","translation":"마케팅팀이 지연 사실을 알았더라면 광고 캠페인을 연기했을 것이다.","part":5},{"id":"p5-782","level":5,"type":"동사 시제·태","question":"By the time the merger is finalized, the two firms ------- for nearly a year.","choices":["are negotiating","have been negotiating","had been negotiating","will have been negotiating"],"answer":3,"explanation":"By the time + 현재시제는 미래 기준점이고, 그때까지 약 1년간 '계속 진행되어 온' 동작이므로 미래완료진행 will have been negotiating이 정답이다. have been negotiating은 현재 기준, had been negotiating은 과거 기준, are negotiating은 현재진행이다.","translation":"합병이 마무리될 무렵이면 두 회사는 거의 1년 동안 협상을 해 온 셈이 될 것이다.","part":5},{"id":"p5-783","level":5,"type":"수 일치","question":"A series of workshops on data security ------- planned for the coming quarter.","choices":["have been","has been","were","are"],"answer":1,"explanation":"A series of는 '일련의'라는 뜻으로 핵심 주어 series가 단수이므로 단수 동사 has been이 정답이다. workshops에 이끌려 have been, are, were 같은 복수 동사를 고르는 것이 함정이다.","translation":"다음 분기에 데이터 보안에 관한 일련의 워크숍이 계획되어 있다.","part":5},{"id":"p5-784","level":5,"type":"수 일치","question":"What the shareholders want ------- a clear plan for returning the company to profitability.","choices":["have","were","is","are"],"answer":2,"explanation":"What이 이끄는 명사절 주어는 단수 취급하므로 is가 정답이다. shareholders에 이끌려 are나 were를 고르기 쉽지만 그것은 명사절 안의 주어다. have는 의미상 보어 관계를 만들지 못한다.","translation":"주주들이 원하는 것은 회사를 다시 흑자로 돌려놓을 명확한 계획이다.","part":5},{"id":"p5-785","level":5,"type":"수 일치","question":"Attached to this e-mail ------- the revised floor plans for the new headquarters.","choices":["has been","is","was","are"],"answer":3,"explanation":"보어(Attached to this e-mail)가 문장 앞으로 나와 주어와 동사가 도치된 구조다. 실제 주어는 뒤의 복수명사 the revised floor plans이므로 복수 동사 are가 정답이다. 앞의 e-mail에 맞춰 단수 is를 고르면 틀린다.","translation":"이 이메일에 새 본사의 수정된 평면도가 첨부되어 있습니다.","part":5},{"id":"p5-786","level":5,"type":"대명사","question":"The finance team reviewed the three bids, but ------- met all of the technical requirements.","choices":["no one","none","nothing","neither"],"answer":1,"explanation":"세 개의 입찰 가운데 '어느 것도' 요건을 충족하지 못했다는 뜻이므로 셋 이상에 쓰는 none이 정답이다. neither는 둘 중 어느 것도 아님을 나타내 three bids와 맞지 않고, no one은 사람, nothing은 '아무것도'라 특정 대상 중에서 고르는 의미가 약하다.","translation":"재무팀은 세 건의 입찰을 검토했지만 어느 것도 기술 요건을 모두 충족하지 못했다.","part":5},{"id":"p5-787","level":5,"type":"대명사","question":"Ms. Bianchi asked that all inquiries about the merger be directed to ------- rather than to her assistant.","choices":["hers","herself","her","she"],"answer":2,"explanation":"전치사 to의 목적어로 Ms. Bianchi 본인을 가리키므로 목적격 her가 정답이다. 주어 Ms. Bianchi와 같은 사람이라 herself를 고르기 쉽지만, 이 대명사는 that절(주어 all inquiries) 안에 있어 재귀대명사의 조건(같은 절의 주어와 동일)을 충족하지 못한다. she는 주격, hers는 소유대명사다.","translation":"비앙키 씨는 합병에 관한 모든 문의를 비서가 아니라 자신에게 보내 달라고 요청했다.","part":5},{"id":"p5-788","level":5,"type":"대명사","question":"Although the two proposals differ in scope, ------- aims to reduce operating costs by at least 10 percent.","choices":["each","every","both","all"],"answer":0,"explanation":"동사 aims가 단수형이므로 단수 취급하면서 대명사로 단독 사용할 수 있는 each가 정답이다. every는 형용사라 뒤에 명사가 필요하고, all과 both는 복수 취급해 aim과 짝을 이룬다.","translation":"두 제안은 범위가 다르지만 각각 운영 비용을 최소 10퍼센트 줄이는 것을 목표로 한다.","part":5},{"id":"p5-789","level":5,"type":"전치사","question":"The museum's new wing will open to the public ------- the completion of the final safety inspection.","choices":["along","following","throughout","toward"],"answer":1,"explanation":"'최종 안전 점검이 완료된 후에'라는 뜻이므로 '~ 이후에'를 뜻하는 전치사 following이 정답이다. along은 ~을 따라, toward는 ~ 쪽으로, throughout은 ~ 내내라 시간 순서를 나타내지 못한다.","translation":"박물관 신관은 최종 안전 점검이 완료된 후 일반에 공개될 것이다.","part":5},{"id":"p5-790","level":5,"type":"전치사","question":"Shipping charges are calculated ------- the weight and destination of each package.","choices":["on the basis of","at the expense of","in the event of","for the sake of"],"answer":0,"explanation":"'무게와 목적지를 기준으로' 계산한다는 뜻이므로 on the basis of가 정답이다. in the event of는 '~할 경우에', at the expense of는 '~을 희생하여', for the sake of는 '~을 위하여'라 계산 기준을 나타내지 못한다.","translation":"배송비는 각 소포의 무게와 목적지를 기준으로 계산된다.","part":5},{"id":"p5-791","level":5,"type":"전치사","question":"All proposals will be evaluated ------- the criteria outlined in the request for bids.","choices":["across","beyond","against","versus"],"answer":2,"explanation":"evaluate A against B는 'B를 기준으로 A를 평가하다'라는 표현이므로 against가 정답이다. across는 ~에 걸쳐, beyond는 ~을 넘어서, versus는 대결·대비(A versus B)를 나타내 평가 기준을 나타내지 못한다.","translation":"모든 제안서는 입찰 요청서에 제시된 기준에 따라 평가될 것이다.","part":5},{"id":"p5-792","level":5,"type":"접속사","question":"------- the factory meets the new emissions standards, it will be allowed to expand production.","choices":["Unless","Lest","Whereas","Provided"],"answer":3,"explanation":"Provided (that)은 '~라는 조건으로, ~하면'이라는 조건 접속사로 문맥에 맞는다. Unless는 '~하지 않으면'이라 의미가 반대가 되고, Lest는 '~하지 않도록', Whereas는 대조를 나타낸다.","translation":"공장이 새 배출 기준을 충족하면 생산 확대가 허용될 것이다.","part":5},{"id":"p5-793","level":5,"type":"접속사","question":"The proposal was well received, ------- some board members questioned its long-term costs.","choices":["so that","unless","although","despite"],"answer":2,"explanation":"'호평을 받았지만 일부 이사가 장기 비용을 문제 삼았다'는 양보 관계이며 뒤에 절이 오므로 접속사 although가 정답이다. despite는 전치사라 절을 이끌 수 없고, unless는 부정 조건, so that은 목적이다.","translation":"그 제안은 좋은 반응을 얻었지만, 일부 이사는 장기적인 비용에 의문을 제기했다.","part":5},{"id":"p5-794","level":5,"type":"접속사","question":"------- had the new director taken office than she announced a hiring freeze.","choices":["No sooner","Scarcely","Hardly","As soon as"],"answer":0,"explanation":"뒤에 than이 있으므로 'No sooner had S p.p. than…(~하자마자 …했다)' 구문이 되는 No sooner가 정답이다. Hardly와 Scarcely는 when 또는 before와 짝을 이루고, As soon as는 도치 없이 쓰며 than과 결합하지 않는다.","translation":"새 이사는 취임하자마자 채용 동결을 발표했다.","part":5},{"id":"p5-795","level":5,"type":"관계사","question":"The committee interviewed six candidates, two of ------- had previously worked for competing firms.","choices":["them","whom","which","who"],"answer":1,"explanation":"콤마 뒤에서 두 절을 연결하면서 '수량 표현 + of + 관계대명사' 구조를 이루므로 목적격 whom이 정답이다(선행사 six candidates는 사람). who는 전치사 of 뒤에 쓸 수 없고, them은 대명사라 접속사 없이 두 절을 연결하지 못하며, which는 사물에 쓴다.","translation":"위원회는 후보자 여섯 명을 면접했는데, 그중 두 명은 이전에 경쟁사에서 근무한 적이 있었다.","part":5},{"id":"p5-796","level":5,"type":"관계사","question":"Applicants should describe the circumstances under ------- they left their previous positions.","choices":["that","whom","what","which"],"answer":3,"explanation":"전치사 under 뒤에서 선행사 the circumstances(사물)를 받는 관계대명사는 which다. that은 전치사 바로 뒤에 쓸 수 없고, what은 선행사를 포함하며, whom은 사람 선행사에 쓴다.","translation":"지원자는 이전 직장을 그만둔 경위를 설명해야 한다.","part":5},{"id":"p5-797","level":5,"type":"준동사(to부정사·동명사·분사)","question":"------- in 1998 as a small repair shop, Torvald Motors now operates 40 dealerships nationwide.","choices":["Having established","Established","To establish","Establishing"],"answer":1,"explanation":"회사 Torvald Motors는 '설립된' 대상이므로 수동의 과거분사 Established로 시작하는 분사구문이 정답이다. Establishing과 Having established는 능동이라 회사가 무언가를 설립했다는 뜻이 되고, To establish는 목적(~하기 위해)을 나타내 1998년이라는 과거 사실과 맞지 않는다.","translation":"1998년 작은 수리점으로 설립된 토르발 모터스는 현재 전국에서 40개의 대리점을 운영하고 있다.","part":5},{"id":"p5-798","level":5,"type":"준동사(to부정사·동명사·분사)","question":"The firm's growth is largely attributable to its willingness ------- in emerging technologies.","choices":["for investing","investing","to invest","invested"],"answer":2,"explanation":"willingness는 to부정사와 결합해 '기꺼이 ~하려는 의지'를 나타내므로 to invest가 정답이다. investing은 전치사 없이 명사 뒤에 붙지 않고, invested는 '투자된'이라는 수동 의미이며, for investing은 willingness와 쓰는 결합이 아니다.","translation":"그 회사의 성장은 대체로 신기술에 기꺼이 투자하려는 자세 덕분이다.","part":5},{"id":"p5-799","level":5,"type":"비교","question":"Of the two marketing strategies, the board considered the digital campaign the ------- effective.","choices":["very","much","most","more"],"answer":3,"explanation":"Of the two(둘 중에서)는 두 대상을 비교하므로 'the + 비교급'을 써서 the more effective가 정답이다. the 때문에 최상급 most를 고르기 쉽지만 셋 이상일 때 쓴다. much와 very는 the ------- effective 구조를 만들지 못한다.","translation":"두 마케팅 전략 중에서 이사회는 디지털 캠페인이 더 효과적이라고 보았다.","part":5},{"id":"p5-800","level":5,"type":"품사","question":"Online sales this quarter were ------- double the figure for the same period last year.","choices":["roughly","roughest","rougher","rough"],"answer":0,"explanation":"배수 표현 double the figure 앞에서 '대략'을 뜻하는 부사 roughly가 정답이다. rough는 형용사로 '거친', rougher와 roughest는 그 비교급·최상급이라 수량 표현을 꾸미지 못한다.","translation":"이번 분기 온라인 매출은 작년 같은 기간 수치의 대략 두 배였다.","part":5}];
